    internal void SeedRuntimeUnlockOfferCriticalSectionForTests(
        string sessionId,
        string nonce,
        long payerDecisionId,
        long generation,
        bool observedSend = false,
        string? observedLane = null,
        bool peerReceived = false,
        bool answerTimeoutScheduled = false,
        bool preserveRecoveryState = false,
        RuntimeUnlockRetryDispatchInstallReceipt? installReceipt = null)
    {
        var normalizedSessionId = string.IsNullOrWhiteSpace(sessionId)
            ? currentSessionSecurityState.SessionId?.Value ?? string.Empty
            : sessionId.Trim();
        var normalizedNonce = string.IsNullOrWhiteSpace(nonce) ? "test_nonce" : nonce.Trim();
        RuntimeUnlockRecoveryRetryState? recoveryStateToClear = null;
        RuntimeUnlockRetryDispatchSettlementReport settlementReport = default;
        var recoveryStateHadDispatchContract = false;
        lock (accelerationGate)
        {
            accelerationSessionId = null;
            accelerationNegotiatedLanes = NknAccelerationLaneKind.None;
            outboundAccelerationOfferNonce = normalizedNonce;
            outboundAccelerationOfferTrigger = "runtime_unlock";
            outboundAccelerationOfferInstallReceipt = installReceipt;
            outboundAccelerationOfferPayerDecisionId = payerDecisionId;
            outboundAccelerationOfferGeneration = generation;
            var transactionDecision = StartRuntimeUnlockTransactionForOfferUnsafe(
                normalizedSessionId,
                generation,
                "runtime_unlock_test_offer_seeded");
            runtimeUnlockOfferProofState = new RuntimeUnlockOfferProofState
            {
                AuthorityMode = installReceipt is null
                    ? RuntimeUnlockOfferAuthorityMode.InitialActivation
                    : RuntimeUnlockOfferAuthorityMode.InstalledRetry,
                Generation = generation,
                Nonce = normalizedNonce,
                SessionId = normalizedSessionId,
                PayerDecisionId = payerDecisionId,
                Trigger = "runtime_unlock",
                CreatedUtcMs = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds(),
                ObservedSend = observedSend,
                ObservedSendLane = observedLane,
                PeerReceived = peerReceived,
                AnswerTimeoutScheduled = answerTimeoutScheduled,
            };
            var leaseGeneration = ++runtimeUnlockTunaPathLeaseNextGeneration;
            var listenerRunId = $"listener-start-{leaseGeneration.ToString(CultureInfo.InvariantCulture)}";
            var lease = RuntimeUnlockTunaPathLease.Start(
                normalizedSessionId,
                transferId: null,
                leaseGeneration,
                listenerRunId,
                payerDecisionId,
                DateTimeOffset.UtcNow.ToUnixTimeMilliseconds());
            RuntimeUnlockTunaPathLease.TryMarkListenerReady(
                lease,
                normalizedSessionId,
                leaseGeneration,
                listenerRunId,
                DateTimeOffset.UtcNow.ToUnixTimeMilliseconds(),
                out lease);
            runtimeUnlockTunaPathLeaseState = RuntimeUnlockTunaPathLease.BindOffer(
                lease,
                transactionDecision.State.TransactionGeneration,
                generation,
                payerDecisionId,
                DateTimeOffset.UtcNow.ToUnixTimeMilliseconds());
            runtimeUnlockTransactionState =
                AttachRuntimeUnlockTunaPathLeaseUnsafe(runtimeUnlockTransactionState);
            outboundRuntimeUnlockOfferAuthorityBoundary =
                new RuntimeUnlockOfferAuthorityBoundary(
                    installReceipt is null
                        ? RuntimeUnlockOfferAuthorityMode.InitialActivation
                        : RuntimeUnlockOfferAuthorityMode.InstalledRetry,
                    normalizedSessionId,
                    runtimeUnlockTunaPathLeaseState.TransferId,
                    FileTransferDirection.Outbound,
                    normalizedNonce,
                    payerDecisionId,
                    generation,
                    transactionDecision.State.TransactionGeneration,
                    runtimeUnlockTunaPathLeaseState.LeaseGeneration,
                    runtimeUnlockTunaPathLeaseState.ListenerRunId,
                    $"test-semantic-{normalizedNonce}",
                    EnvelopeGeneration: 1,
                    EnvelopeSentAtUnixMs:
                        DateTimeOffset.UtcNow.ToUnixTimeMilliseconds(),
                    EnvelopeExpiresAtUnixMs:
                        DateTimeOffset.UtcNow
                            .Add(AccelerationOfferLifetime)
                            .ToUnixTimeMilliseconds(),
                    ControlEnvelopeFingerprint:
                        $"test-envelope-{normalizedNonce}",
                    InstallReceipt: installReceipt);
            if ((preserveRecoveryState || installReceipt is not null) &&
                runtimeUnlockRecoveryRetryState is { } recoveryState &&
                string.Equals(recoveryState.SessionId, normalizedSessionId, StringComparison.Ordinal))
            {
                recoveryState.CurrentOfferGeneration = generation;
            }

            if (!preserveRecoveryState && installReceipt is null)
            {
                recoveryStateToClear = runtimeUnlockRecoveryRetryState;
                if (recoveryStateToClear is not null)
                {
                    _ = InvalidateRuntimeUnlockRetryDispatchDecisionStageUnsafe(
                        recoveryStateToClear,
                        "retry_dispatch_install_stage_invalidated_test_offer_state_replaced");
                }
                recoveryStateHadDispatchContract = recoveryStateToClear?.DispatchContract is not null;
                _ = SettleRuntimeUnlockRetryDispatchContractUnsafe(
                    runtimeUnlockRecoveryRetryState,
                    RuntimeUnlockRetryDispatchSettlementOutcome.StaleRejected,
                    "test_offer_state_replaced",
                    out settlementReport);
                if (!recoveryStateHadDispatchContract)
                {
                    runtimeUnlockRecoveryRetryState = null;
                }
            }
        }

        if (!settlementReport.IsDefault)
        {
            if (PublishRuntimeUnlockRetryDispatchSettlementReport(settlementReport))
            {
                lock (accelerationGate)
                {
                    if (ReferenceEquals(runtimeUnlockRecoveryRetryState, recoveryStateToClear))
                    {
                        runtimeUnlockRecoveryRetryState = null;
                    }
                }
            }
        }
    }

