    private static string FormatFileTransferRouteTransitionAuthorityTuple(
        FileTransferRouteTransitionAuthority authority)
    {
        var sourceOwner = authority.SourceRuntimeOwner;
        var sourcePublication = authority.SourceRoutePublication;
        var checkpoint = authority.DurableCheckpoint;
        var proofTuple = authority.ProofBoundary switch
        {
            FileTransferTunaActivationTransitionProofBoundary activation =>
                $"; proof_boundary=activation; admission_generation={activation.RuntimeUnlockAdmission.AdmissionGeneration}; pending_precommit_generation={activation.PendingPreCommitProbe.PendingGeneration}; transaction_generation={activation.AcceptedLaunchBoundary.TransactionGeneration}; offer_generation={activation.AcceptedLaunchBoundary.OfferGeneration}; launch_generation={activation.LaunchGeneration}; tuna_path_lease_generation={activation.AcceptedLaunchBoundary.TunaPathLeaseGeneration}; tuna_path_lease_listener_run_id={SanitizeLogToken(activation.AcceptedLaunchBoundary.TunaPathLeaseListenerRunId ?? "(none)")}; path_probe_id={SanitizeLogToken(activation.AcceptedLaunchBoundary.PathProbeId ?? "(none)")}; path_probe_state={SanitizeLogToken(activation.AcceptedLaunchBoundary.PathProbeState.ToString())}; path_probe_transport={FormatFileTransferTransportKindForLog(activation.AcceptedLaunchBoundary.PathProbeTransport)}; path_probe_acked_utc_ms={activation.AcceptedLaunchBoundary.PathProbeAckedUtcMs}; retry_authority_id={SanitizeLogToken(activation.EffectiveRetryInstallReceipt?.Authority.AuthorityId.ToString() ?? "(none)")}; install_generation={activation.EffectiveRetryInstallReceipt?.InstallGeneration ?? 0}; release_kind={SanitizeLogToken(activation.EffectiveRetryInstallReceipt?.Authority.ReleaseKind.ToString() ?? "(none)")}; release_authority_id={SanitizeLogToken(activation.EffectiveRetryInstallReceipt?.Authority.ReleaseAuthorityId?.ToString() ?? "(none)")}; release_generation={activation.EffectiveRetryInstallReceipt?.Authority.ReleaseGeneration ?? 0}; release_outcome={SanitizeLogToken(activation.EffectiveRetryInstallReceipt?.Authority.ReleaseOutcome ?? "(none)")}; fallback_tail_yield_authority_id={SanitizeLogToken(activation.FallbackTailPairedReleaseReceipt?.LocalProof.Decision.AuthorityId.ToString() ?? "(none)")}; fallback_tail_yield_predecessor_authority_id={SanitizeLogToken(activation.FallbackTailPairedReleaseReceipt?.LocalProof.Decision.PredecessorAuthorityId?.ToString() ?? "(none)")}; fallback_tail_yield_generation={activation.FallbackTailPairedReleaseReceipt?.LocalProof.Decision.YieldGeneration ?? 0}; fallback_tail_yield_kind={SanitizeLogToken(activation.FallbackTailPairedReleaseReceipt?.LocalProof.Decision.YieldKind.ToString() ?? "(none)")}",
            FileTransferFallbackTransitionProofBoundary fallback =>
                $"; proof_boundary=fallback; source_route_commit_generation={fallback.SourceRouteCommit?.CommitGeneration ?? 0}; peer_proof_generation={fallback.PeerProofEvidence.ProofGeneration}; peer_proof_transport_epoch={fallback.PeerProofEvidence.TransportEpoch}; peer_proof_kind={SanitizeLogToken(fallback.PeerProofEvidence.ProofKind)}; peer_proof_frame_type={SanitizeLogToken(fallback.RetainedFrameIdentity.FrameType)}; peer_proof_frame_transport_epoch={fallback.RetainedFrameIdentity.TransportEpoch}; peer_proof_frame_sha256={SanitizeLogToken(fallback.RetainedFrameIdentity.Sha256)}; target_transport_epoch={fallback.TargetTransportEpoch}; target_bridge_recovery_generation={fallback.TargetBridgeRecoveryGeneration}; proof_predecessor_authority_id={SanitizeLogToken(fallback.PredecessorTransitionAuthorityId?.ToString() ?? "(none)")}",
            _ => "; proof_boundary=unknown",
        };
        return
            $"session_id={SanitizeLogToken(authority.SessionId)}; transfer_id={SanitizeLogToken(authority.TransferId)}; direction={FormatFileTransferDirection(authority.Direction)}; " +
            $"authority_id={SanitizeLogToken(authority.AuthorityId.ToString())}; transition_generation={authority.TransitionGeneration}; transition_kind={SanitizeLogToken(authority.Kind.ToString())}; predecessor_authority_id={SanitizeLogToken(authority.PredecessorTransitionAuthorityId?.ToString() ?? "(none)")}; " +
            $"source_route={SanitizeLogToken(FileTransferRouteResolver.Resolve(authority.SourceRoute).TelemetryToken)}; source_protocol_version={authority.SourceProtocolVersion}; source_transport={FormatFileTransferTransportKindForLog(authority.SourceTransport)}; " +
            $"source_live_route_epoch={authority.SourceLiveRouteEpoch}; source_runtime_generation={sourceOwner.RuntimeGeneration}; source_terminal_generation={authority.SourceTerminalGeneration}; source_leg_generation={authority.SourceLegGeneration}; source_transport_epoch={authority.SourceTransportEpoch}; source_bridge_recovery_generation={authority.SourceBridgeRecoveryGeneration}; data_session_generation={authority.DataSessionGeneration}; " +
            $"source_route_publication_generation={sourcePublication.PublicationGeneration}; source_route_commit_generation={authority.SourceRouteCommit?.CommitGeneration ?? 0}; source_route_commit_generation_present={(authority.SourceRouteCommit.HasValue ? 1 : 0)}; " +
            $"target_route={SanitizeLogToken(FileTransferRouteResolver.Resolve(authority.TargetRoute).TelemetryToken)}; target_protocol_version={authority.TargetProtocolVersion}; target_transport={FormatFileTransferTransportKindForLog(authority.TargetTransport)}; handoff_kind={FormatFileTransferTransportHandoffKindForLog(authority.HandoffKind)}; " +
            $"proof_boundary_kind={SanitizeLogToken(authority.ProofBoundary.GetType().Name)}; checkpoint_generation={checkpoint.CheckpointGeneration}; checkpoint_state_epoch={checkpoint.StateEpoch}; checkpoint_contiguous_committed_chunk_index={checkpoint.ContiguousCommittedChunkIndex}; checkpoint_durable_highest_chunk_index={checkpoint.DurableHighestChunkIndex}; checkpoint_chunk_count={checkpoint.ChunkCount}; transition_reason={SanitizeLogToken(authority.Reason)}{proofTuple}";
    }

    public void ObserveRegularV4FrontierRepairSettlement(FileTransferRegularV4FrontierRepairSettlement settlement)
    {
        var sessionId = string.IsNullOrWhiteSpace(settlement.SessionId)
            ? currentSessionSecurityState.SessionId?.Value
            : settlement.SessionId.Trim();
        var transferId = string.IsNullOrWhiteSpace(settlement.TransferId) ? "(none)" : settlement.TransferId.Trim();

        if (client is not RealNknClientAdapter realClient)
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=filetransfer_regular_v4_frontier_repair_settlement_unsupported; session_id={SanitizeLogToken(sessionId ?? "none")}; transfer_id={SanitizeLogToken(transferId)}; repair_request_key={SanitizeLogToken(settlement.RepairKey)}; outcome={SanitizeLogToken(settlement.Outcome.ToString())}");
            return;
        }

        var normalizedSettlement = settlement with
        {
            SessionId = sessionId ?? "none",
            TransferId = transferId,
        };
        if (!realClient.IsRegularV4FrontierRepairSettlementApplied(normalizedSettlement))
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=filetransfer_regular_v4_frontier_repair_settlement_handoff_rejected; source=nkn_bridge_pressure; stage=settlement_handoff; session_id={SanitizeLogToken(normalizedSettlement.SessionId)}; transfer_id={SanitizeLogToken(normalizedSettlement.TransferId)}; authority_id={SanitizeLogToken(normalizedSettlement.AuthorityId.ToString())}; outcome={SanitizeLogToken(normalizedSettlement.Outcome.ToString())}; decision_reason=coordinator_pressure_settlement_not_applied");
            return;
        }

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=filetransfer_regular_v4_frontier_repair_settlement_observed; source=nkn_bridge_pressure; session_id={SanitizeLogToken(normalizedSettlement.SessionId)}; transfer_id={SanitizeLogToken(normalizedSettlement.TransferId)}; authority_id={SanitizeLogToken(normalizedSettlement.AuthorityId.ToString())}; outcome={SanitizeLogToken(normalizedSettlement.Outcome.ToString())}; decision_reason=coordinator_pressure_settlement_applied");
    }

