    private void LogRuntimeUnlockRetryDispatchProof(
        string eventName,
        RuntimeUnlockRecoveryRetryState state,
        string decisionReason,
        RoutePublicationToken? coordinatorCurrentPublication = null)
    {
        var contract = state.DispatchContract;
        if (contract is not null)
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event={SanitizeLogToken(eventName)}; {FormatRuntimeUnlockRetryDispatchAuthorityTuple(contract.Authority)}; offer_generation={contract.OfferGeneration}; offer_nonce={SanitizeLogToken(contract.OfferNonce ?? "(none)")}; queued_behind_active_negotiation={(state.QueuedBehindActiveNegotiation ? 1 : 0)}; decision_reason={SanitizeLogToken(decisionReason)}");
            if (contract.Lifecycle.SettlementOutcome is { } currentSettlementOutcome)
            {
                LogRuntimeUnlockRetryDispatchContractSettled(
                    contract,
                    currentSettlementOutcome,
                    contract.Lifecycle.SettlementReason ?? decisionReason);
            }
            return;
        }

        var route = string.IsNullOrWhiteSpace(state.DispatchRoute)
            ? "(none)"
            : state.DispatchRoute;
        var protocolVersion = state.DispatchProtocolVersion;
        var liveRouteEpoch = state.DispatchLiveRouteEpoch;
        var requestTuple = state.PendingDispatchAuthorityRequest is { } pendingRequest
            ? $"; request_tuple_present=1; {FormatRuntimeUnlockRetryDispatchAuthorityRequestTuple(pendingRequest)}"
            : "; request_tuple_present=0";

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event={SanitizeLogToken(eventName)}; session_id={SanitizeLogToken(state.SessionId)}; transfer_id={SanitizeLogToken(state.TransferId ?? "(none)")}; contract_generation={state.ContractGeneration}; retired_generation={state.RetiredOfferGeneration}; offer_generation={(state.CurrentOfferGeneration > 0 ? state.CurrentOfferGeneration : state.RetiredOfferGeneration)}; route={SanitizeLogToken(route)}; protocol_version={protocolVersion}; live_route_epoch={liveRouteEpoch}; runtime_generation={state.DispatchRuntimeGeneration}; terminal_generation={state.DispatchTerminalGeneration}; leg_generation={state.DispatchLegGeneration}; regular_v4_liveness_generation=0; bridge_decision_generation=0; queued_behind_active_negotiation={(state.QueuedBehindActiveNegotiation ? 1 : 0)}; decision_reason={SanitizeLogToken(decisionReason)}{requestTuple}{FormatRuntimeUnlockRetrySourcePublicationDiagnosticSuffix(state.PendingDispatchAuthorityRequest?.SourcePublicationAuthority ?? state.SourcePublicationAuthority, FileTransferCoordinator.CreateRoutePublicationAuthority(coordinatorCurrentPublication))}");

    }

    private static string FormatRuntimeUnlockRetrySourcePublicationDiagnosticSuffix(
        FileTransferRoutePublicationAuthority? attempted,
        FileTransferRoutePublicationAuthority? current)
    {
        static string Tuple(string prefix, FileTransferRoutePublicationAuthority? authority)
            => $"; {prefix}_session_id={SanitizeLogToken(authority?.SessionId ?? "(none)")}; {prefix}_transfer_id={SanitizeLogToken(authority?.TransferId ?? "(none)")}; {prefix}_direction={FormatFileTransferDirection(authority?.Direction)}; {prefix}_route={SanitizeLogToken(authority?.RouteToken ?? "(none)")}; {prefix}_protocol_version={authority?.ProtocolVersion ?? 0}; {prefix}_live_route_epoch={authority?.LiveRouteEpoch ?? 0}; {prefix}_runtime_generation={authority?.RuntimeGeneration ?? 0}; {prefix}_terminal_generation={authority?.TerminalGeneration ?? 0}; {prefix}_leg_generation={authority?.LegGeneration ?? 0}; {prefix}_route_publication_generation={authority?.RoutePublicationGeneration ?? 0}; {prefix}_route_commit_generation={authority?.RouteCommitGeneration ?? 0}; {prefix}_target_route={SanitizeLogToken(authority?.TargetRouteToken ?? "(none)")}; {prefix}_target_protocol_version={authority?.TargetProtocolVersion ?? 0}; {prefix}_target_transport={FormatFileTransferTransportKindForLog(authority?.TargetTransport ?? FileTransferTransportKind.Unknown)}; {prefix}_route_publication_action_kind={SanitizeLogToken(authority?.RoutePublicationActionKind ?? "(none)")}";

        return Tuple("attempted_source_publication", attempted) +
               Tuple("current_source_publication", current);
    }

    private void ScheduleRuntimeUnlockRetryDispatchDeadlineEvaluation(
        RuntimeUnlockRecoveryRetryState state)
    {
        if (!state.DispatchAuthorityGranted ||
            state.DispatchAuthorityRejected ||
            state.PendingDispatchSettlementReport is not null ||
            state.DispatchObserved ||
            state.DispatchContract is not { } contract ||
            runtimeUnlockRetryDispatchInstallShadow.LastCommittedReceipt is not { } installReceipt ||
            installReceipt.Authority != contract.Authority)
        {
            return;
        }

        var nowMs = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
        var deadlineUtcMs = installReceipt.DispatchDeadlineUtcMs;
        if (deadlineUtcMs <= 0 ||
            state.DispatchDeadlineUtcMs != deadlineUtcMs)
        {
            return;
        }
        var delayMs = Math.Max(50L, deadlineUtcMs - nowMs + 50);
        var authority = contract.Authority;

        _ = Task.Run(
            async () =>
            {
                await Task.Delay(TimeSpan.FromMilliseconds(delayMs), CancellationToken.None)
                    .ConfigureAwait(false);
                RequestRuntimeUnlockRetryDispatchDeadlineEvaluation(
                    authority,
                    installReceipt);
            },
            CancellationToken.None);
    }

    private void RequestRuntimeUnlockRetryDispatchDeadlineEvaluation(
        RuntimeUnlockRetryDispatchAuthority authority,
        RuntimeUnlockRetryDispatchInstallReceipt installReceipt)
    {
        EventHandler<RuntimeUnlockRetryDispatchDeadlineEvaluationEventArgs>? subscriber;
        RuntimeUnlockRetryDispatchDeadlineEvaluation evaluation;
        lock (accelerationGate)
        {
            var state = runtimeUnlockRecoveryRetryState;
            if (state is null ||
                state.ContractState is SessionRecoveryContractState.Completed or SessionRecoveryContractState.Failed ||
                state.PendingDispatchSettlementReport is not null ||
                state.DispatchAuthorityRejected ||
                state.DispatchObserved ||
                !state.DispatchAuthorityGranted ||
                state.DispatchContract?.Authority != authority ||
                runtimeUnlockRetryDispatchInstallShadow.LastCommittedReceipt != installReceipt)
            {
                return;
            }

            evaluation = new RuntimeUnlockRetryDispatchDeadlineEvaluation(
                authority,
                installReceipt,
                DateTimeOffset.UtcNow.ToUnixTimeMilliseconds(),
                "runtime_unlock_retry_dispatch_deadline_elapsed");
            subscriber = runtimeUnlockRetryDispatchDeadlineEvaluationRequested;
        }

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=runtime_unlock_retry_dispatch_deadline_evaluation_requested; {FormatRuntimeUnlockRetryDispatchAuthorityTuple(authority)}; install_generation={installReceipt.InstallGeneration}; observed_utc_ms={evaluation.ObservedUtcMs}; subscriber_present={(subscriber is null ? 0 : 1)}; decision_reason={SanitizeLogToken(evaluation.Reason)}");
        if (subscriber is null)
        {
            return;
        }

        subscriber.Invoke(
            this,
            new RuntimeUnlockRetryDispatchDeadlineEvaluationEventArgs(evaluation));
    }

    private bool IsActiveRegularV4FileTransferRouteHint(string? sessionId, string? transferId)
        => IsActiveRegularV4FileTransferRouteHint(sessionId, transferId, null);

    private bool IsActiveRegularV4FileTransferRouteHint(
        string? sessionId,
        string? transferId,
        FileTransferDirection? direction)
    {
        var normalizedSessionId = string.IsNullOrWhiteSpace(sessionId) ? string.Empty : sessionId.Trim();
        var normalizedTransferId = string.IsNullOrWhiteSpace(transferId) ? string.Empty : transferId.Trim();
        if (string.IsNullOrWhiteSpace(normalizedSessionId) ||
            string.IsNullOrWhiteSpace(normalizedTransferId))
        {
            return false;
        }

        lock (gate)
        {
            if (!fileTransferDataSessions.TryGetValue(normalizedTransferId, out var session) ||
                session.IsDisposed ||
                !string.Equals(session.SessionId, normalizedSessionId, StringComparison.Ordinal))
            {
                return false;
            }

            FileTransferRouteHint routeHint;
            var routeHintFound = direction.HasValue
                ? TryGetFileTransferRouteHintUnsafe(normalizedSessionId, normalizedTransferId, direction.Value, out routeHint)
                : TryGetFileTransferRouteHintUnsafe(normalizedSessionId, normalizedTransferId, out routeHint);
            return !routeHintFound ||
                   routeHint.Route == FileTransferRoute.RegularNknV4Fast;
        }
    }

    private static bool TryGetRuntimeUnlockRetryCoordinatorBoundedClosureHistoryUnsafe(
        RuntimeUnlockRecoveryRetryState state,
        RuntimeUnlockRetryLifecycleBoundedClosure closure,
        out RuntimeUnlockRetryDispatchHistoricalSettlement history)
    {
        history = null!;
        if (closure.FinalAttempt.Settlement is not { } report ||
            closure.FinalAttempt.InstallReceipt is not { } installReceipt)
        {
            return false;
        }

        var authority = report.Authority;
        var rejectedRequest = closure.RejectedSuccessorRequest;
        if (closure.IsDefault ||
            closure.FinalAttempt.State != RuntimeUnlockRetryLifecycleAttemptState.Closed ||
            state.LastObservedCoordinatorBoundedClosure != closure ||
            state.ContractState != SessionRecoveryContractState.Failed ||
            !state.Settled ||
            !state.BrokenStateFinalized ||
            !string.Equals(
                state.BrokenStateFailureReason,
                closure.Reason,
                StringComparison.Ordinal) ||
            state.LastAppliedDispatchSettlementReport != report ||
            state.LastAppliedDispatchSettlementDecisionStatus is not (
                RuntimeUnlockRetryDispatchSettlementDecisionStatus.Accepted or
                RuntimeUnlockRetryDispatchSettlementDecisionStatus.Idempotent) ||
            report.Outcome != RuntimeUnlockRetryDispatchSettlementOutcome.MissingDispatch ||
            !string.Equals(
                closure.Reason,
                "retry_dispatch_missing_successor_limit_exhausted",
                StringComparison.Ordinal) ||
            installReceipt.InstallGeneration <= 0 ||
            installReceipt.Authority != authority ||
            closure.FinalAttempt.Authority != authority ||
            installReceipt.Request.IsDefault ||
            !FileTransferCoordinator.TryValidateRuntimeUnlockRetryDispatchBinding(
                authority,
                installReceipt.Request,
                out _) ||
            rejectedRequest.IsDefault ||
            rejectedRequest.PredecessorAuthorityId != authority.AuthorityId ||
            rejectedRequest.RecoveryContractGeneration != authority.RecoveryContractGeneration ||
            rejectedRequest.RetiredOfferGeneration != closure.FinalAttempt.OfferGeneration ||
            rejectedRequest.DispatchAttemptGeneration !=
                authority.DispatchAttemptGeneration + 1 ||
            rejectedRequest.MissingDispatchSuccessorGeneration !=
                authority.MissingDispatchSuccessorGeneration + 1 ||
            rejectedRequest.RequestActivePredecessorSupersession ||
            rejectedRequest.SourcePublicationAuthority != installReceipt.Request.SourcePublicationAuthority ||
            closure.FinalAttempt.OfferGeneration <= 0 ||
            string.IsNullOrWhiteSpace(closure.FinalAttempt.OfferNonce) ||
            state.SourceDataSessionGeneration <= 0 ||
            state.DispatchContract is not null ||
            state.DispatchPredecessorContract is not null ||
            state.PendingDispatchAuthorityRequest is not null)
        {
            return false;
        }

        history = new RuntimeUnlockRetryDispatchHistoricalSettlement(
            report,
            state.LastAppliedDispatchSettlementDecisionStatus!.Value,
            SanitizeLogToken(
                state.LastAppliedDispatchSettlementDecisionReason ??
                "retry_dispatch_settlement_accepted"),
            authority.RecoveryContractGeneration,
            DateTimeOffset.UtcNow.ToUnixTimeMilliseconds());
        return true;
    }

    private bool TryRequestFileTransferTunaActivationOfferSendRecovery(
        string purpose,
        string? activationSessionId,
        string trigger,
        RuntimeUnlockOfferAuthorityBoundary? expectedOfferAuthorityBoundary,
        out string? recoveryReason,
        out string? recoverySessionId)
    {
        recoveryReason = null;
        recoverySessionId = null;
        if (!IsTunaActivationOfferSendPurpose(purpose))
        {
            return false;
        }

        if (expectedOfferAuthorityBoundary is not
                { Mode: RuntimeUnlockOfferAuthorityMode.InstalledRetry } ||
            !ValidateRuntimeUnlockOfferAuthorityBoundary(
                expectedOfferAuthorityBoundary,
                "offer_send_recovery_request_entry",
                allowDispatchObservedSettlement: true))
        {
            return false;
        }

        bool ValidateInstalledRetryBoundary(string boundary)
            => ValidateRuntimeUnlockOfferAuthorityBoundary(
                expectedOfferAuthorityBoundary,
                boundary,
                allowDispatchObservedSettlement: true);

        var hasActivationPause = TryGetActiveFileTransferTunaActivationPause(activationSessionId, out var sessionId);
        var postTunaFallbackOfferRecovery = false;
        var regularV4RuntimeUnlockOfferRecovery = false;
        var activeFileTransferRuntimeUnlockOfferRecovery = false;
        var answerTimeoutRuntimeUnlockOfferRecovery = false;
        var peerResponseTimeoutRuntimeUnlockOfferRecovery = false;
        if (!hasActivationPause)
        {
            postTunaFallbackOfferRecovery =
                TryGetPostTunaFallbackRuntimeUnlockOfferRecoverySession(activationSessionId, out sessionId);
        }

        if (!hasActivationPause &&
            !postTunaFallbackOfferRecovery)
        {
            regularV4RuntimeUnlockOfferRecovery =
                TryGetRegularV4RuntimeUnlockOfferRecoverySession(activationSessionId, out sessionId);
        }

        if (!hasActivationPause &&
            !postTunaFallbackOfferRecovery &&
            !regularV4RuntimeUnlockOfferRecovery)
        {
            activeFileTransferRuntimeUnlockOfferRecovery =
                TryGetRuntimeUnlockOfferActiveFileTransferRecoverySession(activationSessionId, out sessionId);
        }

        if (!hasActivationPause &&
            !postTunaFallbackOfferRecovery &&
            !regularV4RuntimeUnlockOfferRecovery &&
            !activeFileTransferRuntimeUnlockOfferRecovery &&
            string.Equals(purpose, "offer_answer", StringComparison.OrdinalIgnoreCase))
        {
            sessionId = string.IsNullOrWhiteSpace(activationSessionId)
                ? currentSessionSecurityState.SessionId?.Value
                : activationSessionId.Trim();
            answerTimeoutRuntimeUnlockOfferRecovery =
                !string.IsNullOrWhiteSpace(sessionId) &&
                (HasActiveRegularV4FileTransferRouteHint(sessionId) ||
                 HasActivePostTunaFallbackFileTransferRouteHint(sessionId) ||
                 HasActiveFileTransferDataSessionForSession(sessionId));
        }

        if (!hasActivationPause &&
            !postTunaFallbackOfferRecovery &&
            !regularV4RuntimeUnlockOfferRecovery &&
            !activeFileTransferRuntimeUnlockOfferRecovery &&
            !answerTimeoutRuntimeUnlockOfferRecovery &&
            string.Equals(purpose, "offer_peer_response", StringComparison.OrdinalIgnoreCase))
        {
            sessionId = string.IsNullOrWhiteSpace(activationSessionId)
                ? currentSessionSecurityState.SessionId?.Value
                : activationSessionId.Trim();
            peerResponseTimeoutRuntimeUnlockOfferRecovery =
                !string.IsNullOrWhiteSpace(sessionId) &&
                (HasActiveRegularV4FileTransferRouteHint(sessionId) ||
                 HasActivePostTunaFallbackFileTransferRouteHint(sessionId) ||
                 HasActiveFileTransferDataSessionForSession(sessionId));
        }

        if (!hasActivationPause &&
            !postTunaFallbackOfferRecovery &&
            !regularV4RuntimeUnlockOfferRecovery &&
            !activeFileTransferRuntimeUnlockOfferRecovery &&
            !answerTimeoutRuntimeUnlockOfferRecovery &&
            !peerResponseTimeoutRuntimeUnlockOfferRecovery)
        {
            return false;
        }

        var normalizedPurpose = SanitizeLogToken(purpose);
        var reason =
            string.Equals(purpose, "offer_replay", StringComparison.OrdinalIgnoreCase)
                ? "tuna_activation_offer_replay_send_timeout"
                : string.Equals(purpose, "offer_answer", StringComparison.OrdinalIgnoreCase)
                    ? "tuna_activation_offer_answer_timeout"
                    : string.Equals(purpose, "offer_peer_response", StringComparison.OrdinalIgnoreCase)
                        ? "tuna_activation_offer_peer_response_timeout"
                        : "tuna_activation_offer_send_timeout";
        var bridgeRecoveryReason = reason;
        if (!ValidateInstalledRetryBoundary(
                "offer_send_recovery_before_authority_effects"))
        {
            return false;
        }

        if (postTunaFallbackOfferRecovery)
        {
            bridgeRecoveryReason = $"post_tuna_fallback_{reason}";
        }
        else if (regularV4RuntimeUnlockOfferRecovery &&
                 TryGetRuntimeUnlockRetryAuthorityForCurrentOffer(out _))
        {
            bridgeRecoveryReason = "runtime_unlock_retry_authority_offer_blocked";
            MarkRuntimeUnlockRecoveryContractAuthorityBlocked(
                bridgeRecoveryReason,
                expectedOfferAuthorityBoundary);
        }
        else if (answerTimeoutRuntimeUnlockOfferRecovery ||
                 peerResponseTimeoutRuntimeUnlockOfferRecovery)
        {
            bridgeRecoveryReason = "runtime_unlock_retry_authority_offer_blocked";
            MarkRuntimeUnlockRecoveryContractAuthorityBlocked(
                bridgeRecoveryReason,
                expectedOfferAuthorityBoundary);
        }

        recoveryReason = reason;
        recoverySessionId = sessionId;
        if (!ValidateInstalledRetryBoundary(
                "offer_send_recovery_before_request"))
        {
            recoveryReason = null;
            recoverySessionId = null;
            return false;
        }

        var accepted = RuntimeUnlockOfferSendRecoveryRequestOverrideForTests?.Invoke(this, reason, sessionId);
        if (accepted is null)
        {
            if (client is not RealNknClientAdapter)
            {
                LocalOperationalLog.Info(
                    "NKN.Tuna",
                    $"event=tuna_activation_control_send_recovery_request_unsupported; session_id={SanitizeLogToken(sessionId ?? "none")}; purpose={normalizedPurpose}; trigger={SanitizeLogToken(trigger)}; reason={SanitizeLogToken(reason)}");
                return false;
            }

            LocalOperationalLog.Warn(
                "NKN.Tuna",
                $"event=nkn_bridge_receive_stall_recovery_rejected_no_filetransfer_authority; session_id={SanitizeLogToken(sessionId ?? "none")}; transfer_id=runtime_unlock; direction=outbound; reason={SanitizeLogToken(bridgeRecoveryReason)}; rejection_reason=transport_callback_without_coordinator_authority; purpose={normalizedPurpose}; trigger={SanitizeLogToken(trigger)}");
            accepted = false;
        }

        LocalOperationalLog.Warn(
            "NKN.Tuna",
            $"event=tuna_activation_control_send_recovery_requested; session_id={SanitizeLogToken(sessionId ?? "none")}; purpose={normalizedPurpose}; trigger={SanitizeLogToken(trigger)}; reason={SanitizeLogToken(reason)}; bridge_reason={SanitizeLogToken(bridgeRecoveryReason)}; post_tuna_fallback_offer_recovery={(postTunaFallbackOfferRecovery ? 1 : 0)}; accepted={(accepted.Value ? 1 : 0)}");
        if (!accepted.Value &&
            ValidateInstalledRetryBoundary(
                "offer_send_recovery_before_existing_recovery_join") &&
            ShouldJoinExistingRegularV4ReceiveStallRecoveryForRuntimeUnlock(
                regularV4RuntimeUnlockOfferRecovery,
                activeFileTransferRuntimeUnlockOfferRecovery,
                answerTimeoutRuntimeUnlockOfferRecovery,
                peerResponseTimeoutRuntimeUnlockOfferRecovery,
                sessionId))
        {
            if (!MarkFileTransferTunaActivationBridgeRecoveryStarted(
                    reason,
                    expectedOfferAuthorityBoundary))
            {
                return false;
            }
            LocalOperationalLog.Warn(
                "NKN.Tuna",
                $"event=tuna_activation_control_send_recovery_joined_existing; session_id={SanitizeLogToken(sessionId ?? "none")}; purpose={normalizedPurpose}; trigger={SanitizeLogToken(trigger)}; reason={SanitizeLogToken(reason)}; existing_recovery=1; join_reason=regular_v4_receive_stall_recovery_in_progress");
            return true;
        }

        if (!accepted.Value &&
            ValidateInstalledRetryBoundary(
                "offer_send_recovery_before_activation_recovery_join") &&
            ShouldJoinExistingFileTransferTunaActivationOfferSendRecovery(
                hasActivationPause,
                regularV4RuntimeUnlockOfferRecovery,
                activeFileTransferRuntimeUnlockOfferRecovery,
                postTunaFallbackOfferRecovery,
                activationSessionId,
                sessionId,
                expectedOfferAuthorityBoundary!))
        {
            LocalOperationalLog.Warn(
                "NKN.Tuna",
                $"event=tuna_activation_control_send_recovery_joined_existing; session_id={SanitizeLogToken(sessionId ?? "none")}; purpose={normalizedPurpose}; trigger={SanitizeLogToken(trigger)}; reason={SanitizeLogToken(reason)}; existing_recovery=1");
            return true;
        }

        if (!accepted.Value)
        {
            return false;
        }

        if (!ValidateInstalledRetryBoundary(
                "offer_send_recovery_before_started"))
        {
            return false;
        }

        return MarkFileTransferTunaActivationBridgeRecoveryStarted(
            reason,
            expectedOfferAuthorityBoundary);
    }

    private bool ShouldJoinExistingRegularV4ReceiveStallRecoveryForRuntimeUnlock(
        bool regularV4RuntimeUnlockOfferRecovery,
        bool activeFileTransferRuntimeUnlockOfferRecovery,
        bool answerTimeoutRuntimeUnlockOfferRecovery,
        bool peerResponseTimeoutRuntimeUnlockOfferRecovery,
        string? sessionId)
    {
        if (!regularV4RuntimeUnlockOfferRecovery &&
            !activeFileTransferRuntimeUnlockOfferRecovery &&
            !answerTimeoutRuntimeUnlockOfferRecovery &&
            !peerResponseTimeoutRuntimeUnlockOfferRecovery)
        {
            return false;
        }

        if (string.IsNullOrWhiteSpace(sessionId) ||
            !HasActiveRegularV4FileTransferRouteHint(sessionId))
        {
            return false;
        }

        return client is RealNknClientAdapter realClient &&
               realClient.TryGetFileTransferRegularV4ActivationSendBlocker(
                   out var blockerReason,
                   out _,
                   includeRegularV4Pressure: false) &&
               IsReceiveStallRecoveryInProgressActivationSendBlocker(blockerReason);
    }

    private bool ShouldJoinExistingFileTransferTunaActivationOfferSendRecovery(
        bool hasActivationPause,
        bool regularV4RuntimeUnlockOfferRecovery,
        bool activeFileTransferRuntimeUnlockOfferRecovery,
        bool postTunaFallbackOfferRecovery,
        string? activationSessionId,
        string? recoverySessionId,
        RuntimeUnlockOfferAuthorityBoundary expectedOfferAuthorityBoundary)
    {
        if (!IsFileTransferTunaActivationBridgeRecoveryActiveForBoundary(
                expectedOfferAuthorityBoundary))
        {
            return false;
        }

        if (hasActivationPause)
        {
            return true;
        }

        if (regularV4RuntimeUnlockOfferRecovery &&
            TryGetRegularV4RuntimeUnlockOfferRecoverySession(activationSessionId, out var regularSessionId))
        {
            return string.IsNullOrWhiteSpace(recoverySessionId) ||
                   string.Equals(regularSessionId, recoverySessionId, StringComparison.Ordinal);
        }

        if (activeFileTransferRuntimeUnlockOfferRecovery &&
            TryGetRuntimeUnlockOfferActiveFileTransferRecoverySession(activationSessionId, out var activeFileTransferSessionId))
        {
            return string.IsNullOrWhiteSpace(recoverySessionId) ||
                   string.Equals(activeFileTransferSessionId, recoverySessionId, StringComparison.Ordinal);
        }

        if (postTunaFallbackOfferRecovery)
        {
            var postTunaFallbackSessionId = string.IsNullOrWhiteSpace(activationSessionId)
                ? currentSessionSecurityState.SessionId?.Value
                : activationSessionId.Trim();
            return string.IsNullOrWhiteSpace(recoverySessionId) ||
                   string.Equals(postTunaFallbackSessionId, recoverySessionId, StringComparison.Ordinal);
        }

        if (!TryGetActivePostTunaFallbackRuntimeUnlockOfferRecoverySession(activationSessionId, out var activeSessionId) &&
            !TryGetPostTunaFallbackRuntimeUnlockOfferRecoverySession(activationSessionId, out activeSessionId))
        {
            return false;
        }

        return string.IsNullOrWhiteSpace(recoverySessionId) ||
               string.Equals(activeSessionId, recoverySessionId, StringComparison.Ordinal);
    }

    private bool IsFileTransferTunaActivationBridgeRecoveryActiveForBoundary(
        RuntimeUnlockOfferAuthorityBoundary expectedOfferAuthorityBoundary)
    {
        lock (accelerationBridgeRecoveryGate)
        {
            return fileTransferTunaActivationBridgeRecoveryActive != 0 &&
                   fileTransferTunaActivationBridgeRecoveryOfferAuthorityBoundary ==
                       expectedOfferAuthorityBoundary;
        }
    }

    private bool TryGetActivePostTunaFallbackRuntimeUnlockOfferRecoverySession(
        string? requestedSessionId,
        out string? sessionId)
    {
        sessionId = string.IsNullOrWhiteSpace(requestedSessionId)
            ? currentSessionSecurityState.SessionId?.Value
            : requestedSessionId.Trim();
        if (string.IsNullOrWhiteSpace(sessionId) ||
            !IsCurrentRuntimeUnlockActivationOffer())
        {
            return false;
        }

        lock (accelerationGate)
        {
            if (string.IsNullOrWhiteSpace(outboundAccelerationOfferNonce) ||
                !TryGetCurrentRuntimeUnlockOfferAuthorityBoundaryUnsafe(out _, out _) ||
                IsAccelerationNegotiatedAndHealthyUnsafe(sessionId))
            {
                return false;
            }
        }

        return TryGetUnresolvedFileTransferV6TransportEpochForCurrentSession(out var pendingEpoch) &&
               IsPostTunaFallbackRegularNknEpoch(pendingEpoch) &&
               TryGetEffectiveFallbackPairedTailYieldInstallReceipt(
                   pendingEpoch.SessionId,
                   pendingEpoch.TransferId,
                   pendingEpoch.Direction,
                   out _);
    }

    private bool TryGetPostTunaFallbackRuntimeUnlockOfferRecoverySession(
        string? requestedSessionId,
        out string? sessionId)
    {
        sessionId = string.IsNullOrWhiteSpace(requestedSessionId)
            ? currentSessionSecurityState.SessionId?.Value
            : requestedSessionId.Trim();
        if (string.IsNullOrWhiteSpace(sessionId) ||
            !IsCurrentRuntimeUnlockActivationOffer())
        {
            return false;
        }

        lock (accelerationGate)
        {
            if (string.IsNullOrWhiteSpace(outboundAccelerationOfferNonce) ||
                !TryGetCurrentRuntimeUnlockOfferAuthorityBoundaryUnsafe(out _, out _) ||
                IsAccelerationNegotiatedAndHealthyUnsafe(sessionId))
            {
                return false;
            }
        }

        if (TryGetUnresolvedFileTransferV6TransportEpochForCurrentSession(out var pendingEpoch) &&
            IsPostTunaFallbackRegularNknEpoch(pendingEpoch))
        {
            return true;
        }

        return HasActivePostTunaFallbackFileTransferRouteHint(sessionId);
    }

    private bool TryGetRuntimeUnlockOfferActiveFileTransferRecoverySession(
        string? requestedSessionId,
        out string? sessionId)
    {
        sessionId = string.IsNullOrWhiteSpace(requestedSessionId)
            ? currentSessionSecurityState.SessionId?.Value
            : requestedSessionId.Trim();
        if (string.IsNullOrWhiteSpace(sessionId) ||
            !IsCurrentRuntimeUnlockActivationOffer())
        {
            return false;
        }

        lock (accelerationGate)
        {
            if (string.IsNullOrWhiteSpace(outboundAccelerationOfferNonce) ||
                !TryGetCurrentRuntimeUnlockOfferAuthorityBoundaryUnsafe(out _, out _) ||
                IsAccelerationNegotiatedAndHealthyUnsafe(sessionId))
            {
                return false;
            }
        }

        lock (gate)
        {
            foreach (var session in fileTransferDataSessions.Values)
            {
                if (!session.IsDisposed &&
                    string.Equals(session.SessionId, sessionId, StringComparison.Ordinal))
                {
                    return true;
                }
            }
        }

        return client is RealNknClientAdapter realClient &&
               realClient.HasActiveFileTransferRuntimeForActivationSend();
    }

    private bool TryGetRegularV4RuntimeUnlockOfferRecoverySession(
        string? requestedSessionId,
        out string? sessionId)
    {
        sessionId = string.IsNullOrWhiteSpace(requestedSessionId)
            ? currentSessionSecurityState.SessionId?.Value
            : requestedSessionId.Trim();
        if (string.IsNullOrWhiteSpace(sessionId) ||
            !IsCurrentRuntimeUnlockActivationOffer())
        {
            return false;
        }

        lock (accelerationGate)
        {
            if (string.IsNullOrWhiteSpace(outboundAccelerationOfferNonce) ||
                !TryGetCurrentRuntimeUnlockOfferAuthorityBoundaryUnsafe(out _, out _) ||
                IsAccelerationNegotiatedAndHealthyUnsafe(sessionId))
            {
                return false;
            }
        }

        if (!HasActiveRegularV4FileTransferRouteHint(sessionId))
        {
            return false;
        }

        if (RuntimeUnlockOfferQueueAcceptedPressureOverrideForTests?.Invoke(this) == true)
        {
            return true;
        }

        return client is RealNknClientAdapter realClient &&
               realClient.TryGetFileTransferRegularV4ActivationSendBlocker(out var blockerReason, out _) &&
               (IsRegularV4PressureActivationSendBlocker(blockerReason) ||
                IsReceiveStallActivationSendBlocker(blockerReason));
    }

    private bool HasActiveRegularV4FileTransferRouteHint(string sessionId)
    {
        lock (gate)
        {
            foreach (var session in fileTransferDataSessions.Values)
            {
                if (session.IsDisposed ||
                    !string.Equals(session.SessionId, sessionId, StringComparison.Ordinal))
                {
                    continue;
                }

                if (!TryGetFileTransferRouteHintUnsafe(session.SessionId, session.TransferId, out var routeHint))
                {
                    return true;
                }

                if (routeHint.Route == FileTransferRoute.RegularNknV4Fast)
                {
                    return true;
                }
            }
        }

        return false;
    }

    private bool HasActiveFileTunaV4FileTransferRouteHint(string? sessionId)
    {
        return TryGetLatestFileTransferRouteHintForSession(sessionId, out var routeHint) &&
               routeHint.Route == FileTransferRoute.FileTunaV4;
    }

    private bool HasAuthorizedRegularV4FileTransferRouteHint(string? sessionId)
    {
        return TryGetLatestFileTransferRouteHintForSession(sessionId, out var routeHint) &&
               routeHint.Route == FileTransferRoute.RegularNknV4Fast &&
               routeHint.ProtocolVersion == FileTransferProtocol.ProtocolVersionV4;
    }

    private bool HasAuthorizedRegularV4FileTransferRouteHint(
        string? sessionId,
        string? transferId,
        FileTransferDirection direction)
    {
        var normalizedSessionId = string.IsNullOrWhiteSpace(sessionId) ? string.Empty : sessionId.Trim();
        var normalizedTransferId = string.IsNullOrWhiteSpace(transferId) ? string.Empty : transferId.Trim();
        if (string.IsNullOrWhiteSpace(normalizedSessionId) ||
            string.IsNullOrWhiteSpace(normalizedTransferId))
        {
            return false;
        }

        lock (gate)
        {
            return TryGetFileTransferRouteHintUnsafe(
                       normalizedSessionId,
                       normalizedTransferId,
                       direction,
                       out var routeHint) &&
                   routeHint.Route == FileTransferRoute.RegularNknV4Fast &&
                   routeHint.ProtocolVersion == FileTransferProtocol.ProtocolVersionV4;
        }
    }

    private bool TryGetLatestFileTransferRouteHintForSession(
        string? sessionId,
        out FileTransferRouteHint routeHint)
    {
        routeHint = default;
        if (string.IsNullOrWhiteSpace(sessionId))
        {
            return false;
        }

        var normalizedSessionId = sessionId.Trim();
        var found = false;
        lock (gate)
        {
            foreach (var candidate in fileTransferRouteHints.Values)
            {
                if (!string.Equals(candidate.SessionId, normalizedSessionId, StringComparison.Ordinal))
                {
                    continue;
                }

                if (!found ||
                    candidate.RecordedUtc > routeHint.RecordedUtc ||
                    (candidate.RecordedUtc == routeHint.RecordedUtc &&
                     candidate.RoutePublicationGeneration > routeHint.RoutePublicationGeneration))
                {
                    routeHint = candidate;
                    found = true;
                }
            }
        }

        return found;
    }

    private static bool IsRegularV4PressureActivationSendBlocker(string? reason)
        => string.Equals(reason, "regular_v4_activation_send_pressure", StringComparison.OrdinalIgnoreCase) ||
           string.Equals(reason, "regular_v4_control_feedback_pressure", StringComparison.OrdinalIgnoreCase);

    private static bool IsReceiveStallActivationSendBlocker(string? reason)
        => string.Equals(reason, "receive_stall_recovery_in_progress", StringComparison.OrdinalIgnoreCase) ||
           string.Equals(reason, "receive_stall_recovery_awaiting_receive_proof", StringComparison.OrdinalIgnoreCase);

    private static bool IsReceiveStallRecoveryInProgressActivationSendBlocker(string? reason)
        => string.Equals(reason, "receive_stall_recovery_in_progress", StringComparison.OrdinalIgnoreCase);

    private static bool ShouldDeferRuntimeUnlockSoftSettleForReceiveStallBlocker(string? reason, long remainingMs)
        => IsReceiveStallActivationSendBlocker(reason) && remainingMs > 0;

    private static bool ShouldBypassRuntimeUnlockReceiveStallAfterBoundedWait(string? reason)
        => string.Equals(reason, "receive_stall_recovery_awaiting_receive_proof", StringComparison.OrdinalIgnoreCase);

    private static string FormatElapsedMilliseconds(long startedTick)
    {
        if (startedTick <= 0)
        {
            return "-1";
        }

        return Math.Max(0, (long)Stopwatch.GetElapsedTime(startedTick).TotalMilliseconds)
            .ToString(CultureInfo.InvariantCulture);
    }

    private void ScheduleFileTransferTunaActivationPauseExpiryObservation(
        string sessionId,
        long generation)
    {
        _ = Task.Run(
            async () =>
            {
                try
                {
                    await Task.Delay(FileTransferTunaActivationPauseMax, CancellationToken.None).ConfigureAwait(false);
                    var observationCurrent = false;
                    lock (accelerationGate)
                    {
                        observationCurrent =
                            generation == fileTransferTunaActivationPauseGeneration &&
                            string.Equals(fileTransferTunaActivationPauseSessionId, sessionId, StringComparison.Ordinal) &&
                            !IsAccelerationNegotiatedAndHealthyUnsafe(sessionId);
                    }

                    if (observationCurrent)
                    {
                        LocalOperationalLog.Warn(
                            "NKN.Tuna",
                            $"event=filetransfer_tuna_activation_negotiation_pause_expiry_observed; session_id={SanitizeLogToken(sessionId)}; pause_generation={generation}; reason=tuna_activation_negotiation_pause_expired; authority_effect=none");
                    }
                }
                catch (Exception ex) when (ex is not OperationCanceledException)
                {
                    LocalOperationalLog.Warn(
                        "NKN.Tuna",
                        $"event=filetransfer_tuna_activation_negotiation_pause_expiry_observation_failed; session_id={SanitizeLogToken(sessionId)}; pause_generation={generation}; error={ex.GetType().Name}");
                }
            },
            CancellationToken.None);
    }

    private bool IsAccelerationNegotiatedAndHealthyUnsafe(string? sessionId)
        => accelerationLane?.IsAvailable == true &&
           accelerationNegotiatedLanes != NknAccelerationLaneKind.None &&
           !string.IsNullOrWhiteSpace(accelerationSessionId) &&
           string.Equals(accelerationSessionId, sessionId, StringComparison.Ordinal);

    private void RebindScreenShareDataSessionsForTunaFallback(
        string reason,
        string? sessionId,
        NknAccelerationLaneKind lanes)
    {
        if ((lanes & NknAccelerationLaneKind.Screen) != NknAccelerationLaneKind.Screen ||
            string.IsNullOrWhiteSpace(sessionId))
        {
            return;
        }

        var normalizedReason = SanitizeLogToken(reason);
        MarkTunaFallbackLaneState(
            sessionId,
            lane: NknAccelerationLaneKind.Screen,
            state: TunaFallbackLaneState.Pending,
            reason: normalizedReason);
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=screenshare_tuna_handoff_started; session_id={sessionId}; reason={normalizedReason}; lanes={FormatAccelerationLanesForLog(lanes)}");
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=tuna_disable_handoff_screen_started; session_id={sessionId}; reason={normalizedReason}; lanes={FormatAccelerationLanesForLog(lanes)}");
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=tuna_disable_handoff_media_pending; session_id={sessionId}; reason={normalizedReason}; lanes={FormatAccelerationLanesForLog(lanes)}");
        ScheduleScreenTunaHandoffWaitingMarker(sessionId, normalizedReason);
    }

    private void CompleteTunaFallbackProof(string reason)
    {
        TunaFallbackProofState? state;
        var normalizedReason = SanitizeLogToken(reason);
        var deferredPendingFileRoute = false;
        lock (accelerationGate)
        {
            state = tunaFallbackProofState;
            if (state is not null &&
                ShouldDeferTunaFallbackProofCompletionForPendingFileRouteUnsafe(state, normalizedReason))
            {
                deferredPendingFileRoute = true;
            }
            else
            {
                tunaFallbackProofState = null;
            }
        }

        if (state is null)
        {
            return;
        }

        var elapsedMs = Math.Max(0, (long)(DateTimeOffset.UtcNow - state.StartedUtc).TotalMilliseconds);
        if (deferredPendingFileRoute)
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=tuna_fallback_summary_deferred; session_id={state.SessionId}; fallback_epoch={state.Epoch}; reason={state.Reason}; deferred_reason={normalizedReason}; elapsed_ms={elapsedMs}; lanes={FormatAccelerationLanesForLog(state.Lanes)}; screen_state={FormatTunaFallbackLaneState(state.ScreenState)}; file_state={FormatTunaFallbackLaneState(state.FileState)}; file_v6_epoch_state={FormatTunaFallbackFileV6EpochState(state)}; file_v6_transport_epoch={state.FileV6TransportEpoch}; pending_file_route=1");
            return;
        }

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=tuna_fallback_summary; session_id={state.SessionId}; fallback_epoch={state.Epoch}; reason={state.Reason}; completed_reason={normalizedReason}; elapsed_ms={elapsedMs}; lanes={FormatAccelerationLanesForLog(state.Lanes)}; screen_state={FormatTunaFallbackLaneState(state.ScreenState)}; file_state={FormatTunaFallbackLaneState(state.FileState)}; screen_nkn_frames_sent={state.ScreenNknFramesSent}; screen_nkn_frames_received={state.ScreenNknFramesReceived}; screen_frames_applied={state.ScreenFramesApplied}; file_nkn_frames_sent={state.FileNknFramesSent}; file_nkn_frames_received={state.FileNknFramesReceived}; control_nkn_messages_sent={state.ControlNknMessagesSent}; acceleration_used_after_fallback={(state.AccelerationUsedAfterFallback ? 1 : 0)}");
        if (IsMixedFallbackLaneSet(state.Lanes))
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=tuna_mixed_handoff_summary; session_id={state.SessionId}; fallback_epoch={state.Epoch}; reason={state.Reason}; completed_reason={normalizedReason}; elapsed_ms={elapsedMs}; screen_state={FormatTunaFallbackLaneState(state.ScreenState)}; file_state={FormatTunaFallbackLaneState(state.FileState)}; screen_frames_applied={state.ScreenFramesApplied}; file_nkn_frames_sent={state.FileNknFramesSent}; file_nkn_frames_received={state.FileNknFramesReceived}; control_nkn_messages_sent={state.ControlNknMessagesSent}");
        }

        NotifyTransportAccelerationStateChanged(reason);
    }

    private bool ShouldDeferTunaFallbackProofCompletionForPendingFileRouteUnsafe(
        TunaFallbackProofState state,
        string normalizedReason)
    {
        if ((state.Lanes & NknAccelerationLaneKind.File) != NknAccelerationLaneKind.File ||
            state.FileState is TunaFallbackLaneState.None or TunaFallbackLaneState.Recovered ||
            IsFinalTunaFallbackProofCompletionReason(normalizedReason))
        {
            return false;
        }

        return IsUserRequestedAccelerationStopReason(normalizedReason) ||
               IsRemoteUserRequestedAccelerationStopReason(normalizedReason) ||
               (!string.IsNullOrWhiteSpace(state.SessionId) &&
                (string.Equals(accelerationUserStoppedSessionId, state.SessionId, StringComparison.Ordinal) ||
                 string.Equals(accelerationPeerUserStoppedSessionId, state.SessionId, StringComparison.Ordinal)));
    }

    private static bool IsFinalTunaFallbackProofCompletionReason(string normalizedReason)
        => normalizedReason is "tuna_activation_started" or
            "dispose" or
            "disposed" or
            "reset_session_tracking" or
            "session_security_state_not_eligible";

    private string ResolveFileRouteAfterPostTunaFallbackClearedForLog()
        => FileTransferRouteResolver.Resolve(new FileTransferRouteResolverInput(
            IsFileTunaActive: IsFileTransferAccelerationPublishedAndHealthy(),
            IsPostTunaFileFallbackActive: false,
            IsDiagnosticRegularNknV6RouteEnabled: IsDiagnosticRegularNknV6RouteEnabledCore(),
            HandoffKind: FileTransferTransportHandoffKind.None,
            TransportProfileKind: FileTransferTransportProfileKind.Default)).TelemetryToken;

    private void MarkTunaFallbackAccelerationUsedAfterProof()
    {
        lock (accelerationGate)
        {
            if (tunaFallbackProofState is { } state)
            {
                state.AccelerationUsedAfterFallback = true;
            }
        }
    }

    private void RecordTunaFallbackNknFrameSent(MsgType messageType, NknBridgeChannel channel, int payloadBytes)
        => RecordTunaFallbackNknFrame(
            direction: "sent",
            messageType,
            channel,
            payloadBytes,
            currentSessionSecurityState.SessionId?.Value);

    private void RecordTunaFallbackNknFrameReceived(MsgType messageType, NknBridgeChannel channel, int payloadBytes, string? sessionId)
    {
        if (handlingTunaAcceleratedInboundMessage)
        {
            return;
        }

        RecordTunaFallbackNknFrame("received", messageType, channel, payloadBytes, sessionId);
    }

    private void RecordTunaFallbackFileTransferDataFrameSent(
        ReadOnlySpan<byte> payload,
        NknBridgeChannel channel,
        int payloadBytes,
        string? sessionId)
    {
        RecordTunaFallbackNknFrame("sent", MsgType.FileTransferDataFrame, channel, payloadBytes, sessionId);
        if (!TryDeserializeFileTransferDataFrameFromWire(payload, out var frame) ||
            frame is null)
        {
            return;
        }

        if (!IsFileTransferFallbackNknProofPending() ||
            !TryMapPostTunaFileTransferFallbackNknProofKind(frame, "sent", out var proofKind))
        {
            return;
        }

        _ = CompleteFileTransferFallbackNknProofIfPending(proofKind, sessionId);
    }

    private void RecordTunaFallbackFileTransferDataFrameReceived(FileTransferDataFrame frame, NknBridgeChannel channel, int payloadBytes, string? sessionId)
    {
        if (handlingTunaAcceleratedInboundMessage)
        {
            return;
        }

        RecordTunaFallbackNknFrame("received", MsgType.FileTransferDataFrame, channel, payloadBytes, sessionId);
        if (TryMapFileTransferFallbackNknProofKind(frame, out var proofKind))
        {
            _ = CompleteFileTransferFallbackNknProofIfPending(proofKind, sessionId, frame);
        }
    }

    private void RecordTunaFallbackNknControlSent(MsgType messageType)
    {
        if (messageType is MsgType.ScreenShareFrame or MsgType.FileTransferDataFrame)
        {
            return;
        }

        lock (accelerationGate)
        {
            if (TryGetCurrentTunaFallbackProofStateUnsafe(currentSessionSecurityState.SessionId?.Value, out var state))
            {
                state.ControlNknMessagesSent++;
            }
        }
    }

    private void RecordTunaFallbackNknControlReceived(MsgType messageType, string? sessionId, int payloadBytes = 0)
    {
        if (messageType is MsgType.ScreenShareFrame or MsgType.FileTransferDataFrame)
        {
            return;
        }

        _ = CompleteFileTransferFallbackNknProofIfPending(
            $"nkn_control_{MapSecureMessageTypeForProof(messageType)}_received",
            sessionId);
    }

    private void RecordTunaFallbackNknFrame(
        string direction,
        MsgType messageType,
        NknBridgeChannel channel,
        int payloadBytes,
        string? sessionId)
    {
        if (!IsTunaFallbackProofFrame(messageType, channel))
        {
            return;
        }

        TunaFallbackProofState? snapshot;
        bool shouldLog;
        bool shouldLogScreenHandoffFrame = false;
        lock (accelerationGate)
        {
            if (!TryGetCurrentTunaFallbackProofStateUnsafe(sessionId, out var state))
            {
                shouldLog = false;
                snapshot = null;
            }
            else
            {
                if (direction == "sent")
                {
                    if (messageType == MsgType.ScreenShareFrame)
                    {
                        state.ScreenNknFramesSent++;
                    }
                    else
                    {
                        state.FileNknFramesSent++;
                    }
                }
                else
                {
                    if (messageType == MsgType.ScreenShareFrame)
                    {
                        state.ScreenNknFramesReceived++;
                    }
                    else
                    {
                        state.FileNknFramesReceived++;
                    }
                }

                if (messageType == MsgType.ScreenShareFrame)
                {
                    shouldLogScreenHandoffFrame = true;
                    if (state.ScreenState is TunaFallbackLaneState.Pending or TunaFallbackLaneState.WaitingForRegularNkn)
                    {
                        state.ScreenState = TunaFallbackLaneState.MediaReady;
                    }
                }

                shouldLog = ShouldLogTunaFallbackProofMarkerUnsafe(state, $"{direction}:{messageType}:{channel}", DateTimeOffset.UtcNow);
                snapshot = state;
            }
        }

        if (shouldLog && snapshot is not null)
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=tuna_fallback_nkn_frame_{direction}; message_type={MapTunaFallbackProofMessageType(messageType)}; channel={MapBridgeChannel(channel)}; session_id={snapshot.SessionId}; fallback_epoch={snapshot.Epoch}; payload_bytes={Math.Max(0, payloadBytes)}; reason={snapshot.Reason}");
            if (shouldLogScreenHandoffFrame && messageType == MsgType.ScreenShareFrame)
            {
                LocalOperationalLog.Info(
                    "NKN.Tuna",
                    $"event=screenshare_tuna_handoff_nkn_frame_{direction}; session_id={snapshot.SessionId}; fallback_epoch={snapshot.Epoch}; payload_bytes={Math.Max(0, payloadBytes)}; reason={snapshot.Reason}");
                LocalOperationalLog.Info(
                    "NKN.Tuna",
                    $"event=tuna_disable_handoff_media_ready; session_id={snapshot.SessionId}; reason={snapshot.Reason}; proof=screen_nkn_frame_{direction}; lanes={FormatAccelerationLanesForLog(snapshot.Lanes)}");
                LogMixedFallbackLaneState(snapshot, "screen_media_ready");
            }
        }
    }

    private void MarkFileTransferFallbackNknProofPending(
        string reason,
        string? sessionId,
        NknAccelerationLaneKind lanes,
        FileTransferReceiveRecoveryRequest? authorityRequest = null)
    {
        if ((lanes & NknAccelerationLaneKind.File) != NknAccelerationLaneKind.File)
        {
            return;
        }

        var normalizedReason = SanitizeLogToken(reason);
        var normalizedSessionId = string.IsNullOrWhiteSpace(sessionId)
            ? currentSessionSecurityState.SessionId?.Value
            : sessionId.Trim();
        RuntimeUnlockRouteCommitSnapshot? acceptedPreCommitSnapshot;
        lock (accelerationGate)
        {
            acceptedPreCommitSnapshot = runtimeUnlockAcceptedPreCommitSnapshot;
        }

        lock (fileTransferFallbackProofGate)
        {
            fileTransferFallbackProofPending = true;
            fileTransferFallbackProofReason = normalizedReason;
            fileTransferFallbackProofSessionId = normalizedSessionId;
            fileTransferFallbackProofLanes = lanes;
            fileTransferFallbackProofGeneration++;
            fileTransferFallbackProofProbeScheduled = false;
            fileTransferFallbackBulkProofObserved = false;
            fileTransferFallbackControlProofObserved = false;
            fileTransferFallbackProofTransferId = authorityRequest?.TransferId;
            fileTransferFallbackProofDirection = authorityRequest?.Direction;
            fileTransferFallbackProofRouteToken = authorityRequest?.RouteToken;
            fileTransferFallbackProofProtocolVersion = authorityRequest?.ProtocolVersion ?? 0;
            fileTransferFallbackProofLiveRouteEpoch = authorityRequest?.LiveRouteEpoch ?? 0;
            fileTransferFallbackProofLegGeneration = authorityRequest?.TransferLegGeneration ?? 0;
            fileTransferFallbackProofBridgeRecoveryGeneration = authorityRequest?.BridgeRecoveryGeneration ?? 0;
            fileTransferFallbackProofTransportEpoch = authorityRequest?.TransportEpoch ?? 0;
            fileTransferFallbackProofCheckpointRequestId = authorityRequest?.CheckpointRequestId;
            fileTransferFallbackProofAuthorityReason = authorityRequest?.AuthorityReason;
            fileTransferFallbackProofPreCommitSnapshot = acceptedPreCommitSnapshot;
        }

        var authorityFields = authorityRequest is null
            ? string.Empty
            : FormatFileTransferFallbackLegAuthorityFields(authorityRequest);
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=filetransfer_fallback_nkn_proof_pending; session_id={SanitizeLogToken(normalizedSessionId ?? "none")}; reason={normalizedReason}; lanes={FormatAccelerationLanesForLog(lanes)}{authorityFields}");
    }

    private bool ShouldUseFileTransferV6EpochForRegularNknRecovery(string? sessionId)
    {
        if (!HasActiveFileTransferDataSessionsForRecovery())
        {
            return false;
        }

        lock (accelerationGate)
        {
            if (TryGetCurrentTunaFallbackProofStateUnsafe(sessionId, out var state) &&
                (state.Lanes & NknAccelerationLaneKind.File) == NknAccelerationLaneKind.File &&
                state.FileState != TunaFallbackLaneState.Recovered)
            {
                return true;
            }
        }

        if (string.IsNullOrWhiteSpace(sessionId))
        {
            return false;
        }

        lock (fileTransferV6TransportEpochGate)
        {
            return fileTransferV6RegularNknEpochScopes.Values.Any(scope =>
                scope.CurrentRecoveredBoundary is { } recovered &&
                scope.LatestSnapshot is { State: V6TransportEpochState.Recovered } latest &&
                latest.TransportEpoch == recovered.TransportEpoch &&
                string.Equals(recovered.SessionId, sessionId.Trim(), StringComparison.Ordinal));
        }
    }

    private bool IsFileTransferFallbackNknProofPending()
    {
        lock (fileTransferFallbackProofGate)
        {
            return fileTransferFallbackProofPending;
        }
    }

    private void CompleteFileTransferFallbackProofUnsafe()
    {
        fileTransferFallbackProofPending = false;
        fileTransferFallbackProofReason = "none";
        fileTransferFallbackProofSessionId = null;
        fileTransferFallbackProofLanes = NknAccelerationLaneKind.None;
        fileTransferFallbackProofGeneration++;
        fileTransferFallbackProofProbeScheduled = false;
        fileTransferFallbackBulkProofObserved = false;
        fileTransferFallbackControlProofObserved = false;
        ClearFileTransferFallbackProofAuthorityUnsafe();
    }

    private bool TryCreatePostTunaFallbackAvailabilityProofEvidence(
        string sessionId,
        string transferId,
        long proofGeneration,
        string proofKind,
        string reason,
        PostTunaFallbackPeerProofFrameIdentity frameIdentity,
        RuntimeUnlockRouteCommitSnapshot? retainedPreCommitSnapshot,
        out PostTunaFallbackAvailabilityProofEvidence boundary,
        out string decisionReason)
    {
        boundary = null!;
        decisionReason = "accepted_precommit_scope_unavailable";
        TransportFileTransferDataSession? dataSession;
        lock (gate)
        {
            if (!fileTransferDataSessions.TryGetValue(transferId, out dataSession) ||
                dataSession.IsDisposed ||
                !string.Equals(dataSession.SessionId, sessionId, StringComparison.Ordinal))
            {
                decisionReason = "data_session_scope_unavailable";
                return false;
            }
        }

        RuntimeUnlockRouteCommitSnapshot snapshot = retainedPreCommitSnapshot!;
        if (snapshot is null &&
            !((IRuntimeUnlockRouteCommitProofProvider)this)
                .TryGetRuntimeUnlockRouteCommitProof(
                    dataSession.SessionId,
                    dataSession.TransferId,
                    out snapshot))
        {
            lock (accelerationGate)
            {
                snapshot = runtimeUnlockPreCommitProbeStartedSnapshot!;
                if (snapshot is null ||
                    !string.Equals(snapshot.SessionId, dataSession.SessionId, StringComparison.Ordinal) ||
                    !string.Equals(snapshot.TransferId, dataSession.TransferId, StringComparison.Ordinal) ||
                    !string.Equals(
                        snapshot.PathProbeState,
                        RuntimeUnlockPathProbeState.Acked.ToString(),
                        StringComparison.OrdinalIgnoreCase))
                {
                    decisionReason = "accepted_precommit_snapshot_unavailable";
                    return false;
                }
            }
        }

        var peerProof = new PostTunaFallbackPeerProofEvidence(
            dataSession.SessionId,
            dataSession.TransferId,
            FileTransferDirection.Outbound,
            proofGeneration,
            frameIdentity.TransportEpoch,
            proofKind,
            reason,
            frameIdentity);
        boundary = new PostTunaFallbackAvailabilityProofEvidence(
            peerProof,
            snapshot);
        decisionReason = boundary.IsComplete
            ? "accepted_precommit_scope_bound"
            : "accepted_precommit_snapshot_incomplete";
        return boundary.IsComplete;
    }

    private static void LogFileTransferRouteTransitionPeerProofBindingDecision(
        string? sessionId,
        string? transferId,
        long proofGeneration,
        long proofTransportEpoch,
        string status,
        string reason)
        => LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=runtime_unlock_uncommitted_tuna_fallback_peer_proof_binding_decided; session_id={SanitizeLogToken(sessionId ?? "none")}; transfer_id={SanitizeLogToken(transferId ?? "none")}; direction=outbound; proof_generation={proofGeneration}; proof_transport_epoch={proofTransportEpoch}; binding_status={SanitizeLogToken(status)}; decision_reason={SanitizeLogToken(reason)}");

    private bool HasCurrentFileTunaV4Publication(string sessionId, string transferId)
    {
        lock (gate)
        {
            return TryGetFileTransferRouteHintUnsafe(
                       sessionId,
                       transferId,
                       FileTransferDirection.Outbound,
                       out var hint) &&
                   hint.Route == FileTransferRoute.FileTunaV4 &&
                   hint.ProtocolVersion == FileTransferProtocol.ProtocolVersionV4;
        }
    }

    private bool CompleteFileTransferFallbackNknProofIfPending(
        string proofKind,
        string? sessionId,
        FileTransferDataFrame? proofFrame = null)
    {
        string reason;
        string? pendingSessionId;
        NknAccelerationLaneKind lanes;
        bool bulkProofObserved;
        bool controlProofObserved;
        bool shouldLogUnconfirmed = false;
        bool requiresV6EpochRecovery = false;
        bool completed = false;
        bool coordinatorFileFallbackEvidenceOnly = false;
        string? authorityTransferId = null;
        FileTransferDirection? authorityDirection = null;
        long authorityProofGeneration = 0;
        string? authorityRouteToken = null;
        int authorityProtocolVersion = 0;
        int authorityLiveRouteEpoch = 0;
        int authorityLegGeneration = 0;
        int authorityBridgeRecoveryGeneration = 0;
        long authorityTransportEpoch = 0;
        string? authorityCheckpointRequestId = null;
        string? authorityReason = null;
        bool needsUncommittedBoundaryBinding = false;
        PostTunaFallbackAvailabilityProofEvidence? uncommittedProofBoundary = null;
        var uncommittedProofBoundaryDecisionReason = "accepted_precommit_scope_unavailable";
        RuntimeUnlockRouteCommitSnapshot? retainedPreCommitSnapshot = null;
        var normalizedProofKind = SanitizeLogToken(proofKind);
        var authoritativeProof = IsAuthoritativeFileTransferFallbackNknProof(normalizedProofKind);
        PostTunaFallbackPeerProofFrameIdentity? proofFrameIdentity = null;
        if (IsPostTunaFileTransferFallbackNknProof(normalizedProofKind) &&
            proofFrame is not null &&
            !PostTunaFallbackPeerProofFrameIdentity.TryCreate(proofFrame, out proofFrameIdentity))
        {
            return false;
        }

        lock (fileTransferFallbackProofGate)
        {
            if (!fileTransferFallbackProofPending)
            {
                return false;
            }

            var normalizedSessionId = string.IsNullOrWhiteSpace(sessionId) ? null : sessionId.Trim();
            if (!string.IsNullOrWhiteSpace(fileTransferFallbackProofSessionId) &&
                !string.IsNullOrWhiteSpace(normalizedSessionId) &&
                !string.Equals(fileTransferFallbackProofSessionId, normalizedSessionId, StringComparison.Ordinal))
            {
                return false;
            }

            var requiresSessionBoundProofFrame =
                !string.IsNullOrWhiteSpace(fileTransferFallbackProofTransferId) &&
                fileTransferFallbackProofDirection == FileTransferDirection.Outbound &&
                fileTransferFallbackProofGeneration > 0 &&
                fileTransferFallbackProofTransportEpoch > 0;
            if (IsPostTunaFileTransferFallbackNknProof(normalizedProofKind) &&
                requiresSessionBoundProofFrame &&
                (proofFrameIdentity is null ||
                 !IsExactPendingPostTunaFallbackProofFrameUnsafe(proofFrame, normalizedSessionId)))
            {
                return false;
            }

            if (!authoritativeProof)
            {
                reason = fileTransferFallbackProofReason;
                pendingSessionId = fileTransferFallbackProofSessionId ?? normalizedSessionId;
                lanes = fileTransferFallbackProofLanes;
                shouldLogUnconfirmed = !fileTransferFallbackBulkProofObserved;
                fileTransferFallbackBulkProofObserved = true;
                bulkProofObserved = fileTransferFallbackBulkProofObserved;
                controlProofObserved = fileTransferFallbackControlProofObserved;
            }
            else
            {
                reason = fileTransferFallbackProofReason;
                pendingSessionId = fileTransferFallbackProofSessionId ?? normalizedSessionId;
                lanes = fileTransferFallbackProofLanes;
                fileTransferFallbackControlProofObserved = true;
                requiresV6EpochRecovery =
                    (lanes & NknAccelerationLaneKind.File) == NknAccelerationLaneKind.File &&
                    !IsPostTunaFileTransferFallbackNknProof(normalizedProofKind);
                bulkProofObserved = fileTransferFallbackBulkProofObserved;
                controlProofObserved = fileTransferFallbackControlProofObserved;
                if (requiresV6EpochRecovery)
                {
                    shouldLogUnconfirmed = true;
                    authorityTransferId = fileTransferFallbackProofTransferId;
                    authorityDirection = fileTransferFallbackProofDirection ??
                        ResolveFileTransferFallbackV6ProofBootstrapDirection(
                            normalizedProofKind);
                    authorityProofGeneration = fileTransferFallbackProofGeneration;
                }
                else
                {
                    coordinatorFileFallbackEvidenceOnly =
                        IsPostTunaFileTransferFallbackNknProof(
                            normalizedProofKind) &&
                        (lanes & NknAccelerationLaneKind.File) ==
                            NknAccelerationLaneKind.File &&
                        proofFrameIdentity is not null &&
                        proofFrame is not null &&
                        !string.IsNullOrWhiteSpace(proofFrame.TransferId) &&
                        !string.IsNullOrWhiteSpace(pendingSessionId) &&
                        string.Equals(
                            proofFrame.SessionId,
                            pendingSessionId,
                            StringComparison.Ordinal);
                    authorityTransferId = fileTransferFallbackProofTransferId;
                    authorityDirection = fileTransferFallbackProofDirection;
                    authorityProofGeneration = fileTransferFallbackProofGeneration;
                    authorityRouteToken = fileTransferFallbackProofRouteToken;
                    authorityProtocolVersion = fileTransferFallbackProofProtocolVersion;
                    authorityLiveRouteEpoch = fileTransferFallbackProofLiveRouteEpoch;
                    authorityLegGeneration = fileTransferFallbackProofLegGeneration;
                    authorityBridgeRecoveryGeneration = fileTransferFallbackProofBridgeRecoveryGeneration;
                    authorityTransportEpoch = fileTransferFallbackProofTransportEpoch;
                    authorityCheckpointRequestId = fileTransferFallbackProofCheckpointRequestId;
                    authorityReason = fileTransferFallbackProofAuthorityReason;
                    retainedPreCommitSnapshot = fileTransferFallbackProofPreCommitSnapshot;
                    needsUncommittedBoundaryBinding =
                        IsPostTunaFileTransferFallbackNknProof(normalizedProofKind) &&
                        string.IsNullOrWhiteSpace(authorityTransferId);
                    if (!needsUncommittedBoundaryBinding)
                    {
                        if (!coordinatorFileFallbackEvidenceOnly)
                        {
                            CompleteFileTransferFallbackProofUnsafe();
                        }
                        completed = true;
                    }
                }
            }
        }

        if (needsUncommittedBoundaryBinding)
        {
            if (coordinatorFileFallbackEvidenceOnly &&
                proofFrame is not null &&
                !string.IsNullOrWhiteSpace(pendingSessionId) &&
                !string.IsNullOrWhiteSpace(proofFrame.TransferId) &&
                string.Equals(
                    proofFrame.SessionId,
                    pendingSessionId,
                    StringComparison.Ordinal) &&
                HasCurrentFileTunaV4Publication(
                    pendingSessionId,
                    proofFrame.TransferId.Trim()))
            {
                completed = true;
                needsUncommittedBoundaryBinding = false;
                LogFileTransferRouteTransitionPeerProofBindingDecision(
                    pendingSessionId,
                    proofFrame.TransferId,
                    authorityProofGeneration,
                    proofFrameIdentity?.TransportEpoch ?? 0,
                    "Observed",
                    "current_tuna_publication_evidence_only");
            }
            else if (!coordinatorFileFallbackEvidenceOnly &&
                proofFrame is not null &&
                !string.IsNullOrWhiteSpace(pendingSessionId) &&
                !string.IsNullOrWhiteSpace(proofFrame.TransferId) &&
                string.Equals(proofFrame.SessionId, pendingSessionId, StringComparison.Ordinal) &&
                HasCurrentFileTunaV4Publication(pendingSessionId, proofFrame.TransferId.Trim()))
            {
                lock (fileTransferFallbackProofGate)
                {
                    if (fileTransferFallbackProofPending &&
                        fileTransferFallbackProofGeneration == authorityProofGeneration &&
                        string.Equals(
                            fileTransferFallbackProofSessionId,
                            pendingSessionId,
                            StringComparison.Ordinal))
                    {
                        CompleteFileTransferFallbackProofUnsafe();
                        completed = true;
                    }
                }
            }

            if (completed)
            {
                needsUncommittedBoundaryBinding = false;
            }
            else if (proofFrameIdentity is null ||
                string.IsNullOrWhiteSpace(pendingSessionId) ||
                proofFrame is null ||
                string.IsNullOrWhiteSpace(proofFrame.TransferId) ||
                !string.Equals(proofFrame.SessionId, pendingSessionId, StringComparison.Ordinal) ||
                !TryCreatePostTunaFallbackAvailabilityProofEvidence(
                    pendingSessionId,
                    proofFrame.TransferId.Trim(),
                    authorityProofGeneration,
                    normalizedProofKind,
                    reason,
                    proofFrameIdentity,
                    retainedPreCommitSnapshot,
                    out uncommittedProofBoundary,
                    out uncommittedProofBoundaryDecisionReason))
            {
                LogFileTransferRouteTransitionPeerProofBindingDecision(
                    pendingSessionId,
                    proofFrame?.TransferId ?? authorityTransferId,
                    authorityProofGeneration,
                    proofFrameIdentity?.TransportEpoch ?? 0,
                    "Held",
                    uncommittedProofBoundaryDecisionReason);
                return false;
            }

            if (needsUncommittedBoundaryBinding)
            {
                lock (fileTransferFallbackProofGate)
                {
                    if (!fileTransferFallbackProofPending ||
                        fileTransferFallbackProofGeneration != authorityProofGeneration ||
                        !string.Equals(
                            fileTransferFallbackProofSessionId,
                            pendingSessionId,
                            StringComparison.Ordinal))
                    {
                        LogFileTransferRouteTransitionPeerProofBindingDecision(
                            pendingSessionId,
                            uncommittedProofBoundary!.PeerProofEvidence.TransferId,
                            authorityProofGeneration,
                            uncommittedProofBoundary.PeerProofEvidence.TransportEpoch,
                            "Invalidated",
                            "pending_proof_scope_replaced");
                        return false;
                    }

                    if (!coordinatorFileFallbackEvidenceOnly)
                    {
                        CompleteFileTransferFallbackProofUnsafe();
                    }
                    completed = true;
                }

                LogFileTransferRouteTransitionPeerProofBindingDecision(
                    pendingSessionId,
                    uncommittedProofBoundary!.PeerProofEvidence.TransferId,
                    authorityProofGeneration,
                    uncommittedProofBoundary.PeerProofEvidence.TransportEpoch,
                    "Bound",
                    "accepted_precommit_scope_bound");
            }
        }

        if (!completed)
        {
            if (shouldLogUnconfirmed)
            {
                LocalOperationalLog.Warn(
                    "NKN.Tuna",
                    $"event=filetransfer_fallback_nkn_proof_unconfirmed; session_id={SanitizeLogToken(pendingSessionId ?? "none")}; reason={reason}; proof={normalizedProofKind}; lanes={FormatAccelerationLanesForLog(lanes)}; requires_control_proof={(controlProofObserved ? 0 : 1)}; requires_v6_epoch_recovery={(requiresV6EpochRecovery ? 1 : 0)}; bulk_seen={(bulkProofObserved ? 1 : 0)}; control_seen={(controlProofObserved ? 1 : 0)}");
                if (requiresV6EpochRecovery)
                {
                    LocalOperationalLog.Info(
                        "NKN.Tuna",
                        $"event=filetransfer_fallback_nkn_proof_waiting_for_v6_epoch; session_id={SanitizeLogToken(pendingSessionId ?? "none")}; reason={reason}; proof={normalizedProofKind}; lanes={FormatAccelerationLanesForLog(lanes)}");
                    PublishFileTransferFallbackV6ProofBootstrapEvaluation(
                        pendingSessionId,
                        authorityDirection,
                        authorityProofGeneration,
                        normalizedProofKind,
                        reason);
                }
            }

            return false;
        }

        PostTunaFallbackHandoffEvidence? postTunaFallbackHandoffEvidence = null;
        if (IsPostTunaFileTransferFallbackNknProof(normalizedProofKind) &&
            !string.IsNullOrWhiteSpace(pendingSessionId) &&
            !string.IsNullOrWhiteSpace(authorityTransferId) &&
            authorityDirection == FileTransferDirection.Outbound &&
            authorityProofGeneration > 0 &&
            string.Equals(
                authorityRouteToken!,
                FileTransferRouteResolver.PostTunaFallbackV6Token,
                StringComparison.Ordinal) &&
            authorityProtocolVersion ==
                FileTransferProtocol.ProtocolVersionV6 &&
            authorityLiveRouteEpoch > 0 &&
            authorityLegGeneration > 0 &&
            authorityBridgeRecoveryGeneration > 0 &&
            authorityTransportEpoch > 0 &&
            !string.IsNullOrWhiteSpace(authorityCheckpointRequestId) &&
            !string.IsNullOrWhiteSpace(authorityReason))
        {
            postTunaFallbackHandoffEvidence = new PostTunaFallbackHandoffEvidence(
                pendingSessionId.Trim(),
                authorityTransferId.Trim(),
                authorityDirection.Value,
                authorityProofGeneration,
                authorityRouteToken!,
                authorityProtocolVersion,
                authorityLiveRouteEpoch,
                authorityLegGeneration,
                authorityBridgeRecoveryGeneration,
                authorityTransportEpoch,
                authorityCheckpointRequestId!,
                normalizedProofKind,
                authorityReason!,
                proofFrameIdentity);
        }

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=filetransfer_fallback_nkn_proof_observed; session_id={SanitizeLogToken(pendingSessionId ?? "none")}; reason={reason}; proof={normalizedProofKind}; lanes={FormatAccelerationLanesForLog(lanes)}; bulk_seen={(bulkProofObserved ? 1 : 0)}; control_seen={(controlProofObserved ? 1 : 0)}");
        if (coordinatorFileFallbackEvidenceOnly)
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=filetransfer_post_tuna_fallback_nkn_proved; session_id={SanitizeLogToken(pendingSessionId ?? "none")}; transfer_id={SanitizeLogToken(uncommittedProofBoundary?.PeerProofEvidence.TransferId ?? authorityTransferId ?? "none")}; direction={FormatFileTransferDirection(uncommittedProofBoundary?.PeerProofEvidence.Direction ?? authorityDirection)}; reason={reason}; proof={normalizedProofKind}; proof_generation={uncommittedProofBoundary?.PeerProofEvidence.ProofGeneration ?? authorityProofGeneration}; proof_transport_epoch={uncommittedProofBoundary?.PeerProofEvidence.TransportEpoch ?? authorityTransportEpoch}; proof_frame_identity={SanitizeLogToken(uncommittedProofBoundary?.PeerProofEvidence.FrameIdentity?.Sha256 ?? proofFrameIdentity?.Sha256 ?? "none")}; transaction_generation={uncommittedProofBoundary?.PreCommitSnapshot.TransactionGeneration ?? 0}; offer_generation={uncommittedProofBoundary?.PreCommitSnapshot.OfferGeneration ?? 0}; tuna_path_lease_generation={uncommittedProofBoundary?.PreCommitSnapshot.TunaPathLeaseGeneration ?? 0}; launch_generation={uncommittedProofBoundary?.PreCommitSnapshot.LaunchGeneration ?? 0}; probe_id={SanitizeLogToken(uncommittedProofBoundary?.PreCommitSnapshot.PathProbeId ?? "none")}; binding_status={(uncommittedProofBoundary is null ? "legacy" : "bound")}; lanes={FormatAccelerationLanesForLog(lanes)}; evidence_only=1");
            if (postTunaFallbackHandoffEvidence is not null ||
                uncommittedProofBoundary is not null)
            {
                SetFileTransferDataSessionsAvailability(
                    isAvailable: true,
                    reason: "transport_recovered",
                    requiresResumeRequest: true,
                    handoffKind:
                        FileTransferTransportHandoffKind.TunaToNormalFallback,
                    targetTransport: FileTransferTransportKind.RegularNkn,
                    postTunaFallbackHandoffEvidence,
                    uncommittedProofBoundary);
            }
            return true;
        }

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=tuna_disable_handoff_nkn_ready; session_id={SanitizeLogToken(pendingSessionId ?? "none")}; reason={reason}; proof={normalizedProofKind}; lanes={FormatAccelerationLanesForLog(lanes)}");
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=tuna_disable_handoff_completed; session_id={SanitizeLogToken(pendingSessionId ?? "none")}; reason={reason}; proof={normalizedProofKind}; lanes={FormatAccelerationLanesForLog(lanes)}");

        if ((lanes & NknAccelerationLaneKind.File) == NknAccelerationLaneKind.File)
        {
            if (IsPostTunaFileTransferFallbackNknProof(normalizedProofKind))
            {
                LocalOperationalLog.Info(
                    "NKN.Tuna",
                    $"event=filetransfer_post_tuna_fallback_nkn_proved; session_id={SanitizeLogToken(pendingSessionId ?? "none")}; transfer_id={SanitizeLogToken(uncommittedProofBoundary?.PeerProofEvidence.TransferId ?? authorityTransferId ?? "none")}; direction={FormatFileTransferDirection(uncommittedProofBoundary?.PeerProofEvidence.Direction ?? authorityDirection)}; reason={reason}; proof={normalizedProofKind}; proof_generation={uncommittedProofBoundary?.PeerProofEvidence.ProofGeneration ?? authorityProofGeneration}; proof_transport_epoch={uncommittedProofBoundary?.PeerProofEvidence.TransportEpoch ?? authorityTransportEpoch}; proof_frame_identity={SanitizeLogToken(uncommittedProofBoundary?.PeerProofEvidence.FrameIdentity?.Sha256 ?? proofFrameIdentity?.Sha256 ?? "none")}; transaction_generation={uncommittedProofBoundary?.PreCommitSnapshot.TransactionGeneration ?? 0}; offer_generation={uncommittedProofBoundary?.PreCommitSnapshot.OfferGeneration ?? 0}; tuna_path_lease_generation={uncommittedProofBoundary?.PreCommitSnapshot.TunaPathLeaseGeneration ?? 0}; launch_generation={uncommittedProofBoundary?.PreCommitSnapshot.LaunchGeneration ?? 0}; probe_id={SanitizeLogToken(uncommittedProofBoundary?.PreCommitSnapshot.PathProbeId ?? "none")}; binding_status={(uncommittedProofBoundary is null ? "legacy" : "bound")}; lanes={FormatAccelerationLanesForLog(lanes)}");
            }

            MarkTunaFallbackLaneState(
                pendingSessionId,
                lane: NknAccelerationLaneKind.File,
                state: TunaFallbackLaneState.Recovered,
                reason: reason);
            SetFileTransferDataSessionsAvailability(
                isAvailable: true,
                reason: "transport_recovered",
                requiresResumeRequest: true,
                handoffKind: FileTransferTransportHandoffKind.TunaToNormalFallback,
                targetTransport: FileTransferTransportKind.RegularNkn,
                postTunaFallbackHandoffEvidence,
                uncommittedProofBoundary);
            if (IsPostTunaFileTransferFallbackNknProof(normalizedProofKind))
            {
                LocalOperationalLog.Info(
                    "NKN.Tuna",
                    $"event=filetransfer_post_tuna_fallback_cleanup_completed; session_id={SanitizeLogToken(pendingSessionId ?? "none")}; reason={reason}; proof={normalizedProofKind}; lanes={FormatAccelerationLanesForLog(lanes)}");
            }
        }

        return true;
    }

    private bool CompleteFileTransferFallbackNknProofFromV6Epoch(FileTransferV6TransportEpochSnapshot snapshot)
    {
        if (HasCurrentFileTransferDataSession(
                snapshot.SessionId,
                snapshot.TransferId) &&
            !HasCommittedPostTunaFallbackTransition(snapshot))
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=filetransfer_v6_epoch_fallback_evidence_held_for_route_transition; session_id={SanitizeLogToken(snapshot.SessionId)}; transfer_id={SanitizeLogToken(snapshot.TransferId)}; direction={snapshot.Direction.ToString().ToLowerInvariant()}; transport_epoch={snapshot.TransportEpoch}; handoff_kind={FormatFileTransferTransportHandoffKindForLog(snapshot.HandoffKind)}; source_transport={FormatFileTransferTransportKindForLog(snapshot.SourceTransport)}; target_transport={FormatFileTransferTransportKindForLog(snapshot.TargetTransport)}; decision_reason=coordinator_route_transition_commit_required");
            return false;
        }

        var reason = SanitizeLogToken(snapshot.Reason);
        var pendingSessionId = snapshot.SessionId;
        var lanes = NknAccelerationLaneKind.File;
        var bulkProofObserved = false;
        var controlProofObserved = true;
        var completedPendingProof = false;
        var awaitingExactPeerFrame = false;
        string? authorityTransferId = null;
        FileTransferDirection? authorityDirection = null;
        long authorityProofGeneration = 0;
        string? authorityRouteToken = null;
        int authorityProtocolVersion = 0;
        int authorityLiveRouteEpoch = 0;
        int authorityLegGeneration = 0;
        int authorityBridgeRecoveryGeneration = 0;
        long authorityTransportEpoch = 0;
        string? authorityCheckpointRequestId = null;
        string? authorityReason = null;
        lock (fileTransferFallbackProofGate)
        {
            if (fileTransferFallbackProofPending &&
                (fileTransferFallbackProofLanes & NknAccelerationLaneKind.File) == NknAccelerationLaneKind.File)
            {
                var normalizedSessionId = snapshot.SessionId.Trim();
                if (!string.IsNullOrWhiteSpace(fileTransferFallbackProofSessionId) &&
                    !string.Equals(fileTransferFallbackProofSessionId, normalizedSessionId, StringComparison.Ordinal))
                {
                    return false;
                }

                var hasBoundFallbackAuthority =
                    !string.IsNullOrWhiteSpace(fileTransferFallbackProofTransferId) ||
                    fileTransferFallbackProofDirection is not null ||
                    fileTransferFallbackProofTransportEpoch > 0;
                if (hasBoundFallbackAuthority &&
                    (!string.Equals(
                         fileTransferFallbackProofTransferId,
                         snapshot.TransferId,
                         StringComparison.Ordinal) ||
                     fileTransferFallbackProofDirection != snapshot.Direction ||
                     snapshot.HandoffKind != FileTransferTransportHandoffKind.TunaToNormalFallback ||
                     snapshot.SourceTransport != FileTransferTransportKind.Tuna ||
                     snapshot.TargetTransport != FileTransferTransportKind.RegularNkn ||
                     snapshot.TransportEpoch != fileTransferFallbackProofTransportEpoch))
                {
                    return false;
                }

                var requiresExactPeerFrame =
                    !string.IsNullOrWhiteSpace(fileTransferFallbackProofTransferId) &&
                    fileTransferFallbackProofDirection == FileTransferDirection.Outbound &&
                    fileTransferFallbackProofGeneration > 0 &&
                    fileTransferFallbackProofTransportEpoch > 0;
                if (requiresExactPeerFrame)
                {
                    // The recovered epoch is a scope boundary, not the exact peer frame
                    // that authorizes the uncommitted-Tuna fallback adoption. Preserve the
                    // pending proof until the matching state/frontier frame binds it.
                    awaitingExactPeerFrame = true;
                }
                else
                {
                    reason = fileTransferFallbackProofReason;
                    pendingSessionId = fileTransferFallbackProofSessionId ?? normalizedSessionId;
                    lanes = fileTransferFallbackProofLanes;
                    bulkProofObserved = fileTransferFallbackBulkProofObserved;
                    authorityTransferId = fileTransferFallbackProofTransferId;
                    authorityDirection = fileTransferFallbackProofDirection;
                    authorityProofGeneration = fileTransferFallbackProofGeneration;
                    authorityRouteToken = fileTransferFallbackProofRouteToken;
                    authorityProtocolVersion = fileTransferFallbackProofProtocolVersion;
                    authorityLiveRouteEpoch = fileTransferFallbackProofLiveRouteEpoch;
                    authorityLegGeneration = fileTransferFallbackProofLegGeneration;
                    authorityBridgeRecoveryGeneration = fileTransferFallbackProofBridgeRecoveryGeneration;
                    authorityTransportEpoch = fileTransferFallbackProofTransportEpoch;
                    authorityCheckpointRequestId = fileTransferFallbackProofCheckpointRequestId;
                    authorityReason = fileTransferFallbackProofAuthorityReason;
                    completedPendingProof = true;
                    fileTransferFallbackProofPending = false;
                    fileTransferFallbackProofReason = "none";
                    fileTransferFallbackProofSessionId = null;
                    fileTransferFallbackProofLanes = NknAccelerationLaneKind.None;
                    fileTransferFallbackProofGeneration++;
                    fileTransferFallbackProofProbeScheduled = false;
                    fileTransferFallbackBulkProofObserved = false;
                    fileTransferFallbackControlProofObserved = false;
                    ClearFileTransferFallbackProofAuthorityUnsafe();
                }
            }
        }

        if (awaitingExactPeerFrame)
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=filetransfer_fallback_nkn_proof_waiting_for_exact_peer_frame; session_id={SanitizeLogToken(snapshot.SessionId)}; transfer_id={SanitizeLogToken(snapshot.TransferId)}; direction={snapshot.Direction.ToString().ToLowerInvariant()}; transport_epoch={snapshot.TransportEpoch}; reason={reason}");
        }

        const string proofKind = "filetransfer_v6_epoch_recovered";
        PostTunaFallbackHandoffEvidence? postTunaFallbackHandoffEvidence = null;
        if (completedPendingProof)
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=filetransfer_fallback_nkn_proof_observed; session_id={SanitizeLogToken(pendingSessionId ?? "none")}; reason={reason}; proof={proofKind}; lanes={FormatAccelerationLanesForLog(lanes)}; bulk_seen={(bulkProofObserved ? 1 : 0)}; control_seen={(controlProofObserved ? 1 : 0)}");
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=tuna_disable_handoff_nkn_ready; session_id={SanitizeLogToken(pendingSessionId ?? "none")}; reason={reason}; proof={proofKind}; lanes={FormatAccelerationLanesForLog(lanes)}");
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=tuna_disable_handoff_completed; session_id={SanitizeLogToken(pendingSessionId ?? "none")}; reason={reason}; proof={proofKind}; lanes={FormatAccelerationLanesForLog(lanes)}");
            if (!string.IsNullOrWhiteSpace(pendingSessionId) &&
                !string.IsNullOrWhiteSpace(authorityTransferId) &&
                authorityDirection == FileTransferDirection.Outbound &&
                authorityProofGeneration > 0 &&
                string.Equals(
                    authorityRouteToken!,
                    FileTransferRouteResolver.PostTunaFallbackV6Token,
                    StringComparison.Ordinal) &&
                authorityProtocolVersion == FileTransferProtocol.ProtocolVersionV6 &&
                authorityLiveRouteEpoch > 0 &&
                authorityLegGeneration > 0 &&
                authorityBridgeRecoveryGeneration > 0 &&
                authorityTransportEpoch > 0 &&
                !string.IsNullOrWhiteSpace(authorityCheckpointRequestId) &&
                !string.IsNullOrWhiteSpace(authorityReason))
            {
                postTunaFallbackHandoffEvidence = new PostTunaFallbackHandoffEvidence(
                    pendingSessionId.Trim(),
                    authorityTransferId.Trim(),
                    authorityDirection.Value,
                    authorityProofGeneration,
                    authorityRouteToken!,
                    authorityProtocolVersion,
                    authorityLiveRouteEpoch,
                    authorityLegGeneration,
                    authorityBridgeRecoveryGeneration,
                    authorityTransportEpoch,
                    authorityCheckpointRequestId!,
                    proofKind,
                    authorityReason!);
            }
        }

        EnsureFileTransferFallbackRecoveredStateFromV6Epoch(snapshot, reason);
        MarkTunaFallbackLaneState(
            pendingSessionId,
            lane: NknAccelerationLaneKind.File,
            state: TunaFallbackLaneState.Recovered,
            reason: reason);
        SetFileTransferDataSessionsAvailability(
            isAvailable: true,
            reason: "transport_recovered",
            requiresResumeRequest: false,
            handoffKind: snapshot.HandoffKind,
            targetTransport: FileTransferTransportKind.RegularNkn,
            postTunaFallbackHandoffEvidence);
        return completedPendingProof;
    }

    private bool HasCurrentFileTransferDataSession(
        string sessionId,
        string transferId)
    {
        lock (gate)
        {
            return fileTransferDataSessions.TryGetValue(
                       transferId,
                       out var dataSession) &&
                   !dataSession.IsDisposed &&
                   string.Equals(
                       dataSession.SessionId,
                       sessionId,
                       StringComparison.Ordinal);
        }
    }

    private bool HasCommittedPostTunaFallbackTransition(
        FileTransferV6TransportEpochSnapshot snapshot)
    {
        lock (accelerationGate)
        {
            var shadow = fileTransferRouteTransitionExecutionShadow;
            if (shadow.Current is not null ||
                shadow.RetainedPredecessor is not null ||
                shadow.LastCurrentDisposition is not { } receipt ||
                receipt.Status is not
                    (FileTransferRouteTransitionDispositionApplyStatus.Applied or
                     FileTransferRouteTransitionDispositionApplyStatus.Idempotent))
            {
                return false;
            }

            var command = receipt.Command;
            return command.Kind ==
                       FileTransferRouteTransitionDispositionKind.Committed &&
                   command.Authority.TargetRoute ==
                       FileTransferRoute.PostTunaFallbackV6 &&
                   command.Authority.TargetProtocolVersion ==
                       FileTransferProtocol.ProtocolVersionV6 &&
                   command.Authority.TargetTransport ==
                       FileTransferTransportKind.RegularNkn &&
                   command.Authority.HandoffKind ==
                       FileTransferTransportHandoffKind.TunaToNormalFallback &&
                   string.Equals(
                       command.Authority.SessionId,
                       snapshot.SessionId,
                       StringComparison.Ordinal) &&
                   string.Equals(
                       command.Authority.TransferId,
                       snapshot.TransferId,
                       StringComparison.Ordinal) &&
                   command.Authority.Direction == snapshot.Direction &&
                   command.Authority.ProofBoundary is
                       FileTransferFallbackTransitionProofBoundary fallback &&
                   fallback.TargetTransportEpoch == snapshot.TransportEpoch &&
                   snapshot.HandoffKind ==
                       FileTransferTransportHandoffKind.TunaToNormalFallback &&
                   snapshot.SourceTransport ==
                       FileTransferTransportKind.Tuna &&
                   snapshot.TargetTransport ==
                       FileTransferTransportKind.RegularNkn;
        }
    }

    private bool IsExactPendingPostTunaFallbackProofFrameUnsafe(
        FileTransferDataFrame? frame,
        string? observedSessionId)
    {
        if (frame is null ||
            string.IsNullOrWhiteSpace(fileTransferFallbackProofSessionId) ||
            string.IsNullOrWhiteSpace(fileTransferFallbackProofTransferId) ||
            fileTransferFallbackProofDirection != FileTransferDirection.Outbound ||
            fileTransferFallbackProofTransportEpoch <= 0 ||
            !string.Equals(
                frame.SessionId,
                fileTransferFallbackProofSessionId,
                StringComparison.Ordinal) ||
            !string.Equals(
                frame.TransferId,
                fileTransferFallbackProofTransferId,
                StringComparison.Ordinal) ||
            (!string.IsNullOrWhiteSpace(observedSessionId) &&
             !string.Equals(
                 observedSessionId,
                 fileTransferFallbackProofSessionId,
                 StringComparison.Ordinal)))
        {
            return false;
        }

        var transportEpoch = frame switch
        {
            IFileTransferTransportMetadataFrame metadata => metadata.TransportEpoch,
            FileTransferTransportEpochFrameV6 transportEpochFrame => transportEpochFrame.TransportEpoch,
            FileTransferFrontierRequestFrameV6 frontier => frontier.TransportEpoch,
            FileTransferRepairProofFrameV6 repairProof => repairProof.TransportEpoch,
            _ => 0,
        };
        return transportEpoch == fileTransferFallbackProofTransportEpoch;
    }

    private static string FormatRuntimeUnlockRetryDispatchAuthorityRequestTuple(
        RuntimeUnlockRetryDispatchAuthorityRequest request)
    {
        var publication = request.SourcePublicationAuthority;
        var routeCommitGeneration = publication.RouteCommitGeneration is { } commitGeneration
            ? commitGeneration.ToString(CultureInfo.InvariantCulture)
            : "(none)";
        return $"session_id={SanitizeLogToken(request.SessionId)}; transfer_id={SanitizeLogToken(request.TransferId)}; direction={request.Direction.ToString().ToLowerInvariant()}; contract_generation={request.RecoveryContractGeneration}; retired_generation={request.RetiredOfferGeneration}; dispatch_attempt_generation={request.DispatchAttemptGeneration}; missing_dispatch_successor_generation={request.MissingDispatchSuccessorGeneration}; predecessor_authority_id={SanitizeLogToken(request.PredecessorAuthorityId?.ToString() ?? "(none)")}; request_active_predecessor_supersession={(request.RequestActivePredecessorSupersession ? 1 : 0)}; listener_rearm_requirement={SanitizeLogToken(request.ListenerRearmRequirement.ToString())}; retry_reason={SanitizeLogToken(request.RetryReason)}; recovery_reason={SanitizeLogToken(request.RecoveryReason)}; regular_v4_liveness_generation={request.RegularV4LivenessGeneration}; bridge_decision_generation={request.BridgeDecisionGeneration}; source_session_id={SanitizeLogToken(publication.SessionId)}; source_transfer_id={SanitizeLogToken(publication.TransferId)}; source_direction={publication.Direction.ToString().ToLowerInvariant()}; source_route={SanitizeLogToken(publication.RouteToken)}; source_protocol_version={publication.ProtocolVersion}; source_live_route_epoch={publication.LiveRouteEpoch}; source_runtime_generation={publication.RuntimeGeneration}; source_terminal_generation={publication.TerminalGeneration}; source_leg_generation={publication.LegGeneration}; source_route_publication_generation={publication.RoutePublicationGeneration}; source_route_commit_generation={routeCommitGeneration}; source_route_commit_generation_present={(publication.RouteCommitGeneration.HasValue ? 1 : 0)}; source_target_route={SanitizeLogToken(publication.TargetRouteToken)}; source_target_protocol_version={publication.TargetProtocolVersion}; source_target_transport={FormatFileTransferTransportKindForLog(publication.TargetTransport)}; source_route_publication_action_kind={SanitizeLogToken(publication.RoutePublicationActionKind)}; source_coordinator_decision_reason={SanitizeLogToken(publication.CoordinatorDecisionReason)}";
    }

    private bool EnsureFileTransferFallbackRecoveredStateFromV6Epoch(
        FileTransferV6TransportEpochSnapshot snapshot,
        string reason)
    {
        if (snapshot.HandoffKind != FileTransferTransportHandoffKind.TunaToNormalFallback ||
            snapshot.TargetTransport != FileTransferTransportKind.RegularNkn)
        {
            return false;
        }

        var sessionId = string.IsNullOrWhiteSpace(snapshot.SessionId)
            ? null
            : snapshot.SessionId.Trim();
        if (string.IsNullOrWhiteSpace(sessionId))
        {
            return false;
        }

        if (!HasActiveFileTransferDataSessionsForRecovery())
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=filetransfer_v6_fallback_recovered_state_synthesis_suppressed_no_active_transfer; session_id={SanitizeLogToken(sessionId)}; transfer_id={SanitizeLogToken(snapshot.TransferId)}; transport_epoch={snapshot.TransportEpoch}; reason={SanitizeLogToken(reason)}");
            return false;
        }

        TunaFallbackProofState? stateToLog = null;
        lock (accelerationGate)
        {
            if (TryGetCurrentTunaFallbackProofStateUnsafe(sessionId, out _))
            {
                return false;
            }

            var epoch = Interlocked.Increment(ref tunaFallbackProofNextEpoch);
            tunaFallbackProofState = new TunaFallbackProofState
            {
                Epoch = epoch,
                SessionId = sessionId,
                Reason = SanitizeLogToken(reason),
                StartedUtc = DateTimeOffset.UtcNow,
                Lanes = NknAccelerationLaneKind.File,
                FileState = TunaFallbackLaneState.Recovered,
                FileV6EpochState = V6TransportEpochState.Recovered,
                FileV6TransportEpoch = snapshot.TransportEpoch,
            };
            stateToLog = tunaFallbackProofState;
        }

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=filetransfer_v6_fallback_recovered_state_synthesized; session_id={SanitizeLogToken(sessionId)}; fallback_epoch={stateToLog.Epoch}; reason={stateToLog.Reason}; transport_epoch={snapshot.TransportEpoch}; file_state={FormatTunaFallbackLaneState(stateToLog.FileState)}; file_v6_epoch_state={FormatTunaFallbackFileV6EpochState(stateToLog)}");
        NotifyTransportAccelerationStateChanged(reason);
        return true;
    }

    private bool TryGetFileTransferFallbackControlProofPendingSnapshot(out string? sessionId, out string reason, out NknAccelerationLaneKind lanes)
    {
        lock (fileTransferFallbackProofGate)
        {
            if (!fileTransferFallbackProofPending ||
                (fileTransferFallbackProofLanes & NknAccelerationLaneKind.File) != NknAccelerationLaneKind.File ||
                fileTransferFallbackControlProofObserved)
            {
                sessionId = null;
                reason = "none";
                lanes = NknAccelerationLaneKind.None;
                return false;
            }

            sessionId = fileTransferFallbackProofSessionId;
            reason = fileTransferFallbackProofReason;
            lanes = fileTransferFallbackProofLanes;
            return true;
        }
    }

    private static bool TryMapFileTransferFallbackNknProofKind(FileTransferDataFrame frame, out string proofKind)
    {
        proofKind = frame switch
        {
            FileTransferManifestFrameV4 and not FileTransferManifestFrameV6 => "file_transfer_v4_manifest_received",
            FileTransferStateFrameV4 and not FileTransferReceiverStateFrameV6 => "file_transfer_v4_state_frame_received",
            FileTransferChunkBatchFrameV4 and not FileTransferChunkBatchFrameV6 => "file_transfer_v4_bulk_frame_received",
            FileTransferPauseControlFrameV4 and not FileTransferPauseControlFrameV6 => "file_transfer_v4_pause_control_frame_received",
            FileTransferCompleteFrameV4 and not FileTransferCompleteFrameV6 => "file_transfer_v4_complete_frame_received",
            FileTransferCancelFrameV4 and not FileTransferCancelFrameV6 => "file_transfer_v4_cancel_frame_received",
            FileTransferErrorFrameV4 and not FileTransferErrorFrameV6 => "file_transfer_v4_error_frame_received",
            FileTransferReceiverStateFrameV6 => "file_transfer_v6_state_frame_received",
            FileTransferTransportEpochFrameV6 => "file_transfer_v6_transport_epoch_frame_received",
            FileTransferFrontierRequestFrameV6 => "file_transfer_v6_frontier_request_frame_received",
            FileTransferRepairProofFrameV6 => "file_transfer_v6_repair_proof_frame_received",
            FileTransferPauseControlFrameV6 => "file_transfer_v6_pause_control_frame_received",
            FileTransferCompleteFrameV6 => "file_transfer_v6_complete_frame_received",
            FileTransferCancelFrameV6 => "file_transfer_v6_cancel_frame_received",
            FileTransferErrorFrameV6 => "file_transfer_v6_error_frame_received",
            FileTransferChunkBatchFrameV6 => "file_transfer_bulk_frame_received",
            _ => string.Empty,
        };

        return proofKind.Length > 0;
    }

    private static bool TryMapPostTunaFileTransferFallbackNknProofKind(
        FileTransferDataFrame frame,
        string direction,
        out string proofKind)
    {
        var suffix = string.Equals(direction, "sent", StringComparison.Ordinal)
            ? "sent"
            : "received";
        proofKind = frame switch
        {
            FileTransferManifestFrameV4 and not FileTransferManifestFrameV6 => $"file_transfer_v4_manifest_{suffix}",
            FileTransferStateFrameV4 and not FileTransferReceiverStateFrameV6 => $"file_transfer_v4_state_frame_{suffix}",
            FileTransferChunkBatchFrameV4 and not FileTransferChunkBatchFrameV6 => $"file_transfer_v4_bulk_frame_{suffix}",
            FileTransferPauseControlFrameV4 and not FileTransferPauseControlFrameV6 => $"file_transfer_v4_pause_control_frame_{suffix}",
            FileTransferCompleteFrameV4 and not FileTransferCompleteFrameV6 => $"file_transfer_v4_complete_frame_{suffix}",
            FileTransferCancelFrameV4 and not FileTransferCancelFrameV6 => $"file_transfer_v4_cancel_frame_{suffix}",
            FileTransferErrorFrameV4 and not FileTransferErrorFrameV6 => $"file_transfer_v4_error_frame_{suffix}",
            _ => string.Empty,
        };

        return proofKind.Length > 0;
    }

    private static bool IsAuthoritativeFileTransferFallbackNknProof(string proofKind)
        => proofKind.StartsWith("nkn_control_", StringComparison.Ordinal) ||
           proofKind is
               "file_transfer_v4_manifest_received" or
               "file_transfer_v4_manifest_sent" or
               "file_transfer_v4_state_frame_received" or
               "file_transfer_v4_state_frame_sent" or
