               "file_transfer_v4_bulk_frame_sent" or
               "file_transfer_v4_pause_control_frame_received" or
               "file_transfer_v4_pause_control_frame_sent" or
               "file_transfer_v4_complete_frame_received" or
               "file_transfer_v4_complete_frame_sent" or
               "file_transfer_v4_cancel_frame_received" or
               "file_transfer_v4_cancel_frame_sent" or
               "file_transfer_v4_error_frame_received" or
               "file_transfer_v4_error_frame_sent" or
               "file_transfer_v6_state_frame_received" or
               "file_transfer_v6_transport_epoch_frame_received" or
               "file_transfer_v6_frontier_request_frame_received" or
               "file_transfer_v6_repair_proof_frame_received" or
               "file_transfer_v6_pause_control_frame_received" or
               "file_transfer_v6_complete_frame_received" or
               "file_transfer_v6_cancel_frame_received" or
               "file_transfer_v6_error_frame_received";

    private static bool IsPostTunaFileTransferFallbackNknProof(string proofKind)
        => proofKind is
            "file_transfer_v6_state_frame_received" or
            "file_transfer_v6_transport_epoch_frame_received" or
            "file_transfer_v6_frontier_request_frame_received" or
            "file_transfer_v6_repair_proof_frame_received" or
            "file_transfer_v6_pause_control_frame_received" or
            "file_transfer_v6_complete_frame_received" or
            "file_transfer_v6_cancel_frame_received" or
            "file_transfer_v6_error_frame_received";

    private static string MapSecureMessageTypeForProof(MsgType messageType)
        => messageType switch
        {
            MsgType.Chat => "chat",
            MsgType.Ack => "ack",
            MsgType.SessionEnd => "session_end",
            MsgType.FileTransferCancel => "file_transfer_cancel",
            MsgType.FileTransferError => "file_transfer_error",
            MsgType.FileTransferComplete => "file_transfer_complete",
            MsgType.FileTransferPauseControl => "file_transfer_pause_control",
            MsgType.FileTransferHeartbeat => "file_transfer_heartbeat",
            MsgType.FileTransferTransportEpoch => "file_transfer_transport_epoch",
            MsgType.FileTransferTransportProbe => "file_transfer_transport_probe",
            MsgType.FileTransferRepairProof => "file_transfer_repair_proof",
            MsgType.FileTransferOffer => "file_transfer_offer",
            MsgType.FileTransferAccept => "file_transfer_accept",
            MsgType.FileTransferDecline => "file_transfer_decline",
            MsgType.FileTransferStart => "file_transfer_start",
            MsgType.FileTransferSessionOpen => "file_transfer_session_open",
            _ => SanitizeLogToken(messageType.ToString()).ToLowerInvariant(),
        };

    private void ScheduleFileTransferFallbackNknProbeIfPending(string trigger)
    {
        long generation;
        string reason;
        string? sessionId;
        NknAccelerationLaneKind lanes;
        lock (fileTransferFallbackProofGate)
        {
            if (!fileTransferFallbackProofPending ||
                fileTransferFallbackProofProbeScheduled ||
                (fileTransferFallbackProofLanes & NknAccelerationLaneKind.File) != NknAccelerationLaneKind.File)
            {
                return;
            }

            fileTransferFallbackProofProbeScheduled = true;
            generation = fileTransferFallbackProofGeneration;
            reason = fileTransferFallbackProofReason;
            sessionId = fileTransferFallbackProofSessionId;
            lanes = fileTransferFallbackProofLanes;
        }

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=filetransfer_fallback_nkn_probe_scheduled; session_id={SanitizeLogToken(sessionId ?? "none")}; reason={SanitizeLogToken(reason)}; trigger={SanitizeLogToken(trigger)}; delay_ms={(long)FileTransferFallbackUnprovenProbeDelay.TotalMilliseconds}; lanes={FormatAccelerationLanesForLog(lanes)}");
        ArmPostTunaFallbackProofSendWindow(reason, trigger, sessionId);

        _ = Task.Run(
            async () =>
            {
                try
                {
                    await Task.Delay(FileTransferFallbackUnprovenProbeDelay).ConfigureAwait(false);
                    if (disposed)
                    {
                        return;
                    }

                    string probeReason;
                    string? probeSessionId;
                    NknAccelerationLaneKind probeLanes;
                    lock (fileTransferFallbackProofGate)
                    {
                        if (!fileTransferFallbackProofPending ||
                            fileTransferFallbackProofGeneration != generation ||
                            (fileTransferFallbackProofLanes & NknAccelerationLaneKind.File) != NknAccelerationLaneKind.File)
                        {
                            return;
                        }

                        probeReason = fileTransferFallbackProofReason;
                        probeSessionId = fileTransferFallbackProofSessionId;
                        probeLanes = fileTransferFallbackProofLanes;
                    }

                    LocalOperationalLog.Warn(
                        "NKN.Tuna",
                        $"event=filetransfer_fallback_nkn_probe_started; session_id={SanitizeLogToken(probeSessionId ?? "none")}; reason={SanitizeLogToken(probeReason)}; trigger={SanitizeLogToken(trigger)}; delay_ms={(long)FileTransferFallbackUnprovenProbeDelay.TotalMilliseconds}; lanes={FormatAccelerationLanesForLog(probeLanes)}");
                    ArmPostTunaFallbackProofSendWindow(probeReason, $"probe_started:{trigger}", probeSessionId);
                    SetFileTransferDataSessionsAvailability(
                        isAvailable: false,
                        reason: "transport_recovered_unproven",
                        requiresResumeRequest: true,
                        handoffKind: ResolveFileTransferFallbackProbeHandoffKind(probeReason, trigger),
                        targetTransport: FileTransferTransportKind.RegularNkn);
                }
                catch (Exception ex)
                {
                    LocalOperationalLog.Warn(
                        "NKN.Tuna",
                        $"event=filetransfer_fallback_nkn_probe_failed; reason={SanitizeLogToken(reason)}; trigger={SanitizeLogToken(trigger)}; error={SanitizeLogToken(ex.GetType().Name)}");
                }
            });
    }

    private void ArmPostTunaFallbackProofSendWindow(string reason, string trigger, string? sessionId)
    {
        if (client is RealNknClientAdapter realClient)
        {
            realClient.ArmPostTunaFallbackProofSendWindow(reason, trigger, sessionId);
        }
    }

    private static FileTransferTransportHandoffKind ResolveFileTransferFallbackProbeHandoffKind(string? reason, string? trigger)
    {
        var normalizedReason = SanitizeLogToken(reason);
        var normalizedTrigger = SanitizeLogToken(trigger);
        return IsRegularNknRecoveryProbeToken(normalizedReason) ||
               IsRegularNknRecoveryProbeToken(normalizedTrigger)
            ? FileTransferTransportHandoffKind.RegularNknRecovery
            : FileTransferTransportHandoffKind.TunaToNormalFallback;
    }

    private static bool IsRegularNknRecoveryProbeToken(string? value)
    {
        if (string.IsNullOrWhiteSpace(value))
        {
            return false;
        }

        return value is "receive_stall_recovery"
            or "receive_resumed_unproven"
            or "bridge_ready_unproven"
            or "bulk_receive_stalled"
            or "control_receive_stalled"
            or "all_channels_zero_receive" ||
            value.Contains("receive_stall", StringComparison.OrdinalIgnoreCase);
    }

    private bool TryGetCurrentTunaFallbackProofStateUnsafe(string? sessionId, out TunaFallbackProofState state)
    {
        state = default!;
        var normalizedSessionId = string.IsNullOrWhiteSpace(sessionId) ? currentSessionSecurityState.SessionId?.Value : sessionId.Trim();
        if (tunaFallbackProofState is null ||
            string.IsNullOrWhiteSpace(normalizedSessionId) ||
            !string.Equals(tunaFallbackProofState.SessionId, normalizedSessionId, StringComparison.Ordinal))
        {
            return false;
        }

        state = tunaFallbackProofState;
        return true;
    }

    private void RecordPendingFileTransferTunaFallbackReason(string? sessionId, string reason)
    {
        var normalizedSessionId = string.IsNullOrWhiteSpace(sessionId)
            ? currentSessionSecurityState.SessionId?.Value
            : sessionId.Trim();
        if (string.IsNullOrWhiteSpace(normalizedSessionId))
        {
            return;
        }

        var normalizedReason = SanitizeLogToken(reason);
        if (string.IsNullOrWhiteSpace(normalizedReason) ||
            normalizedReason == "none")
        {
            return;
        }

        lock (accelerationGate)
        {
            pendingFileTransferTunaFallbackReasonSessionId = normalizedSessionId;
            pendingFileTransferTunaFallbackReason = normalizedReason;
            pendingFileTransferTunaFallbackReasonUtcMs = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
        }
    }

    private bool TryGetRequiredTunaBulkUnavailableFallbackReasonForSession(string? sessionId, out string reason)
    {
        reason = string.Empty;
        var normalizedSessionId = string.IsNullOrWhiteSpace(sessionId)
            ? currentSessionSecurityState.SessionId?.Value
            : sessionId.Trim();
        if (string.IsNullOrWhiteSpace(normalizedSessionId))
        {
            return false;
        }

        lock (accelerationGate)
        {
            if (tunaFallbackProofState is { } fallbackState &&
                string.Equals(fallbackState.SessionId, normalizedSessionId, StringComparison.Ordinal) &&
                (fallbackState.Lanes & NknAccelerationLaneKind.File) == NknAccelerationLaneKind.File &&
                fallbackState.FileState != TunaFallbackLaneState.None &&
                !string.IsNullOrWhiteSpace(fallbackState.Reason))
            {
                reason = fallbackState.Reason;
                return true;
            }

            if (!string.Equals(pendingFileTransferTunaFallbackReasonSessionId, normalizedSessionId, StringComparison.Ordinal) ||
                string.IsNullOrWhiteSpace(pendingFileTransferTunaFallbackReason) ||
                pendingFileTransferTunaFallbackReasonUtcMs <= 0)
            {
                return false;
            }

            var ageMs = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds() - pendingFileTransferTunaFallbackReasonUtcMs;
            if (ageMs >= 0 &&
                ageMs <= RequiredTunaBulkFallbackReasonGrace.TotalMilliseconds)
            {
                reason = pendingFileTransferTunaFallbackReason;
                return true;
            }

            pendingFileTransferTunaFallbackReasonSessionId = null;
            pendingFileTransferTunaFallbackReason = null;
            pendingFileTransferTunaFallbackReasonUtcMs = 0;
            return false;
        }
    }

    private void MarkTunaFallbackLaneState(
        string? sessionId,
        NknAccelerationLaneKind lane,
        TunaFallbackLaneState state,
        string reason)
    {
        TunaFallbackProofState? snapshot = null;
        var changed = false;
        lock (accelerationGate)
        {
            if (!TryGetCurrentTunaFallbackProofStateUnsafe(sessionId, out var current))
            {
                return;
            }

            if ((lane & NknAccelerationLaneKind.Screen) == NknAccelerationLaneKind.Screen &&
                current.ScreenState != state)
            {
                current.ScreenState = state;
                changed = true;
            }

            if ((lane & NknAccelerationLaneKind.File) == NknAccelerationLaneKind.File &&
                current.FileState != state)
            {
                current.FileState = state;
                changed = true;
            }

            snapshot = current;
        }

        if (changed && snapshot is not null)
        {
            LogMixedFallbackLaneState(snapshot, lane == NknAccelerationLaneKind.Screen
                ? "screen_" + FormatTunaFallbackLaneState(state)
                : "file_" + FormatTunaFallbackLaneState(state));
            NotifyTransportAccelerationStateChanged(reason);
        }
    }

    private void MarkTunaFallbackFileV6EpochState(
        string? sessionId,
        long transportEpoch,
        V6TransportEpochState state,
        string reason)
    {
        TunaFallbackProofState? snapshot = null;
        var changed = false;
        lock (accelerationGate)
        {
            if (!TryGetCurrentTunaFallbackProofStateUnsafe(sessionId, out var current))
            {
                return;
            }

            if (IsFileTransferFallbackFinalForLanes(current, NknAccelerationLaneKind.File) &&
                current.FileV6TransportEpoch > 0 &&
                transportEpoch > 0 &&
                transportEpoch < current.FileV6TransportEpoch)
            {
                LocalOperationalLog.Info(
                    "NKN.Tuna",
                    $"event=filetransfer_v6_epoch_state_ignored_final_fallback; session_id={SanitizeLogToken(sessionId ?? "none")}; transport_epoch={transportEpoch}; state={FormatFileTransferV6TransportEpochStateForLog(state)}; reason={SanitizeLogToken(reason)}; file_state={FormatTunaFallbackLaneState(current.FileState)}; file_v6_epoch_state={FormatTunaFallbackFileV6EpochState(current)}; file_v6_transport_epoch={current.FileV6TransportEpoch}");
                return;
            }

            if (IsFileTransferFallbackFinalForLanes(current, NknAccelerationLaneKind.File) &&
                state == V6TransportEpochState.TargetProofPending &&
                current.FileV6EpochState != state)
            {
                LocalOperationalLog.Info(
                    "NKN.Tuna",
                    $"event=filetransfer_v6_epoch_state_ignored_final_fallback; session_id={SanitizeLogToken(sessionId ?? "none")}; transport_epoch={transportEpoch}; state={FormatFileTransferV6TransportEpochStateForLog(state)}; reason={SanitizeLogToken(reason)}; file_state={FormatTunaFallbackLaneState(current.FileState)}; file_v6_epoch_state={FormatTunaFallbackFileV6EpochState(current)}; file_v6_transport_epoch={current.FileV6TransportEpoch}");
                return;
            }

            if (current.FileV6EpochState != state ||
                current.FileV6TransportEpoch != transportEpoch)
            {
                current.FileV6EpochState = state;
                current.FileV6TransportEpoch = transportEpoch;
                changed = true;
            }

            snapshot = current;
        }

        if (changed && snapshot is not null)
        {
            LogMixedFallbackLaneState(snapshot, "file_v6_epoch_" + FormatFileTransferV6TransportEpochStateForLog(state));
        }
    }

    private void ScheduleScreenTunaHandoffWaitingMarker(string sessionId, string reason)
    {
        var fallbackEpoch = 0L;
        lock (accelerationGate)
        {
            if (!TryGetCurrentTunaFallbackProofStateUnsafe(sessionId, out var state) ||
                (state.Lanes & NknAccelerationLaneKind.Screen) != NknAccelerationLaneKind.Screen)
            {
                return;
            }

            fallbackEpoch = state.Epoch;
        }

        _ = Task.Run(
            async () =>
            {
                try
                {
                    await Task.Delay(TimeSpan.FromSeconds(30)).ConfigureAwait(false);
                    TunaFallbackProofState? snapshot = null;
                    var shouldLog = false;
                    lock (accelerationGate)
                    {
                        if (TryGetCurrentTunaFallbackProofStateUnsafe(sessionId, out var state) &&
                            state.Epoch == fallbackEpoch &&
                            state.ScreenState is TunaFallbackLaneState.Pending or TunaFallbackLaneState.MediaReady)
                        {
                            state.ScreenState = TunaFallbackLaneState.WaitingForRegularNkn;
                            snapshot = state;
                            shouldLog = true;
                        }
                    }

                    if (!shouldLog || snapshot is null)
                    {
                        return;
                    }

                    LocalOperationalLog.Warn(
                        "NKN.Tuna",
                        $"event=screenshare_tuna_handoff_waiting_for_regular_nkn; session_id={snapshot.SessionId}; fallback_epoch={snapshot.Epoch}; reason={SanitizeLogToken(reason)}; screen_state={FormatTunaFallbackLaneState(snapshot.ScreenState)}");
                    LogMixedFallbackLaneState(snapshot, "screen_waiting_for_regular_nkn");
                }
                catch
                {
                    // Best-effort diagnostics only.
                }
            },
            CancellationToken.None);
    }

    private void MarkScreenTunaHandoffFrameApplied(ScreenShareVideoFrameReadyEventArgs e)
    {
        TunaFallbackProofState? snapshot = null;
        var recovered = false;
        lock (accelerationGate)
        {
            if (!TryGetCurrentTunaFallbackProofStateUnsafe(e.SessionId, out var state) ||
                (state.Lanes & NknAccelerationLaneKind.Screen) != NknAccelerationLaneKind.Screen)
            {
                return;
            }

            state.ScreenFramesApplied++;
            if (state.ScreenState != TunaFallbackLaneState.Recovered)
            {
                state.ScreenState = TunaFallbackLaneState.Recovered;
                recovered = true;
            }

            snapshot = state;
        }

        if (snapshot is null)
        {
            return;
        }

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=screenshare_tuna_handoff_nkn_frame_applied; session_id={snapshot.SessionId}; fallback_epoch={snapshot.Epoch}; stream_epoch={e.StreamEpoch}; frame_id={e.FrameId}; is_keyframe={(e.IsKeyFrame ? 1 : 0)}; reason={snapshot.Reason}");
        if (recovered)
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=screenshare_tuna_handoff_recovered; session_id={snapshot.SessionId}; fallback_epoch={snapshot.Epoch}; stream_epoch={e.StreamEpoch}; frame_id={e.FrameId}; elapsed_ms={Math.Max(0, (long)(DateTimeOffset.UtcNow - snapshot.StartedUtc).TotalMilliseconds)}; reason={snapshot.Reason}");
            LogMixedFallbackLaneState(snapshot, "screen_recovered");
        }
    }

    private bool ShouldIgnoreAcceleratedScreenShareFrameDuringFallback(string? sessionId)
    {
        if (!handlingTunaAcceleratedInboundMessage || IsAccelerationNegotiatedAndHealthy())
        {
            return false;
        }

        lock (accelerationGate)
        {
            return TryGetCurrentTunaFallbackProofStateUnsafe(sessionId, out var state) &&
                   (state.Lanes & NknAccelerationLaneKind.Screen) == NknAccelerationLaneKind.Screen &&
                   state.ScreenState != TunaFallbackLaneState.None;
        }
    }

    private void LogAcceleratedScreenShareFrameIgnoredDuringFallback(string? sessionId, long streamEpoch, long frameId)
    {
        TunaFallbackProofState? snapshot = null;
        var shouldLog = false;
        lock (accelerationGate)
        {
            if (!TryGetCurrentTunaFallbackProofStateUnsafe(sessionId, out var state))
            {
                return;
            }

            shouldLog = ShouldLogTunaFallbackProofMarkerUnsafe(state, "stale_accelerated_screen_frame_ignored", DateTimeOffset.UtcNow);
            snapshot = state;
        }

        if (!shouldLog || snapshot is null)
        {
            return;
        }

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=screenshare_tuna_handoff_stale_accelerated_frame_ignored; session_id={snapshot.SessionId}; fallback_epoch={snapshot.Epoch}; stream_epoch={streamEpoch}; frame_id={frameId}; screen_state={FormatTunaFallbackLaneState(snapshot.ScreenState)}; reason={snapshot.Reason}");
    }

    private static bool IsMixedFallbackLaneSet(NknAccelerationLaneKind lanes)
        => (lanes & NknAccelerationLaneKind.Screen) == NknAccelerationLaneKind.Screen &&
           (lanes & NknAccelerationLaneKind.File) == NknAccelerationLaneKind.File;

    private static string FormatTunaFallbackLaneState(TunaFallbackLaneState state)
        => state switch
        {
            TunaFallbackLaneState.Pending => "pending",
            TunaFallbackLaneState.MediaReady => "media_ready",
            TunaFallbackLaneState.Recovered => "recovered",
            TunaFallbackLaneState.WaitingForRegularNkn => "waiting_for_regular_nkn",
            _ => "none",
        };

    private static void LogMixedFallbackLaneState(TunaFallbackProofState state, string laneState)
    {
        if (!IsMixedFallbackLaneSet(state.Lanes))
        {
            return;
        }

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=tuna_mixed_handoff_lane_state_changed; session_id={state.SessionId}; fallback_epoch={state.Epoch}; reason={state.Reason}; lane_state={SanitizeLogToken(laneState)}; screen_state={FormatTunaFallbackLaneState(state.ScreenState)}; file_state={FormatTunaFallbackLaneState(state.FileState)}; file_v6_epoch_state={FormatTunaFallbackFileV6EpochState(state)}; file_v6_transport_epoch={state.FileV6TransportEpoch}");
    }

    private static string FormatTunaFallbackFileV6EpochState(TunaFallbackProofState state)
        => state.FileV6EpochState is { } epochState
            ? FormatFileTransferV6TransportEpochStateForLog(epochState)
            : state.FileState == TunaFallbackLaneState.Recovered
                ? "unknown"
                : FormatTunaFallbackLaneState(state.FileState);

    private static bool ShouldLogTunaFallbackProofMarkerUnsafe(TunaFallbackProofState state, string key, DateTimeOffset now)
    {
        if (!state.LogStates.TryGetValue(key, out var logState))
        {
            state.LogStates[key] = new TunaFallbackProofLogState
            {
                LastLoggedUtc = now,
            };
            return true;
        }

        logState.CountSinceLastLog++;
        if (logState.CountSinceLastLog < TunaFallbackProofLogEveryFrames &&
            now - logState.LastLoggedUtc < TunaFallbackProofLogWindow)
        {
            return false;
        }

        logState.CountSinceLastLog = 0;
        logState.LastLoggedUtc = now;
        return true;
    }

    private static bool IsTunaFallbackProofFrame(MsgType messageType, NknBridgeChannel channel)
        => (messageType == MsgType.ScreenShareFrame && channel == NknBridgeChannel.Media) ||
           (messageType == MsgType.FileTransferDataFrame && channel == NknBridgeChannel.Bulk);

    private static string MapTunaFallbackProofMessageType(MsgType messageType)
        => messageType switch
        {
            MsgType.ScreenShareFrame => "screenshare_frame",
            MsgType.FileTransferDataFrame => "file_transfer_data_frame",
            _ => MapEnvelopeTypeForDiagnostics(messageType),
        };

    internal static bool ShouldStartTunaFallbackProofForResetReason(string? reason)
    {
        var normalized = SanitizeLogToken(reason);
        if (normalized is "(none)" or
            "dispose" or
            "disposed" or
            "reset_session_tracking" or
            "session_security_state_not_eligible")
        {
            return false;
        }

        if (IsRemoteUserRequestedAccelerationStopReason(normalized))
        {
            return false;
        }

        if (normalized.StartsWith("remote_", StringComparison.Ordinal))
        {
            return true;
        }

        if (IsUserRequestedAccelerationStopReason(normalized))
        {
            return false;
        }

        return normalized is
            "cap_reached" or
            "byte_cap_reached" or
            "duration_cap_reached" or
            "sidecar_read_failed" or
            "sidecar_write_failed" or
            "sidecar_remote_closed" or
            "sidecar_queue_overflow" or
            "sidecar_status_timeout" or
            "sidecar_invalid_status" or
            "sidecar_status_parse_failed" or
            "sidecar_local_ipc_eof" or
            "sidecar_tuna_stream_eof" or
            "sidecar_local_write_failed" or
            "sidecar_tuna_write_failed" or
            "sidecar_byte_cap_reached" or
            "sidecar_duration_cap_reached" or
            "sidecar_remote_byte_cap_reached" or
            "sidecar_remote_duration_cap_reached" or
            "sidecar_provider_timeout" or
            "sidecar_listener_exited" or
            "sidecar_dialer_exited" or
            "sidecar_process_exited" or
            "sidecar_unexpected_exit";
    }

    internal static string NormalizeAccelerationSidecarResetReason(string? reason)
    {
        var normalized = SanitizeLogToken(reason);
        return normalized.StartsWith("sidecar_", StringComparison.Ordinal)
            ? normalized
            : $"sidecar_{normalized}";
    }

    internal static bool ShouldStartImmediateFileTransferFallbackProbe(string? reason)
    {
        var normalized = SanitizeLogToken(reason);
        if (IsUserRequestedAccelerationStopReason(normalized) ||
            IsRemoteUserRequestedAccelerationStopReason(normalized))
        {
            return false;
        }

        return normalized is
            "cap_reached" or
            "byte_cap_reached" or
            "duration_cap_reached" or
            "sidecar_read_failed" or
            "sidecar_write_failed" or
            "sidecar_remote_closed" or
            "sidecar_queue_overflow" or
            "sidecar_status_timeout" or
            "sidecar_invalid_status" or
            "sidecar_status_parse_failed" or
            "sidecar_local_ipc_eof" or
            "sidecar_tuna_stream_eof" or
            "sidecar_local_write_failed" or
            "sidecar_tuna_write_failed" or
            "sidecar_provider_timeout" or
            "sidecar_listener_exited" or
            "sidecar_dialer_exited" or
            "sidecar_process_exited" or
            "sidecar_unexpected_exit" or
            "remote_cap_reached" or
            "remote_byte_cap_reached" or
            "remote_duration_cap_reached" or
            "remote_read_failed" or
            "remote_write_failed" or
            "remote_closed" or
            "remote_sidecar_read_failed" or
            "remote_sidecar_write_failed" or
            "remote_sidecar_remote_closed" or
            "remote_sidecar_local_ipc_eof" or
            "remote_sidecar_tuna_stream_eof" or
            "remote_sidecar_local_write_failed" or
            "remote_sidecar_tuna_write_failed" or
            "sidecar_byte_cap_reached" or
            "sidecar_duration_cap_reached" or
            "sidecar_remote_byte_cap_reached" or
            "sidecar_remote_duration_cap_reached" or
            "remote_sidecar_byte_cap_reached" or
            "remote_sidecar_duration_cap_reached";
    }

    internal static bool ShouldCompleteTunaFallbackProofForResetReason(string? reason)
    {
        var normalized = SanitizeLogToken(reason);
        return normalized is
            "dispose" or
            "disposed" or
            "reset_session_tracking" or
            "session_security_state_not_eligible";
    }

    private static INknAccelerationLane? CreateAccelerationLane(
        NknTunaAccelerationOptions options,
        INknTunaListenerSidecarSupervisor? listenerSupervisor = null)
    {
        if (options is null || !options.Enabled)
        {
            return null;
        }

        return new NknTunaAccelerationLane(options, listenerSupervisor);
    }

    private void OnAccelerationStateChanged(object? sender, AccelerationStateChangedEventArgs e)
    {
        var reason = SanitizeLogToken(e.Reason);
        var diagnostics = accelerationLane?.GetDiagnosticsSnapshot() ?? NknAccelerationLaneDiagnostics.Empty;
        var downSessionId = string.Empty;
        var downLanes = NknAccelerationLaneKind.None;
        var rearmSessionId = string.Empty;
        var rearmRetryReason = string.Empty;
        var rearmRecoveryReason = string.Empty;
        var rearmRequirement =
            RuntimeUnlockRetryDispatchListenerRearmRequirement.None;
        RuntimeUnlockOfferAuthorityBoundary? rearmOfferAuthorityBoundary = null;
        var shouldRearmRuntimeUnlockListener = !e.IsAvailable &&
                                               TryCaptureRuntimeUnlockListenerRearmAfterSidecarDrop(
                                                   e.Reason,
                                                   out rearmSessionId,
                                                   out rearmRetryReason,
                                                   out rearmRecoveryReason,
                                                   out rearmRequirement,
                                                   out rearmOfferAuthorityBoundary);
        var shouldNotifyRemoteDown = !e.IsAvailable &&
                                     ShouldNotifyRemoteAccelerationDown(e.Reason) &&
                                     TryCaptureAccelerationNegotiation(out downSessionId, out downLanes);
        var shouldRetryEarlyDrop = !e.IsAvailable &&
                                   ShouldRetryEarlyAccelerationDrop(e.Reason, diagnostics) &&
                                   TryCaptureAccelerationNegotiation(out _, out _);
        var fallbackSessionId = string.Empty;
        var fallbackLanes = NknAccelerationLaneKind.None;
        var shouldStartFileTransferFallback = !e.IsAvailable &&
                                              ShouldStartTunaFallbackProofForResetReason(e.Reason) &&
                                              TryCaptureAccelerationNegotiationForFallback(
                                                  out fallbackSessionId,
                                                  out fallbackLanes);
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=tuna_acceleration_state_changed; available={(e.IsAvailable ? 1 : 0)}; reason={reason}");
        if (!e.IsAvailable)
        {
            var resetReason = NormalizeAccelerationSidecarResetReason(e.Reason);
            if (!ResetAccelerationNegotiation(
                    resetReason,
                    invalidationKind:
                        RuntimeUnlockInitialActivationReceiveRecoveryHoldInvalidationKind
                            .GenericReset))
            {
                return;
            }

            FailRuntimeUnlockTunaPathLeaseIfCurrent(
                currentSessionSecurityState.SessionId?.Value,
                offerGeneration: 0,
                resetReason,
                failTransaction: false);
            FailRuntimeUnlockTunaPathProbeForSidecarDropIfActive(
                currentSessionSecurityState.SessionId?.Value,
                resetReason);
            if (shouldStartFileTransferFallback)
            {
                StartTunaFallbackProofAndRebindIfNeeded(
                    resetReason,
                    fallbackSessionId,
                    fallbackLanes);
            }

            if (shouldNotifyRemoteDown)
            {
                ScheduleAccelerationDownNotification(downSessionId, downLanes, reason);
            }

            if (shouldRetryEarlyDrop)
            {
                ScheduleAccelerationEarlyDropRetry(reason, diagnostics);
            }

            if (shouldRearmRuntimeUnlockListener)
            {
                ScheduleRuntimeUnlockListenerRearmAfterSidecarDrop(
                    rearmSessionId,
                    rearmRetryReason,
                    rearmRecoveryReason,
                    rearmRequirement,
                    rearmOfferAuthorityBoundary!,
                    reason);
            }

            return;
        }

        NotifyTransportAccelerationStateChanged(e.Reason);
    }

    private bool TryCaptureRuntimeUnlockListenerRearmAfterSidecarDrop(
        string? reason,
        out string sessionId,
        out string retryReason,
        out string recoveryReason,
        out RuntimeUnlockRetryDispatchListenerRearmRequirement
            listenerRearmRequirement,
        out RuntimeUnlockOfferAuthorityBoundary? offerAuthorityBoundary)
    {
        sessionId = currentSessionSecurityState.SessionId?.Value ?? string.Empty;
        retryReason = "runtime_unlock_listener_sidecar_unavailable";
        recoveryReason = NormalizeAccelerationSidecarResetReason(reason);
        listenerRearmRequirement =
            RuntimeUnlockRetryDispatchListenerRearmRequirement.Required;
        offerAuthorityBoundary = null;
        if (string.IsNullOrWhiteSpace(sessionId) ||
            !IsRuntimeUnlockListenerRearmSidecarDropReason(reason) ||
            IsAccelerationUserStoppedForCurrentSession() ||
            accelerationLane is not INknTunaAccelerationSession { CanOfferListener: true } ||
            !IsSessionAccelerationEligible(out _))
        {
            return false;
        }

        var normalizedSessionId = sessionId.Trim();
        lock (accelerationGate)
        {
            if (!TryGetCurrentRuntimeUnlockOfferAuthorityBoundaryUnsafe(
                    out _,
                    out var currentBoundary) ||
                currentBoundary is null ||
                !string.Equals(
                    currentBoundary.SessionId,
                    normalizedSessionId,
                    StringComparison.Ordinal) ||
                !IsRuntimeUnlockOfferAuthorityBoundaryCurrentUnsafe(
                    currentBoundary,
                    allowDispatchObservedSettlement: true))
            {
                return false;
            }

            offerAuthorityBoundary = currentBoundary;
            var transaction = runtimeUnlockTransactionState;
            if (transaction.PathProbeState == RuntimeUnlockPathProbeState.Started &&
                !string.IsNullOrWhiteSpace(transaction.PathProbeId) &&
                string.Equals(transaction.SessionId, normalizedSessionId, StringComparison.Ordinal))
            {
                retryReason = RuntimeUnlockProbeSidecarClosedRetryReason;
                recoveryReason = RuntimeUnlockProbeSidecarClosedRetryReason;
                listenerRearmRequirement =
                    RuntimeUnlockRetryDispatchListenerRearmRequirement
                        .RequiredBeforeDispatch;
            }
        }

        return HasActiveRegularV4FileTransferRouteHint(normalizedSessionId) ||
               HasActivePostTunaFallbackFileTransferRouteHint(normalizedSessionId) ||
               HasActiveFileTransferDataSessionForSession(normalizedSessionId);
    }

    private static bool IsRuntimeUnlockListenerRearmSidecarDropReason(string? reason)
    {
        var normalized = SanitizeLogToken(reason);
        return normalized is
            "read_failed" or
            "write_failed" or
            "remote_closed" or
            "sidecar_read_failed" or
            "sidecar_write_failed" or
            "sidecar_remote_closed" or
            "sidecar_local_ipc_eof" or
            "sidecar_tuna_stream_eof" or
            "sidecar_local_write_failed" or
            "sidecar_tuna_write_failed" or
            "sidecar_listener_exited" or
            "sidecar_process_exited" or
            "sidecar_unexpected_exit";
    }

    private void ScheduleRuntimeUnlockListenerRearmAfterSidecarDrop(
        string sessionId,
        string retryReason,
        string recoveryReason,
        RuntimeUnlockRetryDispatchListenerRearmRequirement
            listenerRearmRequirement,
        RuntimeUnlockOfferAuthorityBoundary offerAuthorityBoundary,
        string trigger)
    {
        var normalizedSessionId = string.IsNullOrWhiteSpace(sessionId) ? string.Empty : sessionId.Trim();
        if (string.IsNullOrWhiteSpace(normalizedSessionId))
        {
            return;
        }

        LocalOperationalLog.Warn(
            "NKN.Tuna",
            $"event=tuna_acceleration_runtime_unlock_listener_rearm_after_sidecar_drop; session_id={SanitizeLogToken(normalizedSessionId)}; authority_mode={SanitizeLogToken(offerAuthorityBoundary.Mode.ToString())}; retry_reason={SanitizeLogToken(retryReason)}; recovery_reason={SanitizeLogToken(recoveryReason)}; trigger={SanitizeLogToken(trigger)}");
        if (offerAuthorityBoundary.Mode ==
            RuntimeUnlockOfferAuthorityMode.InitialActivation)
        {
            var scheduled = ScheduleRuntimeUnlockOfferAuthorityRetry(
                retryReason,
                offerAuthorityBoundary,
                expectedInstallReceipt: null);
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=tuna_acceleration_runtime_unlock_listener_rearm_initial_offer_decided; session_id={SanitizeLogToken(normalizedSessionId)}; offer_generation={offerAuthorityBoundary.OfferGeneration}; retry_scheduled={(scheduled ? 1 : 0)}; decision_reason={(scheduled ? "initial_activation_retry_scheduled" : "initial_activation_retry_rejected")}");
            return;
        }

        lock (accelerationGate)
        {
            if (!TryGetRetainedInstalledRuntimeUnlockOfferAuthorityUnsafe(
                    offerAuthorityBoundary,
                    out _))
            {
                LogRuntimeUnlockOfferAuthorityBoundaryDecision(
                    offerAuthorityBoundary,
                    "listener_rearm_after_sidecar_drop",
                    accepted: false,
                    "installed_retry_offer_authority_not_retained");
                return;
            }
        }

        if (listenerRearmRequirement ==
            RuntimeUnlockRetryDispatchListenerRearmRequirement
                .RequiredBeforeDispatch)
        {
            LocalOperationalLog.Warn(
                "NKN.Tuna",
                $"event=runtime_unlock_precommit_probe_sidecar_rearm_scheduled; session_id={SanitizeLogToken(normalizedSessionId)}; retry_reason={SanitizeLogToken(retryReason)}; recovery_reason={SanitizeLogToken(recoveryReason)}; trigger={SanitizeLogToken(trigger)}; decision_reason=sidecar_closed_requires_listener_rearm");
        }

        RetirePendingAccelerationAnswerAckForRuntimeUnlockListenerRearm(
            normalizedSessionId,
            recoveryReason,
            trigger);
        ArmRuntimeUnlockRetryAfterRecovery(
            0,
            normalizedSessionId,
            retryReason,
            recoveryReason,
            requiresLocalListenerRetry: true,
            listenerRearmRequirement,
            offerAuthorityBoundary);
    }

    private void ScheduleRuntimeUnlockPreCommitProbeSidecarListenerRearm(
        RuntimeUnlockRecoveryRetryState state,
        string trigger,
        RuntimeUnlockRetryDispatchInstallReceipt? expectedInstallReceipt = null)
    {
        if (!ValidateRuntimeUnlockRetryDispatchInstallReceiptBoundary(
                expectedInstallReceipt,
                "listener_rearm_schedule"))
        {
            return;
        }

        var sessionId = string.IsNullOrWhiteSpace(state.SessionId) ? string.Empty : state.SessionId.Trim();
        var retryReason = SanitizeLogToken(state.RetryReason);
        var recoveryReason = SanitizeLogToken(state.RecoveryReason);
        var contractGeneration = state.ContractGeneration;
        var retiredOfferGeneration = state.RetiredOfferGeneration;
        if (string.IsNullOrWhiteSpace(sessionId))
        {
            return;
        }

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=runtime_unlock_precommit_probe_sidecar_rearm_scheduled; session_id={SanitizeLogToken(sessionId)}; transfer_id={SanitizeLogToken(state.TransferId ?? "(none)")}; retired_generation={retiredOfferGeneration}; contract_generation={contractGeneration}; retry_reason={retryReason}; recovery_reason={recoveryReason}; trigger={SanitizeLogToken(trigger)}; decision_reason=listener_rearm_required_before_dispatch_authority");

        _ = Task.Run(
            async () =>
            {
                try
                {
                    await Task.Delay(AccelerationListenerReadyRetryDelay, CancellationToken.None).ConfigureAwait(false);
                    if (!ValidateRuntimeUnlockRetryDispatchInstallReceiptBoundary(
                            expectedInstallReceipt,
                            "listener_rearm_delay"))
                    {
                        return;
                    }

                    if (disposed)
                    {
                        return;
                    }

                    if (!string.Equals(currentSessionSecurityState.SessionId?.Value, sessionId, StringComparison.Ordinal) ||
                        accelerationLane is not INknTunaAccelerationSession tunaSession ||
                        string.IsNullOrWhiteSpace(remoteEndpoint) ||
                        !IsSessionAccelerationEligible(out _))
                    {
                        FailRuntimeUnlockRecoveryContractIfActive(sessionId, RuntimeUnlockProbeSidecarClosedListenerRearmFailedReason);
                        LocalOperationalLog.Warn(
                            "NKN.Tuna",
                            $"event=session_recovery_contract_listener_rearm_failed; session_id={SanitizeLogToken(sessionId)}; reason={RuntimeUnlockProbeSidecarClosedListenerRearmFailedReason}; trigger=precommit_probe_sidecar_rearm; decision_reason=listener_rearm_context_unavailable");
                        return;
                    }

                    if (!TryCaptureCurrentRuntimeUnlockFileTransferOwnerAuthority(
                            sessionId,
                            out var listenerRearmOwnerAuthority,
                            out var listenerRearmOwnerRejectionReason) ||
                        (!string.IsNullOrWhiteSpace(state.TransferId) &&
                         !string.Equals(
                             state.TransferId,
                             listenerRearmOwnerAuthority.TransferId,
                             StringComparison.Ordinal)))
                    {
                        var rejectionReason = string.Equals(listenerRearmOwnerRejectionReason, "accepted", StringComparison.Ordinal)
                            ? "runtime_unlock_listener_rearm_transfer_owner_mismatch"
                            : listenerRearmOwnerRejectionReason;
                        LogRuntimeUnlockFileTransferOwnerRejectedBeforePathLease(
                            sessionId,
                            retryReason,
                            rejectionReason);
                        FailRuntimeUnlockRecoveryContractIfActive(
                            sessionId,
                            "runtime_unlock_filetransfer_owner_missing_before_path_lease");
                        return;
                    }

                    LogRuntimeUnlockFileTransferOwnerAcceptedBeforePathLease(
                        listenerRearmOwnerAuthority,
                        retryReason);

                    LocalOperationalLog.Info(
                        "NKN.Tuna",
                        $"event=runtime_unlock_precommit_probe_sidecar_rearm_started; session_id={SanitizeLogToken(sessionId)}; retired_generation={retiredOfferGeneration}; contract_generation={contractGeneration}; retry_reason={retryReason}; trigger={SanitizeLogToken(trigger)}; decision_reason=listener_rearm_required_before_dispatch_authority");

                    RuntimeUnlockTunaPathLeaseSnapshot lease;
                    lock (accelerationGate)
                    {
                        var current = runtimeUnlockRecoveryRetryState;
                        if (current is null ||
                            current.ContractState is SessionRecoveryContractState.Completed or SessionRecoveryContractState.Failed ||
                            current.ContractGeneration != contractGeneration ||
                            current.RetiredOfferGeneration != retiredOfferGeneration ||
                            current.ListenerRearmCompleted ||
                            !string.Equals(current.SessionId, sessionId, StringComparison.Ordinal))
                        {
                            return;
                        }

                        if (expectedInstallReceipt is { } receipt &&
                            !TryValidateRuntimeUnlockRetryDispatchInstallReceiptCurrentUnsafe(
                                current,
                                receipt,
                                out var receiptRejectionReason))
                        {
                            LogRuntimeUnlockRetryDispatchInstallRejected(
                                receipt,
                                CaptureRuntimeUnlockRetryDispatchInstallTelemetryUnsafe(current),
                                RuntimeUnlockRetryDispatchInstallStatus.Rejected,
                                $"{receiptRejectionReason}_listener_rearm_start");
                            return;
                        }

                        lease = StartRuntimeUnlockTunaPathLeaseUnsafe(
                            sessionId,
                            listenerRearmOwnerAuthority.TransferId,
                            ResolvePayerDecisionIdForNegotiation(retryReason),
                            retryReason);
                    }

                    if (!await tunaSession.EnsureListenerSidecarConnectedAsync(remoteEndpoint, CancellationToken.None).ConfigureAwait(false) ||
                        string.IsNullOrWhiteSpace(tunaSession.LocalTunaAddress))
                    {
                        FailRuntimeUnlockTunaPathLeaseIfCurrent(
                            sessionId,
                            offerGeneration: 0,
                            RuntimeUnlockProbeSidecarClosedListenerRearmFailedReason,
                            failTransaction: false);
                        FailRuntimeUnlockRecoveryContractIfActive(sessionId, RuntimeUnlockProbeSidecarClosedListenerRearmFailedReason);
                        LocalOperationalLog.Warn(
                            "NKN.Tuna",
                            $"event=session_recovery_contract_listener_rearm_failed; session_id={SanitizeLogToken(sessionId)}; reason={RuntimeUnlockProbeSidecarClosedListenerRearmFailedReason}; trigger=precommit_probe_sidecar_rearm; decision_reason=listener_sidecar_unavailable");
                        return;
                    }

                    if (!TryCaptureCurrentRuntimeUnlockFileTransferOwnerAuthority(
                            sessionId,
                            out var currentListenerRearmOwnerAuthority,
                            out var currentListenerRearmOwnerRejectionReason) ||
                        !Equals(currentListenerRearmOwnerAuthority, listenerRearmOwnerAuthority))
                    {
                        var rejectionReason = string.Equals(
                                currentListenerRearmOwnerRejectionReason,
                                "accepted",
                                StringComparison.Ordinal)
                            ? "current_filetransfer_owner_changed_after_listener_rearm"
                            : currentListenerRearmOwnerRejectionReason;
                        LogRuntimeUnlockFileTransferOwnerRejectedBeforeOfferDispatch(
                            sessionId,
                            listenerRearmOwnerAuthority.TransferId,
                            retryReason,
                            rejectionReason);
                        FailRuntimeUnlockTunaPathLeaseIfCurrent(
                            sessionId,
                            offerGeneration: 0,
                            rejectionReason,
                            failTransaction: false);
                        FailRuntimeUnlockRecoveryContractIfActive(sessionId, rejectionReason);
                        return;
                    }

                    if (!ValidateRuntimeUnlockRetryDispatchInstallReceiptBoundary(
                            expectedInstallReceipt,
                            "listener_rearm_completion"))
                    {
                        return;
                    }

                    MarkRuntimeUnlockTunaPathLeaseListenerReady(lease, sessionId, retryReason);
                    MarkRuntimeUnlockRecoveryContractListenerRearmCompleted(
                        sessionId,
                        "precommit_probe_sidecar_rearm",
                        expectedInstallReceipt);
                    NotifyTransportAccelerationStateChanged("listener_ready");
                }
                catch (Exception ex) when (ex is not OperationCanceledException)
                {
                    FailRuntimeUnlockRecoveryContractIfActive(sessionId, RuntimeUnlockProbeSidecarClosedListenerRearmFailedReason);
                    LocalOperationalLog.Warn(
                        "NKN.Tuna",
                        $"event=session_recovery_contract_listener_rearm_failed; session_id={SanitizeLogToken(sessionId)}; reason={RuntimeUnlockProbeSidecarClosedListenerRearmFailedReason}; trigger=precommit_probe_sidecar_rearm; error={ex.GetType().Name}");
                }
            },
            CancellationToken.None);
    }

    private void OnAccelerationMessageReceived(object? sender, NknIncomingMessage e)
    {
        if (disposed || e.Payload.Length == 0)
        {
            return;
        }

        var source = ResolveSyntheticAccelerationSource(e.Channel);
        if (string.IsNullOrWhiteSpace(source))
        {
            NknRuntimeDiagnostics.SetLastEnvelopeDropReason("tuna_source_unavailable");
            LocalOperationalLog.Warn("NKN.Tuna", $"event=tuna_accelerated_frame_rejected; reason=source_unavailable; channel={MapBridgeChannel(e.Channel)}");
            return;
        }

        var previousAcceleratedInbound = handlingTunaAcceleratedInboundMessage;
        handlingTunaAcceleratedInboundMessage = true;
        try
        {
            OnClientMessageReceived(
                sender,
                new NknIncomingMessage(
                    source,
                    e.Payload,
                    isTopic: false,
                    topic: null,
                    channel: e.Channel,
                    bridgeIngressObservedUtcMs: e.BridgeIngressObservedUtcMs,
                    bridgeMessageObservedUtcMs: e.BridgeMessageObservedUtcMs,
                    binaryFrameDecodedUtcMs: e.BinaryFrameDecodedUtcMs,
                    socketDataEventEmittedUtcMs: e.SocketDataEventEmittedUtcMs,
                    wsReceiverWriteEnteredUtcMs: e.WsReceiverWriteEnteredUtcMs,
                    wsMessageEmittedUtcMs: e.WsMessageEmittedUtcMs,
                    sdkHandleMsgEnteredUtcMs: e.SdkHandleMsgEnteredUtcMs,
                    clientMessageDispatchUtcMs: e.ClientMessageDispatchUtcMs,
                    multiClientMessageDispatchUtcMs: e.MultiClientMessageDispatchUtcMs));
        }
        finally
        {
            handlingTunaAcceleratedInboundMessage = previousAcceleratedInbound;
        }
    }

    private string? ResolveSyntheticAccelerationSource(NknBridgeChannel channel)
        => channel switch
        {
            NknBridgeChannel.Media => ResolveExpectedRemoteMediaPeerAddressForCurrentSession(),
            NknBridgeChannel.Bulk => ResolveExpectedRemoteBulkPeerAddressForCurrentSession(),
            _ => ResolveExpectedRemotePeerAddressForCurrentSession(),
        };

    private void MarkPendingRuntimeUnlockAccelerationNegotiation(
        string reason,
        RuntimeUnlockRetryDispatchInstallReceipt? expectedInstallReceipt = null,
        RuntimeUnlockOfferAuthorityMode authorityMode =
            RuntimeUnlockOfferAuthorityMode.InitialActivation)
    {
        var normalizedReason = SanitizeLogToken(reason);
        lock (accelerationGate)
        {
            _ = TryBindPendingRuntimeUnlockAccelerationNegotiationUnsafe(
                normalizedReason,
                expectedInstallReceipt,
                authorityMode);
        }
    }

    private bool TryQueueRuntimeUnlockNegotiationBehindPendingGeneration(
        string reason,
        string waitReason,
        RuntimeUnlockRetryDispatchInstallReceipt? expectedInstallReceipt = null,
        RuntimeUnlockOfferAuthorityMode authorityMode =
            RuntimeUnlockOfferAuthorityMode.InitialActivation)
    {
        var normalizedReason = SanitizeLogToken(reason);
        bool hasOffer;
        bool hasAnswerAck;
        lock (accelerationGate)
        {
            hasOffer = !string.IsNullOrWhiteSpace(outboundAccelerationOfferNonce);
            hasAnswerAck = !string.IsNullOrWhiteSpace(pendingAccelerationAnswerAckNonce);
            if (!hasOffer && !hasAnswerAck)
            {
                return false;
            }

            if (!TryBindPendingRuntimeUnlockAccelerationNegotiationUnsafe(
                    normalizedReason,
                    expectedInstallReceipt,
                    authorityMode))
            {
                return false;
            }
        }

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=tuna_acceleration_runtime_unlock_queued_behind_pending_generation; reason={normalizedReason}; authority_mode={SanitizeLogToken(authorityMode.ToString())}; wait_reason={SanitizeLogToken(waitReason)}; has_offer={(hasOffer ? 1 : 0)}; has_answer_ack={(hasAnswerAck ? 1 : 0)}");
        return true;
    }

    private static FileTransferDirection?
        ResolveFileTransferFallbackV6ProofBootstrapDirection(string proofKind)
        => proofKind switch
        {
            "file_transfer_v4_state_frame_received" or
            "file_transfer_v4_manifest_received" or
            "file_transfer_v4_complete_frame_received" =>
                FileTransferDirection.Outbound,
            "file_transfer_v4_state_frame_sent" or
            "file_transfer_v4_manifest_sent" or
            "file_transfer_v4_complete_frame_sent" =>
                FileTransferDirection.Inbound,
            "file_transfer_v4_bulk_frame_received" =>
                FileTransferDirection.Inbound,
            "file_transfer_v4_bulk_frame_sent" =>
                FileTransferDirection.Outbound,
            _ => null,
        };

    private void PublishFileTransferFallbackV6ProofBootstrapEvaluation(
        string? sessionId,
        FileTransferDirection? direction,
        long fallbackEpoch,
        string proofKind,
        string source)
    {
        var subscriber = fallbackV6ProofBootstrapEvaluationRequested;
        if (subscriber is null ||
            string.IsNullOrWhiteSpace(sessionId) ||
            direction is not (FileTransferDirection.Outbound or FileTransferDirection.Inbound) ||
            fallbackEpoch <= 0)
        {
            return;
        }

        var key = $"{sessionId}|{direction}|{fallbackEpoch}";
        lock (fileTransferFallbackProofGate)
        {
            if (!fileTransferFallbackV6ProofBootstrapObservationKeys.Add(key))
            {
                return;
            }
        }

        var evaluation = new FileTransferFallbackV6ProofBootstrapEvaluation(
            sessionId.Trim(),
            direction.Value,
            fallbackEpoch,
            fallbackEpoch,
            source,
            proofKind,
            DateTimeOffset.UtcNow.ToUnixTimeMilliseconds());
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=filetransfer_fallback_v6_proof_bootstrap_observed; session_id={SanitizeLogToken(evaluation.SessionId)}; direction={FormatFileTransferDirection(evaluation.Direction)}; observation_generation={evaluation.ObservationGeneration}; fallback_epoch={evaluation.FallbackEpoch}; proof_kind={SanitizeLogToken(evaluation.ProofKind)}; source={SanitizeLogToken(evaluation.Source)}; authority_effect=coordinator_evaluation_only");
        try
        {
            subscriber.Invoke(
                this,
                new FileTransferFallbackV6ProofBootstrapEvaluationRequestedEventArgs(
                    evaluation));
        }
        catch (Exception ex)
        {
            LocalOperationalLog.Warn(
                "NKN.Tuna",
                $"event=filetransfer_fallback_v6_proof_bootstrap_observation_failed; session_id={SanitizeLogToken(evaluation.SessionId)}; direction={FormatFileTransferDirection(evaluation.Direction)}; fallback_epoch={evaluation.FallbackEpoch}; error={SanitizeLogToken(ex.GetType().Name)}");
        }
    }

    private bool TryBindPendingRuntimeUnlockAccelerationNegotiationUnsafe(
        string normalizedReason,
        RuntimeUnlockRetryDispatchInstallReceipt? expectedInstallReceipt,
        RuntimeUnlockOfferAuthorityMode authorityMode)
    {
        if (!TryValidatePendingRuntimeUnlockOfferAuthorityUnsafe(
                authorityMode,
                expectedInstallReceipt,
                out _))
        {
            return false;
        }

        if (pendingRuntimeUnlockAccelerationNegotiation != 0 &&
            pendingRuntimeUnlockAccelerationNegotiationAuthorityMode ==
                RuntimeUnlockOfferAuthorityMode.InstalledRetry &&
            authorityMode == RuntimeUnlockOfferAuthorityMode.InitialActivation)
        {
            return true;
        }

        pendingRuntimeUnlockAccelerationNegotiationReason = normalizedReason;
        pendingRuntimeUnlockAccelerationNegotiationAuthorityMode = authorityMode;
        pendingRuntimeUnlockAccelerationNegotiationInstallReceipt =
            authorityMode == RuntimeUnlockOfferAuthorityMode.InstalledRetry
                ? expectedInstallReceipt
                : null;
        pendingRuntimeUnlockAccelerationNegotiation = 1;
        return true;
    }

    private bool TryConsumePendingRuntimeUnlockAccelerationNegotiation(
        out string reason,
        out RuntimeUnlockRetryDispatchInstallReceipt? expectedInstallReceipt,
        out RuntimeUnlockOfferAuthorityMode authorityMode)
    {
        reason = "runtime_unlock";
        authorityMode = RuntimeUnlockOfferAuthorityMode.InitialActivation;
        lock (accelerationGate)
        {
            return TryConsumePendingRuntimeUnlockAccelerationNegotiationUnsafe(
                out reason,
                out expectedInstallReceipt,
                out authorityMode);
        }
    }

    private bool TryConsumePendingRuntimeUnlockAccelerationNegotiationUnsafe(
        out string reason,
        out RuntimeUnlockRetryDispatchInstallReceipt? expectedInstallReceipt,
        out RuntimeUnlockOfferAuthorityMode authorityMode)
    {
        reason = "runtime_unlock";
        expectedInstallReceipt = null;
        authorityMode = RuntimeUnlockOfferAuthorityMode.InitialActivation;
        if (pendingRuntimeUnlockAccelerationNegotiation == 0)
        {
            return false;
        }

        pendingRuntimeUnlockAccelerationNegotiation = 0;
        if (!string.IsNullOrWhiteSpace(pendingRuntimeUnlockAccelerationNegotiationReason))
        {
            reason = pendingRuntimeUnlockAccelerationNegotiationReason;
        }

        authorityMode =
            pendingRuntimeUnlockAccelerationNegotiationAuthorityMode ??
            RuntimeUnlockOfferAuthorityMode.InitialActivation;
        expectedInstallReceipt = pendingRuntimeUnlockAccelerationNegotiationInstallReceipt;
        pendingRuntimeUnlockAccelerationNegotiationReason = null;
        pendingRuntimeUnlockAccelerationNegotiationAuthorityMode = null;
        pendingRuntimeUnlockAccelerationNegotiationInstallReceipt = null;
        return true;
    }

    private void SchedulePendingRuntimeUnlockAccelerationNegotiationAfterCurrentOperation(string trigger)
    {
        if (ShouldHoldPendingRuntimeUnlockAccelerationNegotiationForRegularV4FrontierRepair(out var holdReason, out var blockerReason, out var blockerEvidenceAgeMs))
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=tuna_acceleration_runtime_unlock_pending_negotiation_held_by_regular_v4_frontier_repair; reason={SanitizeLogToken(holdReason)}; trigger={SanitizeLogToken(trigger)}; blocker_reason={SanitizeLogToken(blockerReason)}; blocker_evidence_age_ms={blockerEvidenceAgeMs}; decision_reason=awaiting_regular_v4_frontier_repair_settlement");
            SchedulePendingRuntimeUnlockRegularV4FrontierRepairRecheck(
                holdReason,
                blockerReason,
                blockerEvidenceAgeMs,
                trigger);
            return;
        }

        if (!TryConsumePendingRuntimeUnlockAccelerationNegotiation(
                out var pendingReason,
                out var expectedInstallReceipt,
                out var authorityMode))
        {
            return;
        }

        ScheduleRuntimeUnlockAccelerationNegotiationWake(
            pendingReason,
            trigger,
            expectedInstallReceipt,
            authorityMode);
    }

    private void SchedulePendingRuntimeUnlockAccelerationNegotiationAfterCurrentOperationUnsafe(string trigger)
    {
        if (ShouldHoldPendingRuntimeUnlockAccelerationNegotiationForRegularV4FrontierRepair(out var holdReason, out var blockerReason, out var blockerEvidenceAgeMs))
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=tuna_acceleration_runtime_unlock_pending_negotiation_held_by_regular_v4_frontier_repair; reason={SanitizeLogToken(holdReason)}; trigger={SanitizeLogToken(trigger)}; blocker_reason={SanitizeLogToken(blockerReason)}; blocker_evidence_age_ms={blockerEvidenceAgeMs}; decision_reason=awaiting_regular_v4_frontier_repair_settlement");
            SchedulePendingRuntimeUnlockRegularV4FrontierRepairRecheck(
                holdReason,
                blockerReason,
                blockerEvidenceAgeMs,
                trigger);
            return;
        }

        if (!TryConsumePendingRuntimeUnlockAccelerationNegotiationUnsafe(
                out var pendingReason,
                out var expectedInstallReceipt,
                out var authorityMode))
        {
            return;
        }

        ScheduleRuntimeUnlockAccelerationNegotiationWake(
            pendingReason,
            trigger,
            expectedInstallReceipt,
            authorityMode);
    }

    private void ScheduleRuntimeUnlockAccelerationNegotiationWake(
        string pendingReason,
        string trigger,
        RuntimeUnlockRetryDispatchInstallReceipt? expectedInstallReceipt,
        RuntimeUnlockOfferAuthorityMode authorityMode)
    {
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=tuna_acceleration_runtime_unlock_pending_negotiation_wake_scheduled; reason={SanitizeLogToken(pendingReason)}; authority_mode={SanitizeLogToken(authorityMode.ToString())}; trigger={SanitizeLogToken(trigger)}");
        _ = Task.Run(
            () => ScheduleAccelerationNegotiationIfEligible(
                pendingReason,
                expectedInstallReceipt,
                requireRuntimeUnlockRetryDispatchInstall:
                    authorityMode == RuntimeUnlockOfferAuthorityMode.InstalledRetry,
                runtimeUnlockActivation: true),
            CancellationToken.None);
    }

    private void SchedulePendingRuntimeUnlockRegularV4FrontierRepairRecheck(
        string pendingReason,
        string blockerReason,
        long blockerEvidenceAgeMs,
        string trigger)
    {
        if (!IsRegularV4PressureActivationSendBlocker(blockerReason))
        {
            return;
        }

        if (Interlocked.CompareExchange(ref pendingRuntimeUnlockRegularV4FrontierRepairRecheckScheduled, 1, 0) != 0)
        {
            return;
        }

        const long evidenceFreshnessWindowMs = 20_000;
        var evidenceFresh = blockerEvidenceAgeMs <= evidenceFreshnessWindowMs;
        var delayMs = evidenceFresh
            ? Math.Clamp(evidenceFreshnessWindowMs - blockerEvidenceAgeMs + 50, 50, 30_000)
            : 50;
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=tuna_acceleration_runtime_unlock_pending_negotiation_recheck_scheduled; reason={SanitizeLogToken(pendingReason)}; trigger={SanitizeLogToken(trigger)}; blocker_reason={SanitizeLogToken(blockerReason)}; blocker_evidence_age_ms={Math.Max(0, blockerEvidenceAgeMs)}; blocker_evidence_fresh={(evidenceFresh ? 1 : 0)}; delay_ms={delayMs}; decision_reason=regular_v4_frontier_repair_blocker_bounded_recheck");

        _ = Task.Run(
            async () =>
            {
                try
                {
                    await Task.Delay(TimeSpan.FromMilliseconds(delayMs)).ConfigureAwait(false);
                }
                finally
                {
                    Interlocked.Exchange(ref pendingRuntimeUnlockRegularV4FrontierRepairRecheckScheduled, 0);
                }

                if (disposed)
                {
                    return;
                }

                SchedulePendingRuntimeUnlockAccelerationNegotiationAfterCurrentOperation(
                    "regular_v4_frontier_repair_blocker_recheck");
            },
            CancellationToken.None);
    }

    private bool ShouldHoldPendingRuntimeUnlockAccelerationNegotiationForRegularV4FrontierRepair(
        out string pendingReason,
        out string blockerReason,
        out long blockerEvidenceAgeMs)
    {
        pendingReason = "runtime_unlock";
        blockerReason = string.Empty;
        blockerEvidenceAgeMs = 0;

        lock (accelerationGate)
        {
            if (pendingRuntimeUnlockAccelerationNegotiation == 0)
            {
                return false;
            }

            if (!string.IsNullOrWhiteSpace(pendingRuntimeUnlockAccelerationNegotiationReason))
            {
                pendingReason = pendingRuntimeUnlockAccelerationNegotiationReason;
            }
        }

        var sessionId = currentSessionSecurityState.SessionId?.Value;
        if (string.IsNullOrWhiteSpace(sessionId) ||
            !HasActiveRegularV4FileTransferRouteHint(sessionId) ||
            HasActivePostTunaFallbackFileTransferRouteHint(sessionId))
        {
            return false;
        }

        var overrideBlocker = RuntimeUnlockRegularV4RepairPressureBlockerOverrideForTests?.Invoke(this);
        if (overrideBlocker is { HasBlocker: true })
        {
            blockerReason = SanitizeLogToken(overrideBlocker.Value.Reason);
            blockerEvidenceAgeMs = Math.Max(0, overrideBlocker.Value.EvidenceAgeMs);
        }
        else if (client is not RealNknClientAdapter realClient ||
                 !realClient.TryGetFileTransferRegularV4ActivationSendBlocker(
                     out blockerReason,
                     out blockerEvidenceAgeMs,
                     includeRegularV4Pressure: true))
        {
            return false;
        }

        return IsRegularV4PressureActivationSendBlocker(blockerReason);
    }

    private void ClearPendingRuntimeUnlockAccelerationNegotiation()
    {
        lock (accelerationGate)
        {
            pendingRuntimeUnlockAccelerationNegotiation = 0;
            pendingRuntimeUnlockAccelerationNegotiationReason = null;
            pendingRuntimeUnlockAccelerationNegotiationAuthorityMode = null;
            pendingRuntimeUnlockAccelerationNegotiationInstallReceipt = null;
        }
    }

    private void ScheduleAccelerationNegotiationIfEligible(
        string reason,
        RuntimeUnlockRetryDispatchInstallReceipt? expectedInstallReceipt = null,
        bool requireRuntimeUnlockRetryDispatchInstall = false,
        bool runtimeUnlockActivation = false)
    {
        runtimeUnlockActivation |= requireRuntimeUnlockRetryDispatchInstall;
        var initialRuntimeUnlockActivation =
            runtimeUnlockActivation &&
            !requireRuntimeUnlockRetryDispatchInstall;
        if (!initialRuntimeUnlockActivation &&
            !ValidateRuntimeUnlockRetryDispatchInstallReceiptBoundary(
                expectedInstallReceipt,
                "negotiation_schedule",
                requireInstalledReceipt:
                    requireRuntimeUnlockRetryDispatchInstall))
        {
            return;
        }

        if (disposed ||
            accelerationLane is not INknTunaAccelerationSession ||
            IsAccelerationUserStoppedForCurrentSession() ||
            !IsSessionAccelerationEligible(out _))
        {
            return;
        }

        if (HasPendingOutboundAccelerationOffer() || HasPendingAccelerationAnswerAck())
        {
            if (runtimeUnlockActivation &&
                TryQueueRuntimeUnlockNegotiationBehindPendingGeneration(
                    reason,
                    "schedule_pending_generation",
                    expectedInstallReceipt,
                    requireRuntimeUnlockRetryDispatchInstall
                        ? RuntimeUnlockOfferAuthorityMode.InstalledRetry
                        : RuntimeUnlockOfferAuthorityMode.InitialActivation))
            {
                return;
            }

            return;
        }

        if (Interlocked.CompareExchange(ref accelerationNegotiationScheduled, 1, 0) != 0)
        {
            if (runtimeUnlockActivation)
            {
                if (requireRuntimeUnlockRetryDispatchInstall &&
                    TrySupersedeStaleActiveNegotiationForRuntimeUnlockRecoveryContract() &&
                    Interlocked.CompareExchange(ref accelerationNegotiationScheduled, 1, 0) == 0)
                {
                    var operationPayerDecisionId = ResolvePayerDecisionIdForNegotiation(reason);
                    var operationGeneration = Interlocked.Increment(
                        ref runtimeUnlockPostTunaFallbackActivationOperationNextGeneration);
                    NotifyTransportAccelerationStateChanged($"negotiation_scheduled_{reason}");
                    LogRuntimeUnlockPostTunaFallbackActivationDisposition(
                        operationGeneration,
                        operationPayerDecisionId,
                        reason,
                        expectedInstallReceipt,
                        "started",
                        "negotiation_task_queued");
                    _ = Task.Run(
                        async () =>
                        {
                            var disposition = "completed";
                            var dispositionReason = "negotiation_operation_completed";
                            try
                            {
                                if (!MarkRuntimeUnlockRecoveryContractRetryDispatched(
                                        reason,
                                        expectedInstallReceipt,
                                        requireRuntimeUnlockRetryDispatchInstall))
                                {
                                    (disposition, dispositionReason) =
                                        ResolveRuntimeUnlockPostTunaFallbackActivationDisposition(
                                            expectedInstallReceipt);
                                    return;
                                }

                                await TrySendAccelerationOfferAsync(
                                        reason,
                                        operationPayerDecisionId,
                                        CancellationToken.None,
                                        expectedInstallReceipt,
                                        requireRuntimeUnlockRetryDispatchInstall,
                                        runtimeUnlockActivation)
                                    .ConfigureAwait(false);
                                (disposition, dispositionReason) =
                                    requireRuntimeUnlockRetryDispatchInstall
                                        ? ResolveRuntimeUnlockPostTunaFallbackActivationDispositionAfterOffer(
                                            expectedInstallReceipt)
                                        : (
                                            "completed",
                                            "initial_activation_offer_flow_completed");
                            }
                            catch (Exception ex) when (ex is not OperationCanceledException)
                            {
                                disposition = "rejected";
                                dispositionReason = $"negotiation_failed_{SanitizeLogToken(ex.GetType().Name)}";
                                LocalOperationalLog.Warn(
                                    "NKN.Tuna",
                                    $"event=tuna_acceleration_negotiation_failed; reason={SanitizeLogToken(reason)}; error={ex.GetType().Name}");
                            }
                            finally
                            {
                                LogRuntimeUnlockPostTunaFallbackActivationDisposition(
                                    operationGeneration,
                                    operationPayerDecisionId,
                                    reason,
                                    expectedInstallReceipt,
                                    disposition,
                                    dispositionReason);
                                Interlocked.Exchange(ref accelerationNegotiationScheduled, 0);
                                SchedulePendingRuntimeUnlockAccelerationNegotiationAfterCurrentOperation("negotiation_complete");
                            }
                        },
                        CancellationToken.None);
                    return;
                }

                MarkPendingRuntimeUnlockAccelerationNegotiation(
                    reason,
                    expectedInstallReceipt,
                    requireRuntimeUnlockRetryDispatchInstall
                        ? RuntimeUnlockOfferAuthorityMode.InstalledRetry
                        : RuntimeUnlockOfferAuthorityMode.InitialActivation);
                if (requireRuntimeUnlockRetryDispatchInstall)
                {
                    MarkRuntimeUnlockRecoveryContractQueuedBehindActiveNegotiation(reason);
                }
                LocalOperationalLog.Info(
                    "NKN.Tuna",
                    $"event=tuna_acceleration_runtime_unlock_queued_behind_active_negotiation; reason={SanitizeLogToken(reason)}; authority_mode={SanitizeLogToken((requireRuntimeUnlockRetryDispatchInstall ? RuntimeUnlockOfferAuthorityMode.InstalledRetry : RuntimeUnlockOfferAuthorityMode.InitialActivation).ToString())}");
            }

            return;
        }

        var payerDecisionId = ResolvePayerDecisionIdForNegotiation(reason);
        var scheduledOperationGeneration = Interlocked.Increment(
            ref runtimeUnlockPostTunaFallbackActivationOperationNextGeneration);
        NotifyTransportAccelerationStateChanged($"negotiation_scheduled_{reason}");
        LogRuntimeUnlockPostTunaFallbackActivationDisposition(
            scheduledOperationGeneration,
            payerDecisionId,
            reason,
            expectedInstallReceipt,
            "started",
            "negotiation_task_queued");
        _ = Task.Run(
            async () =>
            {
                var disposition = "completed";
                var dispositionReason = "negotiation_operation_completed";
                try
                {
                    if (!MarkRuntimeUnlockRecoveryContractRetryDispatched(
                            reason,
                            expectedInstallReceipt,
                            requireRuntimeUnlockRetryDispatchInstall))
                    {
                        (disposition, dispositionReason) =
                        ResolveRuntimeUnlockPostTunaFallbackActivationDisposition(
                            expectedInstallReceipt);
                        return;
                    }

                    await TrySendAccelerationOfferAsync(
                            reason,
                            payerDecisionId,
                            CancellationToken.None,
                            expectedInstallReceipt,
                            requireRuntimeUnlockRetryDispatchInstall,
                            runtimeUnlockActivation)
                        .ConfigureAwait(false);
                    (disposition, dispositionReason) =
                        requireRuntimeUnlockRetryDispatchInstall
                            ? ResolveRuntimeUnlockPostTunaFallbackActivationDispositionAfterOffer(
                                expectedInstallReceipt)
                            : (
                                "completed",
                                "initial_activation_offer_flow_completed");
                }
                catch (Exception ex) when (ex is not OperationCanceledException)
                {
                    disposition = "rejected";
                    dispositionReason = $"negotiation_failed_{SanitizeLogToken(ex.GetType().Name)}";
                    LocalOperationalLog.Warn(
                        "NKN.Tuna",
                        $"event=tuna_acceleration_negotiation_failed; reason={SanitizeLogToken(reason)}; error={ex.GetType().Name}");
                }
                finally
                {
                    LogRuntimeUnlockPostTunaFallbackActivationDisposition(
                        scheduledOperationGeneration,
                        payerDecisionId,
                        reason,
                        expectedInstallReceipt,
                        disposition,
                        dispositionReason);
                    Interlocked.Exchange(ref accelerationNegotiationScheduled, 0);
                    SchedulePendingRuntimeUnlockAccelerationNegotiationAfterCurrentOperation("negotiation_complete");
                }
            },
            CancellationToken.None);
    }

    private (string Disposition, string Reason)
        ResolveRuntimeUnlockPostTunaFallbackActivationDisposition(
            RuntimeUnlockRetryDispatchInstallReceipt? expectedInstallReceipt)
    {
        lock (accelerationGate)
        {
            var state = runtimeUnlockRecoveryRetryState;
            if (state is null ||
                expectedInstallReceipt is not { } receipt ||
                runtimeUnlockRetryDispatchInstallShadow.LastCommittedReceipt != receipt)
            {
                return ("invalidated", "install_receipt_replaced");
            }

            if (state.DispatchDecisionStatus == RuntimeUnlockRetryDispatchDecisionStatus.Held ||
                state.BlockedByRegularV4FrontierRepair)
            {
                return ("held", state.DispatchDecisionReason ?? "coordinator_authority_held");
            }

            if (state.DispatchAuthorityRejected ||
                state.ContractState == SessionRecoveryContractState.Failed)
            {
                return ("rejected", state.AuthorityFailureReason ?? "retry_dispatch_rejected");
            }

            return ("invalidated", state.DispatchDecisionReason ?? "retry_dispatch_not_current");
        }
    }

    private (string Disposition, string Reason)
        ResolveRuntimeUnlockPostTunaFallbackActivationDispositionAfterOffer(
            RuntimeUnlockRetryDispatchInstallReceipt? expectedInstallReceipt)
    {
        lock (accelerationGate)
        {
            var state = runtimeUnlockRecoveryRetryState;
            if (state is null ||
                expectedInstallReceipt is not { } receipt ||
                runtimeUnlockRetryDispatchInstallShadow.LastCommittedReceipt != receipt)
            {
                return ("invalidated", "install_receipt_replaced_after_offer");
            }

            var currentOfferBound =
                outboundAccelerationOfferInstallReceipt == receipt &&
                !string.IsNullOrWhiteSpace(outboundAccelerationOfferNonce);
            var retiredOfferBound =
                retiredAccelerationOfferInstallReceipt == receipt &&
                !string.IsNullOrWhiteSpace(retiredAccelerationOfferNonce);
            if (currentOfferBound || retiredOfferBound)
            {
                return (
                    "completed",
                    currentOfferBound
                        ? "committed_authority_bound_to_current_offer"
                        : "committed_authority_bound_to_retired_offer_proof");
            }

            if (state.DispatchAuthorityRejected ||
                state.ContractState == SessionRecoveryContractState.Failed)
            {
                return ("rejected", state.AuthorityFailureReason ?? "offer_flow_authority_rejected");
            }

            return ("held", state.DispatchDecisionReason ?? "committed_authority_produced_no_offer");
        }
    }

    private static void LogRuntimeUnlockPostTunaFallbackActivationDisposition(
        long operationGeneration,
        long payerDecisionId,
        string trigger,
        RuntimeUnlockRetryDispatchInstallReceipt? receipt,
        string disposition,
        string decisionReason)
    {
        if (receipt is not { } effectiveReceipt ||
            effectiveReceipt.Authority.ReleaseKind !=
                RuntimeUnlockRetryReleaseKind.FallbackPairedTailYield ||
            effectiveReceipt.Authority.ReleaseOutcome !=
                FallbackTailYieldKind.Quiescent.ToString())
        {
            return;
        }

        var authorityTuple =
            FormatRuntimeUnlockRetryDispatchAuthorityTuple(
                effectiveReceipt.Authority);
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=runtime_unlock_post_tuna_fallback_activation_disposition; {authorityTuple}; operation_generation={operationGeneration}; payer_decision_id={payerDecisionId}; retry_authority_id={SanitizeLogToken(effectiveReceipt.Authority.AuthorityId.ToString())}; install_generation={effectiveReceipt.InstallGeneration}; trigger={SanitizeLogToken(trigger)}; disposition={SanitizeLogToken(disposition)}; decision_reason={SanitizeLogToken(decisionReason)}");
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=tuna_acceleration_negotiation_scheduling_{SanitizeLogToken(disposition)}; {authorityTuple}; operation_generation={operationGeneration}; payer_decision_id={payerDecisionId}; retry_authority_id={SanitizeLogToken(effectiveReceipt.Authority.AuthorityId.ToString())}; install_generation={effectiveReceipt.InstallGeneration}; trigger={SanitizeLogToken(trigger)}; decision_reason={SanitizeLogToken(decisionReason)}");
    }

    private async Task TrySendAccelerationOfferAsync(
        string reason,
        long payerDecisionId,
        CancellationToken ct,
        RuntimeUnlockRetryDispatchInstallReceipt? expectedInstallReceipt = null,
        bool requireRuntimeUnlockRetryDispatchInstall = false,
        bool runtimeUnlockActivation = false)
    {
        var offerAuthorityMode = requireRuntimeUnlockRetryDispatchInstall
            ? RuntimeUnlockOfferAuthorityMode.InstalledRetry
            : runtimeUnlockActivation
                ? RuntimeUnlockOfferAuthorityMode.InitialActivation
                : (RuntimeUnlockOfferAuthorityMode?)null;
        var isRuntimeUnlockActivation = offerAuthorityMode is not null;
        var usesInstalledRetryAuthority =
            offerAuthorityMode == RuntimeUnlockOfferAuthorityMode.InstalledRetry;

        bool ValidateOfferAuthority(string boundary)
            => offerAuthorityMode is { } mode
                ? ValidatePendingRuntimeUnlockOfferAuthority(
                    mode,
                    expectedInstallReceipt,
                    boundary)
                : ValidateRuntimeUnlockRetryDispatchInstallReceiptBoundary(
                    expectedInstallReceipt,
                    boundary);

        bool ScheduleOfferRetry(string retryReason)
            => offerAuthorityMode switch
            {
                RuntimeUnlockOfferAuthorityMode.InitialActivation =>
                    ScheduleInitialRuntimeUnlockAccelerationNegotiationRetry(
                        retryReason),
                RuntimeUnlockOfferAuthorityMode.InstalledRetry =>
                    ScheduleRuntimeUnlockAccelerationNegotiationRetry(
                        retryReason,
                        expectedInstallReceipt),
                _ => ScheduleAccelerationNegotiationRetry(
                    retryReason,
                    expectedInstallReceipt),
            };

        if (!ValidateOfferAuthority("offer_preflight"))
        {
            return;
        }

        if (IsStaleLocalPayerDecision(payerDecisionId))
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=tuna_acceleration_negotiation_stale; stage=preflight; payer_decision_id={payerDecisionId}; current_payer_decision_id={Volatile.Read(ref accelerationPayerDecisionId)}; reason={SanitizeLogToken(reason)}");
            return;
        }

        if (accelerationLane is not INknTunaAccelerationSession tunaSession)
        {
            RejectAccelerationOfferPreflight(
                reason,
                "missing_tuna_session",
                retryable: false,
                expectedInstallReceipt: expectedInstallReceipt,
                offerAuthorityMode: offerAuthorityMode);
            return;
        }

        if (string.IsNullOrWhiteSpace(remoteEndpoint))
        {
            RejectAccelerationOfferPreflight(
                reason,
                "missing_remote_endpoint",
                retryable: true,
                expectedInstallReceipt: expectedInstallReceipt,
                offerAuthorityMode: offerAuthorityMode);
            return;
        }

        if (!IsSessionAccelerationEligible(out var eligibleLanes))
        {
            RejectAccelerationOfferPreflight(
                reason,
                "session_not_eligible",
                retryable: false,
                expectedInstallReceipt: expectedInstallReceipt,
                offerAuthorityMode: offerAuthorityMode);
            return;
        }

        var preflightLanes = eligibleLanes & tunaSession.ConfiguredLanes;
        if (preflightLanes == NknAccelerationLaneKind.None)
        {
            RejectAccelerationOfferPreflight(
                reason,
                "no_eligible_lane",
                retryable: false,
                eligibleLanes,
                expectedInstallReceipt,
                offerAuthorityMode);
            NotifyTransportAccelerationStateChanged("no_eligible_lane");
            return;
        }

        var sessionId = currentSessionSecurityState.SessionId?.Value;
        if (string.IsNullOrWhiteSpace(sessionId) || !TryGetCurrentEnvelopeCode(out var envelopeCode))
        {
            RejectAccelerationOfferPreflight(
                reason,
                "missing_secure_session_context",
                retryable: true,
                preflightLanes,
                expectedInstallReceipt,
                offerAuthorityMode);
            return;
        }

        var localRole = ResolveLocalSessionRole();
        var pausedForActivationNegotiation = false;
        void PauseActivationIfNeeded(string pauseTrigger)
        {
            if (pausedForActivationNegotiation)
            {
                return;
            }

            if (IsAccelerationNegotiatedAndHealthy())
            {
                return;
            }

            pausedForActivationNegotiation = PauseFileTransferDataSessionsForTunaActivationNegotiation(
                "activation_negotiation_pending",
                sessionId,
                pauseTrigger);
        }

        void ResumeActivationPauseIfNeeded(string resumeReason, string resumeTrigger)
        {
            if (!pausedForActivationNegotiation)
            {
                return;
            }

            if (string.Equals(resumeReason, "tuna_activation_failed_regular_v4_resumed", StringComparison.Ordinal))
            {
                ResumeFileTransferDataSessionsAfterTunaActivationFailure(
                    resumeTrigger,
                    sessionId,
                    resumeTrigger);
            }
            else
            {
                ResumeFileTransferDataSessionsAfterTunaActivationNegotiation(
                    resumeReason,
                    sessionId,
                    resumeTrigger);
            }

            pausedForActivationNegotiation = false;
        }

        if (!ValidateOfferAuthority("payer_intent_preflight"))
        {
            return;
        }

        FileTransferRoutePublicationAuthority? runtimeUnlockFileTransferOwnerAuthority = null;
        RuntimeUnlockInitialActivationReceiveRecoveryExpectedScope?
            runtimeUnlockInitialActivationExpectedScope = null;
        FileTransferAuthorityId? runtimeUnlockDispatchAuthorityId = null;
        if (isRuntimeUnlockActivation &&
            IsFileTransferRuntimeUnlockContextObserved(sessionId))
        {
            if (!TryCaptureCurrentRuntimeUnlockFileTransferOwnerAuthority(
                    sessionId,
                    out var capturedOwnerAuthority,
                    out var ownerRejectionReason))
            {
                LogRuntimeUnlockFileTransferOwnerRejectedBeforePathLease(
                    sessionId,
                    reason,
                    ownerRejectionReason);
                if (usesInstalledRetryAuthority)
                {
                    RejectRuntimeUnlockRecoveryRetryBeforeDispatchIfActive(
                        sessionId,
                        "runtime_unlock_filetransfer_owner_missing_before_path_lease");
                }
                return;
            }

            runtimeUnlockFileTransferOwnerAuthority = capturedOwnerAuthority;
            LogRuntimeUnlockFileTransferOwnerAcceptedBeforePathLease(
                capturedOwnerAuthority,
                reason);
            if (offerAuthorityMode ==
                RuntimeUnlockOfferAuthorityMode.InitialActivation)
            {
                if (!TryCaptureRuntimeUnlockInitialActivationReceiveRecoveryExpectedScope(
                        capturedOwnerAuthority,
                        out var capturedExpectedScope,
                        out var expectedScopeRejectionReason))
                {
                    LogRuntimeUnlockFileTransferOwnerRejectedBeforePathLease(
                        sessionId,
                        reason,
                        expectedScopeRejectionReason);
                    return;
                }

                runtimeUnlockInitialActivationExpectedScope =
                    capturedExpectedScope;
            }
        }
        if (usesInstalledRetryAuthority &&
            TryGetInstalledRuntimeUnlockRetryDispatchContract(
                sessionId,
                out _,
                out var capturedDispatchContract))
        {
            runtimeUnlockDispatchAuthorityId = capturedDispatchContract!.Authority.AuthorityId;
        }

        var requiresContractLocalListenerRetry = false;
        if (usesInstalledRetryAuthority &&
            ShouldPauseRegularNknV4FileTransferBeforeRuntimeUnlockPayerIntent(sessionId, reason))
        {
            pausedForActivationNegotiation = PauseRegularNknV4FileTransferForRuntimeUnlockMakeBeforeBreak(
                sessionId,
                "runtime_unlock_retry_dispatch_payer_intent",
                reason);
        }

        requiresContractLocalListenerRetry = usesInstalledRetryAuthority &&
            RequiresLocalListenerRetryForRuntimeUnlockRecoveryContract(
                sessionId);
        if (requiresContractLocalListenerRetry && !tunaSession.CanOfferListener)
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=session_recovery_contract_listener_rearm_required; session_id={SanitizeLogToken(sessionId)}; reason={SanitizeLogToken(reason)}; can_offer_listener=0");
        }

        if (offerAuthorityMode ==
                RuntimeUnlockOfferAuthorityMode.InitialActivation &&
            runtimeUnlockFileTransferOwnerAuthority is not null)
        {
            if (!TryCaptureRuntimeUnlockInitialActivationReceiveRecoveryExpectedScope(
                    runtimeUnlockFileTransferOwnerAuthority,
                    out var payerIntentExpectedScope,
                    out var payerIntentScopeRejectionReason) ||
                !RuntimeUnlockInitialActivationExpectedSourceScopeMatches(
                    runtimeUnlockInitialActivationExpectedScope
                        .GetValueOrDefault(),
                    payerIntentExpectedScope))
            {
                LogRuntimeUnlockFileTransferOwnerRejectedBeforeOfferDispatch(
                    sessionId,
                    runtimeUnlockFileTransferOwnerAuthority.TransferId,
                    reason,
                    payerIntentScopeRejectionReason);
                return;
            }

            runtimeUnlockInitialActivationExpectedScope =
                payerIntentExpectedScope;
        }

        var payerIntentSubmission = CreateAccelerationPayerIntentSubmission(
            envelopeCode,
            sessionId,
            localRole,
            preflightLanes,
            tunaSession.CanOfferListener ||
            requiresContractLocalListenerRetry,
            reason,
            payerDecisionId);
        var deferInitialActivationPayerIntent =
            offerAuthorityMode ==
                RuntimeUnlockOfferAuthorityMode.InitialActivation &&
            runtimeUnlockFileTransferOwnerAuthority is not null &&
            runtimeUnlockInitialActivationExpectedScope is
            {
                ExpectedExecutionCommand: not null,
            };
        if (!deferInitialActivationPayerIntent)
        {
            try
            {
                if (!ValidateOfferAuthority("payer_intent_send"))
                {
                    return;
                }

                var payerIntentQueued = await SendAccelerationPayerIntentAsync(
                        remoteEndpoint,
                        sessionId,
                        envelopeCode,
                        localRole,
                        preflightLanes,
                        tunaSession.CanOfferListener ||
                        requiresContractLocalListenerRetry,
                        reason,
                        payerDecisionId,
                        ct,
                        usesInstalledRetryAuthority
                            ? expectedInstallReceipt
                            : null,
                        offerAuthorityMode,
                        preparedSubmission: payerIntentSubmission)
                    .ConfigureAwait(false);
                if (!payerIntentQueued.Succeeded &&
                    !payerIntentQueued.UntrustedProbeSent &&
                    offerAuthorityMode ==
                        RuntimeUnlockOfferAuthorityMode.InitialActivation &&
                    runtimeUnlockFileTransferOwnerAuthority is not null &&
                    !IsStaleLocalPayerDecision(payerDecisionId) &&
                    ValidateOfferAuthority(
                        "payer_intent_receive_recovery_race") &&
                    TryCaptureRuntimeUnlockInitialActivationReceiveRecoveryExpectedScope(
                        runtimeUnlockFileTransferOwnerAuthority,
                        out var racedExpectedScope,
                        out _) &&
                    RuntimeUnlockInitialActivationExpectedSourceScopeMatches(
                        runtimeUnlockInitialActivationExpectedScope
                            .GetValueOrDefault(),
                        racedExpectedScope) &&
                    racedExpectedScope.ExpectedExecutionCommand is not null)
                {
                    runtimeUnlockInitialActivationExpectedScope =
                        racedExpectedScope;
                    deferInitialActivationPayerIntent = true;
                    LocalOperationalLog.Info(
                        "NKN.Tuna",
                        $"event=runtime_unlock_initial_activation_payer_intent_deferred; session_id={SanitizeLogToken(sessionId)}; transfer_id={SanitizeLogToken(runtimeUnlockFileTransferOwnerAuthority.TransferId)}; payer_decision_id={payerDecisionId}; decision_reason=receive_recovery_started_during_unobserved_payer_intent_send");
                }
                else if (!payerIntentQueued.Succeeded)
                {
                    if (payerIntentQueued.StaleCallbackIgnored)
                    {
                        return;
                    }

                    var payerIntentRetryReason = isRuntimeUnlockActivation
                        ? "runtime_unlock_payer_intent_send_rejected"
                        : "payer_intent_send_rejected";
                    ResumeActivationPauseIfNeeded(
                        "tuna_activation_failed_regular_v4_resumed",
                        payerIntentRetryReason);
                    if (usesInstalledRetryAuthority &&
                        TrySettleRuntimeUnlockRetryDispatchMissingBeforeOfferIfCurrent(
                            sessionId,
                            "runtime_unlock_payer_intent_send_rejected_before_retry_dispatch",
                            payerIntentRetryReason,
                            requiresContractLocalListenerRetry,
                            runtimeUnlockDispatchAuthorityId))
                    {
                        return;
                    }

                    _ = ScheduleOfferRetry(payerIntentRetryReason);
                    return;
                }
            }
            catch
            {
                ResumeActivationPauseIfNeeded(
                    "tuna_activation_failed_regular_v4_resumed",
                    "payer_intent_send_failed");
                throw;
            }

            if (!deferInitialActivationPayerIntent &&
                !ValidateOfferAuthority("payer_intent_completion"))
            {
                return;
            }
        }

        if (!tunaSession.CanOfferListener && !requiresContractLocalListenerRetry)
        {
            ResumeActivationPauseIfNeeded("tuna_activation_failed_regular_v4_resumed", "listener_unavailable");
            RejectAccelerationOfferPreflight(
                reason,
                "listener_unavailable",
                retryable: true,
                eligibleLanes,
                expectedInstallReceipt,
                offerAuthorityMode);
            return;
        }

        NotifyTransportAccelerationStateChanged("checking_payer_priority");
        if (await ShouldSuppressLocalPaidOfferForHelpeePriorityAsync(localRole, reason, ct).ConfigureAwait(false))
        {
            ResumeActivationPauseIfNeeded("tuna_activation_failed_regular_v4_resumed", "payer_priority_suppressed");
            return;
        }

        if (IsStaleLocalPayerDecision(payerDecisionId))
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=tuna_acceleration_negotiation_stale; stage=after_payer_priority; payer_decision_id={payerDecisionId}; current_payer_decision_id={Volatile.Read(ref accelerationPayerDecisionId)}; reason={SanitizeLogToken(reason)}");
            ResumeActivationPauseIfNeeded("stale_payer_decision", "after_payer_priority_stale");
            return;
        }

        if (accelerationLane is not INknTunaAccelerationSession ||
            !IsSessionAccelerationEligible(out eligibleLanes))
        {
            ResumeActivationPauseIfNeeded("session_not_eligible_after_payer_priority", "session_not_eligible_after_payer_priority");
            RejectAccelerationOfferPreflight(
                reason,
                "session_not_eligible_after_payer_priority",
                retryable: false,
                expectedInstallReceipt: expectedInstallReceipt,
                offerAuthorityMode: offerAuthorityMode);
            return;
        }

        if (IsAccelerationUserStoppedForCurrentSession())
        {
            ResumeActivationPauseIfNeeded("user_stopped_tuna", "after_payer_priority_user_stopped");
            RejectAccelerationOfferPreflight(
                reason,
                "user_stopped_tuna",
                retryable: false,
                eligibleLanes,
                expectedInstallReceipt,
                offerAuthorityMode);
            return;
        }

        preflightLanes = eligibleLanes & tunaSession.ConfiguredLanes;
        if (preflightLanes == NknAccelerationLaneKind.None)
        {
            ResumeActivationPauseIfNeeded("no_eligible_lane", "after_payer_priority_no_eligible_lane");
            RejectAccelerationOfferPreflight(
                reason,
                "no_eligible_lane",
                retryable: false,
                eligibleLanes,
                expectedInstallReceipt,
                offerAuthorityMode);
            NotifyTransportAccelerationStateChanged("no_eligible_lane");
            return;
        }

        NotifyTransportAccelerationStateChanged("selected_payer_starting_listener");
        NotifyTransportAccelerationStateChanged("listener_starting");
        var runtimeUnlockTunaPathLease = RuntimeUnlockTunaPathLeaseSnapshot.None;
        if (isRuntimeUnlockActivation)
        {
            lock (accelerationGate)
            {
                runtimeUnlockTunaPathLease = StartRuntimeUnlockTunaPathLeaseUnsafe(
                    sessionId,
                    runtimeUnlockFileTransferOwnerAuthority?.TransferId,
                    payerDecisionId,
                    reason);
            }
        }

        if (isRuntimeUnlockActivation &&
            ShouldPauseRegularNknV4FileTransferForRuntimeUnlock(sessionId))
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=filetransfer_tuna_activation_negotiation_regular_nkn_pause_deferred; session_id={SanitizeLogToken(sessionId)}; reason=runtime_unlock_listener_starting; trigger={SanitizeLogToken(reason)}");
        }

        var listenerStartRequest =
            isRuntimeUnlockActivation &&
            offerAuthorityMode == RuntimeUnlockOfferAuthorityMode.InitialActivation &&
            runtimeUnlockFileTransferOwnerAuthority is { } listenerOwner
                ? new NknTunaListenerStartRequest(
                    remoteEndpoint,
                    preflightLanes,
                    NknTunaListenerLifetimePolicy
                        .CoordinatorScopedInitialActivation,
                    string.Join(
                        "|",
                        sessionId,
                        listenerOwner.TransferId,
                        listenerOwner.Direction,
                        listenerOwner.RuntimeGeneration,
                        listenerOwner.RoutePublicationGeneration,
                        payerDecisionId,
                        runtimeUnlockTunaPathLease.LeaseGeneration,
                        runtimeUnlockTunaPathLease.ListenerRunId))
                : new NknTunaListenerStartRequest(
                    remoteEndpoint,
                    preflightLanes);
        if (!await tunaSession.EnsureListenerSidecarConnectedAsync(
                listenerStartRequest,
                ct).ConfigureAwait(false) ||
            string.IsNullOrWhiteSpace(tunaSession.LocalTunaAddress))
        {
            NotifyTransportAccelerationStateChanged("listener_sidecar_unavailable");
            if (isRuntimeUnlockActivation)
            {
                FailRuntimeUnlockTunaPathLeaseIfCurrent(
                    sessionId,
                    offerGeneration: 0,
                    "listener_sidecar_unavailable",
                    failTransaction: false);
            }

            ResumeActivationPauseIfNeeded("tuna_activation_failed_regular_v4_resumed", "listener_sidecar_unavailable");
            var listenerRetryReason = requiresContractLocalListenerRetry
                ? ResolveRuntimeUnlockListenerRearmFailedReason(sessionId)
                : "listener_sidecar_unavailable";
            if (requiresContractLocalListenerRetry)
            {
                MarkRuntimeUnlockRecoveryContractAuthorityBlocked(listenerRetryReason);
                LocalOperationalLog.Info(
                    "NKN.Tuna",
                    $"event=session_recovery_contract_listener_rearm_required; session_id={SanitizeLogToken(sessionId)}; reason={SanitizeLogToken(reason)}; can_offer_listener=0; failure_path=1");
                if (TrySettleRuntimeUnlockRetryDispatchMissingBeforeOfferIfCurrent(
                        sessionId,
                        listenerRetryReason,
                        listenerRetryReason,
                        requiresLocalListenerRetry: true,
                        expectedAuthorityId: runtimeUnlockDispatchAuthorityId))
                {
                    LocalOperationalLog.Warn(
                        "NKN.Tuna",
                        $"event=session_recovery_contract_listener_rearm_failed; session_id={SanitizeLogToken(sessionId)}; reason={SanitizeLogToken(listenerRetryReason)}; trigger={SanitizeLogToken(reason)}; dispatch_successor_requested=1");
                    return;
                }

                FailRuntimeUnlockRecoveryContractIfActive(sessionId, listenerRetryReason);
                LocalOperationalLog.Warn(
                    "NKN.Tuna",
                    $"event=session_recovery_contract_listener_rearm_failed; session_id={SanitizeLogToken(sessionId)}; reason={SanitizeLogToken(listenerRetryReason)}; trigger={SanitizeLogToken(reason)}");
                return;
            }

            if (!usesInstalledRetryAuthority ||
                !TrySettleRuntimeUnlockRetryDispatchMissingBeforeOfferIfCurrent(
                    sessionId,
                    listenerRetryReason,
                    listenerRetryReason,
                    requiresLocalListenerRetry: false,
                    expectedAuthorityId: runtimeUnlockDispatchAuthorityId))
            {
                _ = ScheduleOfferRetry(listenerRetryReason);
            }
            return;
        }

        if (isRuntimeUnlockActivation)
        {
            if (!ValidateOfferAuthority("listener_ready"))
            {
                return;
            }

            MarkRuntimeUnlockTunaPathLeaseListenerReady(
                runtimeUnlockTunaPathLease,
                sessionId,
                reason);
        }

        if (requiresContractLocalListenerRetry)
        {
            MarkRuntimeUnlockRecoveryContractListenerRearmCompleted(
                sessionId,
                reason,
                expectedInstallReceipt);
        }

        NotifyTransportAccelerationStateChanged("listener_ready");
        if (IsStaleLocalPayerDecision(payerDecisionId))
        {
            NotifyTransportAccelerationStateChanged("suppressed_by_peer_payer");
            ResumeActivationPauseIfNeeded("stale_payer_decision", "listener_ready_stale_payer_decision");
            try
            {
                await tunaSession.StopAsync("stale_payer_decision", ct).ConfigureAwait(false);
            }
            catch (Exception ex) when (ex is not OperationCanceledException)
            {
                LocalOperationalLog.Warn(
                    "NKN.Tuna",
                    $"event=tuna_acceleration_stop_failed; reason=stale_payer_decision; error={ex.GetType().Name}");
            }

            return;
        }

        if (IsAccelerationUserStoppedForCurrentSession())
        {
            NotifyTransportAccelerationStateChanged("user_stopped_tuna");
            ResumeActivationPauseIfNeeded("user_stopped_tuna", "listener_ready_user_stopped");
            try
            {
                await tunaSession.StopAsync("user_stopped_tuna", ct).ConfigureAwait(false);
            }
            catch (Exception ex) when (ex is not OperationCanceledException)
            {
                LocalOperationalLog.Warn(
                    "NKN.Tuna",
                    $"event=tuna_acceleration_stop_failed; reason=user_stopped_tuna; error={ex.GetType().Name}");
            }

            return;
        }

        var offeredLanes = eligibleLanes & tunaSession.SupportedLanes;
        if (offeredLanes == NknAccelerationLaneKind.None)
        {
            NotifyTransportAccelerationStateChanged("no_supported_lane");
            ResumeActivationPauseIfNeeded("tuna_activation_failed_regular_v4_resumed", "no_supported_lane");
            if (!usesInstalledRetryAuthority ||
                !TrySettleRuntimeUnlockRetryDispatchMissingBeforeOfferIfCurrent(
                    sessionId,
                    "runtime_unlock_listener_no_supported_lane",
                    "runtime_unlock_listener_sidecar_unavailable",
                    requiresContractLocalListenerRetry,
                    runtimeUnlockDispatchAuthorityId))
            {
                _ = ScheduleOfferRetry("listener_sidecar_unavailable");
            }
            return;
        }

        if (isRuntimeUnlockActivation &&
            runtimeUnlockFileTransferOwnerAuthority is not null)
        {
            if (!TryCaptureCurrentRuntimeUnlockFileTransferOwnerAuthority(
                    sessionId,
                    out var currentOwnerAuthority,
                    out var currentOwnerRejectionReason) ||
                !Equals(currentOwnerAuthority, runtimeUnlockFileTransferOwnerAuthority))
            {
                var rejectionReason = string.Equals(currentOwnerRejectionReason, "accepted", StringComparison.Ordinal)
                    ? "current_filetransfer_owner_changed_after_listener_start"
                    : currentOwnerRejectionReason;
                LogRuntimeUnlockFileTransferOwnerRejectedBeforeOfferDispatch(
                    sessionId,
                    runtimeUnlockFileTransferOwnerAuthority.TransferId,
                    reason,
                    rejectionReason);
                FailRuntimeUnlockTunaPathLeaseIfCurrent(
                    sessionId,
                    offerGeneration: 0,
                    rejectionReason,
                    failTransaction: false);
                if (usesInstalledRetryAuthority)
                {
                    RejectRuntimeUnlockRecoveryRetryBeforeDispatchIfActive(
                        sessionId,
                        rejectionReason);
                }
                ResumeActivationPauseIfNeeded(
                    "tuna_activation_failed_regular_v4_resumed",
                    rejectionReason);
                return;
            }

            if (offerAuthorityMode ==
                RuntimeUnlockOfferAuthorityMode.InitialActivation)
            {
                if (!TryCaptureRuntimeUnlockInitialActivationReceiveRecoveryExpectedScope(
                        runtimeUnlockFileTransferOwnerAuthority,
                        out var currentExpectedScope,
                        out var expectedScopeRejectionReason) ||
                    !RuntimeUnlockInitialActivationExpectedSourceScopeMatches(
                        runtimeUnlockInitialActivationExpectedScope
                            .GetValueOrDefault(),
                        currentExpectedScope))
                {
                    LogRuntimeUnlockFileTransferOwnerRejectedBeforeOfferDispatch(
                        sessionId,
                        runtimeUnlockFileTransferOwnerAuthority.TransferId,
                        reason,
                        expectedScopeRejectionReason);
                    return;
                }

                runtimeUnlockInitialActivationExpectedScope =
                    currentExpectedScope;
            }
        }

        RuntimeUnlockRecoveryRetryState? grantedRetryDispatchState = null;
        var hasCurrentGrantedRetryDispatchContract = usesInstalledRetryAuthority &&
            TryGetInstalledRuntimeUnlockRetryDispatchContract(
                sessionId,
                out grantedRetryDispatchState,
                out _);
        if (!hasCurrentGrantedRetryDispatchContract)
        {
            if (usesInstalledRetryAuthority &&
                TryDeferRuntimeUnlockOfferDispatchForRegularV4FrontierRepair(
                    sessionId,
                    reason,
                    payerDecisionId,
                    expectedInstallReceipt,
                    RuntimeUnlockOfferAuthorityMode.InstalledRetry,
                    out _,
                    out _))
            {
                ResumeActivationPauseIfNeeded(
                    "tuna_activation_failed_regular_v4_resumed",
                    "regular_v4_frontier_repair_pending");
                return;
            }
        }
        else
        {
            LogRuntimeUnlockRetryDispatchProof(
                "runtime_unlock_retry_dispatch_evidence_ignored_after_authority_granted",
                grantedRetryDispatchState!,
                "coordinator_dispatch_authority_current");
        }

        if (usesInstalledRetryAuthority)
        {
            if (!ValidateOfferAuthority("offer_creation"))
            {
                return;
            }

            var dispatchAuthorityResult = TryGrantRuntimeUnlockRecoveryRetryDispatchAuthorityForOfferSend(reason, sessionId);
            if (dispatchAuthorityResult == RuntimeUnlockRetryDispatchAuthorityResult.Held)
            {
                ResumeActivationPauseIfNeeded(
                    "tuna_activation_failed_regular_v4_resumed",
                    "runtime_unlock_retry_dispatch_authority_held");
                return;
            }

            if (dispatchAuthorityResult == RuntimeUnlockRetryDispatchAuthorityResult.Rejected)
            {
                ResumeActivationPauseIfNeeded("tuna_activation_failed_regular_v4_resumed", "runtime_unlock_retry_dispatch_authority_rejected");
                return;
            }
        }

        var nonce = Convert.ToHexString(RandomNumberGenerator.GetBytes(16)).ToLowerInvariant();
        var sentAtUnixMs = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
        var offer = new TransportAccelerationOfferPayload
        {
            SessionId = sessionId,
            SenderRole = localRole,
            TunaAddress = tunaSession.LocalTunaAddress,
            SupportedLanes = NknAccelerationLaneCodec.ToNames(offeredLanes),
            Trigger = SanitizeLogToken(reason),
            PayerDecisionId = payerDecisionId,
            SentAtUnixMs = sentAtUnixMs,
            ExpiresAtUnixMs = sentAtUnixMs + (long)AccelerationOfferLifetime.TotalMilliseconds,
            Nonce = nonce,
            SidecarProtocolVersion = TunaSidecarProtocolVersion,
        };
        var semanticOfferFingerprint =
            ComputeRuntimeUnlockInitialActivationSemanticOfferFingerprint(
                offer);
        var payload = CreateSecureControlPayload(
            MsgType.TransportAccelerationOffer,
            nonce,
            JsonSerializer.SerializeToUtf8Bytes(offer));
        var envelope = CreateEnvelope(envelopeCode, MsgType.TransportAccelerationOffer, payload, replyTo: null);
        var controlEnvelopeFingerprint =
            ComputeRuntimeUnlockControlEnvelopeFingerprint(envelope);
        long offerGeneration;
        RuntimeUnlockRecoveryRetryState? runtimeUnlockAuthorityGrantedSnapshot = null;
        RuntimeUnlockRecoveryRetryState? runtimeUnlockAuthorityOfferWindowSnapshot = null;
        RuntimeUnlockTransactionDecision? runtimeUnlockTransactionStarted = null;
        RuntimeUnlockOfferAuthorityBoundary? runtimeUnlockOfferAuthorityBoundary = null;
        RuntimeUnlockRecoveryRetryState? runtimeUnlockAliasRejectedState = null;
        RuntimeUnlockRecoveryRetryState? terminalRecoveryStateToClear = null;
        var terminalRecoveryStateHadDispatchContract = false;
        RuntimeUnlockRetryDispatchSettlementReport terminalRecoverySettlementReport = default;
        var coordinatorAcceptedOfferGeneration = 0L;
        if (requireRuntimeUnlockRetryDispatchInstall)
        {
            RuntimeUnlockRetryDispatchExecutionObservation aliasProposal;
            lock (accelerationGate)
            {
                var currentState = runtimeUnlockRecoveryRetryState;
                if (expectedInstallReceipt is not { } receipt ||
                    currentState is null ||
                    currentState.DispatchContract is not
                        { } dispatchContract ||
                    dispatchContract.Authority != receipt.Authority ||
                    !TryValidateRuntimeUnlockRetryDispatchInstallReceiptCurrentUnsafe(
                        currentState,
                        receipt,
                        out var receiptRejectionReason) ||
                    outboundAccelerationOfferGeneration == long.MaxValue)
                {
                    if (expectedInstallReceipt is { } rejectedReceipt)
                    {
                        LogRuntimeUnlockRetryDispatchInstallRejected(
                            rejectedReceipt,
                            CaptureRuntimeUnlockRetryDispatchInstallTelemetryUnsafe(
                                currentState),
                            RuntimeUnlockRetryDispatchInstallStatus.Rejected,
                            currentState is null
                                ? "retry_dispatch_install_state_missing_offer_alias_prepare"
                                : "retry_dispatch_install_not_current_offer_alias_prepare");
                    }
                    return;
                }

                aliasProposal =
                    new RuntimeUnlockRetryDispatchExecutionObservation(
                        dispatchContract.Authority,
                        RuntimeUnlockRetryDispatchAttemptPhase.AliasBound,
                        outboundAccelerationOfferGeneration + 1,
                        nonce,
                        DispatchObserved: false)
                    {
                        InstallReceipt = receipt,
                    };
                coordinatorAcceptedOfferGeneration =
                    aliasProposal.OfferGeneration;
            }

            if (!PublishRuntimeUnlockRetryDispatchExecutionObservation(
                    aliasProposal))
            {
                return;
            }
        }

        lock (accelerationGate)
        {
            if (requireRuntimeUnlockRetryDispatchInstall &&
                (coordinatorAcceptedOfferGeneration <= 0 ||
                 outboundAccelerationOfferGeneration ==
                     long.MaxValue ||
                 outboundAccelerationOfferGeneration + 1 !=
                     coordinatorAcceptedOfferGeneration))
            {
                return;
            }

            if (requireRuntimeUnlockRetryDispatchInstall &&
                expectedInstallReceipt is { } receipt)
            {
                var currentState = runtimeUnlockRecoveryRetryState;
                var receiptRejectionReason = "retry_dispatch_install_state_missing";
                if (currentState is null ||
                    !TryValidateRuntimeUnlockRetryDispatchInstallReceiptCurrentUnsafe(
                        currentState,
                        receipt,
                        out receiptRejectionReason))
                {
                    LogRuntimeUnlockRetryDispatchInstallRejected(
                        receipt,
                        CaptureRuntimeUnlockRetryDispatchInstallTelemetryUnsafe(currentState),
                        RuntimeUnlockRetryDispatchInstallStatus.Rejected,
                        $"{receiptRejectionReason}_offer_state_commit");
                    return;
                }
            }

            outboundAccelerationOfferNonce = nonce;
            outboundAccelerationOfferTrigger = SanitizeLogToken(reason);
            outboundAccelerationOfferInstallReceipt =
                isRuntimeUnlockActivation &&
                offerAuthorityMode == RuntimeUnlockOfferAuthorityMode.InstalledRetry
                ? expectedInstallReceipt
                : null;
            outboundRuntimeUnlockOfferAuthorityBoundary = null;
            outboundAccelerationOfferPayerDecisionId = payerDecisionId;
            offerGeneration = ++outboundAccelerationOfferGeneration;
            runtimeUnlockOfferProofState = isRuntimeUnlockActivation
                ? new RuntimeUnlockOfferProofState
                {
                    AuthorityMode = offerAuthorityMode.GetValueOrDefault(),
                    Generation = offerGeneration,
                    Nonce = nonce,
                    SessionId = sessionId,
                    PayerDecisionId = payerDecisionId,
                    Trigger = SanitizeLogToken(reason),
                    CreatedUtcMs = sentAtUnixMs,
                }
                : null;
            RuntimeUnlockRecoveryRetryState? retryState = null;
            if (requireRuntimeUnlockRetryDispatchInstall)
            {
                retryState = runtimeUnlockRecoveryRetryState is { } candidate &&
                             candidate.ContractState is not (
                                 SessionRecoveryContractState.Completed or
                                 SessionRecoveryContractState.Failed) &&
                             string.Equals(candidate.SessionId, sessionId, StringComparison.Ordinal)
                    ? candidate
                    : null;
                var requiresRetryDispatchContract = retryState is not null &&
                    RequiresRuntimeUnlockRetryDispatchProof(retryState);
                if (requiresRetryDispatchContract &&
                    (retryState!.DispatchContract is not { } dispatchContract ||
                     !dispatchContract.TryBindOfferAlias(offerGeneration, nonce)))
                {
                    retryState.AuthorityFailureReason = "runtime_unlock_retry_offer_alias_rejected";
                    retryState.DispatchDecisionReason = retryState.AuthorityFailureReason;
                    runtimeUnlockAliasRejectedState = retryState;
                    ClearOutboundAccelerationOfferLocked();
                    runtimeUnlockOfferProofState = null;
                }
            }

            if (isRuntimeUnlockActivation &&
                runtimeUnlockAliasRejectedState is null)
            {
                runtimeUnlockTransactionStarted = StartRuntimeUnlockTransactionForOfferUnsafe(
                    sessionId,
                    offerGeneration,
                    reason);
                if (runtimeUnlockTunaPathLease.LeaseGeneration > 0)
                {
                    runtimeUnlockTunaPathLease = BindRuntimeUnlockTunaPathLeaseToOfferUnsafe(
                        runtimeUnlockTunaPathLease,
                        runtimeUnlockTransactionStarted.State.TransactionGeneration,
                        offerGeneration,
                        payerDecisionId,
                        reason);
                    runtimeUnlockTransactionStarted = runtimeUnlockTransactionStarted with
                    {
                        State = AttachRuntimeUnlockTunaPathLeaseUnsafe(runtimeUnlockTransactionStarted.State),
                    };
                }

                runtimeUnlockOfferAuthorityBoundary =
                    new RuntimeUnlockOfferAuthorityBoundary(
                        offerAuthorityMode.GetValueOrDefault(),
                        sessionId,
                        runtimeUnlockTunaPathLease.TransferId,
                        runtimeUnlockFileTransferOwnerAuthority?.Direction ??
                        FileTransferDirection.Outbound,
                        nonce,
                        payerDecisionId,
                        offerGeneration,
                        runtimeUnlockTransactionStarted.State.TransactionGeneration,
                        runtimeUnlockTunaPathLease.LeaseGeneration,
                        runtimeUnlockTunaPathLease.ListenerRunId,
                        semanticOfferFingerprint,
                        EnvelopeGeneration: 1,
                        EnvelopeSentAtUnixMs: offer.SentAtUnixMs,
                        EnvelopeExpiresAtUnixMs: offer.ExpiresAtUnixMs,
                        ControlEnvelopeFingerprint:
                            controlEnvelopeFingerprint,
                        InstallReceipt:
                            outboundAccelerationOfferInstallReceipt,
                        InitialActivationExpectedScope:
                            runtimeUnlockInitialActivationExpectedScope
                                .GetValueOrDefault());
                outboundRuntimeUnlockOfferAuthorityBoundary =
                    runtimeUnlockOfferAuthorityBoundary;
                if (offerAuthorityMode ==
                    RuntimeUnlockOfferAuthorityMode.InitialActivation)
                {
                    runtimeUnlockInitialActivationEnvelopeState =
                        new RuntimeUnlockInitialActivationEnvelopeState(
                            runtimeUnlockOfferAuthorityBoundary,
                            offer,
                            envelope);
                    lastRuntimeUnlockInitialActivationEnvelopeRefreshReceipt =
                        null;
                }

                if (offerAuthorityMode == RuntimeUnlockOfferAuthorityMode.InstalledRetry)
                {
                    if (retryState is { } state)
                    {
                        state.CurrentOfferGeneration = offerGeneration;
                        if (!state.RetryAuthorityGranted &&
                            state.RetryDispatched)
                        {
                            GrantRuntimeUnlockRecoveryContractRetryAuthorityUnsafe(state);
                            runtimeUnlockAuthorityGrantedSnapshot = state;
                        }

                        if (state.RetryAuthorityGranted && state.RetryAuthorityPending)
                        {
                            RefreshRuntimeUnlockRecoveryContractOfferSendWindowUnsafe(state, sentAtUnixMs);
                            runtimeUnlockAuthorityOfferWindowSnapshot = state;
                        }
                    }
                    else if (runtimeUnlockRecoveryRetryState is
                             {
                                 ContractState: SessionRecoveryContractState.Completed or SessionRecoveryContractState.Failed
                             } terminalRecoveryState)
                    {
                        terminalRecoveryStateToClear = terminalRecoveryState;
                        _ = InvalidateRuntimeUnlockRetryDispatchDecisionStageUnsafe(
                            terminalRecoveryState,
                            "retry_dispatch_install_stage_invalidated_terminal_recovery_state_cleared");
                        terminalRecoveryStateHadDispatchContract = terminalRecoveryState.DispatchContract is not null;
                        _ = SettleRuntimeUnlockRetryDispatchContractUnsafe(
                            terminalRecoveryState,
                            terminalRecoveryState.ContractState == SessionRecoveryContractState.Completed
                                ? RuntimeUnlockRetryDispatchSettlementOutcome.TransferTerminal
                                : RuntimeUnlockRetryDispatchSettlementOutcome.AuthorityRejected,
                            "terminal_recovery_state_cleared",
                            out terminalRecoverySettlementReport);
                        if (!terminalRecoveryStateHadDispatchContract)
                        {
                            runtimeUnlockRecoveryRetryState = null;
                        }
                    }

                    ClearRuntimeUnlockQueueAcceptedObservedEscapeLocked();
                }
            }
        }

        if (!terminalRecoverySettlementReport.IsDefault)
        {
            if (PublishRuntimeUnlockRetryDispatchSettlementReport(terminalRecoverySettlementReport))
            {
                lock (accelerationGate)
                {
                    if (ReferenceEquals(runtimeUnlockRecoveryRetryState, terminalRecoveryStateToClear))
                    {
                        runtimeUnlockRecoveryRetryState = null;
                    }
                }
            }
        }

        if (runtimeUnlockAliasRejectedState is not null)
        {
            LocalOperationalLog.Warn(
                "NKN.Tuna",
                $"event=runtime_unlock_retry_offer_alias_rejected; session_id={SanitizeLogToken(runtimeUnlockAliasRejectedState.SessionId)}; transfer_id={SanitizeLogToken(runtimeUnlockAliasRejectedState.TransferId ?? "(none)")}; contract_generation={runtimeUnlockAliasRejectedState.ContractGeneration}; retired_generation={runtimeUnlockAliasRejectedState.RetiredOfferGeneration}; dispatch_attempt_generation={runtimeUnlockAliasRejectedState.DispatchAttemptGeneration}; offer_generation={offerGeneration}; decision_reason=runtime_unlock_retry_offer_alias_rejected");
            ResumeActivationPauseIfNeeded(
                "tuna_activation_failed_regular_v4_resumed",
                "runtime_unlock_retry_offer_alias_rejected");
            return;
        }

        if (deferInitialActivationPayerIntent)
        {
            var payerIntentRetryReason =
                "runtime_unlock_payer_intent_send_rejected";
            AccelerationControlSendResult payerIntentQueued;
            try
            {
                if (runtimeUnlockOfferAuthorityBoundary is not
                        {
                            Mode:
                                RuntimeUnlockOfferAuthorityMode
                                    .InitialActivation,
                        } initialActivationBoundary ||
                    !ValidateRuntimeUnlockOfferAuthorityBoundary(
                        initialActivationBoundary,
                        "payer_intent_send",
                        allowDispatchObservedSettlement: false))
                {
                    return;
                }

                payerIntentQueued =
                    await SendAccelerationPayerIntentAsync(
                            remoteEndpoint,
                            sessionId,
                            envelopeCode,
                            localRole,
                            preflightLanes,
                            tunaSession.CanOfferListener ||
                            requiresContractLocalListenerRetry,
                            reason,
                            payerDecisionId,
                            ct,
                            expectedInstallReceipt: null,
                            offerAuthorityMode:
                                RuntimeUnlockOfferAuthorityMode
                                    .InitialActivation,
                            expectedOfferAuthorityBoundary:
                                initialActivationBoundary,
                            preparedSubmission: payerIntentSubmission)
                        .ConfigureAwait(false);
            }
            catch
            {
                _ = RetireRuntimeUnlockOfferIfCurrent(
                    nonce,
                    payerDecisionId,
                    offerGeneration,
                    sessionId,
                    "payer_intent_send_failed",
                    payerIntentRetryReason);
                ResumeActivationPauseIfNeeded(
                    "tuna_activation_failed_regular_v4_resumed",
                    "payer_intent_send_failed");
                throw;
            }

            if (!payerIntentQueued.Succeeded)
            {
                if (payerIntentQueued.StaleCallbackIgnored)
                {
                    return;
                }

                var retired = RetireRuntimeUnlockOfferIfCurrent(
                    nonce,
                    payerDecisionId,
                    offerGeneration,
                    sessionId,
                    "payer_intent_send_not_observed",
                    payerIntentRetryReason);
                ResumeActivationPauseIfNeeded(
                    "tuna_activation_failed_regular_v4_resumed",
                    payerIntentRetryReason);
                if (retired)
                {
                    _ = ScheduleInitialRuntimeUnlockAccelerationNegotiationRetry(
                        payerIntentRetryReason);
                }
                return;
            }

            if (!ValidateRuntimeUnlockOfferAuthorityBoundary(
                    runtimeUnlockOfferAuthorityBoundary,
                    "payer_intent_completion",
                    allowDispatchObservedSettlement: false))
            {
                return;
            }
        }

        LogRuntimeUnlockTransactionDecision(
            RuntimeUnlockTransactionEventKind.OfferGenerationCreated,
            runtimeUnlockTransactionStarted);

        if (requiresContractLocalListenerRetry)
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=runtime_unlock_offer_dispatched_after_listener_rearm; session_id={SanitizeLogToken(sessionId)}; payer_decision_id={payerDecisionId}; generation={offerGeneration}; trigger={SanitizeLogToken(reason)}");
        }

        if (runtimeUnlockAuthorityGrantedSnapshot is not null)
        {
            LogRuntimeUnlockRecoveryContract(
                "session_recovery_contract_retry_authority_granted",
                runtimeUnlockAuthorityGrantedSnapshot.SessionId);
        }

        if (runtimeUnlockAuthorityOfferWindowSnapshot is not null)
        {
            LogRuntimeUnlockRecoveryContract(
                "session_recovery_contract_retry_authority_offer_window_refreshed",
                runtimeUnlockAuthorityOfferWindowSnapshot.SessionId);
        }

        if (!isRuntimeUnlockActivation)
        {
            PauseActivationIfNeeded("offer_send_prepare");
        }
        var runtimeUnlockCutThroughStarted = usesInstalledRetryAuthority &&
            TryStartRuntimeUnlockCutThroughForCurrentOffer(
                sessionId,
                offerGeneration,
                reason);
        if (runtimeUnlockCutThroughStarted)
        {
            PauseActivationIfNeeded("runtime_unlock_cutthrough_offer_send_prepare");
        }

        void PauseRegularV4ForRuntimeUnlockActivationWindowOfferSend()
        {
            if (!usesInstalledRetryAuthority ||
                pausedForActivationNegotiation)
            {
                return;
            }

            if (!ShouldPauseRegularNknV4FileTransferForRuntimeUnlockActivationWindowOfferSend(
                    sessionId,
                    offerGeneration,
                    out _))
            {
                return;
            }

            pausedForActivationNegotiation = PauseRegularNknV4FileTransferForRuntimeUnlockMakeBeforeBreak(
                sessionId,
                "runtime_unlock_regular_v4_activation_window_offer_send",
                reason);
            if (pausedForActivationNegotiation)
            {
                LocalOperationalLog.Info(
                    "NKN.Tuna",
                    $"event=runtime_unlock_regular_v4_activation_window_quiesce_started; session_id={SanitizeLogToken(sessionId)}; payer_decision_id={payerDecisionId}; generation={offerGeneration}; trigger={SanitizeLogToken(reason)}; reason=peer_visible_offer_send");
            }
        }

        RuntimeUnlockInitialActivationReceiveRecoveryHoldPrevalidation
            initialOfferPrevalidation = default;
        if (runtimeUnlockOfferAuthorityBoundary is
                {
                    Mode: RuntimeUnlockOfferAuthorityMode.InitialActivation,
                    TransferId: { Length: > 0 },
                } initialOfferBoundary)
        {
            if (!TryCreateRuntimeUnlockInitialActivationReceiveRecoveryHoldRequest(
                    initialOfferBoundary,
                    RuntimeUnlockInitialActivationReceiveRecoveryHoldBoundary
                        .OfferPreSend,
                    out var offerPreSendHoldRequest))
            {
                return;
            }

            initialOfferPrevalidation =
                await PrevalidateRuntimeUnlockInitialActivationReceiveRecoveryHoldAsync(
                        offerPreSendHoldRequest,
                        ct)
                    .ConfigureAwait(false);
            if (!initialOfferPrevalidation.IsReleased ||
                !ValidateRuntimeUnlockOfferAuthorityBoundary(
                    initialOfferBoundary,
                    "initial_activation_hold_offer_pre_send_released",
                    allowDispatchObservedSettlement: false))
            {
                return;
            }
        }

        Task<AccelerationControlSendResult> SendCurrentOfferEnvelopeAsync(
            RuntimeUnlockInitialActivationReceiveRecoveryHoldPrevalidation?
                holdPrevalidation = null)
        {
            var currentEnvelope = envelope;
            var currentBoundary = runtimeUnlockOfferAuthorityBoundary;
            if (currentBoundary is
                { Mode: RuntimeUnlockOfferAuthorityMode.InitialActivation })
            {
                lock (accelerationGate)
                {
                    if (runtimeUnlockInitialActivationEnvelopeState is
                            { } refreshed &&
                        refreshed.Boundary.OfferGeneration ==
                            currentBoundary.OfferGeneration &&
                        refreshed.Boundary.TransactionGeneration ==
                            currentBoundary.TransactionGeneration &&
                        refreshed.Boundary.TunaPathLeaseGeneration ==
                            currentBoundary.TunaPathLeaseGeneration &&
                        string.Equals(
                            refreshed.Boundary.SemanticOfferFingerprint,
                            currentBoundary.SemanticOfferFingerprint,
                            StringComparison.Ordinal))
                    {
                        currentEnvelope = refreshed.Envelope;
                        currentBoundary = refreshed.Boundary;
                        envelope = refreshed.Envelope;
                        runtimeUnlockOfferAuthorityBoundary =
                            refreshed.Boundary;
                    }
                }
            }

            return SendAccelerationControlEnvelopeWithBulkBypassAsync(
                    remoteEndpoint,
                    currentEnvelope,
                    "offer",
                    ct,
                    requireObservedSend: true,
                    activationSessionId: sessionId,
                    onBeforeSend: PauseRegularV4ForRuntimeUnlockActivationWindowOfferSend,
                    onQueueAccepted: () =>
                    {
                        if (!isRuntimeUnlockActivation && ShouldPauseRuntimeUnlockOfferOnQueueAccepted())
                        {
                            PauseActivationIfNeeded("offer_queue_accepted");
                        }
                    },
                    onObservedSendWaitStarted: isRuntimeUnlockActivation
                        ? null
                        : () => PauseActivationIfNeeded("offer_queue_accepted"),
                    queueAcceptedAsObservedReason: usesInstalledRetryAuthority
                        ? GetRuntimeUnlockOfferQueueAcceptedObservedReason
                        : null,
                    observedSendFallbackAsync:
                        usesInstalledRetryAuthority &&
                        currentBoundary is
                            { } peerVisibleAuthorityBoundary
                        ? () => TrySendRuntimeUnlockOfferViaPeerVisibleControlPlaneAsObservedAsync(
                            remoteEndpoint,
                            currentEnvelope,
                            sessionId,
                            payerDecisionId,
                            nonce,
                            offerGeneration,
                            reason,
                            peerVisibleAuthorityBoundary)
                         : null,
                    expectedInstallReceipt: isRuntimeUnlockActivation
                        ? expectedInstallReceipt
                        : null,
                    expectedOfferAuthorityBoundary:
                        currentBoundary,
                    initialActivationHoldPrevalidation:
                        holdPrevalidation);
        }

        AccelerationControlSendResult offerSend;
        try
        {
            offerSend =
                await SendCurrentOfferEnvelopeAsync(
                        initialOfferPrevalidation.IsReleased
                            ? initialOfferPrevalidation
                            : null)
                    .ConfigureAwait(false);
        }
        catch
        {
            ResumeActivationPauseIfNeeded("tuna_activation_failed_regular_v4_resumed", "offer_send_failed");
            throw;
        }

        while (!offerSend.Succeeded &&
               !offerSend.StaleCallbackIgnored &&
               !offerSend.UntrustedProbeSent &&
               runtimeUnlockOfferAuthorityBoundary is
               {
                   Mode: RuntimeUnlockOfferAuthorityMode.InitialActivation,
                   TransferId: { Length: > 0 },
               } failedInitialOfferBoundary)
        {
            if (!TryCreateRuntimeUnlockInitialActivationReceiveRecoveryHoldRequest(
                    failedInitialOfferBoundary,
                    RuntimeUnlockInitialActivationReceiveRecoveryHoldBoundary
                        .UnobservedOfferSendFailure,
                    out var failureHoldRequest))
            {
                return;
            }

            var failureHold =
                await PrevalidateRuntimeUnlockInitialActivationReceiveRecoveryHoldAsync(
                        failureHoldRequest,
                        ct)
                    .ConfigureAwait(false);
            if (ShouldResumeRuntimeUnlockInitialActivationSameGeneration(
                    failureHold.Result))
            {
                if (!ValidateRuntimeUnlockOfferAuthorityBoundary(
                        failedInitialOfferBoundary,
                        "initial_activation_hold_unobserved_send_resumed",
                        allowDispatchObservedSettlement: false))
                {
                    return;
                }

                offerSend =
                    await SendCurrentOfferEnvelopeAsync(failureHold)
                        .ConfigureAwait(false);
                continue;
            }

            if (!failureHold.IsReleased)
            {
                return;
            }

            break;
        }

        if (isRuntimeUnlockActivation &&
            offerSend.StaleCallbackIgnored)
        {
            return;
        }

        if (isRuntimeUnlockActivation &&
            IsRuntimeUnlockOfferGenerationRetired(nonce, payerDecisionId, offerGeneration))
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=tuna_acceleration_offer_send_result_ignored; reason=retired_generation; trigger={SanitizeLogToken(reason)}; session_id={SanitizeLogToken(sessionId)}; payer_decision_id={payerDecisionId}; generation={offerGeneration}; observed_lane={SanitizeLogToken(offerSend.ObservedLane)}; succeeded={(offerSend.Succeeded ? 1 : 0)}");
            return;
        }

        if (isRuntimeUnlockActivation &&
            !offerSend.Succeeded &&
            await WaitForRuntimeUnlockPeerAnswerAsObservedSendAsync(
                sessionId,
                nonce,
                payerDecisionId,
                offerGeneration,
                ct).ConfigureAwait(false))
        {
            offerSend = AccelerationControlSendResult.Success(AccelerationObservedLanePeerAnswer);
        }

        if (offerSend.Succeeded &&
            isRuntimeUnlockActivation)
        {
            if (requireRuntimeUnlockRetryDispatchInstall)
            {
                if (!ValidateRuntimeUnlockRetryDispatchInstallReceiptBoundary(
                        expectedInstallReceipt,
                        "observed_send"))
                {
                    return;
                }

                if (!MarkRuntimeUnlockRecoveryContractRetryObserved(
                        sessionId,
                        offerGeneration,
                        offerSend.ObservedLane))
                {
                    return;
                }
            }

            MarkRuntimeUnlockOfferObservedSendIfCurrent(
                nonce,
                payerDecisionId,
                offerGeneration,
                offerSend.ObservedLane);
            ApplyRuntimeUnlockTransaction(
                RuntimeUnlockTransactionEventKind.ObservedSend,
                sessionId,
                offerGeneration,
                "offer_observed_send",
                observedLane: offerSend.ObservedLane);
            if (runtimeUnlockCutThroughStarted)
            {
                MarkRuntimeUnlockCutThroughOfferSent(sessionId, offerGeneration, offerSend.ObservedLane);
            }

            var pausedAfterPeerVisibleOffer = PauseRegularNknV4FileTransferForRuntimeUnlockMakeBeforeBreak(
                sessionId,
                "runtime_unlock_offer_observed_waiting_for_answer",
                reason);
            if (pausedAfterPeerVisibleOffer &&
                string.Equals(
                    offerSend.ObservedLane,
                    AccelerationObservedLaneControlPlanePeerVisible,
                    StringComparison.OrdinalIgnoreCase))
            {
                LocalOperationalLog.Info(
                    "NKN.Tuna",
                    $"event=runtime_unlock_regular_v4_activation_window_quiesce_started; session_id={SanitizeLogToken(sessionId)}; payer_decision_id={payerDecisionId}; generation={offerGeneration}; trigger={SanitizeLogToken(reason)}; reason=peer_visible_offer_send_after_proof");
            }

            if (requireRuntimeUnlockRetryDispatchInstall &&
                !string.Equals(
                    offerSend.ObservedLane,
                    AccelerationObservedLaneControlPlanePeerVisible,
                    StringComparison.OrdinalIgnoreCase))
            {
                if (runtimeUnlockOfferAuthorityBoundary is { } authorityBoundary)
                {
                    ScheduleRuntimeUnlockPeerVisibleOfferDeliveryConfirmation(
                        remoteEndpoint,
                        envelope,
                        sessionId,
                        payerDecisionId,
                        nonce,
                        offerGeneration,
                        reason,
                        authorityBoundary);
                }
            }
        }

        if (isRuntimeUnlockActivation && offerSend.UntrustedProbeSent)
        {
            LocalOperationalLog.Warn(
                "NKN.Tuna",
                $"event=tuna_acceleration_offer_probe_sent_untrusted; reason={SanitizeLogToken(reason)}; session_id={SanitizeLogToken(sessionId)}; lanes={string.Join(",", offer.SupportedLanes)}; payer_decision_id={payerDecisionId}; generation={offerGeneration}; observed_lane={SanitizeLogToken(offerSend.ObservedLane)}; queue_local_only=0; replay_scheduled=0; answer_timeout_scheduled=1");
            NotifyTransportAccelerationStateChanged("waiting_for_answer_untrusted_probe");
            MarkRuntimeUnlockOfferAnswerTimeoutScheduledIfCurrent(nonce, payerDecisionId, offerGeneration);
            ScheduleAccelerationOfferAnswerTimeout(
                nonce,
                expectedInstallReceipt,
                requireRuntimeUnlockRetryDispatchInstall:
                    requireRuntimeUnlockRetryDispatchInstall);
            return;
        }

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=tuna_acceleration_offer_{(offerSend.Succeeded ? "queued" : "rejected")}; reason={SanitizeLogToken(reason)}; session_id={sessionId}; lanes={string.Join(",", offer.SupportedLanes)}; payer_decision_id={payerDecisionId}; generation={offerGeneration}; observed_lane={SanitizeLogToken(offerSend.ObservedLane)}; queue_local_only=0; recovery_requested={(offerSend.RecoveryRequested ? 1 : 0)}; recovery_reason={SanitizeLogToken(offerSend.RecoveryReason)}");
        if (!offerSend.Succeeded)
        {
            if (usesInstalledRetryAuthority)
            {
                var missingDispatchSettled = TrySettleRuntimeUnlockRetryDispatchMissingCore(
                    sessionId,
                    offerGeneration,
                    "peer_visible_offer_send_not_observed",
                    requestSuccessor: false);
                var promoteSendBlockToCutThrough =
                    ShouldPromoteRuntimeUnlockAuthoritySendBlockToCutThrough(sessionId);
                var retryReason = promoteSendBlockToCutThrough
                    ? RuntimeUnlockCutThroughRetryReason
                    : "runtime_unlock_offer_send_not_observed";
                var effectiveRecoveryReason = promoteSendBlockToCutThrough
                    ? RuntimeUnlockCutThroughRecoveryReason
                    : offerSend.RecoveryReason ?? "tuna_activation_offer_send_timeout";
                if (missingDispatchSettled)
                {
                    RequestRuntimeUnlockRetryDispatchAuthority(
                        sessionId,
                        "predecessor_missing_dispatch_offer_retired");
                }

                if (!missingDispatchSettled &&
                    FailRuntimeUnlockRegularV4ActivationWindowIfUnproven(
                        sessionId,
                        offerGeneration,
                        "offer_send_not_observed",
                        "runtime_unlock_regular_v4_peer_visible_window_failed"))
                {
                    return;
                }

                var retired = RetireRuntimeUnlockOfferIfCurrent(
                    nonce,
                    payerDecisionId,
                    offerGeneration,
                    sessionId,
                    "offer_send_not_observed",
                    retryReason);
                var alreadyRetiredForRecovery = !retired &&
                    IsRuntimeUnlockOfferGenerationRetired(nonce, payerDecisionId, offerGeneration);
                var deferRetryUntilRecoverySettled =
                    offerSend.RecoveryRequested &&
                    (retired || alreadyRetiredForRecovery);
                var waitingForDispatchSuccessor =
                    missingDispatchSettled;
                if (promoteSendBlockToCutThrough)
                {
                    LocalOperationalLog.Warn(
                        "NKN.Tuna",
                        $"event=tuna_acceleration_runtime_unlock_authority_send_blocked_promoted_to_cutthrough; session_id={SanitizeLogToken(sessionId)}; payer_decision_id={payerDecisionId}; generation={offerGeneration}; retry_reason={SanitizeLogToken(retryReason)}; recovery_reason={SanitizeLogToken(effectiveRecoveryReason)}; source_recovery_reason={SanitizeLogToken(offerSend.RecoveryReason)}");
                }

                LocalOperationalLog.Warn(
                    "NKN.Tuna",
                    $"event=tuna_acceleration_activation_offer_not_observed; trigger={SanitizeLogToken(reason)}; session_id={SanitizeLogToken(sessionId)}; payer_decision_id={payerDecisionId}; generation={offerGeneration}; late_answer_window_ms={(long)AccelerationOfferAnswerTimeout.TotalMilliseconds}; retry_scheduled={(!waitingForDispatchSuccessor && !deferRetryUntilRecoverySettled ? 1 : 0)}; retry_after_recovery_armed={(!waitingForDispatchSuccessor && deferRetryUntilRecoverySettled ? 1 : 0)}; dispatch_successor_requested={(missingDispatchSettled ? 1 : 0)}; replay_scheduled=0; answer_timeout_scheduled=0; pause_deferred={(pausedForActivationNegotiation ? 0 : 1)}; recovery_requested={(offerSend.RecoveryRequested ? 1 : 0)}; recovery_reason={SanitizeLogToken(effectiveRecoveryReason)}");
                NotifyTransportAccelerationStateChanged("activation_offer_not_observed");
                if (pausedForActivationNegotiation)
                {
                    ResumeActivationPauseIfNeeded(
                        "tuna_activation_failed_regular_v4_resumed",
                        "offer_send_not_observed");
                }

                if (missingDispatchSettled)
                {
                    LocalOperationalLog.Info(
                        "NKN.Tuna",
                        $"event=tuna_acceleration_activation_offer_retry_waiting_for_dispatch_successor; trigger={SanitizeLogToken(reason)}; session_id={SanitizeLogToken(sessionId)}; payer_decision_id={payerDecisionId}; generation={offerGeneration}; predecessor_settlement_outcome=MissingDispatch; retry_scheduled=0; decision_reason=coordinator_successor_required");
                }
                else if (deferRetryUntilRecoverySettled)
                {
                    if (retired || (promoteSendBlockToCutThrough && alreadyRetiredForRecovery))
                    {
                        if (runtimeUnlockOfferAuthorityBoundary is not
                            {
                                Mode: RuntimeUnlockOfferAuthorityMode.InstalledRetry,
                            } recoveryAuthorityBoundary)
                        {
                            return;
                        }

                        var requiresLocalListenerRetry =
                            !promoteSendBlockToCutThrough ||
                            !ShouldUseListenerReadyFastRetry(
                                RuntimeUnlockCutThroughRetryReason,
                                runtimeUnlockRetry: true);
                        ArmRuntimeUnlockRetryAfterRecovery(
                            offerGeneration,
                            offerSend.RecoverySessionId ?? sessionId,
                            retryReason,
                            effectiveRecoveryReason,
                            requiresLocalListenerRetry,
                            requiresLocalListenerRetry
                                ? RuntimeUnlockRetryDispatchListenerRearmRequirement.Required
                                : RuntimeUnlockRetryDispatchListenerRearmRequirement.None,
                            recoveryAuthorityBoundary);
                    }
                    else
                    {
                        LocalOperationalLog.Info(
                            "NKN.Tuna",
                            $"event=tuna_acceleration_activation_offer_recovery_joined_retired_generation; trigger={SanitizeLogToken(reason)}; session_id={SanitizeLogToken(sessionId)}; payer_decision_id={payerDecisionId}; generation={offerGeneration}; recovery_reason={SanitizeLogToken(effectiveRecoveryReason)}");
                    }
                }
                else
                {
                    var retryScheduled =
                        ScheduleRuntimeUnlockAccelerationNegotiationRetry(
                            retryReason,
                            expectedInstallReceipt);
                    if (!retryScheduled)
                    {
                        LocalOperationalLog.Warn(
                            "NKN.Tuna",
                            $"event=tuna_acceleration_activation_offer_retry_not_scheduled; trigger={SanitizeLogToken(reason)}; session_id={SanitizeLogToken(sessionId)}; payer_decision_id={payerDecisionId}; generation={offerGeneration}; retry_reason={SanitizeLogToken(retryReason)}");
                    }
                }
            }
            else if (isRuntimeUnlockActivation)
            {
                var retryReason = "runtime_unlock_offer_send_not_observed";
                var retired = RetireRuntimeUnlockOfferIfCurrent(
                    nonce,
                    payerDecisionId,
                    offerGeneration,
                    sessionId,
                    "offer_send_not_observed",
                    retryReason);
                NotifyTransportAccelerationStateChanged(
                    "activation_offer_not_observed");
                if (pausedForActivationNegotiation)
                {
                    ResumeActivationPauseIfNeeded(
                        "tuna_activation_failed_regular_v4_resumed",
                        "offer_send_not_observed");
                }

                var retryScheduled =
                    retired &&
                    ScheduleInitialRuntimeUnlockAccelerationNegotiationRetry(
                        retryReason);
                LocalOperationalLog.Warn(
                    "NKN.Tuna",
                    $"event=tuna_acceleration_activation_offer_not_observed; trigger={SanitizeLogToken(reason)}; session_id={SanitizeLogToken(sessionId)}; payer_decision_id={payerDecisionId}; generation={offerGeneration}; authority_mode={SanitizeLogToken(RuntimeUnlockOfferAuthorityMode.InitialActivation.ToString())}; retry_scheduled={(retryScheduled ? 1 : 0)}; retry_after_recovery_armed=0; dispatch_successor_requested=0; replay_scheduled=0; answer_timeout_scheduled=0; pause_deferred={(pausedForActivationNegotiation ? 0 : 1)}; recovery_requested={(offerSend.RecoveryRequested ? 1 : 0)}; recovery_reason={SanitizeLogToken(offerSend.RecoveryReason)}");
            }
            else
            {
                ClearOutboundAccelerationOfferIfCurrent(nonce, payerDecisionId, offerGeneration, "offer_send_not_observed");
                NotifyTransportAccelerationStateChanged("offer_queue_rejected");
                ResumeActivationPauseIfNeeded("offer_queue_rejected", "offer_queue_rejected");
                ScheduleAccelerationNegotiationRetry(
                    "offer_queue_rejected",
                    expectedInstallReceipt);
            }

            return;
        }

        if (!isRuntimeUnlockActivation)
        {
            PauseActivationIfNeeded("offer_sent");
        }

        NotifyTransportAccelerationStateChanged("waiting_for_answer");
        ScheduleAccelerationOfferReplay(
            remoteEndpoint,
            envelope,
            sessionId,
            nonce,
            payerDecisionId,
            offerGeneration,
            pauseOnQueueAccepted: !isRuntimeUnlockActivation,
            pauseAfterObservedSendOnly: false,
            expectedInstallReceipt: isRuntimeUnlockActivation ? expectedInstallReceipt : null);
        MarkRuntimeUnlockOfferAnswerTimeoutScheduledIfCurrent(nonce, payerDecisionId, offerGeneration);
        ScheduleAccelerationOfferAnswerTimeout(
            nonce,
            isRuntimeUnlockActivation ? expectedInstallReceipt : null,
            requireRuntimeUnlockRetryDispatchInstall:
                requireRuntimeUnlockRetryDispatchInstall);
        ScheduleRuntimeUnlockOfferPeerResponseTimeout(
            nonce,
            payerDecisionId,
            offerGeneration,
            sessionId,
            offerSend.ObservedLane,
            expectedInstallReceipt);
    }

    private void ScheduleAccelerationOfferReplay(
        string target,
        Envelope envelope,
        string sessionId,
        string nonce,
        long payerDecisionId,
        long generation,
        bool pauseOnQueueAccepted,
        bool pauseAfterObservedSendOnly,
        RuntimeUnlockRetryDispatchInstallReceipt? expectedInstallReceipt = null)
    {
        var offerAuthorityBoundary =
            CaptureRuntimeUnlockOfferAuthorityBoundary(
                nonce,
                payerDecisionId,
                generation);
        var replaySubmissionDeadlineUtcMs =
            DateTimeOffset.UtcNow
                .Add(
                    ResolveAccelerationOfferAnswerTimeout(
                        nonce,
                        offerAuthorityBoundary?.Mode ==
                            RuntimeUnlockOfferAuthorityMode.InstalledRetry))
                .ToUnixTimeMilliseconds();
        _ = Task.Run(
            async () =>
            {
                var delay = AccelerationOfferReplayDelayOverrideForTests ?? AccelerationOfferReplayDelay;
                var observedReplaySent = false;
                for (var attempt = 1; attempt <= AccelerationOfferReplayAttempts; attempt++)
                {
                    await Task.Delay(delay, CancellationToken.None).ConfigureAwait(false);
                    if (offerAuthorityBoundary is not null
                            ? !ValidateRuntimeUnlockOfferAuthorityBoundary(
                                offerAuthorityBoundary,
                                "offer_replay_delay",
                                allowDispatchObservedSettlement: true)
                            : !ValidateRuntimeUnlockRetryDispatchInstallReceiptBoundary(
                                expectedInstallReceipt,
                                "offer_replay_delay",
                                allowDispatchObservedSettlement: true))
                    {
                        return;
                    }

                    if (!IsOutboundAccelerationOfferPending(nonce, payerDecisionId, generation))
                    {
                        return;
                    }

                    var pausedForReplayAttempt = false;
                    void PauseReplayAttempt(string trigger)
                    {
                        pausedForReplayAttempt = PauseFileTransferDataSessionsForTunaActivationNegotiation(
                            "activation_negotiation_pending",
                            sessionId,
                            trigger);
                    }

                    Task<AccelerationControlSendResult> SendReplayEnvelopeAsync(
                        RuntimeUnlockInitialActivationReceiveRecoveryHoldPrevalidation?
                            holdPrevalidation = null)
                        => SendAccelerationControlEnvelopeWithBulkBypassAsync(
                            target,
                            envelope,
                            "offer_replay",
                            CancellationToken.None,
                            requireObservedSend: true,
                            activationSessionId: sessionId,
                            onQueueAccepted: () =>
                            {
                                if (pauseOnQueueAccepted &&
                                    ShouldPauseRuntimeUnlockOfferOnQueueAccepted())
                                {
                                    PauseReplayAttempt(
                                        "offer_replay_queue_accepted");
                                }
                            },
                            onObservedSendWaitStarted: pauseAfterObservedSendOnly
                                ? () => PauseReplayAttempt(
                                    "offer_replay_send_observed")
                                : null,
                            queueAcceptedAsObservedReason:
                                offerAuthorityBoundary?.Mode ==
                                    RuntimeUnlockOfferAuthorityMode.InstalledRetry
                                    ? GetRuntimeUnlockOfferQueueAcceptedObservedReason
                                    : null,
                            expectedInstallReceipt: expectedInstallReceipt,
                            allowDispatchObservedInstallReceipt: true,
                            expectedOfferAuthorityBoundary:
                                offerAuthorityBoundary,
                            latestSubmissionUtcMs:
                                replaySubmissionDeadlineUtcMs,
                            rebaseLatestSubmissionAfterInitialActivationHold:
                                () =>
                                {
                                    replaySubmissionDeadlineUtcMs =
                                        DateTimeOffset.UtcNow
                                            .Add(
                                                ResolveAccelerationOfferAnswerTimeout(
                                                    nonce,
                                                    requireRuntimeUnlockRetryDispatchInstall:
                                                        false))
                                            .ToUnixTimeMilliseconds();
                                    return replaySubmissionDeadlineUtcMs;
                                },
                            initialActivationHoldPrevalidation:
                                holdPrevalidation);

                    var queued =
                        await SendReplayEnvelopeAsync().ConfigureAwait(false);
                    while (!queued.Succeeded &&
                           !queued.StaleCallbackIgnored &&
                           !queued.UntrustedProbeSent &&
                           offerAuthorityBoundary is
                           {
                               Mode:
                                   RuntimeUnlockOfferAuthorityMode
                                       .InitialActivation,
                               TransferId: { Length: > 0 },
                           } initialReplayBoundary)
                    {
                        bool peerVisibleDispatchObserved;
                        lock (accelerationGate)
                        {
                            var proof = runtimeUnlockOfferProofState;
                            if (proof is null ||
                                proof.Generation !=
                                    initialReplayBoundary.OfferGeneration ||
                                proof.PayerDecisionId !=
                                    initialReplayBoundary.PayerDecisionId ||
                                !string.Equals(
                                    proof.Nonce,
                                    initialReplayBoundary.Nonce,
                                    StringComparison.Ordinal))
                            {
                                return;
                            }

                            peerVisibleDispatchObserved =
                                proof.ObservedSend || proof.PeerReceived;
                        }

                        if (!TryCreateRuntimeUnlockInitialActivationReceiveRecoveryHoldRequest(
                                initialReplayBoundary,
                                RuntimeUnlockInitialActivationReceiveRecoveryHoldBoundary
                                    .UnobservedOfferSendFailure,
                                out var replayFailureHoldRequest,
                                peerVisibleDispatchObserved))
                        {
                            return;
                        }

                        var replayFailureHold =
                            await PrevalidateRuntimeUnlockInitialActivationReceiveRecoveryHoldAsync(
                                    replayFailureHoldRequest,
                                    CancellationToken.None)
                                .ConfigureAwait(false);
                        if (ShouldResumeRuntimeUnlockInitialActivationSameGeneration(
                                replayFailureHold.Result))
                        {
                            if (!ValidateRuntimeUnlockOfferAuthorityBoundary(
                                    initialReplayBoundary,
                                    "initial_activation_hold_offer_replay_resumed",
                                    allowDispatchObservedSettlement: true))
                            {
                                return;
                            }

                            replaySubmissionDeadlineUtcMs =
                                DateTimeOffset.UtcNow
                                    .Add(
                                        ResolveAccelerationOfferAnswerTimeout(
                                            nonce,
                                            requireRuntimeUnlockRetryDispatchInstall:
                                                false))
                                    .ToUnixTimeMilliseconds();
                            queued =
                                await SendReplayEnvelopeAsync(replayFailureHold)
                                    .ConfigureAwait(false);
                            continue;
                        }

                        if (!replayFailureHold.IsReleased)
                        {
                            return;
                        }

                        break;
                    }

                    if (offerAuthorityBoundary is not null
                            ? !ValidateRuntimeUnlockOfferAuthorityBoundary(
                                offerAuthorityBoundary,
                                "offer_replay_completion",
                                allowDispatchObservedSettlement: true)
                            : !ValidateRuntimeUnlockRetryDispatchInstallReceiptBoundary(
                                expectedInstallReceipt,
                                "offer_replay_completion",
                                allowDispatchObservedSettlement: true))
                    {
                        return;
                    }
                    if (queued.Succeeded)
                    {
                        MarkRuntimeUnlockOfferObservedSendIfCurrent(nonce, payerDecisionId, generation, queued.ObservedLane);
                    }

                    if (pauseAfterObservedSendOnly && queued.Succeeded)
                    {
                        observedReplaySent = true;
                        PauseReplayAttempt("offer_replay_sent");
                    }
                    else if (!queued.Succeeded && (pausedForReplayAttempt || (pauseAfterObservedSendOnly && !observedReplaySent)))
                    {
                        ResumeFileTransferDataSessionsAfterTunaActivationFailure(
                            "offer_replay_not_observed",
                            sessionId,
                            "offer_replay_not_observed");
                    }

                    LocalOperationalLog.Info(
                        "NKN.Tuna",
                        $"event=tuna_acceleration_offer_replay_{(queued.Succeeded ? "sent" : "rejected")}; attempt={attempt}; session_id={SanitizeLogToken(sessionId)}; payer_decision_id={payerDecisionId}; generation={generation}; observed_lane={SanitizeLogToken(queued.ObservedLane)}");
                }
            },
            CancellationToken.None);
    }

    private bool IsOutboundAccelerationOfferPending(string nonce, long payerDecisionId, long generation)
    {
        lock (accelerationGate)
        {
            return outboundAccelerationOfferGeneration == generation &&
                   outboundAccelerationOfferPayerDecisionId == payerDecisionId &&
                   string.Equals(outboundAccelerationOfferNonce, nonce, StringComparison.Ordinal);
        }
    }

    private bool TrySupersedeStaleActiveNegotiationForRuntimeUnlockRecoveryContract()
    {
        RuntimeUnlockRecoveryRetryState? stateSnapshot = null;
        lock (accelerationGate)
        {
            var state = runtimeUnlockRecoveryRetryState;
            if (state is null ||
                state.RetryObserved ||
                state.ContractState is SessionRecoveryContractState.Completed or SessionRecoveryContractState.Failed ||
                !state.RetryQueued ||
                !state.QueuedBehindActiveNegotiation)
            {
                return false;
            }

            var nowMs = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
            var staleWindow = RuntimeUnlockRecoveryContractStaleNegotiationWindowOverrideForTests ??
                RuntimeUnlockRecoveryContractStaleNegotiationWindow;
            if (nowMs - state.CreatedUtcMs < (long)staleWindow.TotalMilliseconds)
            {
                return false;
            }

            if (!string.IsNullOrWhiteSpace(outboundAccelerationOfferNonce) ||
                !string.IsNullOrWhiteSpace(pendingAccelerationAnswerAckNonce))
            {
                return false;
            }

            if (runtimeUnlockOfferProofState is { Retired: false, ObservedSend: true })
            {
                return false;
            }

            state.ContractState = SessionRecoveryContractState.RetryDispatching;
            state.RetryDispatching = true;
            stateSnapshot = state;
        }

        ClearPendingRuntimeUnlockAccelerationNegotiation();
        Interlocked.Exchange(ref accelerationNegotiationScheduled, 0);
        LogRuntimeUnlockRecoveryContract(
            "session_recovery_contract_stale_negotiation_superseded",
            stateSnapshot!.SessionId);
        return true;
    }

    private void MarkRuntimeUnlockRecoveryContractQueuedBehindActiveNegotiation(string reason)
    {
        RuntimeUnlockRecoveryRetryState? stateSnapshot = null;
        lock (accelerationGate)
        {
            var state = runtimeUnlockRecoveryRetryState;
            if (state is null ||
                state.RetryObserved ||
                state.ContractState is SessionRecoveryContractState.Completed or SessionRecoveryContractState.Failed ||
                !HasRuntimeUnlockRetryDispatchLineageUnsafe(state))
            {
                return;
            }

            state.QueuedBehindActiveNegotiation = true;
            state.RetryQueued = false;
            state.RetryDispatching = false;
            state.RetryDispatched = false;
            state.RetryAuthorityPending = state.DispatchContract is not null;
            state.RetryAuthorityGranted = state.DispatchContract is not null;
            state.ObservedSendPending = false;
            state.DispatchObserved = false;
            state.DispatchDecisionReason = "active_negotiation_pending";
            state.ContractState = state.Settled
                ? SessionRecoveryContractState.RecoverySettled
                : state.ContractState;
            stateSnapshot = state;
        }

        LogRuntimeUnlockRetryDispatchProof(
            "runtime_unlock_retry_dispatch_held_by_active_negotiation",
            stateSnapshot!,
            "active_negotiation_pending");
    }

    private void GrantRuntimeUnlockRecoveryContractRetryAuthorityUnsafe(RuntimeUnlockRecoveryRetryState state)
    {
        var nowMs = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
        RefreshRuntimeUnlockRecoveryContractOfferSendWindowUnsafe(state, nowMs);
    }

    private bool PublishRuntimeUnlockRetryDispatchExecutionObservation(
        RuntimeUnlockRetryDispatchExecutionObservation observation)
    {
        if (observation.IsDefault)
        {
            return false;
        }

        var subscriber = runtimeUnlockRetryDispatchExecutionObserved;
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=runtime_unlock_retry_dispatch_execution_observed; {FormatRuntimeUnlockRetryDispatchAuthorityTuple(observation.Authority)}; install_generation={observation.InstallReceipt.InstallGeneration}; attempt_phase={SanitizeLogToken(observation.AttemptPhase.ToString())}; offer_generation={observation.OfferGeneration}; offer_nonce={SanitizeLogToken(observation.OfferNonce ?? "(none)")}; dispatch_observed={(observation.DispatchObserved ? 1 : 0)}; subscriber_present={(subscriber is null ? 0 : 1)}; decision_reason={(subscriber is null ? "execution_observation_subscriber_missing" : "reported_to_core")}");
        if (subscriber is null)
        {
            return false;
        }

        try
        {
            var args =
                new RuntimeUnlockRetryDispatchExecutionObservedEventArgs(
                    observation);
            subscriber.Invoke(
                this,
                args);
            var decision = args.Decision;
            var accepted = decision is
            {
                Accepted: true,
                State: not null,
            };
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=runtime_unlock_retry_dispatch_execution_decided; {FormatRuntimeUnlockRetryDispatchAuthorityTuple(observation.Authority)}; install_generation={observation.InstallReceipt.InstallGeneration}; attempt_phase={SanitizeLogToken(observation.AttemptPhase.ToString())}; offer_generation={observation.OfferGeneration}; offer_nonce={SanitizeLogToken(observation.OfferNonce ?? "(none)")}; decision_status={SanitizeLogToken(decision?.Status.ToString() ?? "(none)")}; decision_reason={SanitizeLogToken(decision?.Reason ?? "execution_observation_decision_missing")}");
            return accepted;
        }
        catch (Exception ex)
        {
            LocalOperationalLog.Warn(
                "NKN.Tuna",
                $"event=runtime_unlock_retry_dispatch_execution_observation_handler_failed; {FormatRuntimeUnlockRetryDispatchAuthorityTuple(observation.Authority)}; attempt_phase={SanitizeLogToken(observation.AttemptPhase.ToString())}; error={SanitizeLogToken(ex.GetType().Name)}; decision_reason=execution_observation_handler_failed");
            return false;
        }
    }

    private void RequestRuntimeUnlockRetryDispatchSuccessorEvaluation(
        RuntimeUnlockRetryDispatchSuccessorEvaluation evaluation,
        string trigger)
    {
        if (evaluation.IsDefault)
        {
            return;
        }

        var subscriber = runtimeUnlockRetryDispatchSuccessorEvaluationRequested;
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=runtime_unlock_retry_dispatch_successor_evaluation_requested; {FormatRuntimeUnlockRetryDispatchAuthorityTuple(evaluation.PredecessorAuthority)}; retired_generation={evaluation.RetiredOfferGeneration}; trigger={SanitizeLogToken(trigger)}; subscriber_present={(subscriber is null ? 0 : 1)}; decision_reason={(subscriber is null ? "successor_evaluation_subscriber_missing" : "reported_to_core")}");
        if (subscriber is null)
        {
            return;
        }

        try
        {
            subscriber.Invoke(
                this,
                new RuntimeUnlockRetryDispatchSuccessorEvaluationEventArgs(evaluation));
        }
        catch (Exception ex)
        {
            LocalOperationalLog.Warn(
                "NKN.Tuna",
                $"event=runtime_unlock_retry_dispatch_successor_evaluation_handler_failed; {FormatRuntimeUnlockRetryDispatchAuthorityTuple(evaluation.PredecessorAuthority)}; error={SanitizeLogToken(ex.GetType().Name)}; decision_reason=successor_evaluation_handler_failed");
        }
    }

    private async Task<
        RuntimeUnlockInitialActivationReceiveRecoveryHoldEvaluation>
        RequestRuntimeUnlockInitialActivationReceiveRecoveryHoldAsync(
            RuntimeUnlockInitialActivationReceiveRecoveryHoldRequest request,
            CancellationToken ct,
            bool allowCommandCaptureRetry = true)
    {
        if (request.IsDefault)
        {
            return new(
                request,
                default,
                RuntimeUnlockInitialActivationReceiveRecoveryHoldAwaitResult
                    .Rejected);
        }

        TaskCompletionSource<
            RuntimeUnlockInitialActivationReceiveRecoveryHoldAwaitResult> completion;
        var invokeSubscriber = false;
        lock (accelerationGate)
        {
            if (runtimeUnlockInitialActivationReceiveRecoveryHoldShadow is
                { } current)
            {
                if (current.Request != request)
                {
                    return new(
                        request,
                        default,
                        RuntimeUnlockInitialActivationReceiveRecoveryHoldAwaitResult
                            .Rejected);
                }

                completion = current.Completion;
            }
            else
            {
                completion =
                    new TaskCompletionSource<
                        RuntimeUnlockInitialActivationReceiveRecoveryHoldAwaitResult>(
                        TaskCreationOptions.RunContinuationsAsynchronously);
                runtimeUnlockInitialActivationReceiveRecoveryHoldShadow =
                    new RuntimeUnlockInitialActivationReceiveRecoveryHoldShadow(
                        request,
                        Decision: null,
                        completion);
                invokeSubscriber = true;
            }
        }

        if (invokeSubscriber)
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=runtime_unlock_initial_activation_receive_recovery_hold_requested; {FormatRuntimeUnlockInitialActivationReceiveRecoveryHoldRequest(request)}; decision_reason=coordinator_receive_recovery_hold_evaluation_requested");
            var args =
                new RuntimeUnlockInitialActivationReceiveRecoveryHoldRequestedEventArgs(
                    request);
            var subscriber =
                runtimeUnlockInitialActivationReceiveRecoveryHoldRequested;
            if (subscriber is null)
            {
                _ = ApplyRuntimeUnlockInitialActivationReceiveRecoveryHoldDecision(
                    new RuntimeUnlockInitialActivationReceiveRecoveryHoldDecision(
                        request,
                        RuntimeUnlockInitialActivationReceiveRecoveryHoldStatus
                            .Rejected,
                        "initial_activation_hold_subscriber_missing",
                        HoldGeneration: 0,
                        ReceiveRecoveryOperation: null),
                    "subscriber_missing");
            }
            else
            {
                try
                {
                    subscriber.Invoke(this, args);
                    _ =
                        ApplyRuntimeUnlockInitialActivationReceiveRecoveryHoldDecision(
                            args.Decision ??
                            new RuntimeUnlockInitialActivationReceiveRecoveryHoldDecision(
                                request,
                                RuntimeUnlockInitialActivationReceiveRecoveryHoldStatus
                                    .Rejected,
                                "initial_activation_hold_decision_missing",
                                HoldGeneration: 0,
                                ReceiveRecoveryOperation: null),
                            "initial_evaluation");
                }
                catch (Exception ex)
                {
                    _ =
                        ApplyRuntimeUnlockInitialActivationReceiveRecoveryHoldDecision(
                            new RuntimeUnlockInitialActivationReceiveRecoveryHoldDecision(
                                request,
                                RuntimeUnlockInitialActivationReceiveRecoveryHoldStatus
                                    .Rejected,
                                $"initial_activation_hold_handler_failed_{SanitizeLogToken(ex.GetType().Name)}",
                                HoldGeneration: 0,
                                ReceiveRecoveryOperation: null),
                            "handler_failed");
                }
            }
        }

        var result =
            await completion.Task.WaitAsync(ct).ConfigureAwait(false);
        if (!allowCommandCaptureRetry ||
            result !=
                RuntimeUnlockInitialActivationReceiveRecoveryHoldAwaitResult
                    .Rejected)
        {
            RuntimeUnlockInitialActivationReceiveRecoveryHoldDecision decision;
            lock (accelerationGate)
            {
                decision =
                    lastRuntimeUnlockInitialActivationReceiveRecoveryHoldDecision
                        is { } exactDecision &&
                    exactDecision.Request == request
                        ? exactDecision
                        : default;
            }

            return new(request, decision, result);
        }

        var commandCaptureRace = false;
        lock (accelerationGate)
        {
            commandCaptureRace =
                lastRuntimeUnlockInitialActivationReceiveRecoveryHoldDecision
                    is
                    {
                        Status:
                            RuntimeUnlockInitialActivationReceiveRecoveryHoldStatus
                                .Rejected,
                        Reason:
                            "runtime_unlock_initial_activation_receive_recovery_command_capture_race",
                    } rejected &&
                rejected.Request == request;
        }
        if (!commandCaptureRace)
        {
            RuntimeUnlockInitialActivationReceiveRecoveryHoldDecision decision;
            lock (accelerationGate)
            {
                decision =
                    lastRuntimeUnlockInitialActivationReceiveRecoveryHoldDecision
                        is { } exactDecision &&
                    exactDecision.Request == request
                        ? exactDecision
                        : default;
            }

            return new(request, decision, result);
        }

        var currentBoundary =
            CaptureRuntimeUnlockOfferAuthorityBoundary(
                request.OfferNonce,
                request.PayerDecisionId,
                request.OfferGeneration);
        if (currentBoundary is null ||
            !RuntimeUnlockInitialActivationHoldRequestMatchesOfferBoundary(
                request,
                currentBoundary) ||
            !TryCreateRuntimeUnlockInitialActivationReceiveRecoveryHoldRequest(
                currentBoundary,
                request.Boundary,
                out var reboundRequest,
                request.PeerVisibleDispatchObserved) ||
            reboundRequest == request ||
            reboundRequest.ExpectedScope.ExpectedExecutionCommand is null)
        {
            return new(request, default, result);
        }

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=runtime_unlock_initial_activation_receive_recovery_hold_command_capture_retried; {FormatRuntimeUnlockInitialActivationReceiveRecoveryHoldRequest(reboundRequest)}; decision_reason=exact_receive_recovery_command_recaptured");
        return await RequestRuntimeUnlockInitialActivationReceiveRecoveryHoldAsync(
                reboundRequest,
                ct,
                allowCommandCaptureRetry: false)
            .ConfigureAwait(false);
    }

    private async Task<
        RuntimeUnlockInitialActivationReceiveRecoveryHoldPrevalidation>
        PrevalidateRuntimeUnlockInitialActivationReceiveRecoveryHoldAsync(
            RuntimeUnlockInitialActivationReceiveRecoveryHoldRequest request,
            CancellationToken ct)
    {
        var evaluation =
            await RequestRuntimeUnlockInitialActivationReceiveRecoveryHoldAsync(
                    request,
                    ct)
                .ConfigureAwait(false);
        if (evaluation.Decision.IsDefault)
        {
            return default;
        }

        var prevalidation =
            new RuntimeUnlockInitialActivationReceiveRecoveryHoldPrevalidation(
                evaluation.Request,
                evaluation.Decision,
                evaluation.Result);
        return prevalidation.IsReleased ? prevalidation : default;
    }

    private bool
        ValidateRuntimeUnlockInitialActivationReceiveRecoveryHoldPrevalidation(
            RuntimeUnlockOfferAuthorityBoundary boundary,
            RuntimeUnlockInitialActivationReceiveRecoveryHoldPrevalidation
                prevalidation,
            string purpose,
            out string? legacyBlockerReason,
            bool emitTelemetry = true)
    {
        legacyBlockerReason =
            CaptureRuntimeUnlockInitialActivationLegacyReceiveStallBlocker();
        var boundaryMatchMode = "none";
        var refreshGeneration = 0L;
        var refreshReceiptCurrent = false;
        var prevalidationReason = "hold_prevalidation_not_released";
        var requestMatchesBoundary =
            TryMatchRuntimeUnlockInitialActivationReceiveRecoveryHoldPrevalidationBoundary(
                prevalidation,
                boundary,
                out boundaryMatchMode,
                out refreshGeneration,
                out refreshReceiptCurrent,
                out prevalidationReason);
        var accepted =
            prevalidation.IsReleased &&
            requestMatchesBoundary &&
            RuntimeUnlockInitialActivationReceiveRecoveryHoldDecisionMatchesRequest(
                prevalidation.Decision) &&
            ValidateRuntimeUnlockOfferAuthorityBoundary(
                boundary,
                "initial_activation_hold_send_prevalidation",
                allowDispatchObservedSettlement: true);
        lock (accelerationGate)
        {
            accepted =
                accepted &&
                runtimeUnlockInitialActivationReceiveRecoveryHoldShadow is
                    null &&
                lastRuntimeUnlockInitialActivationReceiveRecoveryHoldDecision ==
                    prevalidation.Decision;
        }
        if (accepted)
        {
            prevalidationReason =
                boundaryMatchMode == "committed_refresh_successor"
                    ? "committed_refresh_successor_current"
                    : "direct_request_boundary_current";
        }
        else if (requestMatchesBoundary &&
                 prevalidation.IsReleased)
        {
            prevalidationReason =
                "released_hold_or_offer_authority_not_current";
        }

        if (emitTelemetry)
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=runtime_unlock_initial_activation_receive_recovery_hold_send_prevalidated; {FormatRuntimeUnlockInitialActivationReceiveRecoveryHoldRequest(prevalidation.Request)}; send_path={SanitizeLogToken(purpose)}; one_call_prevalidated=1; prevalidation_status={(accepted ? "accepted" : "rejected")}; decision_status={SanitizeLogToken(prevalidation.Decision.Status.ToString())}; same_generation_resume={(ShouldResumeRuntimeUnlockInitialActivationSameGeneration(prevalidation.Result) ? 1 : 0)}; boundary_match_mode={SanitizeLogToken(boundaryMatchMode)}; effective_envelope_generation={boundary.EnvelopeGeneration}; effective_envelope_fingerprint={SanitizeLogToken(boundary.ControlEnvelopeFingerprint)}; refresh_generation={refreshGeneration}; refresh_receipt_current={(refreshReceiptCurrent ? 1 : 0)}; legacy_receive_stall_blocker_observed={(IsReceiveStallActivationSendBlocker(legacyBlockerReason) ? 1 : 0)}; legacy_receive_stall_blocker={SanitizeLogToken(legacyBlockerReason ?? "(none)")}; prevalidation_reason={SanitizeLogToken(prevalidationReason)}; decision_reason={SanitizeLogToken(prevalidation.Decision.Reason)}");
        }
        return accepted;
    }

    private bool
        TryMatchRuntimeUnlockInitialActivationReceiveRecoveryHoldPrevalidationBoundary(
            RuntimeUnlockInitialActivationReceiveRecoveryHoldPrevalidation
                prevalidation,
            RuntimeUnlockOfferAuthorityBoundary boundary,
            out string matchMode,
            out long refreshGeneration,
            out bool refreshReceiptCurrent,
            out string rejectionReason)
    {
        matchMode = "none";
        refreshGeneration = 0;
        refreshReceiptCurrent = false;
        rejectionReason = "hold_request_boundary_mismatch";
        if (!prevalidation.IsReleased)
        {
            return false;
        }

        if (RuntimeUnlockInitialActivationHoldRequestMatchesOfferBoundary(
                prevalidation.Request,
                boundary))
        {
            matchMode = "direct";
            rejectionReason = "direct_request_boundary_current";
            return true;
        }

        lock (accelerationGate)
        {
            if (prevalidation.Decision.EnvelopeRefreshCommand is not
                    { } command ||
                command.HoldRequest != prevalidation.Request)
            {
                rejectionReason =
                    "committed_refresh_command_not_bound_to_hold_request";
                return false;
            }

            refreshGeneration = command.RefreshGeneration;
            if (lastRuntimeUnlockInitialActivationEnvelopeRefreshReceipt is not
                    { } receipt ||
                receipt.Command != command)
            {
                rejectionReason =
                    "committed_refresh_receipt_not_current";
                return false;
            }

            refreshReceiptCurrent = true;
            if (runtimeUnlockInitialActivationEnvelopeState is not
                    { } envelopeState ||
                envelopeState.Boundary != boundary ||
                outboundRuntimeUnlockOfferAuthorityBoundary != boundary)
            {
                rejectionReason =
                    "committed_refresh_successor_boundary_not_current";
                return false;
            }

            var request = command.HoldRequest;
            if (boundary.Mode !=
                    RuntimeUnlockOfferAuthorityMode.InitialActivation ||
                !string.Equals(
                    request.SessionId,
                    boundary.SessionId,
                    StringComparison.Ordinal) ||
                !string.Equals(
                    request.TransferId,
                    boundary.TransferId,
                    StringComparison.Ordinal) ||
                request.Direction != boundary.Direction ||
                !string.Equals(
                    request.OfferNonce,
                    boundary.Nonce,
                    StringComparison.Ordinal) ||
                request.PayerDecisionId != boundary.PayerDecisionId ||
                request.OfferGeneration != boundary.OfferGeneration ||
                request.TransactionGeneration !=
                    boundary.TransactionGeneration ||
                request.TunaPathLeaseGeneration !=
                    boundary.TunaPathLeaseGeneration ||
                !string.Equals(
                    request.TunaPathLeaseListenerRunId,
                    boundary.TunaPathLeaseListenerRunId,
                    StringComparison.Ordinal) ||
                !string.Equals(
                    request.SemanticOfferFingerprint,
                    boundary.SemanticOfferFingerprint,
                    StringComparison.Ordinal) ||
                !RuntimeUnlockInitialActivationExpectedSourceScopeMatches(
                    request.ExpectedScope,
                    boundary.InitialActivationExpectedScope))
            {
                rejectionReason =
                    "committed_refresh_semantic_or_scope_mismatch";
                return false;
            }

            if (boundary.EnvelopeGeneration !=
                    command.SuccessorEnvelopeGeneration ||
                boundary.EnvelopeSentAtUnixMs !=
                    command.SuccessorSentAtUnixMs ||
                boundary.EnvelopeExpiresAtUnixMs !=
                    command.SuccessorExpiresAtUnixMs ||
                !string.Equals(
                    boundary.ControlEnvelopeFingerprint,
                    receipt.SuccessorEnvelopeFingerprint,
                    StringComparison.Ordinal) ||
                !string.Equals(
                    envelopeState.Envelope.MessageId,
                    receipt.MessageId,
                    StringComparison.Ordinal))
            {
                rejectionReason =
                    "committed_refresh_successor_envelope_mismatch";
                return false;
            }
        }

        matchMode = "committed_refresh_successor";
        rejectionReason = "committed_refresh_successor_current";
        return true;
    }

    private string?
        CaptureRuntimeUnlockInitialActivationLegacyReceiveStallBlocker()
    {
        var testBlocker =
            RuntimeUnlockRegularV4ReceiveRecoveryBlockerOverrideForTests?.Invoke(
                this);
        if (!string.IsNullOrWhiteSpace(testBlocker))
        {
            return testBlocker;
        }

        return client is RealNknClientAdapter realClient &&
               realClient.TryGetFileTransferRegularV4ActivationSendBlocker(
                   out var blockerReason,
                   out _,
                   includeRegularV4Pressure: false)
            ? blockerReason
            : null;
    }

    private bool ApplyRuntimeUnlockInitialActivationReceiveRecoveryHoldDecision(
        RuntimeUnlockInitialActivationReceiveRecoveryHoldDecision decision,
        string source)
    {
        if (decision.IsDefault)
        {
            return false;
        }
        if (!RuntimeUnlockInitialActivationReceiveRecoveryHoldDecisionMatchesRequest(
                decision))
        {
            return false;
        }
        if (decision.Status ==
                RuntimeUnlockInitialActivationReceiveRecoveryHoldStatus
                    .Released &&
            decision.EnvelopeRefreshCommand is { } refreshCommand &&
            !TryPrepareAndCommitRuntimeUnlockInitialActivationEnvelopeRefresh(
                refreshCommand))
        {
            return false;
        }

        TaskCompletionSource<
            RuntimeUnlockInitialActivationReceiveRecoveryHoldAwaitResult>?
            completion = null;
        RuntimeUnlockInitialActivationReceiveRecoveryHoldDecision? previousDecision =
            null;
        string? pendingInvalidationReason = null;
        var pendingInvalidationKind =
            RuntimeUnlockInitialActivationReceiveRecoveryHoldInvalidationKind
                .Unspecified;
        var accepted = false;
        var followedHold = false;
        lock (accelerationGate)
        {
            if (runtimeUnlockInitialActivationReceiveRecoveryHoldShadow is
                not { } current ||
                current.Request != decision.Request)
            {
                if (lastRuntimeUnlockInitialActivationReceiveRecoveryHoldDecision
                    == decision)
                {
                    return true;
                }

                return false;
            }
            else if (current.Decision is { } retained &&
                     retained.HoldGeneration > 0 &&
                     decision.HoldGeneration > 0 &&
                     retained.HoldGeneration != decision.HoldGeneration)
            {
                accepted = false;
            }
            else if (decision.Status ==
                         RuntimeUnlockInitialActivationReceiveRecoveryHoldStatus
                             .Held &&
                     lastRuntimeUnlockInitialActivationReceiveRecoveryHoldDecision
                         is
                         {
                             Status:
                                 RuntimeUnlockInitialActivationReceiveRecoveryHoldStatus
                                     .Released or
                                 RuntimeUnlockInitialActivationReceiveRecoveryHoldStatus
                                     .Invalidated,
                             ReceiveRecoveryOperation: { } terminalOperation,
                         } terminalDecision &&
                     terminalDecision.Request == decision.Request &&
                     decision.ReceiveRecoveryOperation?.Authority ==
                         terminalOperation.Authority)
            {
                accepted = false;
            }
            else if (current.Decision is null &&
                     decision.Status is
                         RuntimeUnlockInitialActivationReceiveRecoveryHoldStatus
                             .Held or
                         RuntimeUnlockInitialActivationReceiveRecoveryHoldStatus
                             .Released &&
                     decision.Request.ExpectedScope.ExpectedExecutionCommand is
                         { } expectedCommand &&
                     decision.ReceiveRecoveryOperation?.Authority
                         .ExecutionCommand != expectedCommand &&
                     !(decision.PreviousReceiveRecoveryAuthority is
                           { } capturedPredecessor &&
                       capturedPredecessor.ExecutionCommand ==
                           expectedCommand &&
                       decision.ReceiveRecoveryOperation is
                           { } firstSuccessor &&
                       firstSuccessor.Authority.PredecessorAuthorityId ==
                           capturedPredecessor.AuthorityId &&
                       firstSuccessor.Authority
                               .PredecessorOperationGeneration ==
                           capturedPredecessor.OperationGeneration))
            {
                accepted = false;
            }
            else if (current.Decision is
                     {
                         Status:
                             RuntimeUnlockInitialActivationReceiveRecoveryHoldStatus
                                 .Held,
                         ReceiveRecoveryOperation: { } retainedOperation,
                     } currentHeld &&
                     decision.ReceiveRecoveryOperation is { } candidateOperation &&
                     candidateOperation.Authority != retainedOperation.Authority &&
                     (candidateOperation.Authority.PredecessorAuthorityId !=
                          retainedOperation.Authority.AuthorityId ||
                      candidateOperation.Authority
                              .PredecessorOperationGeneration !=
                          retainedOperation.Authority.OperationGeneration ||
                      decision.Status ==
                          RuntimeUnlockInitialActivationReceiveRecoveryHoldStatus
                              .Held &&
                      decision.PreviousReceiveRecoveryAuthority !=
                          retainedOperation.Authority))
            {
                accepted = false;
            }
            else
            {
                previousDecision = current.Decision;
                pendingInvalidationReason =
                    current.PendingInvalidationReason;
                pendingInvalidationKind =
                    current.PendingInvalidationKind;
                accepted = true;
                if (decision.Status ==
                    RuntimeUnlockInitialActivationReceiveRecoveryHoldStatus.Held)
                {
                    runtimeUnlockInitialActivationReceiveRecoveryHoldShadow =
                        current with
                        {
                            Decision = decision,
                        };
                }
                else
                {
                    followedHold =
                        current.Decision?.Status ==
                        RuntimeUnlockInitialActivationReceiveRecoveryHoldStatus
                            .Held;
                    if (decision.Status ==
                            RuntimeUnlockInitialActivationReceiveRecoveryHoldStatus
                                .Released &&
                        (followedHold ||
                         decision.ReceiveRecoveryOperation is
                         {
                             ExecutionState:
                                 FileTransferReceiveRecoveryExecutionState
                                     .Completed,
                             ClosureState:
                                 FileTransferReceiveRecoveryClosureState.Adopted or
                                 FileTransferReceiveRecoveryClosureState.Reserved or
                                 FileTransferReceiveRecoveryClosureState.Consumed,
                         }))
                    {
                        RebaseRuntimeUnlockInitialActivationPendingAnswerAfterHoldUnsafe(
                            current.Request);
                    }
                    runtimeUnlockInitialActivationReceiveRecoveryHoldShadow =
                        null;
                    lastRuntimeUnlockInitialActivationReceiveRecoveryHoldDecision =
                        decision;
                    completion = current.Completion;
                }
            }
        }

        if (!accepted)
        {
            return false;
        }

        var rebound =
            previousDecision is { } previous &&
            previous.ReceiveRecoveryOperation is { } previousOperation &&
            decision.ReceiveRecoveryOperation is { } reboundCandidateOperation &&
            previousOperation.Authority !=
                reboundCandidateOperation.Authority &&
            reboundCandidateOperation.Authority.PredecessorAuthorityId ==
                previousOperation.Authority.AuthorityId &&
            reboundCandidateOperation.Authority
                    .PredecessorOperationGeneration ==
                previousOperation.Authority.OperationGeneration;
        LogRuntimeUnlockInitialActivationReceiveRecoveryHoldDecision(
            rebound
                ? "runtime_unlock_initial_activation_receive_recovery_hold_rebound"
                : "runtime_unlock_initial_activation_receive_recovery_hold_decided",
            decision,
            source);
        if (decision.Status ==
                RuntimeUnlockInitialActivationReceiveRecoveryHoldStatus.Released &&
            followedHold)
        {
            LogRuntimeUnlockInitialActivationReceiveRecoveryHoldDecision(
                "runtime_unlock_initial_activation_receive_recovery_hold_resumed",
                decision,
                source);
            if (decision.EnvelopeRefreshCommand is
                { } committedRefreshCommand)
            {
                LocalOperationalLog.Info(
                    "NKN.Tuna",
                    $"event=runtime_unlock_initial_activation_offer_envelope_refresh_physical_resume; {FormatRuntimeUnlockInitialActivationReceiveRecoveryHoldRequest(decision.Request)}; refresh_generation={committedRefreshCommand.RefreshGeneration}; successor_envelope_generation={committedRefreshCommand.SuccessorEnvelopeGeneration}; decision_reason=committed_refresh_released_same_semantic_offer");
            }
        }

        var completionResult =
            MapRuntimeUnlockInitialActivationReceiveRecoveryHoldAwaitResult(
                decision,
                followedHold);
        var pendingExplicitCancellation =
            !string.IsNullOrWhiteSpace(pendingInvalidationReason) &&
            pendingInvalidationKind is
                RuntimeUnlockInitialActivationReceiveRecoveryHoldInvalidationKind
                    .UserCancellation or
                RuntimeUnlockInitialActivationReceiveRecoveryHoldInvalidationKind
                    .PeerCancellation;
        if (!pendingExplicitCancellation &&
            decision.Status ==
                RuntimeUnlockInitialActivationReceiveRecoveryHoldStatus
                    .Invalidated)
        {
            _ =
                InvalidateRuntimeUnlockInitialActivationOfferIfCurrent(
                    decision);
        }

        if (pendingExplicitCancellation &&
            decision.Status !=
                RuntimeUnlockInitialActivationReceiveRecoveryHoldStatus.Held)
        {
            var exactReason = pendingInvalidationReason!;
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=runtime_unlock_initial_activation_receive_recovery_hold_resume_suppressed; {FormatRuntimeUnlockInitialActivationReceiveRecoveryHoldRequest(decision.Request)}; reset_reason={SanitizeLogToken(exactReason)}; invalidation_kind={SanitizeLogToken(pendingInvalidationKind.ToString())}; decision_status={SanitizeLogToken(decision.Status.ToString())}; decision_reason=explicit_cancellation_precedes_hold_continuation");
            FailRuntimeUnlockTunaPathLeaseIfCurrent(
                decision.Request.SessionId,
                decision.Request.OfferGeneration,
                exactReason,
                failTransaction: false);
            _ = ResetAccelerationNegotiation(
                exactReason,
                initialActivationHoldAlreadyInvalidated: true,
                expectedInvalidatedHoldRequest: decision.Request,
                invalidationKind: pendingInvalidationKind);
            completion?.TrySetResult(
                RuntimeUnlockInitialActivationReceiveRecoveryHoldAwaitResult
                    .Invalidated);
            return true;
        }

        completion?.TrySetResult(completionResult);
        if (!string.IsNullOrWhiteSpace(pendingInvalidationReason) &&
            !string.Equals(
                source,
                "reset_invalidation",
                StringComparison.Ordinal))
        {
            var exactReason = pendingInvalidationReason;
            if (decision.Status ==
                    RuntimeUnlockInitialActivationReceiveRecoveryHoldStatus
                        .Released &&
                pendingInvalidationKind is not
                    (RuntimeUnlockInitialActivationReceiveRecoveryHoldInvalidationKind
                        .UserCancellation or
                     RuntimeUnlockInitialActivationReceiveRecoveryHoldInvalidationKind
                        .PeerCancellation))
            {
                LocalOperationalLog.Info(
                    "NKN.Tuna",
                    $"event=runtime_unlock_initial_activation_receive_recovery_hold_reset_ignored; {FormatRuntimeUnlockInitialActivationReceiveRecoveryHoldRequest(decision.Request)}; reset_reason={SanitizeLogToken(exactReason)}; decision_reason=generic_reset_not_authorized_after_hold_release");
                return true;
            }

            _ = Task.Run(
                () =>
                {
                    if (decision.Status ==
                        RuntimeUnlockInitialActivationReceiveRecoveryHoldStatus
                            .Held)
                    {
                        if (!TryInvalidateRuntimeUnlockInitialActivationReceiveRecoveryHoldForReset(
                                pendingInvalidationKind,
                                exactReason,
                                out var holdWasCurrent) ||
                            !holdWasCurrent)
                        {
                            return;
                        }
                    }

                    if (!IsRuntimeUnlockInitialActivationHoldRequestCurrentForTeardown(
                            decision.Request))
                    {
                        LocalOperationalLog.Info(
                            "NKN.Tuna",
                            $"event=runtime_unlock_initial_activation_receive_recovery_hold_reset_ignored; {FormatRuntimeUnlockInitialActivationReceiveRecoveryHoldRequest(decision.Request)}; reset_reason={SanitizeLogToken(exactReason)}; decision_reason=stale_hold_request_after_deferred_invalidation");
                        return;
                    }

                    FailRuntimeUnlockTunaPathLeaseIfCurrent(
                        decision.Request.SessionId,
                        decision.Request.OfferGeneration,
                        exactReason,
                        failTransaction: false);
                    _ = ResetAccelerationNegotiation(
                        exactReason,
                        initialActivationHoldAlreadyInvalidated: true,
                        expectedInvalidatedHoldRequest: decision.Request,
                        invalidationKind: pendingInvalidationKind);
                },
                CancellationToken.None);
        }
        return true;
    }

    private bool
        TryPrepareAndCommitRuntimeUnlockInitialActivationEnvelopeRefresh(
            RuntimeUnlockInitialActivationOfferEnvelopeRefreshCommand command)
    {
        if (command.IsDefault)
        {
            return false;
        }

        RuntimeUnlockInitialActivationEnvelopeState predecessor;
        lock (accelerationGate)
        {
            if (lastRuntimeUnlockInitialActivationEnvelopeRefreshReceipt is
                    { } duplicate &&
                duplicate.Command == command)
            {
                return true;
            }

            if (runtimeUnlockInitialActivationEnvelopeState is not
                    { } current ||
                current.Boundary.Mode !=
                    RuntimeUnlockOfferAuthorityMode.InitialActivation ||
                !RuntimeUnlockInitialActivationHoldRequestMatchesOfferBoundary(
                    command.HoldRequest,
                    current.Boundary) ||
                !string.Equals(
                    current.Offer.TunaAddress,
                    (accelerationLane as INknTunaAccelerationSession)
                        ?.LocalTunaAddress,
                    StringComparison.Ordinal) ||
                !IsRuntimeUnlockOfferAuthorityBoundaryCurrentUnsafe(
                    current.Boundary,
                    allowDispatchObservedSettlement: true))
            {
                LocalOperationalLog.Warn(
                    "NKN.Tuna",
                    $"event=runtime_unlock_initial_activation_offer_envelope_refresh_rejected; {FormatRuntimeUnlockInitialActivationReceiveRecoveryHoldRequest(command.HoldRequest)}; refresh_generation={command.RefreshGeneration}; decision_reason=predecessor_boundary_not_current");
                return false;
            }

            predecessor = current;
        }

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=runtime_unlock_initial_activation_offer_envelope_refresh_issued; {FormatRuntimeUnlockInitialActivationReceiveRecoveryHoldRequest(command.HoldRequest)}; refresh_generation={command.RefreshGeneration}; successor_envelope_generation={command.SuccessorEnvelopeGeneration}; successor_sent_at_unix_ms={command.SuccessorSentAtUnixMs}; successor_expires_at_unix_ms={command.SuccessorExpiresAtUnixMs}; decision_reason=coordinator_refresh_command_current");
        var refreshedOffer = new TransportAccelerationOfferPayload
        {
            SessionId = predecessor.Offer.SessionId,
            SenderRole = predecessor.Offer.SenderRole,
            TunaAddress = predecessor.Offer.TunaAddress,
            SupportedLanes = [.. predecessor.Offer.SupportedLanes],
            Trigger = predecessor.Offer.Trigger,
            PayerDecisionId = predecessor.Offer.PayerDecisionId,
            SentAtUnixMs = command.SuccessorSentAtUnixMs,
            ExpiresAtUnixMs = command.SuccessorExpiresAtUnixMs,
            Nonce = predecessor.Offer.Nonce,
            SidecarProtocolVersion =
                predecessor.Offer.SidecarProtocolVersion,
        };
        if (!string.Equals(
                ComputeRuntimeUnlockInitialActivationSemanticOfferFingerprint(
                    refreshedOffer),
                command.HoldRequest.SemanticOfferFingerprint,
                StringComparison.Ordinal))
        {
            return false;
        }

        var securePayload = CreateSecureControlPayload(
            MsgType.TransportAccelerationOffer,
            refreshedOffer.Nonce,
            JsonSerializer.SerializeToUtf8Bytes(refreshedOffer));
        var refreshedEnvelope = CreateEnvelope(
            predecessor.Envelope.Code,
            MsgType.TransportAccelerationOffer,
            securePayload,
            replyTo: null);
        var refreshedFingerprint =
            ComputeRuntimeUnlockControlEnvelopeFingerprint(refreshedEnvelope);
        var receipt =
            new RuntimeUnlockInitialActivationOfferEnvelopeRefreshReceipt(
                command,
                refreshedFingerprint,
                Volatile.Read(ref nextOutboundControlSecureSequence),
                refreshedEnvelope.MessageId);
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=runtime_unlock_initial_activation_offer_envelope_refresh_prepared; {FormatRuntimeUnlockInitialActivationReceiveRecoveryHoldRequest(command.HoldRequest)}; refresh_generation={command.RefreshGeneration}; successor_envelope_generation={command.SuccessorEnvelopeGeneration}; successor_envelope_fingerprint={SanitizeLogToken(refreshedFingerprint)}; successor_sent_at_unix_ms={command.SuccessorSentAtUnixMs}; successor_expires_at_unix_ms={command.SuccessorExpiresAtUnixMs}; secure_sequence={receipt.SecureSequence}; message_id={SanitizeLogToken(receipt.MessageId)}; decision_reason=fresh_envelope_prepared");
        var args =
            new RuntimeUnlockInitialActivationOfferEnvelopeRefreshPreparedEventArgs(
                receipt);
        var subscriber =
            runtimeUnlockInitialActivationOfferEnvelopeRefreshPrepared;
        if (subscriber is null)
        {
            return false;
        }

        try
        {
            subscriber.Invoke(this, args);
        }
        catch (Exception ex)
        {
            LocalOperationalLog.Warn(
                "NKN.Tuna",
                $"event=runtime_unlock_initial_activation_offer_envelope_refresh_rejected; refresh_generation={command.RefreshGeneration}; error={SanitizeLogToken(ex.GetType().Name)}; decision_reason=refresh_receipt_handler_failed");
            return false;
        }

        if (args.Decision is not { Accepted: true } decision ||
            decision.Receipt != receipt)
        {
            return false;
        }

        lock (accelerationGate)
        {
            if (runtimeUnlockInitialActivationEnvelopeState is not
                    { } current ||
                current != predecessor ||
                outboundRuntimeUnlockOfferAuthorityBoundary !=
                    predecessor.Boundary)
            {
                return false;
            }

            var successorBoundary = predecessor.Boundary with
            {
                EnvelopeGeneration = command.SuccessorEnvelopeGeneration,
                EnvelopeSentAtUnixMs = command.SuccessorSentAtUnixMs,
                EnvelopeExpiresAtUnixMs = command.SuccessorExpiresAtUnixMs,
                ControlEnvelopeFingerprint = refreshedFingerprint,
            };
            runtimeUnlockInitialActivationEnvelopeState =
                new RuntimeUnlockInitialActivationEnvelopeState(
                    successorBoundary,
                    refreshedOffer,
                    refreshedEnvelope);
            outboundRuntimeUnlockOfferAuthorityBoundary = successorBoundary;
            lastRuntimeUnlockInitialActivationEnvelopeRefreshReceipt =
                receipt;
        }

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=runtime_unlock_initial_activation_offer_envelope_refresh_committed; {FormatRuntimeUnlockInitialActivationReceiveRecoveryHoldRequest(command.HoldRequest)}; refresh_generation={command.RefreshGeneration}; successor_envelope_generation={command.SuccessorEnvelopeGeneration}; successor_envelope_fingerprint={SanitizeLogToken(refreshedFingerprint)}; successor_sent_at_unix_ms={command.SuccessorSentAtUnixMs}; successor_expires_at_unix_ms={command.SuccessorExpiresAtUnixMs}; secure_sequence={receipt.SecureSequence}; message_id={SanitizeLogToken(receipt.MessageId)}; decision_status={decision.Status}; decision_reason={SanitizeLogToken(decision.Reason)}");
        return true;
    }

    private void
        RebaseRuntimeUnlockInitialActivationPendingAnswerAfterHoldUnsafe(
            RuntimeUnlockInitialActivationReceiveRecoveryHoldRequest request)
    {
        if (request.Boundary !=
                RuntimeUnlockInitialActivationReceiveRecoveryHoldBoundary
                    .AnswerTimeout ||
            runtimeUnlockOfferProofState is not
            {
                AuthorityMode:
                    RuntimeUnlockOfferAuthorityMode.InitialActivation,
                Retired: true,
            } proof ||
            proof.Generation != request.OfferGeneration ||
            proof.PayerDecisionId != request.PayerDecisionId ||
            !string.Equals(
                proof.SessionId,
                request.SessionId,
                StringComparison.Ordinal) ||
            !string.Equals(
                proof.Nonce,
                request.OfferNonce,
                StringComparison.Ordinal) ||
            !IsRuntimeUnlockPendingAnswerRetiredReason(proof.RetiredReason) ||
            retiredRuntimeUnlockOfferAuthorityBoundary is not { } retired ||
            retired.OfferGeneration != request.OfferGeneration ||
            retired.PayerDecisionId != request.PayerDecisionId ||
            !string.Equals(
                retired.Nonce,
                request.OfferNonce,
                StringComparison.Ordinal) ||
            !string.Equals(
                retiredAccelerationOfferNonce,
                request.OfferNonce,
                StringComparison.Ordinal))
        {
            return;
        }

        var timeout =
            AccelerationOfferAnswerTimeoutOverrideForTests ??
            RuntimeUnlockAccelerationOfferAnswerTimeout;
        var rebasedDeadlineUtcMs =
            DateTimeOffset.UtcNow
                .Add(timeout)
                .Add(RuntimeUnlockPeerAnswerObservedSendGrace)
                .ToUnixTimeMilliseconds();
        retiredAccelerationOfferExpiresUtcMs = rebasedDeadlineUtcMs;
        proof.RetiredAnswerExpiresUtcMs = rebasedDeadlineUtcMs;
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=runtime_unlock_initial_activation_receive_recovery_hold_answer_deadline_rebased; {FormatRuntimeUnlockInitialActivationReceiveRecoveryHoldRequest(request)}; answer_deadline_utc_ms={rebasedDeadlineUtcMs}; decision_reason=same_generation_answer_window_resumed");
    }

    private static bool
        RuntimeUnlockInitialActivationReceiveRecoveryHoldDecisionMatchesRequest(
            RuntimeUnlockInitialActivationReceiveRecoveryHoldDecision decision)
    {
        if (decision.ReceiveRecoveryOperation is not { } operation)
        {
            return decision.Status !=
                RuntimeUnlockInitialActivationReceiveRecoveryHoldStatus.Held;
        }

        var request = decision.Request;
        var expected = request.ExpectedScope;
        var authority = operation.Authority;
        var observation = authority.Observation;
        var publication = observation.RoutePublication;
        var expectedPublication = expected.SourcePublicationAuthority;
        return expectedPublication is not null &&
               string.Equals(
                   request.SessionId,
                   observation.SessionId,
                   StringComparison.Ordinal) &&
               string.Equals(
                   request.TransferId,
                   observation.TransferId,
                   StringComparison.Ordinal) &&
               request.Direction == observation.Direction &&
               string.Equals(
                   publication.SessionId,
                   expectedPublication.SessionId,
                   StringComparison.Ordinal) &&
               string.Equals(
                   publication.TransferId,
                   expectedPublication.TransferId,
                   StringComparison.Ordinal) &&
               publication.Direction == expectedPublication.Direction &&
               string.Equals(
                   publication.RouteToken,
                   expectedPublication.RouteToken,
                   StringComparison.Ordinal) &&
               publication.ProtocolVersion ==
                   expectedPublication.ProtocolVersion &&
               publication.LiveRouteEpoch ==
                   expectedPublication.LiveRouteEpoch &&
               publication.RuntimeGeneration ==
                   expectedPublication.RuntimeGeneration &&
               publication.TerminalGeneration ==
                   expectedPublication.TerminalGeneration &&
               publication.LegGeneration ==
                   expectedPublication.LegGeneration &&
               publication.PublicationGeneration ==
                   expectedPublication.RoutePublicationGeneration &&
               publication.RouteCommitGeneration ==
                   expectedPublication.RouteCommitGeneration &&
               string.Equals(
                   FileTransferRouteResolver.Resolve(
                       publication.TargetRoute).TelemetryToken,
                   expectedPublication.TargetRouteToken,
                   StringComparison.Ordinal) &&
               publication.TargetProtocolVersion ==
                   expectedPublication.TargetProtocolVersion &&
               publication.TargetTransport ==
                   expectedPublication.TargetTransport &&
               string.Equals(
                   publication.ActionKind.ToString(),
                   expectedPublication.RoutePublicationActionKind,
                   StringComparison.Ordinal) &&
               observation.TransportEpoch == expected.TransportEpoch &&
               observation.BridgeRecoveryGeneration ==
                   expected.BridgeRecoveryGeneration &&
               string.Equals(
                   observation.CheckpointRequestId,
                   expected.CheckpointRequestId,
                   StringComparison.Ordinal) &&
               string.Equals(
                   observation.DataSessionIdentity,
                   expected.DataSessionIdentity,
                   StringComparison.Ordinal) &&
               observation.DataSessionGeneration ==
                   expected.DataSessionGeneration;
    }

    private static RuntimeUnlockInitialActivationReceiveRecoveryHoldAwaitResult
        MapRuntimeUnlockInitialActivationReceiveRecoveryHoldAwaitResult(
            RuntimeUnlockInitialActivationReceiveRecoveryHoldDecision decision,
            bool followedHold)
        => decision.Status switch
        {
            RuntimeUnlockInitialActivationReceiveRecoveryHoldStatus.Released =>
                followedHold
                    ? RuntimeUnlockInitialActivationReceiveRecoveryHoldAwaitResult
                        .ReleasedAfterHold
                    : decision.ReceiveRecoveryOperation is
                        {
                            ExecutionState:
                                FileTransferReceiveRecoveryExecutionState
                                    .Completed,
                            ClosureState:
                                FileTransferReceiveRecoveryClosureState.Adopted or
                                FileTransferReceiveRecoveryClosureState.Reserved or
                                FileTransferReceiveRecoveryClosureState.Consumed,
                        }
                        ? RuntimeUnlockInitialActivationReceiveRecoveryHoldAwaitResult
                            .ReleasedAfterRecoveryProof
                    : RuntimeUnlockInitialActivationReceiveRecoveryHoldAwaitResult
                        .Released,
            RuntimeUnlockInitialActivationReceiveRecoveryHoldStatus.Invalidated =>
                RuntimeUnlockInitialActivationReceiveRecoveryHoldAwaitResult
                    .Invalidated,
            _ => RuntimeUnlockInitialActivationReceiveRecoveryHoldAwaitResult
                .Rejected,
        };

    private static bool
        IsRuntimeUnlockInitialActivationReceiveRecoveryHoldReleased(
            RuntimeUnlockInitialActivationReceiveRecoveryHoldAwaitResult result)
        => result is
            RuntimeUnlockInitialActivationReceiveRecoveryHoldAwaitResult.Released or
            RuntimeUnlockInitialActivationReceiveRecoveryHoldAwaitResult
                .ReleasedAfterHold or
            RuntimeUnlockInitialActivationReceiveRecoveryHoldAwaitResult
                .ReleasedAfterRecoveryProof;

    private static bool
        ShouldResumeRuntimeUnlockInitialActivationSameGeneration(
            RuntimeUnlockInitialActivationReceiveRecoveryHoldAwaitResult result)
        => result is
            RuntimeUnlockInitialActivationReceiveRecoveryHoldAwaitResult
                .ReleasedAfterHold or
            RuntimeUnlockInitialActivationReceiveRecoveryHoldAwaitResult
                .ReleasedAfterRecoveryProof;

    private bool
        TryCreateRuntimeUnlockInitialActivationReceiveRecoveryHoldRequest(
            RuntimeUnlockOfferAuthorityBoundary boundary,
            RuntimeUnlockInitialActivationReceiveRecoveryHoldBoundary
                holdBoundary,
            out RuntimeUnlockInitialActivationReceiveRecoveryHoldRequest request,
            bool peerVisibleDispatchObserved = false)
    {
        request = default;
        if (boundary.InitialActivationExpectedScope.IsDefault ||
            boundary.InitialActivationExpectedScope
                .SourcePublicationAuthority is not { } sourcePublication ||
            !TryCaptureRuntimeUnlockInitialActivationReceiveRecoveryExpectedScope(
                sourcePublication,
                out var currentExpectedScope,
                out _) ||
            !RuntimeUnlockInitialActivationExpectedSourceScopeMatches(
                boundary.InitialActivationExpectedScope,
                currentExpectedScope))
        {
            return false;
        }

        request = new(
            boundary.SessionId,
            boundary.TransferId ?? string.Empty,
            boundary.Direction,
            boundary.Nonce,
            boundary.PayerDecisionId,
            boundary.OfferGeneration,
            boundary.TransactionGeneration,
            boundary.TunaPathLeaseGeneration,
            boundary.TunaPathLeaseListenerRunId ?? string.Empty,
            boundary.ControlEnvelopeFingerprint,
            peerVisibleDispatchObserved,
            Boundary: holdBoundary)
        {
            ExpectedScope = currentExpectedScope,
            SemanticOfferFingerprint = boundary.SemanticOfferFingerprint,
            EnvelopeGeneration = boundary.EnvelopeGeneration,
            EnvelopeSentAtUnixMs = boundary.EnvelopeSentAtUnixMs,
            EnvelopeExpiresAtUnixMs = boundary.EnvelopeExpiresAtUnixMs,
        };
        return !request.IsDefault;
    }

    private async Task<
        RuntimeUnlockInitialActivationReceiveRecoveryHoldAwaitResult>
        WaitForRuntimeUnlockInitialActivationReceiveRecoveryTimeoutHoldAsync(
            RuntimeUnlockOfferAuthorityBoundary boundary,
            RuntimeUnlockInitialActivationReceiveRecoveryHoldBoundary
                holdBoundary,
            string validationBoundary)
    {
        if (boundary.Mode !=
            RuntimeUnlockOfferAuthorityMode.InitialActivation)
        {
            return RuntimeUnlockInitialActivationReceiveRecoveryHoldAwaitResult
                .Released;
        }
        if (string.IsNullOrWhiteSpace(boundary.TransferId) ||
            boundary.InitialActivationExpectedScope.IsDefault)
        {
            return RuntimeUnlockInitialActivationReceiveRecoveryHoldAwaitResult
                .Released;
        }

        while (true)
        {
            Task<RuntimeUnlockInitialActivationReceiveRecoveryHoldAwaitResult>?
                activeSameOfferCompletion = null;
            lock (accelerationGate)
            {
                if (runtimeUnlockInitialActivationReceiveRecoveryHoldShadow is
                        { } active)
                {
                    if (!RuntimeUnlockInitialActivationHoldRequestMatchesOfferBoundary(
                            active.Request,
                            boundary))
                    {
                        return RuntimeUnlockInitialActivationReceiveRecoveryHoldAwaitResult
                            .Rejected;
                    }

                    activeSameOfferCompletion = active.Completion.Task;
                }
            }

            if (activeSameOfferCompletion is not null)
            {
                var joinedResult =
                    await activeSameOfferCompletion.ConfigureAwait(false);
                if (!IsRuntimeUnlockInitialActivationReceiveRecoveryHoldReleased(
                        joinedResult))
                {
                    return joinedResult;
                }

                if (!ValidateRuntimeUnlockOfferAuthorityBoundary(
                        boundary,
                        validationBoundary,
                        allowDispatchObservedSettlement: true))
                {
                    return RuntimeUnlockInitialActivationReceiveRecoveryHoldAwaitResult
                        .Rejected;
                }

                return joinedResult;
            }

            bool peerVisibleDispatchObserved;
            lock (accelerationGate)
            {
                var proof = runtimeUnlockOfferProofState;
                if (proof is null ||
                    proof.Generation != boundary.OfferGeneration ||
                    proof.PayerDecisionId != boundary.PayerDecisionId ||
                    !string.Equals(
                        proof.SessionId,
                        boundary.SessionId,
                        StringComparison.Ordinal) ||
                    !string.Equals(
                        proof.Nonce,
                        boundary.Nonce,
                        StringComparison.Ordinal))
                {
                    return RuntimeUnlockInitialActivationReceiveRecoveryHoldAwaitResult
                        .Rejected;
                }

                peerVisibleDispatchObserved =
                    proof.ObservedSend || proof.PeerReceived;
            }

            if (!TryCreateRuntimeUnlockInitialActivationReceiveRecoveryHoldRequest(
                    boundary,
                    holdBoundary,
                    out var request,
                    peerVisibleDispatchObserved))
            {
                return RuntimeUnlockInitialActivationReceiveRecoveryHoldAwaitResult
                    .Rejected;
            }

            var evaluation =
                await RequestRuntimeUnlockInitialActivationReceiveRecoveryHoldAsync(
                        request,
                        CancellationToken.None)
                    .ConfigureAwait(false);
            if (!IsRuntimeUnlockInitialActivationReceiveRecoveryHoldReleased(
                    evaluation.Result))
            {
                lock (accelerationGate)
                {
                    if (runtimeUnlockInitialActivationReceiveRecoveryHoldShadow is
                            { } raced &&
                        RuntimeUnlockInitialActivationHoldRequestMatchesOfferBoundary(
                            raced.Request,
                            boundary))
                    {
                        continue;
                    }
                }

                return evaluation.Result;
            }

            return ValidateRuntimeUnlockOfferAuthorityBoundary(
                    boundary,
                    validationBoundary,
                    allowDispatchObservedSettlement: true)
                ? evaluation.Result
                : RuntimeUnlockInitialActivationReceiveRecoveryHoldAwaitResult
                    .Rejected;
        }
    }

    private Task<bool>
        ReplayCommittedRuntimeUnlockInitialActivationEnvelopeAfterHoldAsync(
            RuntimeUnlockOfferAuthorityBoundary predecessorBoundary,
            RuntimeUnlockInitialActivationReceiveRecoveryHoldAwaitResult
                holdResult,
            string timeoutBoundary)
    {
        RuntimeUnlockInitialActivationEnvelopeState envelopeState;
        RuntimeUnlockInitialActivationReceiveRecoveryHoldPrevalidation
            prevalidation;
        string replayIdentity;
        lock (accelerationGate)
        {
            if (!ShouldResumeRuntimeUnlockInitialActivationSameGeneration(
                    holdResult) ||
                runtimeUnlockInitialActivationEnvelopeState is not
                    { } currentEnvelopeState ||
                lastRuntimeUnlockInitialActivationEnvelopeRefreshReceipt is not
                    { } refreshReceipt ||
                lastRuntimeUnlockInitialActivationReceiveRecoveryHoldDecision is not
                    { } releasedDecision ||
                releasedDecision.Status !=
                    RuntimeUnlockInitialActivationReceiveRecoveryHoldStatus
                        .Released ||
                releasedDecision.Request.IsDefault ||
                !RuntimeUnlockInitialActivationHoldRequestMatchesOfferBoundary(
                    releasedDecision.Request,
                    predecessorBoundary) ||
                releasedDecision.EnvelopeRefreshCommand is not { } refreshCommand ||
                refreshReceipt.Command != refreshCommand ||
                currentEnvelopeState.Boundary.Mode !=
                    RuntimeUnlockOfferAuthorityMode.InitialActivation ||
                currentEnvelopeState.Boundary.OfferGeneration !=
                    predecessorBoundary.OfferGeneration ||
                currentEnvelopeState.Boundary.TransactionGeneration !=
                    predecessorBoundary.TransactionGeneration ||
                currentEnvelopeState.Boundary.TunaPathLeaseGeneration !=
                    predecessorBoundary.TunaPathLeaseGeneration ||
                !string.Equals(
                    currentEnvelopeState.Boundary.SemanticOfferFingerprint,
                    predecessorBoundary.SemanticOfferFingerprint,
                    StringComparison.Ordinal) ||
                currentEnvelopeState.Boundary.EnvelopeGeneration !=
                    refreshCommand.SuccessorEnvelopeGeneration ||
                !string.Equals(
                    currentEnvelopeState.Boundary.ControlEnvelopeFingerprint,
                    refreshReceipt.SuccessorEnvelopeFingerprint,
                    StringComparison.Ordinal) ||
                !string.Equals(
                    currentEnvelopeState.Envelope.MessageId,
                    refreshReceipt.MessageId,
                    StringComparison.Ordinal))
            {
                return Task.FromResult(false);
            }

            replayIdentity = string.Join(
                "|",
                refreshCommand.RefreshGeneration,
                refreshReceipt.SuccessorEnvelopeFingerprint,
                refreshReceipt.MessageId);
            if (string.Equals(
                    runtimeUnlockInitialActivationRefreshReplayIdentity,
                    replayIdentity,
                    StringComparison.Ordinal) &&
                runtimeUnlockInitialActivationRefreshReplayTask is { } existing)
            {
                return existing.IsCompleted
                    ? Task.FromResult(true)
                    : AwaitJoinedRuntimeUnlockInitialActivationRefreshReplayAsync(
                        existing);
            }

            envelopeState = currentEnvelopeState;
            prevalidation = new(
                releasedDecision.Request,
                releasedDecision,
                holdResult);
            runtimeUnlockInitialActivationRefreshReplayIdentity = replayIdentity;
            runtimeUnlockInitialActivationRefreshReplayTask =
                ReplayCommittedRuntimeUnlockInitialActivationEnvelopeCoreAsync(
                    envelopeState,
                    prevalidation,
                    timeoutBoundary,
                    refreshCommand.RefreshGeneration);
            return runtimeUnlockInitialActivationRefreshReplayTask;
        }
    }

    private bool IsRuntimeUnlockInitialActivationEnvelopeRefreshReplayRequired()
    {
        lock (accelerationGate)
        {
            return lastRuntimeUnlockInitialActivationReceiveRecoveryHoldDecision is
                {
                    Status: RuntimeUnlockInitialActivationReceiveRecoveryHoldStatus
                        .Released,
                    EnvelopeRefreshCommand: not null,
                };
        }
    }

    private static async Task<bool>
        AwaitJoinedRuntimeUnlockInitialActivationRefreshReplayAsync(
            Task<bool> replayTask)
    {
        await replayTask.ConfigureAwait(false);
        return true;
    }

    private async Task<bool>
        ReplayCommittedRuntimeUnlockInitialActivationEnvelopeCoreAsync(
            RuntimeUnlockInitialActivationEnvelopeState envelopeState,
            RuntimeUnlockInitialActivationReceiveRecoveryHoldPrevalidation
                prevalidation,
            string timeoutBoundary,
            long refreshGeneration)
    {
        var boundary = envelopeState.Boundary;
        var target = remoteEndpoint;
        if (string.IsNullOrWhiteSpace(target))
        {
            return true;
        }

        var send = await SendAccelerationControlEnvelopeWithBulkBypassAsync(
                target,
                envelopeState.Envelope,
                "offer",
                CancellationToken.None,
                requireObservedSend: true,
                activationSessionId: boundary.SessionId,
                onBeforeSend: () =>
                    PauseRegularNknV4FileTransferForRuntimeUnlockMakeBeforeBreak(
                        boundary.SessionId,
                        "runtime_unlock_initial_activation_refresh_replay",
                        timeoutBoundary),
                expectedOfferAuthorityBoundary: boundary,
                initialActivationHoldPrevalidation: prevalidation)
            .ConfigureAwait(false);

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=runtime_unlock_initial_activation_offer_envelope_refresh_replay_completed; session_id={SanitizeLogToken(boundary.SessionId)}; transfer_id={SanitizeLogToken(boundary.TransferId ?? "(none)")}; direction={SanitizeLogToken(boundary.Direction.ToString().ToLowerInvariant())}; offer_nonce={SanitizeLogToken(boundary.Nonce)}; payer_decision_id={boundary.PayerDecisionId}; offer_generation={boundary.OfferGeneration}; transaction_generation={boundary.TransactionGeneration}; tuna_path_lease_generation={boundary.TunaPathLeaseGeneration}; tuna_path_lease_listener_run_id={SanitizeLogToken(boundary.TunaPathLeaseListenerRunId ?? "(none)")}; envelope_generation={boundary.EnvelopeGeneration}; control_envelope_fingerprint={SanitizeLogToken(boundary.ControlEnvelopeFingerprint)}; refresh_generation={refreshGeneration}; send_succeeded={(send.Succeeded ? 1 : 0)}; stale_callback_ignored={(send.StaleCallbackIgnored ? 1 : 0)}; timeout_boundary={SanitizeLogToken(timeoutBoundary)}; decision_reason=committed_refresh_replay_terminal");
        if (!send.Succeeded)
        {
            return true;
        }

        MarkRuntimeUnlockOfferObservedSendIfCurrent(
            boundary.Nonce,
            boundary.PayerDecisionId,
            boundary.OfferGeneration,
            send.ObservedLane);
        ApplyRuntimeUnlockTransaction(
            RuntimeUnlockTransactionEventKind.ObservedSend,
            boundary.SessionId,
            boundary.OfferGeneration,
            "refreshed_offer_observed_send",
            observedLane: send.ObservedLane);
        NotifyTransportAccelerationStateChanged("waiting_for_answer");
        ScheduleAccelerationOfferReplay(
            target,
            envelopeState.Envelope,
            boundary.SessionId,
            boundary.Nonce,
            boundary.PayerDecisionId,
            boundary.OfferGeneration,
            pauseOnQueueAccepted: false,
            pauseAfterObservedSendOnly: false);
        MarkRuntimeUnlockOfferAnswerTimeoutScheduledIfCurrent(
            boundary.Nonce,
            boundary.PayerDecisionId,
            boundary.OfferGeneration);
        ScheduleAccelerationOfferAnswerTimeout(
            boundary.Nonce,
            expectedInstallReceipt: null,
            requireRuntimeUnlockRetryDispatchInstall: false);
        ScheduleRuntimeUnlockOfferPeerResponseTimeout(
            boundary.Nonce,
            boundary.PayerDecisionId,
            boundary.OfferGeneration,
            boundary.SessionId,
            send.ObservedLane,
            expectedInstallReceipt: null,
            resumedAfterReceiveRecoveryHold: true);
        return true;
    }

    private static bool
        RuntimeUnlockInitialActivationHoldRequestMatchesOfferBoundary(
            RuntimeUnlockInitialActivationReceiveRecoveryHoldRequest request,
            RuntimeUnlockOfferAuthorityBoundary boundary)
        => string.Equals(
               request.SessionId,
               boundary.SessionId,
               StringComparison.Ordinal) &&
           string.Equals(
               request.TransferId,
               boundary.TransferId,
               StringComparison.Ordinal) &&
           request.Direction == boundary.Direction &&
           string.Equals(
               request.OfferNonce,
               boundary.Nonce,
               StringComparison.Ordinal) &&
           request.PayerDecisionId == boundary.PayerDecisionId &&
           request.OfferGeneration == boundary.OfferGeneration &&
           request.TransactionGeneration ==
               boundary.TransactionGeneration &&
           request.TunaPathLeaseGeneration ==
               boundary.TunaPathLeaseGeneration &&
           string.Equals(
               request.TunaPathLeaseListenerRunId,
               boundary.TunaPathLeaseListenerRunId,
               StringComparison.Ordinal) &&
           string.Equals(
               request.ControlEnvelopeFingerprint,
               boundary.ControlEnvelopeFingerprint,
               StringComparison.Ordinal) &&
           string.Equals(
               request.SemanticOfferFingerprint,
               boundary.SemanticOfferFingerprint,
               StringComparison.Ordinal) &&
           request.EnvelopeGeneration == boundary.EnvelopeGeneration &&
           request.EnvelopeSentAtUnixMs == boundary.EnvelopeSentAtUnixMs &&
           request.EnvelopeExpiresAtUnixMs ==
               boundary.EnvelopeExpiresAtUnixMs &&
           RuntimeUnlockInitialActivationExpectedSourceScopeMatches(
               request.ExpectedScope,
               boundary.InitialActivationExpectedScope);

    private bool
        IsRuntimeUnlockInitialActivationHoldRequestCurrentForTeardown(
            RuntimeUnlockInitialActivationReceiveRecoveryHoldRequest request,
            bool requireCurrentPathLease = true)
    {
        if (!string.Equals(
                currentSessionSecurityState.SessionId?.Value,
                request.SessionId,
                StringComparison.Ordinal))
        {
            return false;
        }

        var boundary =
            CaptureRuntimeUnlockOfferAuthorityBoundary(
                request.OfferNonce,
                request.PayerDecisionId,
                request.OfferGeneration);
        if (boundary is null ||
            !RuntimeUnlockInitialActivationHoldRequestMatchesOfferBoundary(
                request,
                boundary) ||
            requireCurrentPathLease &&
            !ValidateRuntimeUnlockOfferAuthorityBoundary(
                boundary,
                "deferred_hold_reset",
                allowDispatchObservedSettlement: true))
        {
            return false;
        }

        lock (accelerationGate)
        {
            return runtimeUnlockTransactionState.SessionId ==
                       request.SessionId &&
                   runtimeUnlockTransactionState.TransactionGeneration ==
                       request.TransactionGeneration &&
                   runtimeUnlockTransactionState.OfferGeneration ==
                       request.OfferGeneration &&
                   runtimeUnlockTransactionState.TunaPathLeaseGeneration ==
                       request.TunaPathLeaseGeneration &&
                   string.Equals(
                       runtimeUnlockTransactionState
                           .TunaPathLeaseListenerRunId,
                       request.TunaPathLeaseListenerRunId,
                       StringComparison.Ordinal) &&
                   runtimeUnlockTransactionState.State is
                       RuntimeUnlockTransactionState.OfferPreparing or
                       RuntimeUnlockTransactionState.OfferSentObserved or
                       RuntimeUnlockTransactionState.PeerReceived;
        }
    }

    private bool
        InvalidateRuntimeUnlockInitialActivationOfferIfCurrent(
            RuntimeUnlockInitialActivationReceiveRecoveryHoldDecision decision)
    {
        if (decision.Status !=
                RuntimeUnlockInitialActivationReceiveRecoveryHoldStatus
                    .Invalidated ||
            decision.Request.IsDefault)
        {
            return false;
        }

        var request = decision.Request;
        var reason = SanitizeLogToken(decision.Reason);
        var cleared = false;
        lock (accelerationGate)
        {
            var currentBoundary =
                outboundRuntimeUnlockOfferAuthorityBoundary;
            var retiredBoundary =
                retiredRuntimeUnlockOfferAuthorityBoundary;
            var currentMatches =
                currentBoundary is not null &&
                RuntimeUnlockInitialActivationHoldRequestMatchesOfferBoundary(
                    request,
                    currentBoundary);
            var retiredMatches =
                retiredBoundary is not null &&
                RuntimeUnlockInitialActivationHoldRequestMatchesOfferBoundary(
                    request,
                    retiredBoundary);
            var proof = runtimeUnlockOfferProofState;
            if ((!currentMatches && !retiredMatches) ||
                proof is null ||
                proof.AuthorityMode !=
                    RuntimeUnlockOfferAuthorityMode.InitialActivation ||
                proof.Generation != request.OfferGeneration ||
                proof.PayerDecisionId != request.PayerDecisionId ||
                !string.Equals(
                    proof.SessionId,
                    request.SessionId,
                    StringComparison.Ordinal) ||
                !string.Equals(
                    proof.Nonce,
                    request.OfferNonce,
                    StringComparison.Ordinal) ||
                runtimeUnlockTransactionState.TransactionGeneration !=
                    request.TransactionGeneration ||
                runtimeUnlockTransactionState.OfferGeneration !=
                    request.OfferGeneration ||
                runtimeUnlockTransactionState.TunaPathLeaseGeneration !=
                    request.TunaPathLeaseGeneration ||
                !string.Equals(
                    runtimeUnlockTransactionState
                        .TunaPathLeaseListenerRunId,
                    request.TunaPathLeaseListenerRunId,
                    StringComparison.Ordinal))
            {
                return false;
            }

            proof.Retired = true;
            proof.RetiredReason = reason;
            proof.RetryReason =
                "runtime_unlock_initial_activation_receive_recovery_invalidated";
            proof.RetiredAnswerExpiresUtcMs = 0;
            if (currentMatches)
            {
                ClearOutboundAccelerationOfferLocked();
            }

            if (retiredMatches)
            {
                ClearRetiredOutboundAccelerationOfferLocked();
            }

            cleared = true;
        }

        var leaseFailed = FailRuntimeUnlockTunaPathLeaseIfCurrent(
            request.SessionId,
            request.OfferGeneration,
            reason,
            failTransaction: true,
            expectedTransactionGeneration: request.TransactionGeneration,
            expectedLeaseGeneration: request.TunaPathLeaseGeneration,
            expectedListenerRunId: request.TunaPathLeaseListenerRunId);
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=runtime_unlock_initial_activation_receive_recovery_hold_invalidated; {FormatRuntimeUnlockInitialActivationReceiveRecoveryHoldRequest(request)}; offer_retired={(cleared ? 1 : 0)}; tuna_path_lease_failed={(leaseFailed ? 1 : 0)}; retry_scheduled=0; decision_reason={reason}");
        return cleared;
    }

    private static string
        FormatRuntimeUnlockInitialActivationReceiveRecoveryHoldRequest(
            RuntimeUnlockInitialActivationReceiveRecoveryHoldRequest request)
    {
        var scope = request.ExpectedScope;
        var publication = scope.SourcePublicationAuthority;
        var command = scope.ExpectedExecutionCommand;
        return
            $"session_id={SanitizeLogToken(request.SessionId)}; transfer_id={SanitizeLogToken(request.TransferId)}; direction={request.Direction.ToString().ToLowerInvariant()}; boundary={SanitizeLogToken(request.Boundary.ToString())}; offer_nonce={SanitizeLogToken(request.OfferNonce)}; payer_decision_id={request.PayerDecisionId}; offer_generation={request.OfferGeneration}; transaction_generation={request.TransactionGeneration}; tuna_path_lease_generation={request.TunaPathLeaseGeneration}; tuna_path_lease_listener_run_id={SanitizeLogToken(request.TunaPathLeaseListenerRunId)}; semantic_offer_fingerprint={SanitizeLogToken(request.SemanticOfferFingerprint)}; envelope_generation={request.EnvelopeGeneration}; envelope_sent_at_unix_ms={request.EnvelopeSentAtUnixMs}; envelope_expires_at_unix_ms={request.EnvelopeExpiresAtUnixMs}; control_envelope_fingerprint={SanitizeLogToken(request.ControlEnvelopeFingerprint)}; peer_visible_dispatch_observed={(request.PeerVisibleDispatchObserved ? 1 : 0)}; source_route={SanitizeLogToken(publication?.RouteToken ?? "(none)")}; source_protocol_version={publication?.ProtocolVersion ?? 0}; source_live_route_epoch={publication?.LiveRouteEpoch ?? 0}; source_runtime_generation={publication?.RuntimeGeneration ?? 0}; source_terminal_generation={publication?.TerminalGeneration ?? 0}; source_leg_generation={publication?.LegGeneration ?? 0}; source_route_publication_generation={publication?.RoutePublicationGeneration ?? 0}; source_transport_epoch={scope.TransportEpoch}; source_bridge_recovery_generation={scope.BridgeRecoveryGeneration}; source_checkpoint_request_id={SanitizeLogToken(scope.CheckpointRequestId ?? "(none)")}; data_session_identity={SanitizeLogToken(scope.DataSessionIdentity)}; data_session_generation={scope.DataSessionGeneration}; expected_bridge_decision_generation={command?.Decision.BridgeDecisionGeneration ?? 0}";
    }

    private static void
        LogRuntimeUnlockInitialActivationReceiveRecoveryHoldDecision(
            string eventName,
            RuntimeUnlockInitialActivationReceiveRecoveryHoldDecision decision,
            string source)
    {
        var operation = decision.ReceiveRecoveryOperation;
        var authority = operation?.Authority;
        var observation = authority?.Observation;
        var lease = authority?.RecoveryLivenessLease;
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event={eventName}; {FormatRuntimeUnlockInitialActivationReceiveRecoveryHoldRequest(decision.Request)}; decision_status={decision.Status}; hold_generation={decision.HoldGeneration}; refresh_generation={decision.EnvelopeRefreshCommand?.RefreshGeneration ?? 0}; successor_envelope_generation={decision.EnvelopeRefreshCommand?.SuccessorEnvelopeGeneration ?? 0}; receive_recovery_operation_authority_id={SanitizeLogToken(authority?.AuthorityId.ToString() ?? "(none)")}; receive_recovery_operation_generation={authority?.OperationGeneration ?? 0}; previous_receive_recovery_operation_authority_id={SanitizeLogToken(decision.PreviousReceiveRecoveryAuthority?.AuthorityId.ToString() ?? "(none)")}; previous_receive_recovery_operation_generation={decision.PreviousReceiveRecoveryAuthority?.OperationGeneration ?? 0}; receive_recovery_execution_state={SanitizeLogToken(operation?.ExecutionState.ToString() ?? "(none)")}; receive_recovery_closure_state={SanitizeLogToken(operation?.ClosureState.ToString() ?? "(none)")}; receive_recovery_closure_generation={operation?.ClosureGeneration ?? 0}; bridge_decision_generation={authority?.BridgeRecoveryDecision.BridgeDecisionGeneration ?? 0}; bridge_recovery_generation={observation?.BridgeRecoveryGeneration ?? 0}; recovery_liveness_lease_authority_id={SanitizeLogToken(lease?.AuthorityId.ToString() ?? "(none)")}; recovery_liveness_lease_generation={lease?.LeaseGeneration ?? 0}; runtime_generation={observation?.RuntimeOwner.RuntimeGeneration ?? 0}; route_publication_generation={observation?.RoutePublication.PublicationGeneration ?? 0}; terminal_generation={observation?.TerminalGeneration ?? 0}; leg_generation={observation?.LegGeneration ?? 0}; transport_epoch={observation?.TransportEpoch ?? 0}; data_session_identity={SanitizeLogToken(observation?.DataSessionIdentity ?? "(none)")}; data_session_generation={observation?.DataSessionGeneration ?? 0}; decision_source={SanitizeLogToken(source)}; decision_reason={SanitizeLogToken(decision.Reason)}");
    }

