    private bool TryPromoteRetiredPendingRuntimeUnlockAnswer(
        RuntimeUnlockOfferAuthorityBoundary expectedBoundary,
        string sessionId,
        long payerDecisionId,
        string nonce,
        string source)
    {
        RuntimeUnlockTransactionDecision? transactionDecision = null;
        var accepted = false;
        var status = "rejected";
        var decisionReason = "retired_pending_answer_not_current";
        var priorState = RuntimeUnlockTransactionState.Idle;
        var resultingState = RuntimeUnlockTransactionState.Idle;
        var retirementReason = "(none)";
        var retainedDeadlineUtcMs = 0L;
        var normalizedSessionId = string.IsNullOrWhiteSpace(sessionId)
            ? string.Empty
            : sessionId.Trim();
        var normalizedNonce = string.IsNullOrWhiteSpace(nonce)
            ? string.Empty
            : nonce.Trim();
        lock (accelerationGate)
        {
            var proof = runtimeUnlockOfferProofState;
            var transaction = runtimeUnlockTransactionState;
            var lease = runtimeUnlockTunaPathLeaseState;
            priorState = transaction.State;
            resultingState = transaction.State;
            retirementReason = proof?.RetiredReason ?? "(none)";
            retainedDeadlineUtcMs = proof?.RetiredAnswerExpiresUtcMs ?? 0;
            var nowMs = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();

            if (expectedBoundary.Mode !=
                    RuntimeUnlockOfferAuthorityMode.InitialActivation ||
                expectedBoundary.InstallReceipt is not null)
            {
                decisionReason = "retired_pending_answer_not_initial_activation";
            }
            else if (retiredRuntimeUnlockOfferAuthorityBoundary !=
                         expectedBoundary ||
                     outboundRuntimeUnlockOfferAuthorityBoundary is not null ||
                     !string.IsNullOrWhiteSpace(outboundAccelerationOfferNonce))
            {
                decisionReason = "retired_pending_answer_authority_replaced";
            }
            else if (proof is not
                     {
                         AuthorityMode:
                             RuntimeUnlockOfferAuthorityMode.InitialActivation,
                         Retired: true,
                     } ||
                     proof.Generation != expectedBoundary.OfferGeneration ||
                     proof.PayerDecisionId != payerDecisionId ||
                     !string.Equals(
                         proof.SessionId,
                         normalizedSessionId,
                         StringComparison.Ordinal) ||
                     !string.Equals(
                         proof.Nonce,
                         normalizedNonce,
                         StringComparison.Ordinal) ||
                     !string.Equals(
                         expectedBoundary.SessionId,
                         normalizedSessionId,
                         StringComparison.Ordinal) ||
                     expectedBoundary.PayerDecisionId != payerDecisionId ||
                     !string.Equals(
                         expectedBoundary.Nonce,
                         normalizedNonce,
                         StringComparison.Ordinal))
            {
                decisionReason = "retired_pending_answer_tuple_mismatch";
            }
            else if (!IsRuntimeUnlockPendingAnswerRetiredReason(
                         proof.RetiredReason))
            {
                decisionReason = "retired_pending_answer_reason_unauthorized";
            }
            else if (proof.RetiredAnswerExpiresUtcMs <= 0 ||
                     retiredAccelerationOfferExpiresUtcMs !=
                         proof.RetiredAnswerExpiresUtcMs ||
                     nowMs >= proof.RetiredAnswerExpiresUtcMs)
            {
                decisionReason = "retired_pending_answer_deadline_expired";
            }
            else if (transaction.IsTerminal ||
                     transaction.TransactionGeneration !=
                         expectedBoundary.TransactionGeneration ||
                     transaction.OfferGeneration !=
                         expectedBoundary.OfferGeneration ||
                     !string.Equals(
                         transaction.SessionId,
                         expectedBoundary.SessionId,
                         StringComparison.Ordinal) ||
                     transaction.State is not (
                         RuntimeUnlockTransactionState.OfferSentObserved or
                         RuntimeUnlockTransactionState.PeerReceived or
                         RuntimeUnlockTransactionState.AnswerReceived))
            {
                decisionReason = "retired_pending_answer_transaction_not_current";
            }
            else if (lease.LeaseGeneration !=
                         expectedBoundary.TunaPathLeaseGeneration ||
                     !lease.IsCurrent ||
                     lease.PayerDecisionId != payerDecisionId ||
                     !string.Equals(
                         lease.ListenerRunId,
                         expectedBoundary.TunaPathLeaseListenerRunId,
                         StringComparison.Ordinal) ||
                     !RuntimeUnlockTunaPathLease.IsApplicableToOffer(
                         lease,
                         expectedBoundary.SessionId,
                         expectedBoundary.TransactionGeneration,
                         expectedBoundary.OfferGeneration))
            {
                decisionReason = "retired_pending_answer_tuna_path_lease_not_current";
            }
            else if (transaction.AnswerReceived)
            {
                accepted = true;
                status = "idempotent";
                decisionReason = "retired_pending_answer_already_promoted";
            }
            else
            {
                transactionDecision = ApplyRuntimeUnlockTransactionUnsafe(
                    RuntimeUnlockTransactionEventKind.AnswerReceived,
                    expectedBoundary.SessionId,
                    expectedBoundary.OfferGeneration,
                    source,
                    transactionGeneration:
                        expectedBoundary.TransactionGeneration);
                resultingState = transactionDecision.State.State;
                accepted = transactionDecision.State.AnswerReceived &&
                    transactionDecision.State.PeerReceived &&
                    transactionDecision.State.TransactionGeneration ==
                        expectedBoundary.TransactionGeneration &&
                    transactionDecision.State.OfferGeneration ==
                        expectedBoundary.OfferGeneration;
                status = accepted ? "accepted" : "rejected";
                decisionReason = accepted
                    ? "retired_pending_answer_promoted"
                    : "retired_pending_answer_transaction_apply_rejected";
            }
        }

        if (transactionDecision is not null && accepted)
        {
            LogRuntimeUnlockTransactionDecision(
                RuntimeUnlockTransactionEventKind.AnswerReceived,
                transactionDecision);
        }
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=runtime_unlock_retired_pending_answer_transaction_handoff_decided; session_id={SanitizeLogToken(expectedBoundary.SessionId)}; transfer_id={SanitizeLogToken(expectedBoundary.TransferId ?? "(none)")}; direction={expectedBoundary.Direction.ToString().ToLowerInvariant()}; authority_mode={expectedBoundary.Mode}; nonce={SanitizeLogToken(expectedBoundary.Nonce)}; payer_decision_id={expectedBoundary.PayerDecisionId}; offer_generation={expectedBoundary.OfferGeneration}; transaction_generation={expectedBoundary.TransactionGeneration}; tuna_path_lease_generation={expectedBoundary.TunaPathLeaseGeneration}; tuna_path_lease_listener_run_id={SanitizeLogToken(expectedBoundary.TunaPathLeaseListenerRunId ?? "(none)")}; retirement_reason={SanitizeLogToken(retirementReason)}; retained_answer_deadline_utc_ms={retainedDeadlineUtcMs}; prior_transaction_state={priorState.ToString().ToLowerInvariant()}; resulting_transaction_state={resultingState.ToString().ToLowerInvariant()}; decision_status={status}; decision_reason={SanitizeLogToken(decisionReason)}");
        return accepted;
    }

    private bool TryPromoteRuntimeUnlockObservedSendFromPeerAnswer(
        string sessionId,
        string nonce,
        long payerDecisionId,
        long offerGeneration)
    {
        if (string.IsNullOrWhiteSpace(sessionId) ||
            string.IsNullOrWhiteSpace(nonce) ||
            offerGeneration <= 0)
        {
            return false;
        }

        var normalizedSessionId = sessionId.Trim();
        if (!HasActiveRegularV4FileTransferRouteHint(normalizedSessionId) ||
            HasActivePostTunaFallbackFileTransferRouteHint(normalizedSessionId) ||
            TryGetUnresolvedFileTransferV6TransportEpochForCurrentSession(out _))
        {
            return false;
        }

        RuntimeUnlockRecoveryRetryState? stateSnapshot = null;
        var hasAuthorityState = false;
        lock (accelerationGate)
        {
            if (!TryGetCurrentRuntimeUnlockOfferAuthorityBoundaryUnsafe(
                    out var offer,
                    out var authorityBoundary) ||
                authorityBoundary?.Mode !=
                    RuntimeUnlockOfferAuthorityMode.InstalledRetry)
            {
                return false;
            }

            var state = runtimeUnlockRecoveryRetryState;
            if (offer is null ||
                offer.Retired ||
                offer.ObservedSend ||
                !offer.PeerReceived ||
                offer.Generation != offerGeneration ||
                offer.PayerDecisionId != payerDecisionId ||
                !string.Equals(offer.Nonce, nonce, StringComparison.Ordinal) ||
                !string.Equals(offer.SessionId, normalizedSessionId, StringComparison.Ordinal))
            {
                return false;
            }

            if (state is not null &&
                string.Equals(state.SessionId, normalizedSessionId, StringComparison.Ordinal) &&
                state.CurrentOfferGeneration == offerGeneration)
            {
                hasAuthorityState = true;
                stateSnapshot = state;
            }
        }

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=runtime_unlock_observed_send_promoted_from_peer_answer; session_id={SanitizeLogToken(normalizedSessionId)}; payer_decision_id={payerDecisionId}; generation={offerGeneration}; observed_lane={AccelerationObservedLanePeerAnswer}; contract_generation={(hasAuthorityState ? stateSnapshot!.ContractGeneration : 0)}; authority_attempt={(hasAuthorityState ? stateSnapshot!.AuthorityAttempt : 0)}; reason=peer_answer_proves_offer_visibility");
        return true;
    }

    private async Task<bool> WaitForRuntimeUnlockPeerAnswerAsObservedSendAsync(
        string sessionId,
        string nonce,
        long payerDecisionId,
        long offerGeneration,
        CancellationToken ct)
    {
        if (TryPromoteRuntimeUnlockObservedSendFromPeerAnswer(sessionId, nonce, payerDecisionId, offerGeneration))
        {
            return true;
        }

        var deadline = DateTimeOffset.UtcNow + RuntimeUnlockPeerAnswerObservedSendGrace;
        while (DateTimeOffset.UtcNow < deadline)
        {
            if (ct.IsCancellationRequested)
            {
                return false;
            }

            await Task.Delay(TimeSpan.FromMilliseconds(25), CancellationToken.None).ConfigureAwait(false);
            if (TryPromoteRuntimeUnlockObservedSendFromPeerAnswer(sessionId, nonce, payerDecisionId, offerGeneration))
            {
                return true;
            }
        }

        return false;
    }

    private void MarkInboundRuntimeUnlockOfferAccepted(
        TransportAccelerationOfferPayload offer,
        long answerAckGeneration)
    {
        if (answerAckGeneration <= 0 ||
            !IsRuntimeUnlockActivationReason(offer.Trigger))
        {
            return;
        }

        var sessionId = string.IsNullOrWhiteSpace(offer.SessionId)
            ? currentSessionSecurityState.SessionId?.Value ?? string.Empty
            : offer.SessionId.Trim();
        if (string.IsNullOrWhiteSpace(sessionId))
        {
            return;
        }

        FileTransferRoutePublicationAuthority? runtimeUnlockFileTransferOwnerAuthority = null;
        if (IsFileTransferRuntimeUnlockContextObserved(sessionId))
        {
            if (!TryCaptureCurrentRuntimeUnlockFileTransferOwnerAuthority(
                    sessionId,
                    out var capturedOwnerAuthority,
                    out var ownerRejectionReason))
            {
                LogRuntimeUnlockFileTransferOwnerRejectedBeforePathLease(
                    sessionId,
                    offer.Trigger,
                    ownerRejectionReason);
                return;
            }

            runtimeUnlockFileTransferOwnerAuthority = capturedOwnerAuthority;
            LogRuntimeUnlockFileTransferOwnerAcceptedBeforePathLease(
                capturedOwnerAuthority,
                offer.Trigger);
        }

        RuntimeUnlockTransactionDecision? started;
        RuntimeUnlockTransactionDecision? peerReceived;
        RuntimeUnlockTransactionDecision? answerReceived;
        lock (accelerationGate)
        {
            started = StartRuntimeUnlockTransactionForOfferUnsafe(
                sessionId,
                answerAckGeneration,
                "peer_runtime_unlock_offer_accepted");
            StartPeerOfferRuntimeUnlockTunaPathLeaseUnsafe(
                sessionId,
                runtimeUnlockFileTransferOwnerAuthority?.TransferId,
                started.State.TransactionGeneration,
                answerAckGeneration,
                offer.PayerDecisionId,
                "peer_runtime_unlock_offer_accepted");
            started = started with
            {
                State = AttachRuntimeUnlockTunaPathLeaseUnsafe(started.State),
            };
            peerReceived = ApplyRuntimeUnlockTransactionUnsafe(
                RuntimeUnlockTransactionEventKind.PeerReceived,
                sessionId,
                answerAckGeneration,
                "transport_acceleration_offer_received");
            answerReceived = ApplyRuntimeUnlockTransactionUnsafe(
                RuntimeUnlockTransactionEventKind.AnswerReceived,
                sessionId,
                answerAckGeneration,
                "transport_acceleration_answer_pending");
        }

        LogRuntimeUnlockTransactionDecision(RuntimeUnlockTransactionEventKind.OfferGenerationCreated, started);
        LogRuntimeUnlockTransactionDecision(RuntimeUnlockTransactionEventKind.PeerReceived, peerReceived);
        LogRuntimeUnlockTransactionDecision(RuntimeUnlockTransactionEventKind.AnswerReceived, answerReceived);
    }

    private RuntimeUnlockTunaPathLeaseSnapshot StartPeerOfferRuntimeUnlockTunaPathLeaseUnsafe(
        string sessionId,
        string? transferId,
        long transactionGeneration,
        long offerGeneration,
        long payerDecisionId,
        string reason)
    {
        var nowMs = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
        var leaseGeneration = ++runtimeUnlockTunaPathLeaseNextGeneration;
        var listenerRunId = $"peer-offer-dialer-{leaseGeneration.ToString(CultureInfo.InvariantCulture)}";
        var lease = RuntimeUnlockTunaPathLease.Start(
            sessionId,
            transferId,
            leaseGeneration,
            listenerRunId,
            payerDecisionId,
            nowMs);
        runtimeUnlockTunaPathLeaseState = lease;
        LogRuntimeUnlockTunaPathLease("tuna_path_lease_started", lease, reason);

        if (RuntimeUnlockTunaPathLease.TryMarkListenerReady(
                runtimeUnlockTunaPathLeaseState,
                sessionId,
                leaseGeneration,
                listenerRunId,
                nowMs,
                out var ready))
        {
            runtimeUnlockTunaPathLeaseState = ready;
        }

        var bound = RuntimeUnlockTunaPathLease.BindOffer(
            runtimeUnlockTunaPathLeaseState,
            transactionGeneration,
            offerGeneration,
            payerDecisionId,
            nowMs);
        runtimeUnlockTunaPathLeaseState = bound;
        runtimeUnlockTransactionState = AttachRuntimeUnlockTunaPathLeaseUnsafe(runtimeUnlockTransactionState);
        LogRuntimeUnlockTunaPathLease("tuna_path_lease_listener_ready", bound, reason);
        return bound;
    }

    private bool FailRuntimeUnlockCutThroughIfCurrent(
        string sessionId,
        long payerDecisionId,
        long offerGeneration,
        string reason)
    {
        RuntimeUnlockRecoveryRetryState? stateSnapshot = null;
        RuntimeUnlockTransactionDecision? transactionDecision = null;
        RuntimeUnlockRetryDispatchSettlementReport settlementReport = default;
        var normalizedReason = SanitizeLogToken(reason);
        lock (accelerationGate)
        {
            var state = runtimeUnlockRecoveryRetryState;
            if (state is null ||
                state.ContractState is SessionRecoveryContractState.Completed or SessionRecoveryContractState.Failed ||
                !state.CutThroughActive ||
                state.CutThroughPeerReceived ||
                !string.Equals(state.SessionId, sessionId.Trim(), StringComparison.Ordinal) ||
                state.CurrentOfferGeneration != offerGeneration)
            {
                return false;
            }

            stateSnapshot = state;
            if (state.DispatchContract is not null)
            {
                if (!SettleRuntimeUnlockRetryDispatchContractUnsafe(
                        state,
                        RuntimeUnlockRetryDispatchSettlementOutcome.TerminalRejected,
                        normalizedReason,
                        out settlementReport))
                {
                    return false;
                }
            }
            else
            {
                state.RetryAuthorityPending = false;
                state.ObservedSendPending = false;
                state.AuthorityFailureReason = normalizedReason;
                state.ContractState = SessionRecoveryContractState.Failed;
                transactionDecision = ApplyRuntimeUnlockTransactionUnsafe(
                    RuntimeUnlockTransactionEventKind.Failed,
                    sessionId,
                    offerGeneration,
                    normalizedReason);
            }
        }

        if (!settlementReport.IsDefault)
        {
            if (!PublishRuntimeUnlockRetryDispatchSettlementReport(settlementReport))
            {
                return false;
            }

            lock (accelerationGate)
            {
                if (!ReferenceEquals(runtimeUnlockRecoveryRetryState, stateSnapshot) ||
                    stateSnapshot!.ContractState != SessionRecoveryContractState.Failed ||
                    stateSnapshot.LastAppliedDispatchSettlementReport != settlementReport)
                {
                    return false;
                }

                transactionDecision = ApplyRuntimeUnlockTransactionUnsafe(
                    RuntimeUnlockTransactionEventKind.Failed,
                    sessionId,
                    offerGeneration,
                    normalizedReason);
            }
        }

        LogRuntimeUnlockTransactionDecision(RuntimeUnlockTransactionEventKind.Failed, transactionDecision);
        LocalOperationalLog.Warn(
            "NKN.Tuna",
            $"event=runtime_unlock_cutthrough_failed; session_id={SanitizeLogToken(sessionId)}; payer_decision_id={payerDecisionId}; offer_generation={offerGeneration}; contract_generation={stateSnapshot!.ContractGeneration}; attempt={stateSnapshot.CutThroughAttempt}; reason={SanitizeLogToken(reason)}");
        LogRuntimeUnlockRecoveryContract("session_recovery_contract_failed", stateSnapshot.SessionId);
        return true;
    }

    private bool MarkRuntimeUnlockRecoveryContractAuthorityBlocked(
        string? reason,
        RuntimeUnlockOfferAuthorityBoundary? expectedOfferAuthorityBoundary = null)
    {
        RuntimeUnlockRecoveryRetryState? stateSnapshot = null;
        RuntimeUnlockRecoveryRetryState? ignoredEvidenceState = null;
        lock (accelerationGate)
        {
            if (expectedOfferAuthorityBoundary is { } expected &&
                !IsRuntimeUnlockOfferAuthorityBoundaryCurrentUnsafe(
                    expected,
                    allowDispatchObservedSettlement: true))
            {
                return false;
            }

            var state = runtimeUnlockRecoveryRetryState;
            if (state is null ||
                !state.RetryAuthorityGranted ||
                state.ContractState is SessionRecoveryContractState.Completed or SessionRecoveryContractState.Failed)
            {
                return false;
            }

            if (HasCurrentGrantedRuntimeUnlockRetryDispatchContractUnsafe(state, out _))
            {
                ignoredEvidenceState = state;
            }
            else
            {
                state.AuthorityFailureReason = string.IsNullOrWhiteSpace(reason)
                    ? "runtime_unlock_retry_authority_offer_blocked"
                    : SanitizeLogToken(reason);
                stateSnapshot = state;
            }
        }

        if (ignoredEvidenceState is not null)
        {
            LogRuntimeUnlockRetryDispatchProof(
                "runtime_unlock_retry_dispatch_evidence_ignored_after_authority_granted",
                ignoredEvidenceState,
                SanitizeLogToken(reason));
            return false;
        }

        LogRuntimeUnlockRecoveryContract("session_recovery_contract_retry_authority_send_blocked", stateSnapshot!.SessionId);
        return true;
    }

    private bool ShouldPromoteRuntimeUnlockAuthoritySendBlockToCutThrough(string? sessionId)
    {
        if (string.IsNullOrWhiteSpace(sessionId))
        {
            return false;
        }

        var normalizedSessionId = sessionId.Trim();
        if (!HasActiveRegularV4FileTransferRouteHint(normalizedSessionId) ||
            HasActivePostTunaFallbackFileTransferRouteHint(normalizedSessionId) ||
            TryGetUnresolvedFileTransferV6TransportEpochForCurrentSession(out _))
        {
            return false;
        }

        if (!TryGetRuntimeUnlockRetryAuthorityForCurrentOffer(out var state, normalizedSessionId) ||
            state is null ||
            !state.RetryAuthorityGranted ||
            state.RetryObserved ||
            state.CutThroughActive ||
            state.ContractState is SessionRecoveryContractState.Completed or SessionRecoveryContractState.Failed)
        {
            return false;
        }

        var failureReason = SanitizeLogToken(state.AuthorityFailureReason);
        return failureReason is "runtime_unlock_retry_authority_offer_blocked" or
            "regular_v4_receive_recovery_unproven" or
            "runtime_unlock_authority_missing_recent_peer_proof";
    }

    private RuntimeUnlockRetryDispatchAuthorityResult TryGrantRuntimeUnlockRecoveryRetryDispatchAuthorityForOfferSend(
        string reason,
        string sessionId)
    {
        RuntimeUnlockRecoveryRetryState? stateSnapshot = null;
        RuntimeUnlockRecoveryRetryState? rejectedState = null;
        RuntimeUnlockRetryDispatchSettlementReport rejectedSettlementReport = default;
        var rejectedHadDispatchContract = false;
        var authorityGranted = false;
        var normalizedSessionId = string.IsNullOrWhiteSpace(sessionId)
            ? string.Empty
            : sessionId.Trim();
        string? transferId = null;
        var expectedLiveRouteEpoch = 0;
        var expectedDispatchDirection = FileTransferDirection.Outbound;
        var capturedContractGeneration = 0L;
        var capturedRetiredOfferGeneration = 0L;
        string? capturedSessionId = null;
        string? capturedTransferId = null;
        var allowPostTunaFallbackDispatchAuthority = false;
        var hasSettledDispatchAuthorityForCurrentRetry = false;
        RuntimeUnlockRetryDispatchContract? pendingSuccessorPredecessor = null;
        lock (accelerationGate)
        {
            var state = runtimeUnlockRecoveryRetryState;
            if (state is not null &&
                state.ContractState is not (SessionRecoveryContractState.Completed or SessionRecoveryContractState.Failed) &&
                !state.RetryObserved &&
                string.Equals(state.SessionId, normalizedSessionId, StringComparison.Ordinal))
            {
                transferId = state.TransferId;
                expectedLiveRouteEpoch = GetRuntimeUnlockRetryExpectedDispatchLiveRouteEpoch(state);
                expectedDispatchDirection = GetRuntimeUnlockRetryExpectedDispatchDirection(state);
                capturedContractGeneration = state.ContractGeneration;
                capturedRetiredOfferGeneration = state.RetiredOfferGeneration;
                capturedSessionId = state.SessionId;
                capturedTransferId = state.TransferId;
                allowPostTunaFallbackDispatchAuthority =
                    HasEffectiveFallbackPairedTailYieldInstallReceiptUnsafe(state);
                hasSettledDispatchAuthorityForCurrentRetry =
                    state.Settled &&
                    state.RetryAuthorityGranted &&
                    HasCurrentGrantedRuntimeUnlockRetryDispatchContractUnsafe(
                        state,
                        out _);
                if (state.DispatchContract is { } predecessor &&
                    predecessor.Lifecycle.SettlementOutcome ==
                        RuntimeUnlockRetryDispatchSettlementOutcome.MissingDispatch)
                {
                    pendingSuccessorPredecessor = predecessor;
                }
            }
        }

        if (pendingSuccessorPredecessor is not null)
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=runtime_unlock_retry_dispatch_held_for_missing_dispatch_successor; {FormatRuntimeUnlockRetryDispatchAuthorityTuple(pendingSuccessorPredecessor.Authority)}; trigger={SanitizeLogToken(reason)}; decision_reason=coordinator_successor_pending");
            return RuntimeUnlockRetryDispatchAuthorityResult.Held;
        }

        var hasCurrentRuntimeUnlockRetryContract =
            capturedContractGeneration > 0 &&
            !string.IsNullOrWhiteSpace(capturedSessionId);

        var hasDispatchAuthority = TryGetInstalledRuntimeUnlockRetryDispatchAuthority(
            normalizedSessionId,
            transferId,
            expectedDispatchDirection,
            expectedLiveRouteEpoch,
            allowPostTunaFallbackDispatchAuthority,
            out var dispatchAuthority,
            out var dispatchAuthorityRejectionReason);

        lock (accelerationGate)
        {
            var state = runtimeUnlockRecoveryRetryState;
            if (state is null ||
                state.RetryObserved ||
                !string.Equals(state.SessionId, normalizedSessionId, StringComparison.Ordinal) ||
                state.ContractState is SessionRecoveryContractState.Completed or SessionRecoveryContractState.Failed)
            {
                return state?.DispatchAuthorityRejected == true
                    ? RuntimeUnlockRetryDispatchAuthorityResult.Rejected
                    : RuntimeUnlockRetryDispatchAuthorityResult.Granted;
            }

            if (!IsRuntimeUnlockRetryDispatchAuthorityCaptureCurrent(
                         state,
                         capturedContractGeneration,
                         capturedRetiredOfferGeneration,
                          capturedSessionId,
                          capturedTransferId,
                          expectedLiveRouteEpoch))
            {
                return RuntimeUnlockRetryDispatchAuthorityResult.Rejected;
            }
            else if (!hasDispatchAuthority)
            {
                rejectedHadDispatchContract = state.DispatchContract is not null;
                _ = MarkRuntimeUnlockRetryDispatchAuthorityRejectedUnsafe(
                    state,
                    dispatchAuthorityRejectionReason,
                    out rejectedSettlementReport);
                rejectedState = state;
                stateSnapshot = state;
            }
            else
            {
                var wasQueuedBehindActiveNegotiation = state.QueuedBehindActiveNegotiation;
                state.QueuedBehindActiveNegotiation = false;
                state.RetryQueued = true;
                state.RetryDispatching = true;
                state.RetryDispatched = true;
                if (state.Settled && !state.RetryAuthorityGranted)
                {
                    GrantRuntimeUnlockRecoveryContractRetryAuthorityUnsafe(state);
                    authorityGranted = true;
                }

                if (state.Settled)
                {
                    state.DispatchDecisionReason = wasQueuedBehindActiveNegotiation
                        ? "queued_retry_dispatch_reacquired_for_offer_send"
                        : "retry_dispatch_reacquired_for_offer_send";
                }

                state.ContractState = SessionRecoveryContractState.RetryDispatched;
                stateSnapshot = state;
            }
        }

        if (rejectedState is not null)
        {
            if (!ConfirmRuntimeUnlockRetryDispatchRejection(
                    rejectedState,
                    rejectedHadDispatchContract,
                    rejectedSettlementReport))
            {
                return RuntimeUnlockRetryDispatchAuthorityResult.Rejected;
            }
            LogRuntimeUnlockRetryDispatchProof(
                "runtime_unlock_retry_dispatch_authority_rejected",
                rejectedState,
                rejectedState.DispatchDecisionReason ?? dispatchAuthorityRejectionReason);
            LogRuntimeUnlockRecoveryContract("session_recovery_contract_failed", rejectedState.SessionId);
            return RuntimeUnlockRetryDispatchAuthorityResult.Rejected;
        }

        if (authorityGranted)
        {
            LogRuntimeUnlockRecoveryContract("session_recovery_contract_retry_authority_granted", stateSnapshot!.SessionId);
        }

        LogRuntimeUnlockRecoveryContract("session_recovery_contract_retry_dispatched", stateSnapshot!.SessionId);
        return RuntimeUnlockRetryDispatchAuthorityResult.Granted;
    }

    private bool TryDeferRuntimeUnlockOfferDispatchForRegularV4FrontierRepair(
        string? sessionId,
        string trigger,
        long payerDecisionId,
        RuntimeUnlockRetryDispatchInstallReceipt? expectedInstallReceipt,
        RuntimeUnlockOfferAuthorityMode authorityMode,
        out string blockerReason,
        out long blockerEvidenceAgeMs)
    {
        blockerReason = string.Empty;
        blockerEvidenceAgeMs = 0;
        if (string.IsNullOrWhiteSpace(sessionId))
        {
            return false;
        }

        if (authorityMode != RuntimeUnlockOfferAuthorityMode.InstalledRetry ||
            expectedInstallReceipt is null)
        {
            return false;
        }

        var normalizedSessionId = sessionId.Trim();
        if (!HasActiveRegularV4FileTransferRouteHint(normalizedSessionId) ||
            HasActivePostTunaFallbackFileTransferRouteHint(normalizedSessionId))
        {
            return false;
        }

        var overrideBlocker = RuntimeUnlockRegularV4RepairPressureBlockerOverrideForTests?.Invoke(this);
        if (overrideBlocker is { HasBlocker: true })
        {
            blockerReason = SanitizeLogToken(overrideBlocker.Value.Reason);
            blockerEvidenceAgeMs = Math.Max(0, overrideBlocker.Value.EvidenceAgeMs);
        }
        else if (client is not RealNknClientAdapter realClient)
        {
            return false;
        }
        else if (!realClient.TryGetFileTransferRegularV4ActivationSendBlocker(
                     out blockerReason,
                     out blockerEvidenceAgeMs,
                     includeRegularV4Pressure: true))
        {
            return false;
        }

        if (!IsRegularV4PressureActivationSendBlocker(blockerReason))
        {
            return false;
        }

        RuntimeUnlockRecoveryRetryState? ignoredEvidenceState = null;
        RuntimeUnlockRecoveryRetryState? blockedState = null;
        var pendingBound = false;
        lock (accelerationGate)
        {
            var state = runtimeUnlockRecoveryRetryState;
            if (!TryValidatePendingRuntimeUnlockOfferAuthorityUnsafe(
                    authorityMode,
                    expectedInstallReceipt,
                    out _))
            {
                return false;
            }

            if (state is null ||
                !state.RetryAuthorityGranted ||
                state.ContractState is SessionRecoveryContractState.Completed or
                    SessionRecoveryContractState.Failed ||
                !string.Equals(state.SessionId, normalizedSessionId, StringComparison.Ordinal))
            {
                return false;
            }

            if (HasCurrentGrantedRuntimeUnlockRetryDispatchContractUnsafe(state, out _))
            {
                ignoredEvidenceState = state;
            }
            else
            {
                state.AuthorityFailureReason = SanitizeLogToken(blockerReason);
                state.BlockedByRegularV4FrontierRepair = true;
                state.RegularV4FrontierRepairTrigger = SanitizeLogToken(trigger);
                state.RegularV4FrontierRepairPayerDecisionId = payerDecisionId;
                state.RegularV4FrontierRepairBlockerReason = SanitizeLogToken(blockerReason);
                state.RegularV4FrontierRepairBlockedUtcMs = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
                pendingBound = TryBindPendingRuntimeUnlockAccelerationNegotiationUnsafe(
                    SanitizeLogToken(trigger),
                    expectedInstallReceipt,
                    authorityMode);
                blockedState = pendingBound ? state : null;
            }
        }

        if (ignoredEvidenceState is not null)
        {
            LogRuntimeUnlockRetryDispatchProof(
                "runtime_unlock_retry_dispatch_evidence_ignored_after_authority_granted",
                ignoredEvidenceState,
                "regular_v4_frontier_repair_evidence");
            return false;
        }

        if (!pendingBound || blockedState is null)
        {
            return false;
        }

        LogRuntimeUnlockRecoveryContract(
            "session_recovery_contract_retry_authority_send_blocked",
            blockedState.SessionId);
        var retryScheduled = false;
        LocalOperationalLog.Warn(
            "NKN.Tuna",
            $"event=runtime_unlock_offer_dispatch_held_by_regular_v4_frontier_repair; session_id={SanitizeLogToken(normalizedSessionId)}; trigger={SanitizeLogToken(trigger)}; payer_decision_id={payerDecisionId}; blocker_reason={SanitizeLogToken(blockerReason)}; blocker_evidence_age_ms={blockerEvidenceAgeMs}; retry_scheduled={(retryScheduled ? 1 : 0)}; decision_reason=awaiting_regular_v4_frontier_repair_settlement");
        NotifyTransportAccelerationStateChanged("runtime_unlock_regular_v4_frontier_repair_pending");
        return true;
    }

    private bool TryGetRuntimeUnlockRecoveryContractForSession(
        string? sessionId,
        out long retiredOfferGeneration,
        out string contractSessionId)
    {
        retiredOfferGeneration = 0;
        contractSessionId = string.Empty;
        var normalizedSessionId = string.IsNullOrWhiteSpace(sessionId) ? string.Empty : sessionId.Trim();
        lock (accelerationGate)
        {
            var state = runtimeUnlockRecoveryRetryState;
            if (state is null ||
                (!string.IsNullOrWhiteSpace(normalizedSessionId) &&
                 !string.Equals(state.SessionId, normalizedSessionId, StringComparison.Ordinal)))
            {
                return false;
            }

            retiredOfferGeneration = state.RetiredOfferGeneration;
            contractSessionId = state.SessionId;
            return true;
        }
    }

    private bool MarkRuntimeUnlockRecoveryContractRetryDispatched(
        string reason,
        RuntimeUnlockRetryDispatchInstallReceipt? expectedInstallReceipt,
        bool requireRuntimeUnlockRetryDispatchInstall)
    {
        if (!requireRuntimeUnlockRetryDispatchInstall)
        {
            return true;
        }

        if (!ValidateRuntimeUnlockRetryDispatchInstallReceiptBoundary(
                expectedInstallReceipt,
                "retry_dispatch",
                requireInstalledReceipt:
                    requireRuntimeUnlockRetryDispatchInstall))
        {
            return false;
        }

        RuntimeUnlockRecoveryRetryState? stateSnapshot = null;
        RuntimeUnlockRecoveryRetryState? rejectedState = null;
        RuntimeUnlockRetryDispatchSettlementReport rejectedSettlementReport = default;
        var rejectedHadDispatchContract = false;
        var sessionId = currentSessionSecurityState.SessionId?.Value;
        var normalizedSessionId = string.IsNullOrWhiteSpace(sessionId)
            ? string.Empty
            : sessionId.Trim();
        string? transferId = null;
        var expectedLiveRouteEpoch = 0;
        var expectedDispatchDirection = FileTransferDirection.Outbound;
        var capturedContractGeneration = 0L;
        var capturedRetiredOfferGeneration = 0L;
        string? capturedSessionId = null;
        string? capturedTransferId = null;
        var allowPostTunaFallbackDispatchAuthority = false;
        RuntimeUnlockRetryDispatchContract? settledPredecessor = null;
        lock (accelerationGate)
        {
            var state = runtimeUnlockRecoveryRetryState;
            if (state is { DispatchAuthorityRejected: true } &&
                string.Equals(state.SessionId, normalizedSessionId, StringComparison.Ordinal))
            {
                return false;
            }

            if (state?.DispatchContract is { } candidatePredecessor &&
                candidatePredecessor.Lifecycle.SettlementOutcome ==
                    RuntimeUnlockRetryDispatchSettlementOutcome.MissingDispatch)
            {
                settledPredecessor = candidatePredecessor;
            }

            if (state is not null &&
                state.ContractState is not (SessionRecoveryContractState.Completed or SessionRecoveryContractState.Failed) &&
                !state.RetryObserved)
            {
                sessionId = state.SessionId;
                transferId = state.TransferId;
                expectedLiveRouteEpoch = GetRuntimeUnlockRetryExpectedDispatchLiveRouteEpoch(state);
                expectedDispatchDirection = GetRuntimeUnlockRetryExpectedDispatchDirection(state);
                capturedContractGeneration = state.ContractGeneration;
                capturedRetiredOfferGeneration = state.RetiredOfferGeneration;
                capturedSessionId = state.SessionId;
                capturedTransferId = state.TransferId;
                allowPostTunaFallbackDispatchAuthority =
                    HasEffectiveFallbackPairedTailYieldInstallReceiptUnsafe(state);
            }
        }

        if (settledPredecessor is not null)
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=runtime_unlock_retry_settled_predecessor_retry_blocked; {FormatRuntimeUnlockRetryDispatchAuthorityTuple(settledPredecessor.Authority)}; failed_offer_generation={settledPredecessor.OfferGeneration}; local_retry_reused_predecessor=0; decision_reason=coordinator_successor_required");
            RequestRuntimeUnlockRetryDispatchAuthority(
                settledPredecessor.Authority.SessionId,
                "settled_predecessor_retry_callback_coalesced");

            return false;
        }

        var hasDispatchAuthority = TryGetInstalledRuntimeUnlockRetryDispatchAuthority(
            sessionId,
            transferId,
            expectedDispatchDirection,
            expectedLiveRouteEpoch,
            allowPostTunaFallbackDispatchAuthority,
            out var dispatchAuthority,
            out var dispatchAuthorityRejectionReason);

        lock (accelerationGate)
        {
            var state = runtimeUnlockRecoveryRetryState;
            if (state is null ||
                state.RetryObserved ||
                state.ContractState is SessionRecoveryContractState.Completed or SessionRecoveryContractState.Failed)
            {
                return state?.DispatchAuthorityRejected != true;
            }

            if (expectedInstallReceipt is { } receipt &&
                !TryValidateRuntimeUnlockRetryDispatchInstallReceiptCurrentUnsafe(
                    state,
                    receipt,
                    out var receiptRejectionReason))
            {
                LogRuntimeUnlockRetryDispatchInstallRejected(
                    receipt,
                    CaptureRuntimeUnlockRetryDispatchInstallTelemetryUnsafe(state),
                    RuntimeUnlockRetryDispatchInstallStatus.Rejected,
                    $"{receiptRejectionReason}_retry_dispatch_commit");
                return false;
            }

            if (!IsRuntimeUnlockRetryDispatchAuthorityCaptureCurrent(
                    state,
                    capturedContractGeneration,
                    capturedRetiredOfferGeneration,
                    capturedSessionId,
                    capturedTransferId,
                    expectedLiveRouteEpoch))
            {
                return false;
            }

            if (!hasDispatchAuthority)
            {
                rejectedHadDispatchContract = state.DispatchContract is not null;
                _ = MarkRuntimeUnlockRetryDispatchAuthorityRejectedUnsafe(
                    state,
                    dispatchAuthorityRejectionReason,
                    out rejectedSettlementReport);
                rejectedState = state;
                stateSnapshot = state;
            }
            else
            {
                state.RetryQueued = true;
                state.RetryDispatching = true;
                GrantRuntimeUnlockRecoveryContractRetryAuthorityUnsafe(state);
                state.RetryDispatched = false;
                state.ContractState = SessionRecoveryContractState.RetryDispatching;
            }
            stateSnapshot = state;
        }

        if (rejectedState is not null)
        {
            if (!ConfirmRuntimeUnlockRetryDispatchRejection(
                    rejectedState,
                    rejectedHadDispatchContract,
                    rejectedSettlementReport))
            {
                return false;
            }
            LogRuntimeUnlockRetryDispatchProof(
                "runtime_unlock_retry_dispatch_authority_rejected",
                rejectedState,
                rejectedState.DispatchDecisionReason ?? dispatchAuthorityRejectionReason);
            LogRuntimeUnlockRecoveryContract("session_recovery_contract_failed", rejectedState.SessionId);
            return false;
        }

        return true;
    }

    private bool HasPendingOutboundAccelerationOffer()
    {
        lock (accelerationGate)
        {
            return !string.IsNullOrWhiteSpace(outboundAccelerationOfferNonce);
        }
    }

    private bool HasPendingAccelerationAnswerAck()
    {
        lock (accelerationGate)
        {
            return !string.IsNullOrWhiteSpace(pendingAccelerationAnswerAckNonce) &&
                   pendingAccelerationAnswerAckPayerDecisionId > 0;
        }
    }

    private void ClearOutboundAccelerationOfferIfCurrent(
        string nonce,
        long payerDecisionId,
        long generation,
        string reason)
    {
        lock (accelerationGate)
        {
            if (outboundAccelerationOfferGeneration != generation ||
                outboundAccelerationOfferPayerDecisionId != payerDecisionId ||
                !string.Equals(outboundAccelerationOfferNonce, nonce, StringComparison.Ordinal))
            {
                return;
            }

            ClearOutboundAccelerationOfferLocked();
        }

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=tuna_acceleration_outbound_offer_cleared; reason={SanitizeLogToken(reason)}; payer_decision_id={payerDecisionId}; generation={generation}");
        SchedulePendingRuntimeUnlockAccelerationNegotiationAfterCurrentOperation("outbound_offer_cleared");
    }

    private void MarkRuntimeUnlockOfferObservedSendIfCurrent(
        string nonce,
        long payerDecisionId,
        long generation,
        string? observedLane)
    {
        if (string.IsNullOrWhiteSpace(observedLane))
        {
            return;
        }

        lock (accelerationGate)
        {
            var state = runtimeUnlockOfferProofState;
            if (state is null ||
                state.Retired ||
                state.Generation != generation ||
                state.PayerDecisionId != payerDecisionId ||
                !string.Equals(state.Nonce, nonce, StringComparison.Ordinal))
            {
                return;
            }

            state.ObservedSend = true;
            state.ObservedSendLane = SanitizeLogToken(observedLane);
        }
    }

    private bool MarkRuntimeUnlockRecoveryContractRetryObserved(
        string sessionId,
        long offerGeneration,
        string? observedLane)
    {
        RuntimeUnlockRecoveryRetryState? stateSnapshot = null;
        RuntimeUnlockRecoveryRetryState? rejectedState = null;
        RuntimeUnlockRetryDispatchContract? settledContract = null;
        RuntimeUnlockRetryDispatchContract? duplicateContract = null;
        RuntimeUnlockRetryDispatchContract? staleContract = null;
        RuntimeUnlockRetryDispatchSettlementReport settlementReport = default;
        RuntimeUnlockRetryDispatchSettlementReport rejectedSettlementReport = default;
        var rejectedHadDispatchContract = false;
        var staleReason = "none";
        var normalizedSessionId = string.IsNullOrWhiteSpace(sessionId) ? string.Empty : sessionId.Trim();

        lock (accelerationGate)
        {
            var state = runtimeUnlockRecoveryRetryState;
            if (state is null)
            {
                return true;
            }

            if (!string.Equals(state.SessionId, normalizedSessionId, StringComparison.Ordinal))
            {
                return false;
            }

            if (state.ContractState == SessionRecoveryContractState.Failed)
            {
                return false;
            }

            if (state.ContractState == SessionRecoveryContractState.Completed)
            {
                if (state.CurrentOfferGeneration > 0 &&
                    offerGeneration > 0 &&
                    state.CurrentOfferGeneration != offerGeneration)
                {
                    return false;
                }

                state.AuthorizedObservedLane = SanitizeLogToken(observedLane ?? "(none)");
                stateSnapshot = state;
            }
            else
            {
                if (state.RetryObserved)
                {
                    return false;
                }

                var requiresDispatchProof = RequiresRuntimeUnlockRetryDispatchProof(state);
                var contract = state.DispatchContract;
                RuntimeUnlockRetryDispatchSettlementReport observedProposal =
                    default;
                if (requiresDispatchProof && contract is null)
                {
                    rejectedHadDispatchContract = false;
                    _ = MarkRuntimeUnlockRetryDispatchAuthorityRejectedUnsafe(
                        state,
                        "missing_runtime_unlock_retry_authority",
                        out rejectedSettlementReport);
                    rejectedState = state;
                    stateSnapshot = state;
                }
                else if (requiresDispatchProof &&
                         (contract!.Authority.RecoveryContractGeneration != state.ContractGeneration ||
                          contract.Authority.RetiredOfferGeneration != state.RetiredOfferGeneration ||
                          contract.Authority.DispatchAttemptGeneration != state.DispatchAttemptGeneration ||
                          !contract.MatchesOfferAlias(offerGeneration)))
                {
                    staleContract = contract;
                    staleReason = "runtime_unlock_retry_offer_alias_stale";
                }
                else if (requiresDispatchProof && contract!.Lifecycle.IsSettled)
                {
                    duplicateContract = contract;
                }
                else if (requiresDispatchProof &&
                         (!contract!.TryGetInFlightAttempt(out var dispatchAttempt) ||
                          !contract.TryCreateObservedSettlementProposal(
                              dispatchAttempt,
                              "peer_visible_offer_send_observed",
                              out observedProposal)))
                {
                    duplicateContract = contract;
                }
                else if (!requiresDispatchProof || contract is not null)
                {
                    if (requiresDispatchProof)
                    {
                        state.DispatchDecisionReason = "peer_visible_offer_send_observed";
                        if (!TryCaptureRuntimeUnlockRetryDispatchSettlementReportUnsafe(
                                state,
                                contract!,
                                observedProposal,
                                new RuntimeUnlockRetryDispatchSettlementConsequence(
                                    offerGeneration,
                                    state.RetryReason,
                                    state.RecoveryReason,
                                    state.RequiresLocalListenerRetry,
                                    RequestSuccessor: false,
                                    observedLane),
                                out settlementReport))
                        {
                            duplicateContract = contract;
                        }
                        settledContract = contract;
                    }
                    else
                    {
                        var now = DateTimeOffset.UtcNow;
                        var answerTimeout = AccelerationOfferAnswerTimeoutOverrideForTests ??
                            RuntimeUnlockAccelerationOfferAnswerTimeout;
                        var peerProofDeadline = now.Add(answerTimeout + TimeSpan.FromSeconds(2))
                            .ToUnixTimeMilliseconds();
                        state.RetryDispatched = true;
                        state.RetryDispatching = false;
                        state.CurrentOfferGeneration = offerGeneration;
                        state.RetryAuthorityPending = false;
                        state.RetryAuthorityGranted = true;
                        state.ObservedSendPending = true;
                        state.AuthorizedObservedLane = SanitizeLogToken(observedLane ?? "(none)");
                        state.AuthorityFailureReason = null;
                        state.ObservedSendDeadlineUtcMs = Math.Max(
                            state.ObservedSendDeadlineUtcMs,
                            peerProofDeadline);
                        state.RetryDeadlineUtcMs = Math.Max(state.RetryDeadlineUtcMs, peerProofDeadline);
                        state.LivenessDeferralDeadlineUtcMs = Math.Max(
                            state.LivenessDeferralDeadlineUtcMs,
                            peerProofDeadline);
                        state.ContractState = SessionRecoveryContractState.RetryDispatched;
                    }
                }
                stateSnapshot = state;
            }
        }

        if (staleContract is not null)
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=runtime_unlock_retry_dispatch_stale_callback_ignored; {FormatRuntimeUnlockRetryDispatchAuthorityTuple(staleContract.Authority)}; callback_offer_generation={offerGeneration}; bound_offer_generation={staleContract.OfferGeneration}; callback_kind=observed_send; decision_reason={SanitizeLogToken(staleReason)}");
            return false;
        }

        if (duplicateContract is not null)
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=runtime_unlock_retry_dispatch_duplicate_callback_ignored; {FormatRuntimeUnlockRetryDispatchAuthorityTuple(duplicateContract.Authority)}; callback_offer_generation={offerGeneration}; bound_offer_generation={duplicateContract.OfferGeneration}; callback_kind=observed_send; settled_outcome={SanitizeLogToken(duplicateContract.Lifecycle.SettlementOutcome?.ToString() ?? "(none)")}; decision_reason=dispatch_already_observed_or_settled");
            return false;
        }

        if (rejectedState is not null)
        {
            if (!ConfirmRuntimeUnlockRetryDispatchRejection(
                    rejectedState,
                    rejectedHadDispatchContract,
                    rejectedSettlementReport))
            {
                return false;
            }
            LogRuntimeUnlockRetryDispatchProof(
                "runtime_unlock_retry_dispatch_authority_rejected",
                rejectedState,
                rejectedState.DispatchDecisionReason ?? "missing_runtime_unlock_retry_authority");
            LogRuntimeUnlockRecoveryContract("session_recovery_contract_failed", rejectedState.SessionId);
            return false;
        }

        if (settledContract is not null)
        {
            LogRuntimeUnlockRetryDispatchContractSettled(
                settledContract,
                RuntimeUnlockRetryDispatchSettlementOutcome.DispatchObserved,
                "peer_visible_offer_send_observed");
            if (!PublishRuntimeUnlockRetryDispatchSettlementReport(settlementReport))
            {
                return false;
            }
            if (settledContract.TryMarkDispatchLogged())
            {
                LocalOperationalLog.Info(
                    "NKN.Tuna",
                    $"event=runtime_unlock_retry_dispatch_observed; {FormatRuntimeUnlockRetryDispatchAuthorityTuple(settledContract.Authority)}; offer_generation={settledContract.OfferGeneration}; offer_nonce={SanitizeLogToken(settledContract.OfferNonce ?? "(none)")}; observed_lane={SanitizeLogToken(observedLane ?? "(none)")}; decision_reason=peer_visible_offer_send_observed");
            }
        }

        LogRuntimeUnlockRecoveryContract("session_recovery_contract_retry_authority_observed", stateSnapshot!.SessionId);
        return true;
    }

    private bool TrySettleRuntimeUnlockRetryDispatchMissingIfCurrent(
        string sessionId,
        long offerGeneration,
        string reason)
        => TrySettleRuntimeUnlockRetryDispatchMissingCore(
            sessionId,
            offerGeneration,
            reason,
            requestSuccessor: true);

    private bool TrySettleRuntimeUnlockRetryDispatchMissingCore(
        string sessionId,
        long offerGeneration,
        string reason,
        bool requestSuccessor)
    {
        RuntimeUnlockRetryDispatchContract? settledContract = null;
        RuntimeUnlockRetryDispatchSettlementReport settlementReport = default;
        lock (accelerationGate)
        {
            var state = runtimeUnlockRecoveryRetryState;
            var contract = state?.DispatchContract;
            if (state is null ||
                contract is null ||
                contract.Lifecycle.IsSettled ||
                !string.Equals(state.SessionId, sessionId?.Trim(), StringComparison.Ordinal) ||
                !contract.MatchesOfferAlias(offerGeneration) ||
                !contract.TryGetInFlightAttempt(out var dispatchAttempt) ||
                !contract.TryCreateMissingDispatchSettlementProposal(
                    dispatchAttempt,
                    reason,
                    out var proposal))
            {
                return false;
            }

            state.DispatchDecisionReason = reason;
            if (!TryCaptureRuntimeUnlockRetryDispatchSettlementReportUnsafe(
                    state,
                    contract,
                    proposal,
                    new RuntimeUnlockRetryDispatchSettlementConsequence(
                        offerGeneration,
                        "runtime_unlock_offer_send_not_observed",
                        reason,
                        state.RequiresLocalListenerRetry,
                        requestSuccessor,
                        ObservedLane: null),
                    out settlementReport))
            {
                return false;
            }
            settledContract = contract;
        }

        LogRuntimeUnlockRetryDispatchContractSettled(
            settledContract,
            RuntimeUnlockRetryDispatchSettlementOutcome.MissingDispatch,
            reason);
        return PublishRuntimeUnlockRetryDispatchSettlementReport(settlementReport);
    }

    private bool TrySettleRuntimeUnlockRetryDispatchMissingBeforeOfferIfCurrent(
        string? sessionId,
        string reason,
        string retryReason,
        bool requiresLocalListenerRetry,
        FileTransferAuthorityId? expectedAuthorityId)
    {
        RuntimeUnlockRetryDispatchContract? predecessor = null;
        RuntimeUnlockRetryDispatchSettlementReport settlementReport = default;
        var settledNow = false;
        var normalizedSessionId = string.IsNullOrWhiteSpace(sessionId)
            ? string.Empty
            : sessionId.Trim();
        lock (accelerationGate)
        {
            var state = runtimeUnlockRecoveryRetryState;
            var contract = state?.DispatchContract;
            if (state is not null &&
                expectedAuthorityId is { IsDefault: false } duplicateAuthorityId &&
                string.Equals(state.SessionId, normalizedSessionId, StringComparison.Ordinal) &&
                state.LastAppliedDispatchSettlementReport is { } appliedSettlement &&
                appliedSettlement.Authority.AuthorityId == duplicateAuthorityId &&
                appliedSettlement.Outcome == RuntimeUnlockRetryDispatchSettlementOutcome.MissingDispatch)
            {
                LocalOperationalLog.Info(
                    "NKN.Tuna",
                    $"event=runtime_unlock_retry_dispatch_stale_callback_ignored; authority_schema={FileTransferAuthoritySchema.Current}; authority_id={SanitizeLogToken(duplicateAuthorityId.ToString())}; current_authority_id={SanitizeLogToken(contract?.Authority.AuthorityId.ToString() ?? "(none)")}; stage=before_offer_missing_dispatch; decision_reason=duplicate_missing_dispatch_settlement_after_coordinator_disposition");
                return true;
            }

            if (state is null ||
                contract is null ||
                state.DispatchObserved ||
                state.DispatchAuthorityRejected ||
                state.ContractState is SessionRecoveryContractState.Completed or SessionRecoveryContractState.Failed ||
                !string.Equals(state.SessionId, normalizedSessionId, StringComparison.Ordinal))
            {
                return false;
            }

            if (expectedAuthorityId is not { IsDefault: false } expectedId)
            {
                LocalOperationalLog.Info(
                    "NKN.Tuna",
                    $"event=runtime_unlock_retry_dispatch_stale_callback_ignored; authority_schema={FileTransferAuthoritySchema.Current}; authority_id=(none); current_authority_id={SanitizeLogToken(contract.Authority.AuthorityId.ToString())}; stage=before_offer_missing_dispatch; decision_reason=callback_authority_not_captured");
                return true;
            }

            if (contract.Authority.AuthorityId != expectedId)
            {
                LocalOperationalLog.Info(
                    "NKN.Tuna",
                    $"event=runtime_unlock_retry_dispatch_stale_callback_ignored; authority_schema={FileTransferAuthoritySchema.Current}; authority_id={SanitizeLogToken(expectedId.ToString())}; current_authority_id={SanitizeLogToken(contract.Authority.AuthorityId.ToString())}; stage=before_offer_missing_dispatch; decision_reason=predecessor_callback_after_successor_installation");
                return true;
            }

            if (!contract.Lifecycle.IsSettled)
            {
                settledNow =
                    contract.TryCreatePreOfferMissingDispatchSettlementProposal(
                    reason,
                    out var proposal);
                if (!settledNow)
                {
                    return false;
                }

                if (!TryCaptureRuntimeUnlockRetryDispatchSettlementReportUnsafe(
                        state,
                        contract,
                        proposal,
                        new RuntimeUnlockRetryDispatchSettlementConsequence(
                            contract.OfferGeneration > 0
                                ? contract.OfferGeneration
                                : state.CurrentOfferGeneration > 0
                                    ? state.CurrentOfferGeneration
                                    : state.RetiredOfferGeneration,
                            retryReason,
                            reason,
                            requiresLocalListenerRetry,
                            RequestSuccessor: true,
                            ObservedLane: null),
                        out settlementReport))
                {
                    return false;
                }
            }
            else if (contract.Lifecycle.SettlementOutcome !=
                     RuntimeUnlockRetryDispatchSettlementOutcome.MissingDispatch)
            {
                return false;
            }

            if (settlementReport.IsDefault &&
                !TryCaptureRuntimeUnlockRetryDispatchSettlementReportUnsafe(
                    state,
                    contract,
                    new RuntimeUnlockRetryDispatchSettlementConsequence(
                        contract.OfferGeneration > 0
                            ? contract.OfferGeneration
                            : state.CurrentOfferGeneration > 0
                                ? state.CurrentOfferGeneration
                                : state.RetiredOfferGeneration,
                        retryReason,
                        reason,
                        requiresLocalListenerRetry,
                        RequestSuccessor: true,
                        ObservedLane: null),
                    out settlementReport))
            {
                return false;
            }

            predecessor = contract;
        }

        if (settledNow)
        {
            LogRuntimeUnlockRetryDispatchContractSettled(
                predecessor!,
                RuntimeUnlockRetryDispatchSettlementOutcome.MissingDispatch,
                reason);
        }

        return PublishRuntimeUnlockRetryDispatchSettlementReport(settlementReport);
    }

    internal bool BindRuntimeUnlockRetryDispatchOfferAliasForTests(long offerGeneration, string nonce)
    {
        lock (accelerationGate)
        {
            var contract = runtimeUnlockRecoveryRetryState?.DispatchContract;
            return contract is not null &&
                   contract.TryBindOfferAlias(offerGeneration, nonce);
        }
    }

    internal bool BeginRuntimeUnlockRetryDispatchSendForTests()
    {
        lock (accelerationGate)
        {
            var contract = runtimeUnlockRecoveryRetryState?.DispatchContract;
            return contract is not null &&
                   contract.TryBeginSend(out _);
        }
    }

    private void MarkRuntimeUnlockRegularV4ActivationWindowPeerVisibleIfCurrent(
        string sessionId,
        long offerGeneration,
        string reason)
    {
        RuntimeUnlockRecoveryRetryState? stateSnapshot = null;
        var normalizedSessionId = string.IsNullOrWhiteSpace(sessionId) ? string.Empty : sessionId.Trim();
        if (string.IsNullOrWhiteSpace(normalizedSessionId) || offerGeneration <= 0)
        {
            return;
        }

        lock (accelerationGate)
        {
            var state = runtimeUnlockRecoveryRetryState;
            if (state is null ||
                state.ContractState == SessionRecoveryContractState.Failed ||
                !state.RegularV4ActivationWindowStarted ||
                state.RegularV4ActivationWindowPeerVisible ||
                !string.Equals(state.SessionId, normalizedSessionId, StringComparison.Ordinal) ||
                state.CurrentOfferGeneration != offerGeneration)
            {
                return;
            }

            state.RegularV4ActivationWindowPeerVisible = true;
            state.AuthorityFailureReason = null;
            stateSnapshot = state;
        }

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=runtime_unlock_regular_v4_activation_window_peer_visible; session_id={SanitizeLogToken(stateSnapshot!.SessionId)}; transfer_id={SanitizeLogToken(stateSnapshot.TransferId ?? "(none)")}; contract_generation={stateSnapshot.ContractGeneration}; offer_generation={offerGeneration}; reason={SanitizeLogToken(reason)}");
        LogRuntimeUnlockRecoveryContract("session_recovery_contract_regular_v4_activation_window_peer_visible", stateSnapshot.SessionId);
    }

    private void CompleteRuntimeUnlockRecoveryContractIfActive(string sessionId, string reason)
    {
        RuntimeUnlockRecoveryRetryState? stateSnapshot = null;
        RuntimeUnlockRecoveryRetryState? rejectedState = null;
        RuntimeUnlockRecoveryRetryState? deferredState = null;
        RuntimeUnlockRetryDispatchSettlementReport rejectedSettlementReport = default;
        var rejectedHadDispatchContract = false;
        lock (accelerationGate)
        {
            var state = runtimeUnlockRecoveryRetryState;
            if (state is null ||
                state.ContractState is SessionRecoveryContractState.Completed or SessionRecoveryContractState.Failed ||
                !string.Equals(state.SessionId, sessionId.Trim(), StringComparison.Ordinal))
            {
                return;
            }

            if (ShouldDeferRuntimeUnlockRetryCompletionUntilListenerRearm(state, out var completionDeferReason))
            {
                state.AuthorityFailureReason = completionDeferReason;
                deferredState = state;
                stateSnapshot = state;
            }
            else if (RequiresRuntimeUnlockRetryDispatchProofBeforeCompletion(state) &&
                !state.DispatchObserved)
            {
                rejectedHadDispatchContract = state.DispatchContract is not null;
                _ = MarkRuntimeUnlockRetryDispatchAuthorityRejectedUnsafe(
                    state,
                    "runtime_unlock_retry_dispatch_missing_before_completion",
                    out rejectedSettlementReport);
                rejectedState = state;
                stateSnapshot = state;
            }
            else
            {
                state.RetryObserved = true;
                state.RetryDispatching = false;
                state.RetryDispatched = true;
                state.RetryAuthorityPending = false;
                state.ObservedSendPending = false;
                ClearRuntimeUnlockBrokenStateRetryBudgetUnsafe(sessionId);
                var cutThroughCompleted = state.CutThroughActive && !state.CutThroughCompleted;
                if (cutThroughCompleted)
                {
                    state.CutThroughCompleted = true;
                    state.CutThroughPeerReceived = true;
                }

                state.ContractState = SessionRecoveryContractState.Completed;
                stateSnapshot = state;
            }
        }

        if (deferredState is not null)
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=runtime_unlock_retry_completion_deferred_listener_rearm_pending; session_id={SanitizeLogToken(deferredState.SessionId)}; transfer_id={SanitizeLogToken(deferredState.TransferId ?? "(none)")}; contract_generation={deferredState.ContractGeneration}; offer_generation={(deferredState.CurrentOfferGeneration > 0 ? deferredState.CurrentOfferGeneration : deferredState.RetiredOfferGeneration)}; retry_reason={SanitizeLogToken(deferredState.RetryReason)}; recovery_reason={SanitizeLogToken(deferredState.RecoveryReason)}; completion_reason={SanitizeLogToken(reason)}; decision_reason={SanitizeLogToken(deferredState.AuthorityFailureReason ?? "listener_rearm_required_before_dispatch_completion")}");
            LogRuntimeUnlockRecoveryContract("session_recovery_contract_completion_deferred", deferredState.SessionId);
            return;
        }

        if (rejectedState is not null)
        {
            if (!ConfirmRuntimeUnlockRetryDispatchRejection(
                    rejectedState,
                    rejectedHadDispatchContract,
                    rejectedSettlementReport))
            {
                return;
            }
            LogRuntimeUnlockRetryDispatchProof(
                "runtime_unlock_retry_dispatch_authority_rejected",
                rejectedState,
                rejectedState.DispatchDecisionReason ?? "runtime_unlock_retry_dispatch_missing_before_completion");
            LogRuntimeUnlockRecoveryContract("session_recovery_contract_failed", rejectedState.SessionId);
            return;
        }

        if (stateSnapshot!.CutThroughCompleted)
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=runtime_unlock_cutthrough_completed; session_id={SanitizeLogToken(stateSnapshot.SessionId)}; offer_generation={stateSnapshot.CurrentOfferGeneration}; contract_generation={stateSnapshot.ContractGeneration}; attempt={stateSnapshot.CutThroughAttempt}; reason={SanitizeLogToken(reason)}");
        }

        LogRuntimeUnlockRecoveryContract("session_recovery_contract_completed", stateSnapshot!.SessionId);
    }

    private void MarkRuntimeUnlockRecoveryContractListenerRearmCompleted(
        string sessionId,
        string reason,
        RuntimeUnlockRetryDispatchInstallReceipt? expectedInstallReceipt = null)
    {
        RuntimeUnlockRecoveryRetryState? stateSnapshot = null;
        var retryWasHeldForListenerRearm = false;
        var joinedPendingDispatchSuccessor = false;
        var normalizedSessionId = string.IsNullOrWhiteSpace(sessionId) ? string.Empty : sessionId.Trim();
        if (string.IsNullOrWhiteSpace(normalizedSessionId))
        {
            return;
        }

        lock (accelerationGate)
        {
            var state = runtimeUnlockRecoveryRetryState;
            if (state is null ||
                (!state.RequiresLocalListenerRetry && !state.RetryAuthorityPending) ||
                state.ContractState is SessionRecoveryContractState.Completed or SessionRecoveryContractState.Failed ||
                !string.Equals(state.SessionId, normalizedSessionId, StringComparison.Ordinal))
            {
                return;
            }

            // Keep receipt validation and listener-rearm mutation under one lock
            // boundary so a replaced lifecycle cannot consume an older callback.
            if (!ValidateRuntimeUnlockRetryDispatchInstallReceiptBoundary(
                    expectedInstallReceipt,
                    "listener_rearm_completion_mutation",
                    requireInstalledReceipt: state.DispatchContract is not null))
            {
                return;
            }

            if (state.DispatchContract is { } settledPredecessor &&
                settledPredecessor.Lifecycle.SettlementOutcome ==
                    RuntimeUnlockRetryDispatchSettlementOutcome.MissingDispatch)
            {
                state.ListenerRearmCompleted = true;
                stateSnapshot = state;
                joinedPendingDispatchSuccessor = true;
            }
            else
            {
                var nowMs = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
                retryWasHeldForListenerRearm =
                    state.Settled &&
                    !state.RetryQueued &&
                    !state.RetryDispatching &&
                    !state.RetryDispatched &&
                    string.Equals(
                        state.AuthorityFailureReason,
                        "listener_rearm_required_before_dispatch_authority",
                        StringComparison.Ordinal);
                RefreshRuntimeUnlockRecoveryContractOfferSendWindowUnsafe(state, nowMs);
                state.AuthorityFailureReason = null;
                state.ListenerRearmCompleted = true;
                state.ObservedSendPending = false;
                if (retryWasHeldForListenerRearm)
                {
                    state.RetryQueued = false;
                    state.RetryDispatching = false;
                    state.RetryDispatched = false;
                    state.RetryAuthorityPending = false;
                    state.RetryAuthorityGranted = false;
                    state.ObservedSendDeadlineUtcMs = 0;
                    state.ContractState = SessionRecoveryContractState.RecoverySettled;
                }
                else
                {
                    state.ContractState = state.RetryDispatched
                        ? SessionRecoveryContractState.RetryDispatched
                        : SessionRecoveryContractState.RetryQueued;
                }

                stateSnapshot = state;
            }
        }

        if (joinedPendingDispatchSuccessor)
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=runtime_unlock_retry_settled_predecessor_retry_blocked; session_id={SanitizeLogToken(normalizedSessionId)}; trigger={SanitizeLogToken(reason)}; blocker=listener_rearm_completed; decision_reason=awaiting_coordinator_dispatch_successor");
            LogRuntimeUnlockRecoveryContract(
                "session_recovery_contract_listener_rearm_joined_dispatch_successor",
                stateSnapshot!.SessionId);
            return;
        }

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=session_recovery_contract_listener_rearm_completed; session_id={SanitizeLogToken(normalizedSessionId)}; trigger={SanitizeLogToken(reason)}");
        LogRuntimeUnlockRecoveryContract("session_recovery_contract_listener_rearm_completed", stateSnapshot!.SessionId);
        if (retryWasHeldForListenerRearm)
        {
            ScheduleRuntimeUnlockRetryAfterRecoveryIfArmed(
                "listener_rearm_completed",
                expectedInstallReceipt);
        }

        ScheduleRuntimeUnlockRetryDispatchDeadlineEvaluation(stateSnapshot);
    }

    private void FailRuntimeUnlockRecoveryContractIfActive(string? sessionId, string reason)
    {
        RuntimeUnlockRecoveryRetryState? stateSnapshot = null;
        RuntimeUnlockTransactionDecision? transactionDecision = null;
        RuntimeUnlockRetryDispatchSettlementReport settlementReport = default;
        var normalizedSessionId = string.IsNullOrWhiteSpace(sessionId) ? string.Empty : sessionId.Trim();
        var normalizedReason = SanitizeLogToken(reason);
        lock (accelerationGate)
        {
            var state = runtimeUnlockRecoveryRetryState;
            if (state is null ||
                state.ContractState is SessionRecoveryContractState.Completed or SessionRecoveryContractState.Failed ||
                (!string.IsNullOrWhiteSpace(normalizedSessionId) &&
                 !string.Equals(state.SessionId, normalizedSessionId, StringComparison.Ordinal)))
            {
                return;
            }

            stateSnapshot = state;
            if (state.DispatchContract is not null)
            {
                if (!SettleRuntimeUnlockRetryDispatchContractUnsafe(
                        state,
                        RuntimeUnlockRetryDispatchSettlementOutcome.TerminalRejected,
                        normalizedReason,
                        out settlementReport))
                {
                    return;
                }
            }
            else
            {
                state.RetryDispatching = false;
                state.RetryAuthorityPending = false;
                state.ObservedSendPending = false;
                state.AuthorityFailureReason = normalizedReason;
                state.ContractState = SessionRecoveryContractState.Failed;
                transactionDecision = ApplyRuntimeUnlockTransactionUnsafe(
                    RuntimeUnlockTransactionEventKind.Failed,
                    state.SessionId,
                    state.CurrentOfferGeneration > 0 ? state.CurrentOfferGeneration : state.RetiredOfferGeneration,
                    normalizedReason);
            }
        }

        if (!settlementReport.IsDefault)
        {
            if (!PublishRuntimeUnlockRetryDispatchSettlementReport(settlementReport))
            {
                return;
            }

            lock (accelerationGate)
            {
                if (!ReferenceEquals(runtimeUnlockRecoveryRetryState, stateSnapshot) ||
                    stateSnapshot!.ContractState != SessionRecoveryContractState.Failed ||
                    stateSnapshot.LastAppliedDispatchSettlementReport != settlementReport)
                {
                    return;
                }

                transactionDecision = ApplyRuntimeUnlockTransactionUnsafe(
                    RuntimeUnlockTransactionEventKind.Failed,
                    stateSnapshot.SessionId,
                    stateSnapshot.CurrentOfferGeneration > 0
                        ? stateSnapshot.CurrentOfferGeneration
                        : stateSnapshot.RetiredOfferGeneration,
                    normalizedReason);
            }
        }

        LogRuntimeUnlockTransactionDecision(RuntimeUnlockTransactionEventKind.Failed, transactionDecision);
        LogRuntimeUnlockRecoveryContract("session_recovery_contract_failed", stateSnapshot!.SessionId);
    }

    private bool FailRuntimeUnlockRegularV4ActivationWindowIfUnproven(
        string sessionId,
        long offerGeneration,
        string sourceReason,
        string failureReason)
    {
        if (string.IsNullOrWhiteSpace(sessionId))
        {
            return false;
        }

        var normalizedSessionId = sessionId.Trim();
        var normalizedSourceReason = SanitizeLogToken(sourceReason);
        var normalizedFailureReason = SanitizeLogToken(failureReason);
        RuntimeUnlockRecoveryRetryState? stateSnapshot = null;
        RuntimeUnlockTransactionDecision? transactionDecision = null;
        RuntimeUnlockRetryDispatchSettlementReport settlementReport = default;

        lock (accelerationGate)
        {
            var state = runtimeUnlockRecoveryRetryState;
            if (state is null ||
                !string.Equals(state.SessionId, normalizedSessionId, StringComparison.Ordinal))
            {
                return false;
            }

            if (state.ContractState == SessionRecoveryContractState.Failed)
            {
                return state.RegularV4ActivationWindowStarted &&
                       state.RegularV4ActivationWindowFailed &&
                       !state.RegularV4ActivationWindowPeerVisible;
            }

            if (state.ContractState == SessionRecoveryContractState.Completed ||
                !state.RegularV4ActivationWindowStarted ||
                state.RegularV4ActivationWindowPeerVisible ||
                (offerGeneration > 0 &&
                 state.CurrentOfferGeneration > 0 &&
                 state.CurrentOfferGeneration != offerGeneration))
            {
                return false;
            }

            stateSnapshot = state;
            if (state.DispatchContract is not null)
            {
                if (!SettleRuntimeUnlockRetryDispatchContractUnsafe(
                        state,
                        RuntimeUnlockRetryDispatchSettlementOutcome.TerminalRejected,
                        normalizedFailureReason,
                        out settlementReport))
                {
                    return false;
                }
            }
            else
            {
                state.RegularV4ActivationWindowFailed = true;
                state.RetryQueued = false;
                state.RetryDispatching = false;
                state.RetryAuthorityPending = false;
                state.RetryAuthorityGranted = false;
                state.ObservedSendPending = false;
                state.CutThroughPending = false;
                state.CutThroughActive = false;
                state.AuthorityFailureReason = normalizedFailureReason;
                state.BrokenStateFinalized = true;
                state.BrokenStateFailureReason = normalizedFailureReason;
                state.ContractState = SessionRecoveryContractState.Failed;
                ClearRuntimeUnlockBrokenStateRetryBudgetUnsafe(normalizedSessionId);
                transactionDecision = ApplyRuntimeUnlockTransactionUnsafe(
                    RuntimeUnlockTransactionEventKind.Failed,
                    normalizedSessionId,
                    offerGeneration > 0 ? offerGeneration : state.CurrentOfferGeneration,
                    normalizedFailureReason);
            }
        }

        if (stateSnapshot is null)
        {
            return false;
        }

        if (!settlementReport.IsDefault)
        {
            if (!PublishRuntimeUnlockRetryDispatchSettlementReport(settlementReport))
            {
                return false;
            }

            lock (accelerationGate)
            {
                if (!ReferenceEquals(runtimeUnlockRecoveryRetryState, stateSnapshot) ||
                    stateSnapshot.ContractState != SessionRecoveryContractState.Failed ||
                    stateSnapshot.LastAppliedDispatchSettlementReport != settlementReport)
                {
                    return false;
                }

                stateSnapshot.RegularV4ActivationWindowFailed = true;
                stateSnapshot.CutThroughPending = false;
                stateSnapshot.CutThroughActive = false;
                stateSnapshot.AuthorityFailureReason = normalizedFailureReason;
                stateSnapshot.BrokenStateFinalized = true;
                stateSnapshot.BrokenStateFailureReason = normalizedFailureReason;
                ClearRuntimeUnlockBrokenStateRetryBudgetUnsafe(normalizedSessionId);
                transactionDecision = ApplyRuntimeUnlockTransactionUnsafe(
                    RuntimeUnlockTransactionEventKind.Failed,
                    normalizedSessionId,
                    offerGeneration > 0 ? offerGeneration : stateSnapshot.CurrentOfferGeneration,
                    normalizedFailureReason);
            }
        }

        LocalOperationalLog.Warn(
            "NKN.Tuna",
            $"event=runtime_unlock_regular_v4_activation_window_failed; session_id={SanitizeLogToken(stateSnapshot.SessionId)}; transfer_id={SanitizeLogToken(stateSnapshot.TransferId ?? "(none)")}; contract_generation={stateSnapshot.ContractGeneration}; offer_generation={(offerGeneration > 0 ? offerGeneration : stateSnapshot.CurrentOfferGeneration)}; reason={normalizedFailureReason}; source_reason={normalizedSourceReason}; peer_visible=0; retry_scheduled=0; retry_after_recovery_armed=0");
        LogRuntimeUnlockTransactionDecision(RuntimeUnlockTransactionEventKind.Failed, transactionDecision);
        LogRuntimeUnlockRecoveryContract("session_recovery_contract_failed", stateSnapshot.SessionId);
        TryResumeFileTransferDataSessionsAfterTunaActivationNegotiation(
            "runtime_unlock_regular_v4_activation_window_failed",
            stateSnapshot.SessionId,
            normalizedFailureReason);
        NotifyTransportAccelerationStateChanged("runtime_unlock_regular_v4_activation_window_failed");
        return true;
    }

    private bool TryConsumeRuntimeUnlockBrokenStateRetryBudget(string normalizedReason)
    {
        if (!IsRuntimeUnlockBrokenStateRetryReason(normalizedReason))
        {
            return true;
        }

        RuntimeUnlockRecoveryRetryState? consumedState = null;
        RuntimeUnlockRecoveryRetryState? suppressedState = null;
        RuntimeUnlockRecoveryRetryState? peerVisibleWindowDeferredState = null;
        RuntimeUnlockTransactionDecision? suppressedDecision = null;
        RuntimeUnlockRetryDispatchSettlementReport suppressedSettlementReport = default;
        string? regularV4WindowFailureReason = null;
        long peerVisibleWindowDeadlineRemainingMs = 0;
        var family = GetRuntimeUnlockBrokenStateRetryFamily(normalizedReason);
        var failureReason = $"runtime_unlock_broken_state_retry_exhausted_{family}";
        var nowMs = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();

        lock (accelerationGate)
        {
            var state = runtimeUnlockRecoveryRetryState;
            if (state is null ||
                state.ContractState is SessionRecoveryContractState.Completed or SessionRecoveryContractState.Failed)
            {
                return true;
            }

            var budgetExpired = runtimeUnlockBrokenStateRetryBudgetStartedUtcMs <= 0 ||
                nowMs - runtimeUnlockBrokenStateRetryBudgetStartedUtcMs >
                    (long)RuntimeUnlockBrokenStateRetryBudgetTtl.TotalMilliseconds;
            if (budgetExpired ||
                !string.Equals(runtimeUnlockBrokenStateRetryBudgetSessionId, state.SessionId, StringComparison.Ordinal) ||
                !string.Equals(runtimeUnlockBrokenStateRetryBudgetFamily, family, StringComparison.Ordinal))
            {
                runtimeUnlockBrokenStateRetryBudgetSessionId = state.SessionId;
                runtimeUnlockBrokenStateRetryBudgetFamily = family;
                runtimeUnlockBrokenStateRetryBudgetStartedUtcMs = nowMs;
                runtimeUnlockBrokenStateFreshRetriesUsed = 0;
            }

            if (state.RegularV4ActivationWindowStarted &&
                !state.RegularV4ActivationWindowPeerVisible &&
                !state.RegularV4ActivationWindowFailed &&
                state.ObservedSendPending &&
                state.ObservedSendDeadlineUtcMs > nowMs)
            {
                peerVisibleWindowDeferredState = state;
                peerVisibleWindowDeadlineRemainingMs = state.ObservedSendDeadlineUtcMs - nowMs;
            }
            else
            if (runtimeUnlockBrokenStateFreshRetriesUsed >= RuntimeUnlockBrokenStateMaxFreshRetries)
            {
                if (state.RegularV4ActivationWindowStarted && !state.RegularV4ActivationWindowPeerVisible)
                {
                    failureReason = "runtime_unlock_regular_v4_peer_visible_window_failed";
                    regularV4WindowFailureReason = failureReason;
                }

                suppressedState = state;
                if (state.DispatchContract is not null)
                {
                    if (!SettleRuntimeUnlockRetryDispatchContractUnsafe(
                            state,
                            RuntimeUnlockRetryDispatchSettlementOutcome.TerminalRejected,
                            failureReason,
                            out suppressedSettlementReport))
                    {
                        return false;
                    }
                }
                else
                {
                    state.RegularV4ActivationWindowFailed =
                        regularV4WindowFailureReason is not null;
                    state.RetryQueued = false;
                    state.RetryDispatching = false;
                    state.RetryAuthorityPending = false;
                    state.RetryAuthorityGranted = false;
                    state.ObservedSendPending = false;
                    state.AuthorityFailureReason = failureReason;
                    state.BrokenStateFinalized = true;
                    state.BrokenStateFailureReason = failureReason;
                    state.ContractState = SessionRecoveryContractState.Failed;
                    suppressedDecision = ApplyRuntimeUnlockTransactionUnsafe(
                        RuntimeUnlockTransactionEventKind.Failed,
                        state.SessionId,
                        state.CurrentOfferGeneration > 0 ? state.CurrentOfferGeneration : state.RetiredOfferGeneration,
                        failureReason);
                }
            }
            else
            {
                runtimeUnlockBrokenStateFreshRetriesUsed++;
                state.BrokenStateFreshRetryAttempt = runtimeUnlockBrokenStateFreshRetriesUsed;
                consumedState = state;
            }
        }

        if (peerVisibleWindowDeferredState is not null)
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=runtime_unlock_broken_state_retry_deferred_for_peer_visible_window; session_id={SanitizeLogToken(peerVisibleWindowDeferredState.SessionId)}; transfer_id={SanitizeLogToken(peerVisibleWindowDeferredState.TransferId ?? "(none)")}; contract_generation={peerVisibleWindowDeferredState.ContractGeneration}; offer_generation={(peerVisibleWindowDeferredState.CurrentOfferGeneration > 0 ? peerVisibleWindowDeferredState.CurrentOfferGeneration : peerVisibleWindowDeferredState.RetiredOfferGeneration)}; reason={SanitizeLogToken(normalizedReason)}; family={SanitizeLogToken(family)}; deadline_remaining_ms={peerVisibleWindowDeadlineRemainingMs}; fresh_retry_attempts={runtimeUnlockBrokenStateFreshRetriesUsed}; max_fresh_retries={RuntimeUnlockBrokenStateMaxFreshRetries}; deferred=1");
            LogRuntimeUnlockRecoveryContract(
                "session_recovery_contract_peer_visible_window_retry_deferred",
                peerVisibleWindowDeferredState.SessionId);
            return false;
        }

        if (suppressedState is not null)
        {
            if (!suppressedSettlementReport.IsDefault)
            {
                if (!PublishRuntimeUnlockRetryDispatchSettlementReport(suppressedSettlementReport))
                {
                    return false;
                }

                lock (accelerationGate)
                {
                    if (!ReferenceEquals(runtimeUnlockRecoveryRetryState, suppressedState) ||
                        suppressedState.ContractState != SessionRecoveryContractState.Failed ||
                        suppressedState.LastAppliedDispatchSettlementReport !=
                            suppressedSettlementReport)
                    {
                        return false;
                    }

                    suppressedState.RegularV4ActivationWindowFailed =
                        regularV4WindowFailureReason is not null;
                    suppressedState.AuthorityFailureReason = failureReason;
                    suppressedState.BrokenStateFinalized = true;
                    suppressedState.BrokenStateFailureReason = failureReason;
                    suppressedDecision = ApplyRuntimeUnlockTransactionUnsafe(
                        RuntimeUnlockTransactionEventKind.Failed,
                        suppressedState.SessionId,
                        suppressedState.CurrentOfferGeneration > 0
                            ? suppressedState.CurrentOfferGeneration
                            : suppressedState.RetiredOfferGeneration,
                        failureReason);
                }
            }

            LocalOperationalLog.Warn(
                "NKN.Tuna",
                $"event=runtime_unlock_broken_state_retry_suppressed; session_id={SanitizeLogToken(suppressedState.SessionId)}; transfer_id={SanitizeLogToken(suppressedState.TransferId ?? "(none)")}; contract_generation={suppressedState.ContractGeneration}; offer_generation={(suppressedState.CurrentOfferGeneration > 0 ? suppressedState.CurrentOfferGeneration : suppressedState.RetiredOfferGeneration)}; reason={SanitizeLogToken(normalizedReason)}; family={SanitizeLogToken(family)}; fresh_retry_attempts={runtimeUnlockBrokenStateFreshRetriesUsed}; max_fresh_retries={RuntimeUnlockBrokenStateMaxFreshRetries}; final_reason={SanitizeLogToken(failureReason)}");
            LogRuntimeUnlockTransactionDecision(RuntimeUnlockTransactionEventKind.Failed, suppressedDecision);
            LogRuntimeUnlockRecoveryContract("session_recovery_contract_failed", suppressedState.SessionId);
            if (regularV4WindowFailureReason is not null)
            {
                LocalOperationalLog.Warn(
                    "NKN.Tuna",
                    $"event=runtime_unlock_regular_v4_activation_window_failed; session_id={SanitizeLogToken(suppressedState.SessionId)}; transfer_id={SanitizeLogToken(suppressedState.TransferId ?? "(none)")}; contract_generation={suppressedState.ContractGeneration}; offer_generation={(suppressedState.CurrentOfferGeneration > 0 ? suppressedState.CurrentOfferGeneration : suppressedState.RetiredOfferGeneration)}; reason={SanitizeLogToken(regularV4WindowFailureReason)}; original_reason={SanitizeLogToken(normalizedReason)}");
            }

            TryResumeFileTransferDataSessionsAfterTunaActivationNegotiation(
                "runtime_unlock_broken_state_retry_exhausted",
                suppressedState.SessionId,
                failureReason);
            return false;
        }

        if (consumedState is not null)
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=runtime_unlock_broken_state_fresh_retry_consumed; session_id={SanitizeLogToken(consumedState.SessionId)}; transfer_id={SanitizeLogToken(consumedState.TransferId ?? "(none)")}; contract_generation={consumedState.ContractGeneration}; offer_generation={(consumedState.CurrentOfferGeneration > 0 ? consumedState.CurrentOfferGeneration : consumedState.RetiredOfferGeneration)}; reason={SanitizeLogToken(normalizedReason)}; family={SanitizeLogToken(family)}; fresh_retry_attempt={consumedState.BrokenStateFreshRetryAttempt}; max_fresh_retries={RuntimeUnlockBrokenStateMaxFreshRetries}");
        }

        return true;
    }

    private bool TryConsumeRuntimeUnlockBrokenStateRetryBudgetForOfferDispatch(
        string activationReason,
        out string retryReason)
    {
        retryReason = SanitizeLogToken(activationReason);
        if (!IsRuntimeUnlockBrokenStateRetryReason(retryReason))
        {
            var currentSessionId = currentSessionSecurityState.SessionId?.Value;
            lock (accelerationGate)
            {
                var state = runtimeUnlockRecoveryRetryState;
                if (state is not null &&
                    state.ContractState is not (SessionRecoveryContractState.Completed or SessionRecoveryContractState.Failed) &&
                    !state.RetryObserved &&
                    HasRuntimeUnlockRetryDispatchLineageUnsafe(state) &&
                    (string.IsNullOrWhiteSpace(currentSessionId) ||
                     string.Equals(state.SessionId, currentSessionId.Trim(), StringComparison.Ordinal)))
                {
                    retryReason = SanitizeLogToken(state.RetryReason);
                }
            }
        }

        return TryConsumeRuntimeUnlockBrokenStateRetryBudget(retryReason);
    }

    private void ClearRuntimeUnlockBrokenStateRetryBudgetUnsafe(string? sessionId)
    {
        if (!string.IsNullOrWhiteSpace(sessionId) &&
            !string.IsNullOrWhiteSpace(runtimeUnlockBrokenStateRetryBudgetSessionId) &&
            !string.Equals(runtimeUnlockBrokenStateRetryBudgetSessionId, sessionId.Trim(), StringComparison.Ordinal))
        {
            return;
        }

        runtimeUnlockBrokenStateRetryBudgetSessionId = null;
        runtimeUnlockBrokenStateRetryBudgetFamily = null;
        runtimeUnlockBrokenStateRetryBudgetStartedUtcMs = 0;
        runtimeUnlockBrokenStateFreshRetriesUsed = 0;
    }

    private static bool IsRuntimeUnlockBrokenStateRetryReason(string normalizedReason)
        => normalizedReason is
            "runtime_unlock_offer_send_not_observed" or
            "runtime_unlock_offer_peer_response_timeout" or
            "runtime_unlock_offer_answer_timeout" or
            "runtime_unlock_answer_ack_timeout" or
            "runtime_unlock_sidecar_unavailable" or
            "runtime_unlock_listener_sidecar_unavailable" or
            "runtime_unlock_tuna_dial_failed" or
            RuntimeUnlockProbeSidecarClosedRetryReason or
            "runtime_unlock_sidecar_remote_closed" or
            "runtime_unlock_remote_sidecar_remote_closed";

    private static string GetRuntimeUnlockBrokenStateRetryFamily(string normalizedReason)
        => normalizedReason switch
        {
            "runtime_unlock_sidecar_unavailable" or
            "runtime_unlock_listener_sidecar_unavailable" or
            "runtime_unlock_tuna_dial_failed" or
            RuntimeUnlockProbeSidecarClosedRetryReason or
            "runtime_unlock_sidecar_remote_closed" or
            "runtime_unlock_remote_sidecar_remote_closed" => "listener_or_dialer_unavailable",
            "runtime_unlock_offer_answer_timeout" or
            "runtime_unlock_answer_ack_timeout" => "offer_answer_untrusted",
            "runtime_unlock_offer_peer_response_timeout" => "offer_peer_response_not_received",
            _ => "offer_send_not_observed",
        };

    private bool ShouldSuppressRuntimeUnlockRetryAfterTerminalTransactionFailure(string normalizedReason)
    {
        if (!IsRuntimeUnlockBrokenStateRetryReason(normalizedReason))
        {
            return false;
        }

        lock (accelerationGate)
        {
            if (runtimeUnlockRecoveryRetryState is
                {
                    ContractState: SessionRecoveryContractState.Failed,
                    RegularV4ActivationWindowStarted: true,
                    RegularV4ActivationWindowFailed: true,
                    RegularV4ActivationWindowPeerVisible: false,
                } failedRegularV4WindowState)
            {
                var contractFailureReason = SanitizeLogToken(
                    failedRegularV4WindowState.BrokenStateFailureReason ??
                    failedRegularV4WindowState.AuthorityFailureReason);
                if (contractFailureReason.Contains(
                        "regular_v4_recovery_window",
                        StringComparison.OrdinalIgnoreCase) ||
                    contractFailureReason.Contains(
                        "regular_v4_peer_visible_window",
                        StringComparison.OrdinalIgnoreCase))
                {
                    return true;
                }
            }

            if (!runtimeUnlockTransactionState.IsTerminal ||
                runtimeUnlockTransactionState.State != RuntimeUnlockTransactionState.Failed)
            {
                return false;
            }

            var failureReason = SanitizeLogToken(runtimeUnlockTransactionState.FailureReason);
            if (string.IsNullOrWhiteSpace(failureReason) ||
                string.Equals(failureReason, "(none)", StringComparison.Ordinal))
            {
                return false;
            }

            if (normalizedReason is
                "runtime_unlock_sidecar_unavailable" or
                "runtime_unlock_listener_sidecar_unavailable" or
                "runtime_unlock_sidecar_remote_closed" or
                "runtime_unlock_remote_sidecar_remote_closed")
            {
                return failureReason.Contains("sidecar", StringComparison.OrdinalIgnoreCase) ||
                       failureReason.Contains("listener", StringComparison.OrdinalIgnoreCase) ||
                       failureReason.Contains("dialer", StringComparison.OrdinalIgnoreCase) ||
                       failureReason.Contains("lease", StringComparison.OrdinalIgnoreCase);
            }

            return failureReason.Contains("runtime_unlock_broken_state", StringComparison.OrdinalIgnoreCase) ||
                   failureReason.Contains("regular_v4_recovery_window", StringComparison.OrdinalIgnoreCase) ||
                   failureReason.Contains("regular_v4_peer_visible_window", StringComparison.OrdinalIgnoreCase) ||
                   failureReason.Contains("path_probe", StringComparison.OrdinalIgnoreCase) ||
                   failureReason.Contains("precommit_probe", StringComparison.OrdinalIgnoreCase);
        }
    }

    private void MarkRuntimeUnlockOfferAnswerTimeoutScheduledIfCurrent(
        string nonce,
        long payerDecisionId,
        long generation)
    {
        lock (accelerationGate)
        {
            var state = runtimeUnlockOfferProofState;
            if (state is null ||
                state.Retired ||
                state.Generation != generation ||
                state.PayerDecisionId != payerDecisionId ||
                !string.Equals(state.Nonce, nonce, StringComparison.Ordinal))
            {
                return;
            }

            state.AnswerTimeoutScheduled = true;
        }
    }

    private bool RetireRuntimeUnlockOfferIfCurrent(
        string nonce,
        long payerDecisionId,
        long generation,
        string sessionId,
        string reason,
        string retryReason)
    {
        lock (accelerationGate)
        {
            if (outboundAccelerationOfferGeneration != generation ||
                outboundAccelerationOfferPayerDecisionId != payerDecisionId ||
                !string.Equals(outboundAccelerationOfferNonce, nonce, StringComparison.Ordinal))
            {
                return false;
            }

            var state = runtimeUnlockOfferProofState;
            if (state is not null &&
                state.Generation == generation &&
                state.PayerDecisionId == payerDecisionId &&
                string.Equals(state.Nonce, nonce, StringComparison.Ordinal))
            {
                state.Retired = true;
                state.RetiredReason = SanitizeLogToken(reason);
                state.RetryReason = SanitizeLogToken(retryReason);
            }

            RetireOutboundAccelerationOfferLocked(sessionId, reason);
        }

        return true;
    }

    private bool IsRuntimeUnlockOfferGenerationRetired(
        string nonce,
        long payerDecisionId,
        long generation)
    {
        lock (accelerationGate)
        {
            var state = runtimeUnlockOfferProofState;
            return state is not null &&
                   state.Retired &&
                   state.Generation == generation &&
                   state.PayerDecisionId == payerDecisionId &&
                   string.Equals(state.Nonce, nonce, StringComparison.Ordinal);
        }
    }

    private bool InterruptRuntimeUnlockOfferForBridgeRecovery(
        string reason,
        string recoveryReason,
        string trigger)
        => InterruptRuntimeUnlockOfferCriticalSection(
            reason,
            recoveryReason,
            trigger,
            observedLane: null,
            queueLane: null,
            queueClears: 0,
            clearedSinceLast: 0);

    private void HandleRuntimeUnlockOfferQueueCleared(BridgeLifecycleEvent e)
    {
        var lane = string.IsNullOrWhiteSpace(e.QueueLane) ? "unknown" : e.QueueLane.Trim();
        InterruptRuntimeUnlockOfferCriticalSection(
            "offer_interrupted_by_queue_clear",
            $"{SanitizeLogToken(lane)}_queue_cleared",
            "bridge_queue_cleared",
            observedLane: null,
            queueLane: lane,
            queueClears: e.QueueClears,
            clearedSinceLast: e.ClearedSinceLast);
    }

    private bool InterruptRuntimeUnlockOfferCriticalSection(
        string reason,
        string recoveryReason,
        string trigger,
        string? observedLane,
        string? queueLane,
        long queueClears,
        long clearedSinceLast)
    {
        RuntimeUnlockOfferProofState? interruptedState = null;
        RuntimeUnlockOfferAuthorityBoundary? interruptedAuthorityBoundary =
            null;
        lock (accelerationGate)
        {
            var state = runtimeUnlockOfferProofState;
            if (state is null ||
                state.Retired ||
                state.PeerReceived ||
                IsAccelerationNegotiatedAndHealthyUnsafe(state.SessionId) ||
                outboundAccelerationOfferGeneration != state.Generation ||
                outboundAccelerationOfferPayerDecisionId != state.PayerDecisionId ||
                string.IsNullOrWhiteSpace(outboundAccelerationOfferNonce) ||
                !string.Equals(
                    outboundAccelerationOfferNonce,
                    state.Nonce,
                    StringComparison.Ordinal) ||
                !TryGetCurrentRuntimeUnlockOfferAuthorityBoundaryUnsafe(
                    out _,
                    out var currentAuthorityBoundary) ||
                currentAuthorityBoundary is null ||
                !IsRuntimeUnlockOfferAuthorityBoundaryCurrentUnsafe(
                    currentAuthorityBoundary,
                    allowDispatchObservedSettlement: true))
            {
                return false;
            }

            if (ShouldPreserveRuntimeUnlockOfferAcrossBridgeInterruptionUnsafe(state, queueLane))
            {
                LogRuntimeUnlockObservedOfferPreservedDuringBridgeInterruption(
                    state,
                    reason,
                    recoveryReason,
                    trigger,
                    observedLane,
                    queueLane,
                    queueClears,
                    clearedSinceLast);
                return false;
            }

            if (ShouldPreserveRuntimeUnlockOfferForAtomicPeerVisibleWindowUnsafe(state))
            {
                LogRuntimeUnlockOfferPreservedForAtomicPeerVisibleWindow(
                    state,
                    reason,
                    recoveryReason,
                    trigger,
                    observedLane,
                    queueLane,
                    queueClears,
                    clearedSinceLast);
                return false;
            }

            state.Retired = true;
            state.RetiredReason = SanitizeLogToken(reason);
            state.RetryReason = "runtime_unlock_offer_send_not_observed";
            interruptedState = state;
            interruptedAuthorityBoundary = currentAuthorityBoundary;
            RetireOutboundAccelerationOfferLocked(state.SessionId, reason);
        }

        if (interruptedState is null ||
            interruptedAuthorityBoundary is null)
        {
            return false;
        }

        var installedRetry =
            interruptedAuthorityBoundary.Mode ==
            RuntimeUnlockOfferAuthorityMode.InstalledRetry;
        var retryAfterRecoveryArmed = false;
        var initialRetryScheduled = false;
        if (installedRetry)
        {
            lock (accelerationGate)
            {
                retryAfterRecoveryArmed =
                    TryGetRetainedInstalledRuntimeUnlockOfferAuthorityUnsafe(
                        interruptedAuthorityBoundary,
                        out _);
            }
        }
        else
        {
            initialRetryScheduled = ScheduleRuntimeUnlockOfferAuthorityRetry(
                "runtime_unlock_offer_send_not_observed",
                interruptedAuthorityBoundary,
                expectedInstallReceipt: null);
        }
        if (retryAfterRecoveryArmed &&
            string.Equals(
                reason,
                "offer_interrupted_by_bridge_recovery",
                StringComparison.Ordinal))
        {
            MarkFileTransferTunaActivationBridgeRecoveryStarted(
                recoveryReason,
                interruptedAuthorityBoundary);
        }

        LocalOperationalLog.Warn(
            "NKN.Tuna",
            $"event=tuna_acceleration_activation_offer_not_observed; trigger={SanitizeLogToken(interruptedState.Trigger)}; session_id={SanitizeLogToken(interruptedState.SessionId)}; payer_decision_id={interruptedState.PayerDecisionId}; generation={interruptedState.Generation}; authority_mode={SanitizeLogToken(interruptedAuthorityBoundary.Mode.ToString())}; late_answer_window_ms={(long)AccelerationOfferAnswerTimeout.TotalMilliseconds}; retry_scheduled={(initialRetryScheduled ? 1 : 0)}; retry_after_recovery_armed={(retryAfterRecoveryArmed ? 1 : 0)}; replay_scheduled=0; answer_timeout_scheduled=0; pause_deferred=1; recovery_requested={(installedRetry ? 1 : 0)}; recovery_reason={SanitizeLogToken(recoveryReason)}; interruption_reason={SanitizeLogToken(reason)}; interruption_trigger={SanitizeLogToken(trigger)}; observed_send={(interruptedState.ObservedSend ? 1 : 0)}; observed_lane={SanitizeLogToken(observedLane ?? interruptedState.ObservedSendLane)}; queue_lane={SanitizeLogToken(queueLane)}; queue_clears={Math.Max(0, queueClears)}; cleared_since_last={Math.Max(0, clearedSinceLast)}");
        NotifyTransportAccelerationStateChanged("activation_offer_not_observed");
        TryResumeFileTransferDataSessionsAfterTunaActivationNegotiation(
            "tuna_activation_failed_regular_v4_resumed",
            interruptedState.SessionId,
            reason);
        if (retryAfterRecoveryArmed)
        {
            ArmRuntimeUnlockRetryAfterRecovery(
                interruptedState.Generation,
                interruptedState.SessionId,
                "runtime_unlock_offer_send_not_observed",
                recoveryReason,
                requiresLocalListenerRetry: true,
                RuntimeUnlockRetryDispatchListenerRearmRequirement.Required,
                interruptedAuthorityBoundary);
        }
        return true;
    }

    private bool ShouldPreserveRuntimeUnlockOfferAcrossBridgeInterruptionUnsafe(
        RuntimeUnlockOfferProofState state,
        string? queueLane)
        => state.ObservedSend &&
           state.AnswerTimeoutScheduled &&
           !string.IsNullOrWhiteSpace(state.ObservedSendLane);

    private bool ShouldPreserveRuntimeUnlockOfferForAtomicPeerVisibleWindowUnsafe(
        RuntimeUnlockOfferProofState offer)
    {
        var state = runtimeUnlockRecoveryRetryState;
        if (state is null ||
            state.ContractState is SessionRecoveryContractState.Completed or SessionRecoveryContractState.Failed ||
            !state.RegularV4ActivationWindowStarted ||
            state.RegularV4ActivationWindowPeerVisible ||
            state.RegularV4ActivationWindowFailed ||
            !state.RetryAuthorityGranted ||
            !state.RetryAuthorityPending ||
            !state.ObservedSendPending ||
            state.CurrentOfferGeneration != offer.Generation ||
            !string.Equals(state.SessionId, offer.SessionId, StringComparison.Ordinal))
        {
            return false;
        }

        var nowMs = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
        return state.ObservedSendDeadlineUtcMs <= 0 || state.ObservedSendDeadlineUtcMs > nowMs;
    }

    private void LogRuntimeUnlockObservedOfferPreservedDuringBridgeInterruption(
        RuntimeUnlockOfferProofState state,
        string reason,
        string recoveryReason,
        string trigger,
        string? observedLane,
        string? queueLane,
        long queueClears,
        long clearedSinceLast)
    {
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=tuna_acceleration_runtime_unlock_observed_offer_preserved; trigger={SanitizeLogToken(state.Trigger)}; session_id={SanitizeLogToken(state.SessionId)}; payer_decision_id={state.PayerDecisionId}; generation={state.Generation}; interruption_reason={SanitizeLogToken(reason)}; interruption_trigger={SanitizeLogToken(trigger)}; recovery_reason={SanitizeLogToken(recoveryReason)}; observed_send={(state.ObservedSend ? 1 : 0)}; observed_lane={SanitizeLogToken(observedLane ?? state.ObservedSendLane)}; peer_received={(state.PeerReceived ? 1 : 0)}; queue_lane={SanitizeLogToken(queueLane)}; queue_clears={Math.Max(0, queueClears)}; cleared_since_last={Math.Max(0, clearedSinceLast)}");
    }

    private void LogRuntimeUnlockOfferPreservedForAtomicPeerVisibleWindow(
