            recoveryReason,
            requiresLocalListenerRetry,
            requiresLocalListenerRetry
                ? RuntimeUnlockRetryDispatchListenerRearmRequirement.Required
                : RuntimeUnlockRetryDispatchListenerRearmRequirement.None);

    private void ArmRuntimeUnlockRetryAfterRecovery(
        long retiredOfferGeneration,
        string sessionId,
        string retryReason,
        string recoveryReason,
        bool requiresLocalListenerRetry,
        RuntimeUnlockRetryDispatchListenerRearmRequirement
            listenerRearmRequirement)
        => ArmRuntimeUnlockRetryAfterRecovery(
            retiredOfferGeneration,
            sessionId,
            retryReason,
            recoveryReason,
            requiresLocalListenerRetry,
            listenerRearmRequirement,
            expectedOfferAuthorityBoundary: null);

    private void ArmRuntimeUnlockRetryAfterRecovery(
        long retiredOfferGeneration,
        string sessionId,
        string retryReason,
        string recoveryReason,
        bool requiresLocalListenerRetry,
        RuntimeUnlockRetryDispatchListenerRearmRequirement
            listenerRearmRequirement,
        RuntimeUnlockOfferAuthorityBoundary?
            expectedOfferAuthorityBoundary)
    {
        var normalizedSessionId = string.IsNullOrWhiteSpace(sessionId)
            ? currentSessionSecurityState.SessionId?.Value ?? string.Empty
            : sessionId.Trim();
        if (string.IsNullOrWhiteSpace(normalizedSessionId))
        {
            ScheduleRuntimeUnlockAccelerationNegotiationRetry(retryReason);
            return;
        }

        if (expectedOfferAuthorityBoundary is { } expectedBoundary)
        {
            lock (accelerationGate)
            {
                if (!TryGetRetainedInstalledRuntimeUnlockOfferAuthorityUnsafe(
                        expectedBoundary,
                        out _))
                {
                    LogRuntimeUnlockOfferAuthorityBoundaryDecision(
                        expectedBoundary,
                        "arm_retry_after_recovery_entry",
                        accepted: false,
                        "installed_retry_offer_authority_not_retained");
                    return;
                }
            }
        }

        FileTransferRoutePublicationAuthority? sourcePublicationAuthority = null;
        var sourceDataSessionGeneration = 0L;
        _ = TryCaptureCurrentRuntimeUnlockFileTransferOwnerAndDataSession(
            normalizedSessionId,
            out sourcePublicationAuthority,
            out sourceDataSessionGeneration,
            out _);
        var transferId = sourcePublicationAuthority?.TransferId;

        RuntimeUnlockRecoveryRetryState? preservedCutThroughState = null;
        RuntimeUnlockRecoveryRetryState? preservedDispatchState = null;
        RuntimeUnlockRetryDispatchSuccessorEvaluation? preservedDispatchEvaluation = null;
        lock (accelerationGate)
        {
            if (expectedOfferAuthorityBoundary is { } commitBoundary &&
                !TryGetRetainedInstalledRuntimeUnlockOfferAuthorityUnsafe(
                    commitBoundary,
                    out _))
            {
                LogRuntimeUnlockOfferAuthorityBoundaryDecision(
                    commitBoundary,
                    "arm_retry_after_recovery_commit",
                    accepted: false,
                    "installed_retry_offer_authority_not_retained");
                return;
            }

            var now = DateTimeOffset.UtcNow;
            var nowMs = now.ToUnixTimeMilliseconds();
            var cutThroughReason =
                string.Equals(
                    SanitizeLogToken(retryReason),
                    RuntimeUnlockCutThroughRetryReason,
                    StringComparison.Ordinal) ||
                string.Equals(
                    SanitizeLogToken(recoveryReason),
                    RuntimeUnlockCutThroughRecoveryReason,
                    StringComparison.Ordinal);
            var regularV4CutThroughCandidate =
                IsActiveRegularV4FileTransferRouteHint(normalizedSessionId, transferId) ||
                HasActiveRegularV4FileTransferRouteHint(normalizedSessionId) ||
                (cutThroughReason &&
                 !string.IsNullOrWhiteSpace(transferId) &&
                 !HasActivePostTunaFallbackFileTransferRouteHint(normalizedSessionId) &&
                 !TryGetUnresolvedFileTransferV6TransportEpochForCurrentSession(out _));
            var cutThroughPending = regularV4CutThroughCandidate && cutThroughReason;
            var previousCutThroughAttempt = 0;
            if (cutThroughPending &&
                runtimeUnlockRecoveryRetryState is { } existingCutThroughState &&
                string.Equals(existingCutThroughState.SessionId, normalizedSessionId, StringComparison.Ordinal) &&
                existingCutThroughState.ContractState is not SessionRecoveryContractState.Completed and not SessionRecoveryContractState.Failed &&
                (existingCutThroughState.CutThroughPending ||
                 existingCutThroughState.CutThroughActive ||
                 string.Equals(existingCutThroughState.RetryReason, RuntimeUnlockCutThroughRetryReason, StringComparison.Ordinal) ||
                 string.Equals(existingCutThroughState.RecoveryReason, RuntimeUnlockCutThroughRecoveryReason, StringComparison.Ordinal)))
            {
                previousCutThroughAttempt = Math.Max(0, existingCutThroughState.CutThroughAttempt);
            }

            if (!cutThroughPending &&
                runtimeUnlockRecoveryRetryState is { } existingState &&
                existingState.RetiredOfferGeneration == retiredOfferGeneration &&
                string.Equals(existingState.SessionId, normalizedSessionId, StringComparison.Ordinal) &&
                (existingState.CutThroughPending ||
                 existingState.CutThroughActive ||
                 string.Equals(existingState.RetryReason, RuntimeUnlockCutThroughRetryReason, StringComparison.Ordinal) ||
                 string.Equals(existingState.RecoveryReason, RuntimeUnlockCutThroughRecoveryReason, StringComparison.Ordinal)) &&
                existingState.ContractState is not SessionRecoveryContractState.Completed and not SessionRecoveryContractState.Failed)
            {
                preservedCutThroughState = existingState;
            }
            else if (runtimeUnlockRecoveryRetryState is { } activeDispatchState &&
                     string.Equals(activeDispatchState.SessionId, normalizedSessionId, StringComparison.Ordinal) &&
                     activeDispatchState.ContractState is not SessionRecoveryContractState.Completed and not SessionRecoveryContractState.Failed &&
                     activeDispatchState.DispatchContract is { Lifecycle.IsSettled: false } activeContract)
            {
                preservedDispatchEvaluation =
                    new RuntimeUnlockRetryDispatchSuccessorEvaluation(
                        activeContract.Authority,
                        retiredOfferGeneration);

                preservedDispatchState = activeDispatchState;
            }
            else
            {
                var contractGeneration = ++runtimeUnlockRecoveryContractNextGeneration;
                var newState = new RuntimeUnlockRecoveryRetryState
                {
                    ContractGeneration = contractGeneration,
                    RetiredOfferGeneration = retiredOfferGeneration,
                    SessionId = normalizedSessionId,
                    TransferId = transferId,
                    RetryReason = SanitizeLogToken(retryReason),
                    RecoveryReason = SanitizeLogToken(recoveryReason),
                    CreatedUtcMs = nowMs,
                    RetryDeadlineUtcMs = now
                        .Add(RuntimeUnlockRecoveryContractRetryDeadline)
                        .ToUnixTimeMilliseconds(),
                    LivenessDeferralDeadlineUtcMs = now
                        .Add(RuntimeUnlockRecoveryContractLivenessDeferral)
                        .ToUnixTimeMilliseconds(),
                    RequiresLocalListenerRetry = requiresLocalListenerRetry,
                    ListenerRearmRequirement = requiresLocalListenerRetry
                        ? listenerRearmRequirement
                        : RuntimeUnlockRetryDispatchListenerRearmRequirement.None,
                    CutThroughPending = cutThroughPending,
                    CutThroughAttempt = previousCutThroughAttempt,
                    SourcePublicationAuthority = sourcePublicationAuthority,
                    SourceDataSessionGeneration = sourceDataSessionGeneration,
                };

                if (runtimeUnlockRecoveryRetryState is { } replacedState &&
                    !ReferenceEquals(replacedState, newState))
                {
                    _ = InvalidateRuntimeUnlockRetryDispatchDecisionStageUnsafe(
                        replacedState,
                        "retry_dispatch_install_stage_invalidated_recovery_contract_replaced");
                }
                runtimeUnlockRecoveryRetryState = newState;
            }
        }

        if (preservedDispatchState is not null)
        {
            var activeContract = preservedDispatchState.DispatchContract!;
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=runtime_unlock_retry_successor_intent_coalesced; {FormatRuntimeUnlockRetryDispatchAuthorityTuple(activeContract.Authority)}; offer_generation={activeContract.OfferGeneration}; offer_nonce={SanitizeLogToken(activeContract.OfferNonce ?? "(none)")}; attempt_phase={SanitizeLogToken(activeContract.AttemptPhase.ToString())}; requested_retired_generation={retiredOfferGeneration}; requested_retry_reason={SanitizeLogToken(retryReason)}; requested_recovery_reason={SanitizeLogToken(recoveryReason)}; decision_reason=current_dispatch_contract_owns_attempt");

            if (preservedDispatchEvaluation is { } evaluation)
            {
                RequestRuntimeUnlockRetryDispatchSuccessorEvaluation(
                    evaluation,
                    "successor_intent_coalesced");
            }

            return;
        }

        if (preservedCutThroughState is not null)
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=tuna_acceleration_runtime_unlock_retry_after_recovery_arm_downgrade_ignored; session_id={SanitizeLogToken(normalizedSessionId)}; retired_generation={retiredOfferGeneration}; retry_reason={SanitizeLogToken(retryReason)}; recovery_reason={SanitizeLogToken(recoveryReason)}; preserved_retry_reason={SanitizeLogToken(preservedCutThroughState.RetryReason)}; preserved_recovery_reason={SanitizeLogToken(preservedCutThroughState.RecoveryReason)}; cutthrough_pending={(preservedCutThroughState.CutThroughPending ? 1 : 0)}; cutthrough_active={(preservedCutThroughState.CutThroughActive ? 1 : 0)}");
            LogRuntimeUnlockRecoveryContract("session_recovery_contract_started", normalizedSessionId);
            return;
        }

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=tuna_acceleration_runtime_unlock_retry_after_recovery_armed; session_id={SanitizeLogToken(normalizedSessionId)}; retired_generation={retiredOfferGeneration}; retry_reason={SanitizeLogToken(retryReason)}; recovery_reason={SanitizeLogToken(recoveryReason)}; requires_local_listener_retry={(requiresLocalListenerRetry ? 1 : 0)}");
        LogRuntimeUnlockRecoveryContract("session_recovery_contract_started", normalizedSessionId);
        RequestRuntimeUnlockRetryDispatchAuthority(normalizedSessionId, "retry_contract_armed");
        lock (accelerationGate)
        {
            var requestedState = runtimeUnlockRecoveryRetryState;
            if (requestedState is not null &&
                runtimeUnlockRetryDispatchInstallShadow.LastCommittedReceipt is { } committedReceipt &&
                requestedState.DispatchContract?.Authority == committedReceipt.Authority)
            {
                // Phase 2 owns activation after commit. Its serialized follow-up logs the
                // effective grant and schedules with the exact receipt; scheduling here
                // would let an older arm path overtake that proof boundary.
                return;
            }
        }
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=tuna_acceleration_runtime_unlock_retry_after_recovery_awaiting_coordinator_install; session_id={SanitizeLogToken(normalizedSessionId)}; retired_generation={retiredOfferGeneration}; retry_reason={SanitizeLogToken(retryReason)}; recovery_reason={SanitizeLogToken(recoveryReason)}; authority_effect=none; decision_reason=phase2_install_required");
    }

    private static void ClearRuntimeUnlockRetryEvidenceBlockersUnsafe(
        RuntimeUnlockRecoveryRetryState state)
    {
        state.BlockedByRegularV4FrontierRepair = false;
        state.RegularV4FrontierRepairTrigger = null;
        state.RegularV4FrontierRepairPayerDecisionId = 0;
        state.RegularV4FrontierRepairBlockerReason = null;
        state.RegularV4FrontierRepairBlockedUtcMs = 0;
    }

    private bool HasRuntimeUnlockRecoveryContractRequiringLocalListenerRetry(string sessionId)
    {
        if (string.IsNullOrWhiteSpace(sessionId))
        {
            return false;
        }

        var normalizedSessionId = sessionId.Trim();
        lock (accelerationGate)
        {
            var state = runtimeUnlockRecoveryRetryState;
            return state is not null &&
                   state.RequiresLocalListenerRetry &&
                   !state.ListenerRearmCompleted &&
                   !state.RetryObserved &&
                   GetRuntimeUnlockRetryDispatchListenerRearmRequirementUnsafe(state) !=
                       RuntimeUnlockRetryDispatchListenerRearmRequirement.None &&
                   state.ContractState is not (SessionRecoveryContractState.Completed or SessionRecoveryContractState.Failed) &&
                   string.Equals(state.SessionId, normalizedSessionId, StringComparison.Ordinal);
