    private bool HasRuntimeUnlockRecoveryContractRequiringCutThroughProbe(
        string sessionId,
        long retiredOfferGeneration = 0)
    {
        if (string.IsNullOrWhiteSpace(sessionId))
        {
            return false;
        }

        var normalizedSessionId = sessionId.Trim();
        lock (accelerationGate)
        {
            var state = runtimeUnlockRecoveryRetryState;
            return state is not null &&
                   state.CutThroughPending &&
                   !state.CutThroughActive &&
                   !state.CutThroughCompleted &&
                   !state.RetryQueued &&
                   !state.RetryObserved &&
                   (retiredOfferGeneration <= 0 || state.RetiredOfferGeneration == retiredOfferGeneration) &&
                   string.Equals(state.RetryReason, RuntimeUnlockCutThroughRetryReason, StringComparison.Ordinal) &&
                   state.ContractState is not (SessionRecoveryContractState.Completed or SessionRecoveryContractState.Failed) &&
                   string.Equals(state.SessionId, normalizedSessionId, StringComparison.Ordinal);
        }
    }

    private bool ShouldAllowRuntimeUnlockRegularV4CutThroughProbeAfterSoftSettle(
        long retiredOfferGeneration,
        string sessionId,
        string stateReason,
        long deadlineRemainingMs,
        out string settleReason)
    {
        settleReason = "none";
        if (string.IsNullOrWhiteSpace(sessionId))
        {
            return false;
        }

        var normalizedSessionId = sessionId.Trim();
        lock (accelerationGate)
        {
            var state = runtimeUnlockRecoveryRetryState;
            if (state is null ||
                !state.CutThroughPending ||
                state.CutThroughActive ||
                state.CutThroughCompleted ||
                state.RetryQueued ||
                state.RetryObserved ||
                state.RetiredOfferGeneration != retiredOfferGeneration ||
                !string.Equals(state.RetryReason, RuntimeUnlockCutThroughRetryReason, StringComparison.Ordinal) ||
                state.ContractState is SessionRecoveryContractState.Completed or SessionRecoveryContractState.Failed ||
                !string.Equals(state.SessionId, normalizedSessionId, StringComparison.Ordinal))
            {
                return false;
            }

            state.Settled = true;
            state.AuthorityFailureReason = null;
            state.ContractState = SessionRecoveryContractState.RecoverySettled;
        }

        settleReason = "active_regular_v4_recovery_cutthrough_peer_visible_probe";
        LocalOperationalLog.Warn(
            "NKN.Tuna",
            $"event=tuna_acceleration_runtime_unlock_retry_after_regular_v4_cutthrough_allowed; session_id={SanitizeLogToken(normalizedSessionId)}; retired_generation={retiredOfferGeneration}; liveness_state={SanitizeLogToken(stateReason)}; liveness_deadline_remaining_ms={deadlineRemainingMs}; reason=cutthrough_must_precede_receive_proof");
        return true;
    }

    private bool HasSettledRuntimeUnlockRegularV4AuthorityProbeCandidate(string sessionId)
    {
        if (string.IsNullOrWhiteSpace(sessionId))
        {
            return false;
        }

        var normalizedSessionId = sessionId.Trim();
        lock (accelerationGate)
        {
            var state = runtimeUnlockRecoveryRetryState;
            return state is not null &&
                   state.Settled &&
                   !state.RetryQueued &&
                   !state.RetryObserved &&
                   HasRuntimeUnlockRetryDispatchLineageUnsafe(state) &&
                   state.ContractState is not (SessionRecoveryContractState.Completed or SessionRecoveryContractState.Failed) &&
                   string.Equals(state.SessionId, normalizedSessionId, StringComparison.Ordinal);
        }
    }

    private bool ShouldAllowRuntimeUnlockRegularV4AuthorityProbeAfterSoftSettle(
        long retiredOfferGeneration,
        string sessionId,
        out string settleReason)
    {
        settleReason = "none";
        return false;
    }

    private void ScheduleRuntimeUnlockRetryAfterRecoveryIfArmed(
        string trigger,
        RuntimeUnlockRetryDispatchInstallReceipt? expectedInstallReceipt = null)
    {
        RuntimeUnlockRecoveryRetryState? stateSnapshot = null;
        RuntimeUnlockRecoveryRetryState? staleStateToClear = null;
        RuntimeUnlockRetryDispatchSettlementReport staleSettlementReport = default;
        var staleStateHadDispatchContract = false;
        lock (accelerationGate)
        {
            var state = runtimeUnlockRecoveryRetryState;
            if (state is null ||
                state.RetryQueued ||
                state.ContractState is SessionRecoveryContractState.Completed or SessionRecoveryContractState.Failed)
            {
                return;
            }

            if (state.RetryDispatching ||
                state.RetryDispatched ||
                state.ObservedSendPending ||
                state.CutThroughActive)
            {
                LocalOperationalLog.Info(
                    "NKN.Tuna",
                    $"event=tuna_acceleration_runtime_unlock_recovery_settle_ignored_after_dispatch; session_id={SanitizeLogToken(state.SessionId)}; retired_generation={state.RetiredOfferGeneration}; trigger={SanitizeLogToken(trigger)}; retry_dispatching={(state.RetryDispatching ? 1 : 0)}; retry_dispatched={(state.RetryDispatched ? 1 : 0)}; observed_send_pending={(state.ObservedSendPending ? 1 : 0)}; cutthrough_pending={(state.CutThroughPending ? 1 : 0)}; cutthrough_active={(state.CutThroughActive ? 1 : 0)}");
                return;
            }

            var currentSessionId = currentSessionSecurityState.SessionId?.Value;
            if (string.IsNullOrWhiteSpace(currentSessionId) ||
                !string.Equals(currentSessionId.Trim(), state.SessionId, StringComparison.Ordinal))
            {
                staleStateToClear = state;
                _ = InvalidateRuntimeUnlockRetryDispatchDecisionStageUnsafe(
                    state,
                    "retry_dispatch_install_stage_invalidated_session_owner_replaced");
                staleStateHadDispatchContract = state.DispatchContract is not null;
                _ = SettleRuntimeUnlockRetryDispatchContractUnsafe(
                    state,
                    RuntimeUnlockRetryDispatchSettlementOutcome.StaleRejected,
                    "session_owner_replaced",
                    out staleSettlementReport);
                if (!staleStateHadDispatchContract)
                {
                    runtimeUnlockRecoveryRetryState = null;
                }
            }
            else
            {
                stateSnapshot = state;
            }
        }

        if (staleStateHadDispatchContract &&
            staleStateToClear is not null &&
            !PublishRuntimeUnlockRetryDispatchSettlementReportAndConfirmFailure(
                staleSettlementReport,
                staleStateToClear))
        {
            return;
        }

        if (!staleSettlementReport.IsDefault)
        {
            lock (accelerationGate)
            {
                if (ReferenceEquals(runtimeUnlockRecoveryRetryState, staleStateToClear))
                {
                    runtimeUnlockRecoveryRetryState = null;
                }
            }
        }

        if (stateSnapshot is null)
        {
            return;
        }

        RuntimeUnlockRecoveryRetryState? stateToSchedule = null;
        RuntimeUnlockRecoveryRetryState? rejectedDispatchState = null;
        RuntimeUnlockRecoveryRetryState? activeNegotiationHeldState = null;
        RuntimeUnlockRecoveryRetryState? coordinatorHeldState = null;
        RuntimeUnlockRetryDispatchSettlementReport rejectedSettlementReport = default;
        var rejectedDispatchHadContract = false;
        var queuedBehindActiveNegotiation = false;
        var requiresDispatchAuthority = HasRuntimeUnlockRetryDispatchLineageUnsafe(stateSnapshot);
        var holdDispatchGrantForListenerRearm =
            GetRuntimeUnlockRetryDispatchListenerRearmRequirementUnsafe(
                stateSnapshot) ==
                RuntimeUnlockRetryDispatchListenerRearmRequirement
                    .RequiredBeforeDispatch &&
            !stateSnapshot.ListenerRearmCompleted &&
            stateSnapshot.RequiresLocalListenerRetry;
        var expectedDispatchLiveRouteEpoch = GetRuntimeUnlockRetryExpectedDispatchLiveRouteEpoch(stateSnapshot);
        var expectedDispatchDirection = GetRuntimeUnlockRetryExpectedDispatchDirection(stateSnapshot);
        RuntimeUnlockRetryDispatchAuthority dispatchAuthority = default;
        var dispatchAuthorityRejectionReason = "accepted";
        var hasDispatchAuthority = !requiresDispatchAuthority ||
            TryGetInstalledRuntimeUnlockRetryDispatchAuthority(
                stateSnapshot.SessionId,
                stateSnapshot.TransferId,
                expectedDispatchDirection,
                expectedDispatchLiveRouteEpoch,
                HasEffectiveFallbackPairedTailYieldInstallReceiptUnsafe(stateSnapshot),
                out dispatchAuthority,
                out dispatchAuthorityRejectionReason);
        if (!requiresDispatchAuthority)
        {
            dispatchAuthority = default;
            dispatchAuthorityRejectionReason = "accepted";
        }
        if (requiresDispatchAuthority &&
            hasDispatchAuthority &&
            !ValidateRuntimeUnlockRetryDispatchInstallReceiptBoundary(
                expectedInstallReceipt,
                "recovery_schedule_entry",
                requireInstalledReceipt: true))
        {
            return;
        }

        lock (accelerationGate)
        {
            var state = runtimeUnlockRecoveryRetryState;
            if (state is null ||
                state.RetryQueued ||
                state.RetiredOfferGeneration != stateSnapshot.RetiredOfferGeneration ||
                !string.Equals(state.SessionId, stateSnapshot.SessionId, StringComparison.Ordinal))
            {
                return;
            }

            var requiresDispatchProof =
                requiresDispatchAuthority ||
                RequiresRuntimeUnlockRetryDispatchProof(state);
            if (requiresDispatchProof &&
                !IsRuntimeUnlockRetryDispatchAuthorityCaptureCurrent(
                    state,
                    stateSnapshot.ContractGeneration,
                    stateSnapshot.RetiredOfferGeneration,
                    stateSnapshot.SessionId,
                    stateSnapshot.TransferId,
                    expectedDispatchLiveRouteEpoch))
            {
                return;
            }

            if (expectedInstallReceipt is { } receipt &&
                !TryValidateRuntimeUnlockRetryDispatchInstallReceiptCurrentUnsafe(
                    state,
                    receipt,
                    out var receiptRejectionReason))
            {
                LogRuntimeUnlockRetryDispatchInstallRejected(
                    receipt,
                    CaptureRuntimeUnlockRetryDispatchInstallTelemetryUnsafe(state),
                    RuntimeUnlockRetryDispatchInstallStatus.Rejected,
                    $"{receiptRejectionReason}_retry_queue_boundary");
                return;
            }

            state.Settled = true;
            queuedBehindActiveNegotiation = Volatile.Read(ref accelerationNegotiationScheduled) != 0;
            var pendingDispatchRequest = state.PendingDispatchAuthorityRequest;
            var exactCoordinatorHold =
                requiresDispatchProof &&
                state.DispatchDecisionStatus == RuntimeUnlockRetryDispatchDecisionStatus.Held &&
                pendingDispatchRequest is { } heldRequest &&
                heldRequest.RecoveryContractGeneration == state.ContractGeneration &&
                heldRequest.RetiredOfferGeneration == state.RetiredOfferGeneration &&
                heldRequest.DispatchAttemptGeneration == state.DispatchAttemptGeneration &&
                heldRequest.MissingDispatchSuccessorGeneration ==
                    state.MissingDispatchSuccessorGeneration &&
                string.Equals(heldRequest.SessionId, state.SessionId, StringComparison.Ordinal) &&
                string.Equals(heldRequest.TransferId, state.TransferId, StringComparison.Ordinal) &&
                heldRequest.SourcePublicationAuthority == state.SourcePublicationAuthority;
            if (exactCoordinatorHold)
            {
                state.RetryQueued = false;
                state.RetryDispatching = false;
                state.RetryDispatched = false;
                state.RetryAuthorityPending = true;
                state.RetryAuthorityGranted = state.DispatchContract is not null;
                state.ObservedSendPending = false;
                state.QueuedBehindActiveNegotiation = false;
                state.DispatchObserved = false;
                state.ContractState = SessionRecoveryContractState.RecoverySettled;
                coordinatorHeldState = state;
                stateToSchedule = state;
            }
            else if (requiresDispatchProof &&
                queuedBehindActiveNegotiation &&
                !holdDispatchGrantForListenerRearm)
            {
                state.RetryQueued = false;
                state.RetryDispatching = false;
                state.RetryDispatched = false;
                state.RetryAuthorityPending = state.DispatchContract is not null;
                state.RetryAuthorityGranted = state.DispatchContract is not null;
                state.ObservedSendPending = false;
                state.QueuedBehindActiveNegotiation = true;
                state.DispatchObserved = false;
                state.DispatchDecisionReason = "active_negotiation_pending";
                state.AuthorityFailureReason = null;
                state.ContractState = SessionRecoveryContractState.RecoverySettled;
                pendingRuntimeUnlockAccelerationNegotiationReason = IsRuntimeUnlockActivationReason(state.RetryReason)
                    ? SanitizeLogToken(state.RetryReason)
                    : "runtime_unlock";
                pendingRuntimeUnlockAccelerationNegotiationAuthorityMode =
                    RuntimeUnlockOfferAuthorityMode.InstalledRetry;
                pendingRuntimeUnlockAccelerationNegotiationInstallReceipt =
                    expectedInstallReceipt;
                pendingRuntimeUnlockAccelerationNegotiation = 1;
                activeNegotiationHeldState = state;
                stateToSchedule = state;
            }
            else if (requiresDispatchProof && !hasDispatchAuthority)
            {
                rejectedDispatchHadContract = state.DispatchContract is not null;
                _ = MarkRuntimeUnlockRetryDispatchAuthorityRejectedUnsafe(
                    state,
                    dispatchAuthorityRejectionReason,
                    out rejectedSettlementReport);
                rejectedDispatchState = state;
                stateToSchedule = state;
            }
            else if (requiresDispatchAuthority &&
                holdDispatchGrantForListenerRearm)
            {
                state.RetryQueued = false;
                state.RetryDispatching = false;
                state.RetryDispatched = false;
                state.RetryAuthorityPending = false;
                state.RetryAuthorityGranted = false;
                state.ObservedSendPending = false;
                state.QueuedBehindActiveNegotiation = false;
                state.AuthorityFailureReason = "listener_rearm_required_before_dispatch_authority";
                state.ContractState = SessionRecoveryContractState.RecoverySettled;
                stateToSchedule = state;
            }
            else
            {
                state.RetryQueued = true;
                state.QueuedBehindActiveNegotiation = false;
                GrantRuntimeUnlockRecoveryContractRetryAuthorityUnsafe(state);
                if (requiresDispatchAuthority)
                {
                    state.DispatchDecisionReason = "retry_dispatch_forwarded_for_recovery_schedule";
                }

                state.ContractState = SessionRecoveryContractState.RetryQueued;
                stateToSchedule = state;
            }
        }

        if (stateToSchedule is null)
        {
            return;
        }

        if (coordinatorHeldState is not null)
        {
            LogRuntimeUnlockRetryDispatchProof(
                "runtime_unlock_retry_dispatch_authority_hold_preserved",
                coordinatorHeldState,
                coordinatorHeldState.DispatchDecisionReason ?? "runtime_unlock_retry_dispatch_authority_held");
            LogRuntimeUnlockRecoveryContract(
                "session_recovery_contract_recovery_settled",
                coordinatorHeldState.SessionId);
            ResumeFileTransferDataSessionsAfterTunaActivationNegotiation(
                "runtime_unlock_retry_dispatch_authority_held",
                coordinatorHeldState.SessionId,
                "runtime_unlock_retry_dispatch_authority_hold_preserved");
            return;
        }

        if (activeNegotiationHeldState is not null)
        {
            LogRuntimeUnlockRetryDispatchProof(
                "runtime_unlock_retry_dispatch_held_by_active_negotiation",
                activeNegotiationHeldState,
                activeNegotiationHeldState.DispatchDecisionReason ?? "active_negotiation_pending");
            LogRuntimeUnlockRecoveryContract("session_recovery_contract_recovery_settled", activeNegotiationHeldState.SessionId);
            NotifyTransportAccelerationStateChanged("runtime_unlock_retry_dispatch_held_by_active_negotiation");
            return;
        }

        if (rejectedDispatchState is not null)
        {
            if (!ConfirmRuntimeUnlockRetryDispatchRejection(
                    rejectedDispatchState,
                    rejectedDispatchHadContract,
                    rejectedSettlementReport))
            {
                return;
            }

            LogRuntimeUnlockRetryDispatchProof(
                "runtime_unlock_retry_dispatch_authority_rejected",
                rejectedDispatchState,
                rejectedDispatchState.DispatchDecisionReason ?? dispatchAuthorityRejectionReason);
            LogRuntimeUnlockRecoveryContract("session_recovery_contract_failed", rejectedDispatchState.SessionId);
            return;
        }

        var scheduledRoute = requiresDispatchAuthority && hasDispatchAuthority && !string.IsNullOrWhiteSpace(dispatchAuthority.RouteToken)
            ? dispatchAuthority.RouteToken
            : stateToSchedule.DispatchRoute;
        var scheduledProtocolVersion = requiresDispatchAuthority && hasDispatchAuthority && dispatchAuthority.ProtocolVersion > 0
            ? dispatchAuthority.ProtocolVersion
            : stateToSchedule.DispatchProtocolVersion;
        var scheduledLiveRouteEpoch = requiresDispatchAuthority && hasDispatchAuthority
            ? dispatchAuthority.LiveRouteEpoch
            : GetRuntimeUnlockRetryExpectedDispatchLiveRouteEpoch(stateToSchedule);
        if (string.IsNullOrWhiteSpace(scheduledRoute) ||
            string.Equals(scheduledRoute, "(none)", StringComparison.Ordinal) ||
            scheduledProtocolVersion <= 0)
        {
            RuntimeUnlockRecoveryRetryState? routeLessRejectedState = null;
            RuntimeUnlockRetryDispatchSettlementReport routeLessSettlementReport = default;
            var routeLessHadDispatchContract = false;
            lock (accelerationGate)
            {
                var state = runtimeUnlockRecoveryRetryState;
                if (state is not null &&
                    state.ContractGeneration == stateToSchedule.ContractGeneration &&
                    state.RetiredOfferGeneration == stateToSchedule.RetiredOfferGeneration &&
                    string.Equals(state.SessionId, stateToSchedule.SessionId, StringComparison.Ordinal))
                {
                    routeLessHadDispatchContract = state.DispatchContract is not null;
                    _ = MarkRuntimeUnlockRetryDispatchAuthorityRejectedUnsafe(
                        state,
                        "missing_route_publication_authority",
                        out routeLessSettlementReport);
                    routeLessRejectedState = state;
                }
            }

            if (routeLessRejectedState is null)
            {
                return;
            }

            if (!ConfirmRuntimeUnlockRetryDispatchRejection(
                    routeLessRejectedState,
                    routeLessHadDispatchContract,
                    routeLessSettlementReport))
            {
                return;
            }

            LogRuntimeUnlockRetryDispatchProof(
                "runtime_unlock_retry_dispatch_authority_rejected",
                routeLessRejectedState,
                routeLessRejectedState.DispatchDecisionReason ?? "missing_route_publication_authority");
            LogRuntimeUnlockRecoveryContract("session_recovery_contract_failed", routeLessRejectedState.SessionId);
            return;
        }

        if (requiresDispatchAuthority && holdDispatchGrantForListenerRearm)
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=runtime_unlock_retry_dispatch_pending_listener_rearm; session_id={SanitizeLogToken(stateToSchedule.SessionId)}; transfer_id={SanitizeLogToken(stateToSchedule.TransferId ?? "(none)")}; retired_generation={stateToSchedule.RetiredOfferGeneration}; contract_generation={stateToSchedule.ContractGeneration}; retry_reason={SanitizeLogToken(stateToSchedule.RetryReason)}; recovery_reason={SanitizeLogToken(stateToSchedule.RecoveryReason)}; trigger={SanitizeLogToken(trigger)}; route={SanitizeLogToken(scheduledRoute)}; protocol_version={scheduledProtocolVersion}; live_route_epoch={scheduledLiveRouteEpoch}; decision_reason=listener_rearm_required_before_dispatch_authority");
            LogRuntimeUnlockRecoveryContract("session_recovery_contract_recovery_settled", stateToSchedule.SessionId);
            ScheduleRuntimeUnlockPreCommitProbeSidecarListenerRearm(
                stateToSchedule,
                trigger,
                expectedInstallReceipt);
            return;
        }

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=tuna_acceleration_runtime_unlock_retry_after_recovery_scheduled; session_id={SanitizeLogToken(stateToSchedule.SessionId)}; transfer_id={SanitizeLogToken(stateToSchedule.TransferId ?? "(none)")}; retired_generation={stateToSchedule.RetiredOfferGeneration}; contract_generation={stateToSchedule.ContractGeneration}; offer_generation={(stateToSchedule.CurrentOfferGeneration > 0 ? stateToSchedule.CurrentOfferGeneration : stateToSchedule.RetiredOfferGeneration)}; retry_reason={SanitizeLogToken(stateToSchedule.RetryReason)}; recovery_reason={SanitizeLogToken(stateToSchedule.RecoveryReason)}; trigger={SanitizeLogToken(trigger)}; queued_behind_active_negotiation={(queuedBehindActiveNegotiation ? 1 : 0)}; route={SanitizeLogToken(scheduledRoute)}; protocol_version={scheduledProtocolVersion}; live_route_epoch={scheduledLiveRouteEpoch}; regular_v4_liveness_generation=0; bridge_decision_generation=0");
        LogRuntimeUnlockRecoveryContract("session_recovery_contract_recovery_settled", stateToSchedule.SessionId);
        LogRuntimeUnlockRecoveryContract("session_recovery_contract_retry_authority_granted", stateToSchedule.SessionId);
        LogRuntimeUnlockRecoveryContract("session_recovery_contract_retry_queued", stateToSchedule.SessionId);
        ScheduleRuntimeUnlockAccelerationNegotiationRetry(
            stateToSchedule.RetryReason,
            expectedInstallReceipt);
    }

    private async Task<AccelerationControlSendResult>
        SendAccelerationPayerIntentAsync(
        string target,
        string sessionId,
        string envelopeCode,
        string localRole,
        NknAccelerationLaneKind lanes,
        bool canOfferListener,
        string trigger,
        long payerDecisionId,
        CancellationToken ct,
        RuntimeUnlockRetryDispatchInstallReceipt? expectedInstallReceipt = null,
        RuntimeUnlockOfferAuthorityMode? offerAuthorityMode = null,
        RuntimeUnlockOfferAuthorityBoundary? expectedOfferAuthorityBoundary =
            null,
        AccelerationPayerIntentSubmission? preparedSubmission = null)
    {
        var submission =
            preparedSubmission ??
            CreateAccelerationPayerIntentSubmission(
                envelopeCode,
                sessionId,
                localRole,
                lanes,
                canOfferListener,
                trigger,
                payerDecisionId);
        var envelope = submission.Envelope;
        var intent = submission.Intent;
        Task<AccelerationControlSendResult> SendCurrentPayerIntentAsync(
            RuntimeUnlockInitialActivationReceiveRecoveryHoldPrevalidation?
                holdPrevalidation = null)
            => SendAccelerationControlEnvelopeWithBulkBypassAsync(
                target,
                envelope,
                "payer_intent",
                ct,
                expectedInstallReceipt: expectedInstallReceipt,
                expectedOfferAuthorityBoundary:
                    expectedOfferAuthorityBoundary,
                expectedOfferAuthorityMode:
                    expectedOfferAuthorityBoundary is null
                        ? offerAuthorityMode
                        : null,
                initialActivationPhysicalHoldBoundary:
                    expectedOfferAuthorityBoundary?.Mode ==
                        RuntimeUnlockOfferAuthorityMode.InitialActivation
                        ? RuntimeUnlockInitialActivationReceiveRecoveryHoldBoundary
                            .PayerIntentPreSend
                        : null,
                initialActivationHoldPrevalidation:
                    holdPrevalidation);

        var queued = await SendCurrentPayerIntentAsync().ConfigureAwait(false);
        while (!queued.Succeeded &&
               !queued.StaleCallbackIgnored &&
               !queued.UntrustedProbeSent &&
               expectedOfferAuthorityBoundary is
               {
                   Mode: RuntimeUnlockOfferAuthorityMode.InitialActivation,
                   TransferId: { Length: > 0 },
               } initialActivationBoundary)
        {
            if (!TryCreateRuntimeUnlockInitialActivationReceiveRecoveryHoldRequest(
                    initialActivationBoundary,
                    RuntimeUnlockInitialActivationReceiveRecoveryHoldBoundary
                        .UnobservedPayerIntentSendFailure,
                    out var failureHoldRequest))
            {
                return AccelerationControlSendResult.StaleCallback;
            }

            var failureHold =
                await PrevalidateRuntimeUnlockInitialActivationReceiveRecoveryHoldAsync(
                        failureHoldRequest,
                        ct)
                    .ConfigureAwait(false);
            if (ShouldResumeRuntimeUnlockInitialActivationSameGeneration(
                    failureHold.Result))
            {
                if (!ValidateRuntimeUnlockOfferAuthorityBoundary(
                        initialActivationBoundary,
                        "initial_activation_hold_unobserved_payer_intent_resumed",
                        allowDispatchObservedSettlement: false))
                {
                    return AccelerationControlSendResult.StaleCallback;
                }

                queued =
                    await SendCurrentPayerIntentAsync(failureHold)
                        .ConfigureAwait(false);
                continue;
            }

            if (!failureHold.IsReleased)
            {
                return AccelerationControlSendResult.StaleCallback;
            }

            break;
        }

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=tuna_acceleration_payer_intent_{(queued.Succeeded ? "queued" : "rejected")}; intent={intent}; role={SanitizeLogToken(localRole)}; trigger={SanitizeLogToken(trigger)}; lanes={FormatAccelerationLanesForLog(lanes)}; payer_decision_id={payerDecisionId}");
        return queued;
    }

    private AccelerationPayerIntentSubmission
        CreateAccelerationPayerIntentSubmission(
            string envelopeCode,
            string sessionId,
            string localRole,
            NknAccelerationLaneKind lanes,
            bool canOfferListener,
            string trigger,
            long payerDecisionId)
    {
        var nonce = Convert.ToHexString(RandomNumberGenerator.GetBytes(16)).ToLowerInvariant();
        var intent = canOfferListener ? "will_listen" : "dialer_only";
        var payloadModel = new TransportAccelerationPayerIntentPayload
        {
            SessionId = sessionId,
            SenderRole = localRole,
            Intent = intent,
            SupportedLanes = NknAccelerationLaneCodec.ToNames(lanes),
            Trigger = SanitizeLogToken(trigger),
            PayerDecisionId = payerDecisionId,
            SentAtUnixMs = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds(),
            ExpiresAtUnixMs = DateTimeOffset.UtcNow.Add(AccelerationOfferLifetime).ToUnixTimeMilliseconds(),
            Nonce = nonce,
            SidecarProtocolVersion = TunaSidecarProtocolVersion,
        };
        var payload = CreateSecureControlPayload(
            MsgType.TransportAccelerationPayerIntent,
            nonce,
            JsonSerializer.SerializeToUtf8Bytes(payloadModel));
        var envelope = CreateEnvelope(envelopeCode, MsgType.TransportAccelerationPayerIntent, payload, replyTo: null);
        return new AccelerationPayerIntentSubmission(envelope, intent);
    }

    private void HandleTransportAccelerationPayerIntent(string source, Envelope env)
    {
        if (!TryDecryptControlPayload(source, env, MsgType.TransportAccelerationPayerIntent, out var securePayload))
        {
            return;
        }

        if (!TryDeserializeAccelerationPayload<TransportAccelerationPayerIntentPayload>(securePayload.Plaintext, out var intent) ||
            intent is null)
        {
            RejectAccelerationEnvelope("transport_acceleration_payer_intent", "payload_invalid", env.MessageId);
            return;
        }

        if (!TryValidateControlSecureMetadata("transport_acceleration_payer_intent", securePayload.Metadata, intent.Nonce, env.MessageId))
        {
            return;
        }

        var validation = ValidateAccelerationPayerIntent(source, intent);
        if (!validation.IsValid)
        {
            RejectAccelerationEnvelope("transport_acceleration_payer_intent", validation.Reason ?? "invalid", env.MessageId);
            return;
        }

        ClearAccelerationUserStoppedForFreshPeerMessage("payer_intent", intent.Trigger, intent.SentAtUnixMs);
        ObserveRemotePayerIntentForPayerPriority(intent, validation);
        if (ShouldYieldLocalPaidListenerToRemoteHelpeeIntent(intent))
        {
            YieldLocalPaidListenerToRemoteHelpee("payer_intent_will_listen", intent.PayerDecisionId);
        }

        if (IsHelpeeSessionRole(ResolveLocalSessionRole()) &&
            IsHelperSessionRole(intent.SenderRole) &&
            accelerationLane is INknTunaAccelerationSession { CanOfferListener: true } &&
            !IsAccelerationNegotiatedAndHealthy())
        {
            ScheduleAccelerationNegotiationIfEligible("remote_payer_intent");
        }

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=tuna_acceleration_payer_intent_received; intent={SanitizeLogToken(intent.Intent)}; sender_role={SanitizeLogToken(intent.SenderRole)}; lanes={FormatAccelerationLanesForLog(validation.AcceptedLanes)}; payer_decision_id={intent.PayerDecisionId}");
    }

    private void HandleTransportAccelerationOffer(string source, Envelope env)
    {
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=tuna_acceleration_offer_received_raw; msg_id={SanitizeLogToken(env.MessageId)}");
        if (!TryDecryptControlPayload(source, env, MsgType.TransportAccelerationOffer, out var securePayload))
        {
            return;
        }

        if (!TryDeserializeAccelerationPayload<TransportAccelerationOfferPayload>(securePayload.Plaintext, out var offer) ||
            offer is null)
        {
            RejectAccelerationEnvelope("transport_acceleration_offer", "payload_invalid", env.MessageId);
            return;
        }

        if (!TryValidateControlSecureMetadata("transport_acceleration_offer", securePayload.Metadata, offer.Nonce, env.MessageId))
        {
            return;
        }

        SendAccelerationLifecycleAckIfValid(source, env, "transport_acceleration_offer");

        _ = Task.Run(
            () => HandleTransportAccelerationOfferAsync(source, offer, env.MessageId, CancellationToken.None),
            CancellationToken.None);
    }

    private async Task HandleTransportAccelerationOfferAsync(
        string source,
        TransportAccelerationOfferPayload offer,
        string messageId,
        CancellationToken ct)
    {
        var validation = ValidateAccelerationOffer(source, offer);
        if (validation.IsHardReject)
        {
            RejectAccelerationEnvelope("transport_acceleration_offer", validation.Reason ?? "invalid", messageId);
            return;
        }

        var replyTarget = CreateAccelerationReplyTargetEvidence(
            source,
            messageId,
            offer.SessionId,
            offer.Nonce,
            offer.PayerDecisionId,
            lineageGeneration: 0,
            purpose: "answer");

        if (validation.IsValid)
        {
            ClearAccelerationUserStoppedForFreshPeerMessage("offer", offer.Trigger, offer.SentAtUnixMs);
        }

        if (validation.IsValid && IsAccelerationUserStoppedForCurrentSession())
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                "event=tuna_acceleration_offer_rejected; reason=user_stopped_tuna");
            await SendAccelerationAnswerAsync(
                offer,
                replyTarget,
                accepted: false,
                lanes: NknAccelerationLaneKind.None,
                rejectReason: "user_stopped_tuna",
                pendingAnswerAckGeneration: 0,
                ct).ConfigureAwait(false);
            return;
        }

        if (validation.IsValid &&
            IsRuntimeUnlockActivationReason(offer.Trigger) &&
            TryGetPendingRuntimeUnlockAnswerAckForOffer(
                offer,
                out var pendingAnswerAckGeneration,
                out var pendingAnswerAckLanes,
                out var matchesPendingAnswerAck))
        {
            if (matchesPendingAnswerAck)
            {
                LocalOperationalLog.Info(
                    "NKN.Tuna",
                    $"event=tuna_acceleration_runtime_unlock_offer_duplicate_pending_answer_ack; session_id={SanitizeLogToken(offer.SessionId)}; payer_decision_id={offer.PayerDecisionId}; generation={pendingAnswerAckGeneration}; action=answer_replay");
                await SendAccelerationAnswerAsync(
                        offer,
                        UpdatePendingAccelerationAnswerReplyTarget(replyTarget, pendingAnswerAckGeneration),
                        accepted: true,
                        lanes: pendingAnswerAckLanes,
                        rejectReason: null,
                        pendingAnswerAckGeneration: pendingAnswerAckGeneration,
                        scheduleReplay: false,
                        ct: ct)
                    .ConfigureAwait(false);
            }
            else
            {
                LocalOperationalLog.Warn(
                    "NKN.Tuna",
                    $"event=tuna_acceleration_runtime_unlock_offer_rejected_pending_answer_ack; session_id={SanitizeLogToken(offer.SessionId)}; payer_decision_id={offer.PayerDecisionId}; generation={pendingAnswerAckGeneration}; action=reject; reject_reason=answer_ack_pending");
                await SendAccelerationAnswerAsync(
                        offer,
                        replyTarget,
                        accepted: false,
                        lanes: NknAccelerationLaneKind.None,
                        rejectReason: "answer_ack_pending",
                        pendingAnswerAckGeneration: 0,
                        ct: ct)
                    .ConfigureAwait(false);
            }

            return;
        }

        ObserveRemoteOfferForPayerPriority(offer, validation);
        if (validation.IsValid && ShouldRejectRemoteHelperOfferForHelpeePriority(offer))
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                "event=tuna_acceleration_offer_rejected; reason=helpee_payer_preferred; sender_role=helper");
            ScheduleAccelerationNegotiationIfEligible("helpee_payer_preferred");
            await SendAccelerationAnswerAsync(
                offer,
                replyTarget,
                accepted: false,
                lanes: NknAccelerationLaneKind.None,
                rejectReason: "helpee_payer_preferred",
                pendingAnswerAckGeneration: 0,
                ct).ConfigureAwait(false);
            return;
        }

        var isRuntimeUnlockOffer = validation.IsValid && IsRuntimeUnlockActivationReason(offer.Trigger);
        var runtimeUnlockDialAttemptStarted = false;
        if (isRuntimeUnlockOffer &&
            !TryBeginInboundRuntimeUnlockDialAttempt(offer, out var dialGateReason))
        {
            LocalOperationalLog.Warn(
                "NKN.Tuna",
                $"event=runtime_unlock_tuna_dial_offer_duplicate_ignored; session_id={SanitizeLogToken(offer.SessionId)}; payer_decision_id={offer.PayerDecisionId}; reason={SanitizeLogToken(dialGateReason)}; nonce_len={(offer.Nonce?.Length ?? 0)}");
            return;
        }

        runtimeUnlockDialAttemptStarted = isRuntimeUnlockOffer;

        var rejectReason = validation.Reason;
        if (validation.IsValid)
        {
            PauseRegularNknV4FileTransferForRuntimeUnlockMakeBeforeBreak(
                offer.SessionId,
                "peer_offer_answer_ack_pending",
                offer.Trigger);

            NotifyTransportAccelerationStateChanged("dialer_starting");
        }

        var accepted = validation.IsValid &&
                       accelerationLane is INknTunaAccelerationSession tunaSession &&
                       await tunaSession.StartDialerSidecarAsync(offer.TunaAddress, source, ct).ConfigureAwait(false);
        if (accepted &&
            !validation.AllowsStaleRemotePayerDecision &&
            IsStaleRemotePayerDecision(offer.PayerDecisionId))
        {
            accepted = false;
            rejectReason = "stale_payer_decision";
            ScheduleAccelerationLaneStop("stale_payer_decision");
        }

        if (!accepted && rejectReason is null)
        {
            rejectReason = isRuntimeUnlockOffer
                ? "runtime_unlock_tuna_dial_failed"
                : "sidecar_unavailable";
        }

        if (runtimeUnlockDialAttemptStarted)
        {
            CompleteInboundRuntimeUnlockDialAttempt(offer, accepted, rejectReason ?? (accepted ? "connected" : "runtime_unlock_tuna_dial_failed"));
        }

        if (!accepted)
        {
            NotifyTransportAccelerationStateChanged(rejectReason ?? "sidecar_unavailable");
            ResumeFileTransferDataSessionsAfterTunaActivationNegotiation(
                rejectReason ?? "sidecar_unavailable",
                offer.SessionId,
                "dialer_not_accepted");
        }

        if (accepted)
        {
            NotifyTransportAccelerationStateChanged("dialer_ready");
            var answerAckGeneration = BeginPendingAccelerationAnswerAck(
                offer,
                validation.AcceptedLanes,
                replyTarget);
            MarkInboundRuntimeUnlockOfferAccepted(offer, answerAckGeneration);
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=tuna_acceleration_answer_ack_pending; session_id={SanitizeLogToken(offer.SessionId)}; lanes={FormatAccelerationLanesForLog(validation.AcceptedLanes)}; payer_decision_id={offer.PayerDecisionId}; generation={answerAckGeneration}");
            if (!isRuntimeUnlockOffer)
            {
                ScheduleAccelerationAnswerAckTimeout(
                    offer.SessionId,
                    offer.Nonce,
                    offer.PayerDecisionId,
                    answerAckGeneration);
            }
        }

        await SendAccelerationAnswerAsync(
                offer,
                accepted
                    ? GetPendingAccelerationAnswerReplyTarget() ?? replyTarget
                    : replyTarget,
                accepted,
                accepted ? validation.AcceptedLanes : NknAccelerationLaneKind.None,
                rejectReason,
                accepted ? GetPendingAccelerationAnswerAckGeneration() : 0,
                ct)
            .ConfigureAwait(false);
    }

    private bool TryBeginInboundRuntimeUnlockDialAttempt(
        TransportAccelerationOfferPayload offer,
        out string reason)
    {
        var sessionId = string.IsNullOrWhiteSpace(offer.SessionId)
            ? currentSessionSecurityState.SessionId?.Value ?? string.Empty
            : offer.SessionId.Trim();
        var nonce = string.IsNullOrWhiteSpace(offer.Nonce) ? string.Empty : offer.Nonce.Trim();
        reason = "unknown";
        if (string.IsNullOrWhiteSpace(sessionId) ||
            string.IsNullOrWhiteSpace(nonce))
        {
            reason = "missing_offer_identity";
            return false;
        }

        lock (accelerationGate)
        {
            var sameOffer =
                string.Equals(inboundRuntimeUnlockDialSessionId, sessionId, StringComparison.Ordinal) &&
                string.Equals(inboundRuntimeUnlockDialNonce, nonce, StringComparison.Ordinal) &&
                inboundRuntimeUnlockDialPayerDecisionId == offer.PayerDecisionId;
            if (inboundRuntimeUnlockDialPending != 0)
            {
                reason = sameOffer
                    ? "dial_pending"
                    : "other_dial_pending";
                return false;
            }

            if (sameOffer &&
                !string.IsNullOrWhiteSpace(inboundRuntimeUnlockDialTerminalReason))
            {
                reason = inboundRuntimeUnlockDialTerminalReason!;
                return false;
            }

            inboundRuntimeUnlockDialSessionId = sessionId;
            inboundRuntimeUnlockDialNonce = nonce;
            inboundRuntimeUnlockDialPayerDecisionId = offer.PayerDecisionId;
            inboundRuntimeUnlockDialPending = 1;
            inboundRuntimeUnlockDialTerminalReason = null;
        }

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=runtime_unlock_tuna_dial_attempt_started; session_id={SanitizeLogToken(sessionId)}; payer_decision_id={offer.PayerDecisionId}; nonce_len={nonce.Length}");
        reason = "started";
        return true;
    }

    private void CompleteInboundRuntimeUnlockDialAttempt(
        TransportAccelerationOfferPayload offer,
        bool accepted,
        string reason)
    {
        var sessionId = string.IsNullOrWhiteSpace(offer.SessionId)
            ? currentSessionSecurityState.SessionId?.Value ?? string.Empty
            : offer.SessionId.Trim();
        var nonce = string.IsNullOrWhiteSpace(offer.Nonce) ? string.Empty : offer.Nonce.Trim();
        var normalizedReason = SanitizeLogToken(reason);
        var matched = false;
        lock (accelerationGate)
        {
            matched =
                inboundRuntimeUnlockDialPending != 0 &&
                string.Equals(inboundRuntimeUnlockDialSessionId, sessionId, StringComparison.Ordinal) &&
                string.Equals(inboundRuntimeUnlockDialNonce, nonce, StringComparison.Ordinal) &&
                inboundRuntimeUnlockDialPayerDecisionId == offer.PayerDecisionId;
            if (!matched)
            {
                return;
            }

            inboundRuntimeUnlockDialPending = 0;
            if (accepted)
            {
                inboundRuntimeUnlockDialSessionId = null;
                inboundRuntimeUnlockDialNonce = null;
                inboundRuntimeUnlockDialPayerDecisionId = 0;
                inboundRuntimeUnlockDialTerminalReason = null;
            }
            else
            {
                inboundRuntimeUnlockDialTerminalReason = normalizedReason;
            }
        }

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=runtime_unlock_tuna_dial_attempt_{(accepted ? "connected" : "failed")}; session_id={SanitizeLogToken(sessionId)}; payer_decision_id={offer.PayerDecisionId}; reason={SanitizeLogToken(normalizedReason)}; nonce_len={nonce.Length}");
    }

    private long BeginPendingAccelerationAnswerAck(
        TransportAccelerationOfferPayload offer,
        NknAccelerationLaneKind lanes,
        AccelerationReplyTargetEvidence replyTarget)
    {
        var sessionId = string.IsNullOrWhiteSpace(offer.SessionId)
            ? currentSessionSecurityState.SessionId?.Value ?? string.Empty
            : offer.SessionId.Trim();
        var nonce = string.IsNullOrWhiteSpace(offer.Nonce) ? string.Empty : offer.Nonce.Trim();
        lock (accelerationGate)
        {
            RetireOutboundAccelerationOfferLocked(sessionId, "accepted_peer_offer");
            accelerationSessionId = null;
            accelerationNegotiatedLanes = NknAccelerationLaneKind.None;
            pendingAccelerationAnswerAckSessionId = sessionId;
            pendingAccelerationAnswerAckNonce = nonce;
            pendingAccelerationAnswerAckTrigger = SanitizeLogToken(offer.Trigger);
            pendingAccelerationAnswerAckLanes = lanes;
            pendingAccelerationAnswerAckPayerDecisionId = offer.PayerDecisionId;
            pendingAccelerationAnswerAckAuthorityMode =
                IsRuntimeUnlockActivationReason(offer.Trigger)
                    ? RuntimeUnlockOfferAuthorityMode.InitialActivation
                    : null;
            var generation = ++pendingAccelerationAnswerAckGeneration;
            pendingAccelerationAnswerAckReplyTarget =
                replyTarget with { LineageGeneration = generation };
            pendingAccelerationAnswerReplyShadow = null;
            return generation;
        }
    }

    private long BeginPendingAccelerationAnswerAck(
        TransportAccelerationOfferPayload offer,
        NknAccelerationLaneKind lanes)
        => BeginPendingAccelerationAnswerAck(
            offer,
            lanes,
            CreateAccelerationReplyTargetEvidence(
                remoteEndpoint ?? string.Empty,
                "legacy_test_boundary",
                offer.SessionId,
                offer.Nonce,
                offer.PayerDecisionId,
                lineageGeneration: 0,
                purpose: "answer"));

    private AccelerationReplyTargetEvidence? GetPendingAccelerationAnswerReplyTarget()
    {
        lock (accelerationGate)
        {
            return pendingAccelerationAnswerAckReplyTarget;
        }
    }

    private AccelerationReplyTargetEvidence UpdatePendingAccelerationAnswerReplyTarget(
        AccelerationReplyTargetEvidence replyTarget,
        long generation)
    {
        lock (accelerationGate)
        {
            if (pendingAccelerationAnswerAckGeneration == generation &&
                string.Equals(pendingAccelerationAnswerAckSessionId, replyTarget.SessionId, StringComparison.Ordinal) &&
                string.Equals(pendingAccelerationAnswerAckNonce, replyTarget.Nonce, StringComparison.Ordinal) &&
                pendingAccelerationAnswerAckPayerDecisionId == replyTarget.PayerDecisionId)
            {
                pendingAccelerationAnswerAckReplyTarget =
                    replyTarget with { LineageGeneration = generation };
                if (pendingAccelerationAnswerReplyShadow is { } shadow &&
                    shadow.PendingGeneration == generation)
                {
                    pendingAccelerationAnswerReplyShadow = shadow with
                    {
                        ReplyTarget = pendingAccelerationAnswerAckReplyTarget,
                    };
                }
            }

            return pendingAccelerationAnswerAckReplyTarget ?? replyTarget;
        }
    }

    private PendingAccelerationReplyShadow? BindPendingAccelerationAnswerReplyShadow(
        Envelope envelope,
        AccelerationReplyTargetEvidence replyTarget,
        string sessionId,
        string nonce,
        long payerDecisionId,
        long generation,
        long deadlineUtcMs,
        out bool workerCreated)
    {
        lock (accelerationGate)
        {
            workerCreated = false;
            if (!IsPendingAccelerationAnswerAck(
                    sessionId,
                    nonce,
                    payerDecisionId,
                    generation))
            {
                return null;
            }

            if (pendingAccelerationAnswerReplyShadow is { } current)
            {
                return current;
            }

            var shadow = new PendingAccelerationReplyShadow(
                envelope,
                replyTarget,
                sessionId.Trim(),
                nonce.Trim(),
                payerDecisionId,
                generation,
                pendingAccelerationAnswerAckAuthorityMode,
                deadlineUtcMs,
                ++pendingAccelerationReplyWorkerGeneration,
                "answer");
            pendingAccelerationAnswerReplyShadow = shadow;
            workerCreated = true;
            return shadow;
        }
    }

    private bool TryGetCurrentPendingAccelerationReplyShadow(
        PendingAccelerationReplyShadow expected,
        out PendingAccelerationReplyShadow current)
    {
        lock (accelerationGate)
        {
            current = pendingAccelerationAnswerReplyShadow!;
            return current is not null &&
                   current.WorkerGeneration == expected.WorkerGeneration &&
                   current.PendingGeneration == expected.PendingGeneration &&
                   string.Equals(
                       current.Envelope.MessageId,
                       expected.Envelope.MessageId,
                       StringComparison.Ordinal) &&
                   IsPendingAccelerationAnswerAck(
                       current.SessionId,
                       current.Nonce,
                       current.PayerDecisionId,
                       current.PendingGeneration);
        }
    }

    private PendingAccelerationReplyShadow BindPendingAccelerationAnswerAckReplyShadow(
        Envelope envelope,
        AccelerationReplyTargetEvidence replyTarget,
        string sessionId,
        string nonce,
        long payerDecisionId,
        long pendingGeneration,
        long deadlineUtcMs,
        bool runtimeUnlock,
        out bool workerCreated)
    {
        lock (accelerationGate)
        {
            workerCreated = false;
            if (pendingAccelerationAnswerAckReplyShadow is { } current &&
                string.Equals(current.SessionId, sessionId.Trim(), StringComparison.Ordinal) &&
                string.Equals(current.Nonce, nonce.Trim(), StringComparison.Ordinal) &&
                current.PayerDecisionId == payerDecisionId &&
                current.PendingGeneration == pendingGeneration)
            {
                current = current with { ReplyTarget = replyTarget };
                pendingAccelerationAnswerAckReplyShadow = current;
                return current;
            }

            var shadow = new PendingAccelerationReplyShadow(
                envelope,
                replyTarget,
                sessionId.Trim(),
                nonce.Trim(),
                payerDecisionId,
                pendingGeneration,
                runtimeUnlock
                    ? RuntimeUnlockOfferAuthorityMode.InitialActivation
                    : null,
                deadlineUtcMs,
                ++pendingAccelerationReplyWorkerGeneration,
                "answer_ack");
            pendingAccelerationAnswerAckReplyShadow = shadow;
            workerCreated = true;
            return shadow;
        }
    }

    private bool TryGetCurrentPendingAccelerationAnswerAckReplyShadow(
        PendingAccelerationReplyShadow expected,
        out PendingAccelerationReplyShadow current)
    {
        lock (accelerationGate)
        {
            current = pendingAccelerationAnswerAckReplyShadow!;
            return current is not null &&
                   current.WorkerGeneration == expected.WorkerGeneration &&
                   current.PendingGeneration == expected.PendingGeneration &&
                   string.Equals(current.SessionId, expected.SessionId, StringComparison.Ordinal) &&
                   string.Equals(current.Nonce, expected.Nonce, StringComparison.Ordinal) &&
                   current.PayerDecisionId == expected.PayerDecisionId &&
                   string.Equals(
                       current.Envelope.MessageId,
                       expected.Envelope.MessageId,
                       StringComparison.Ordinal);
        }
    }

    private void RetireOutboundAccelerationOfferLocked(string sessionId, string reason)
    {
        if (string.IsNullOrWhiteSpace(outboundAccelerationOfferNonce))
        {
            return;
        }

        retiredAccelerationOfferSessionId = sessionId;
        retiredAccelerationOfferNonce = outboundAccelerationOfferNonce;
        retiredAccelerationOfferTrigger = outboundAccelerationOfferTrigger;
        retiredAccelerationOfferInstallReceipt = outboundAccelerationOfferInstallReceipt;
        retiredRuntimeUnlockOfferAuthorityBoundary =
            outboundRuntimeUnlockOfferAuthorityBoundary;
        retiredAccelerationOfferPayerDecisionId = outboundAccelerationOfferPayerDecisionId;
        retiredAccelerationOfferExpiresUtcMs = DateTimeOffset.UtcNow
            .Add(AccelerationOfferAnswerTimeout)
            .ToUnixTimeMilliseconds();
        ClearOutboundAccelerationOfferLocked();
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=tuna_acceleration_outbound_offer_retired; reason={SanitizeLogToken(reason)}; session_id={SanitizeLogToken(sessionId)}; payer_decision_id={retiredAccelerationOfferPayerDecisionId}");
    }

    private bool RetireRuntimeUnlockOfferForPendingAnswerLocked(string reason)
    {
        if (runtimeUnlockOfferProofState is not { Retired: false } state ||
            outboundRuntimeUnlockOfferAuthorityBoundary is not { } boundary ||
            string.IsNullOrWhiteSpace(outboundAccelerationOfferNonce) ||
            outboundAccelerationOfferGeneration != state.Generation ||
            outboundAccelerationOfferPayerDecisionId != state.PayerDecisionId ||
            !string.Equals(outboundAccelerationOfferNonce, state.Nonce, StringComparison.Ordinal) ||
            boundary.Mode != state.AuthorityMode ||
            boundary.OfferGeneration != state.Generation ||
            boundary.PayerDecisionId != state.PayerDecisionId ||
            !string.Equals(boundary.Nonce, state.Nonce, StringComparison.Ordinal) ||
            !string.Equals(boundary.SessionId, state.SessionId, StringComparison.Ordinal))
        {
            return false;
        }

        if (!state.ObservedSend &&
            !state.PeerReceived &&
            !state.AnswerTimeoutScheduled)
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=tuna_acceleration_pending_runtime_unlock_answer_not_preserved; reason={SanitizeLogToken(reason)}; session_id={SanitizeLogToken(state.SessionId)}; payer_decision_id={state.PayerDecisionId}; generation={state.Generation}; observed_send=0; peer_received=0; answer_timeout_scheduled=0");
            return false;
        }

        if (state.RetiredAnswerExpiresUtcMs > 0 &&
            DateTimeOffset.UtcNow.ToUnixTimeMilliseconds() >=
                state.RetiredAnswerExpiresUtcMs)
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=tuna_acceleration_pending_runtime_unlock_answer_not_preserved; reason={SanitizeLogToken(reason)}; session_id={SanitizeLogToken(state.SessionId)}; payer_decision_id={state.PayerDecisionId}; generation={state.Generation}; observed_send={(state.ObservedSend ? 1 : 0)}; peer_received={(state.PeerReceived ? 1 : 0)}; answer_timeout_scheduled={(state.AnswerTimeoutScheduled ? 1 : 0)}; decision_reason=absolute_answer_deadline_elapsed");
            return false;
        }

        state.Retired = true;
        state.RetiredReason = SanitizeLogToken(reason);
        state.RetryReason = "runtime_unlock_pending_answer_preserved";
        RetireOutboundAccelerationOfferLocked(state.SessionId, reason);
        retiredAccelerationOfferExpiresUtcMs =
            state.RetiredAnswerExpiresUtcMs > 0
                ? state.RetiredAnswerExpiresUtcMs
                : DateTimeOffset.UtcNow
                    .Add(RuntimeUnlockAccelerationOfferAnswerTimeout)
                    .ToUnixTimeMilliseconds();
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=tuna_acceleration_pending_runtime_unlock_answer_preserved; reason={SanitizeLogToken(reason)}; session_id={SanitizeLogToken(state.SessionId)}; payer_decision_id={state.PayerDecisionId}; generation={state.Generation}; observed_send={(state.ObservedSend ? 1 : 0)}; answer_timeout_scheduled={(state.AnswerTimeoutScheduled ? 1 : 0)}");
        return true;
    }

    private bool ShouldPreserveRuntimeUnlockPendingAnswerAcrossResetLocked(string reason)
    {
        var normalizedReason = SanitizeLogToken(reason);
        if (normalizedReason is not "sidecar_payer_yield_to_helpee" and not
            "payer_yield_to_helpee")
        {
            return false;
        }

        if (RetireRuntimeUnlockOfferForPendingAnswerLocked($"{normalizedReason}_pending_runtime_unlock_answer"))
        {
            return true;
        }

        var state = runtimeUnlockOfferProofState;
        return state is
               {
                   Retired: true,
               } &&
               IsRuntimeUnlockPendingAnswerRetiredReason(state.RetiredReason) &&
               !string.IsNullOrWhiteSpace(retiredAccelerationOfferNonce) &&
               string.Equals(retiredAccelerationOfferNonce, state.Nonce, StringComparison.Ordinal) &&
               string.Equals(retiredAccelerationOfferSessionId, state.SessionId, StringComparison.Ordinal) &&
               DateTimeOffset.UtcNow.ToUnixTimeMilliseconds() < retiredAccelerationOfferExpiresUtcMs;
    }

    private bool TryCaptureInterruptedRuntimeUnlockOfferResetRetryLocked(
        string reason,
        out string sessionId,
        out long payerDecisionId,
        out long generation,
        out string retryReason,
        out RuntimeUnlockRetryDispatchInstallReceipt? installReceipt,
        out RuntimeUnlockOfferAuthorityBoundary? authorityBoundary)
    {
        var normalizedReason = SanitizeLogToken(reason);
        sessionId = string.Empty;
        payerDecisionId = 0;
        generation = 0;
        retryReason = string.Empty;
        installReceipt = null;
        authorityBoundary = null;

        if (normalizedReason is not "sidecar_remote_closed" and not "remote_sidecar_remote_closed")
        {
            return false;
        }

        if (!TryGetCurrentRuntimeUnlockOfferAuthorityBoundaryUnsafe(
                out var state,
                out var currentBoundary) ||
            state is null ||
            currentBoundary is null)
        {
            return false;
        }

        if (!state.ObservedSend &&
            !state.PeerReceived &&
            !state.AnswerTimeoutScheduled)
        {
            return false;
        }

        var retiredReason = $"{normalizedReason}_runtime_unlock_offer_reset";
        retryReason = $"runtime_unlock_{normalizedReason}_after_observed_send";
        state.Retired = true;
        state.RetiredReason = retiredReason;
        state.RetryReason = retryReason;
        sessionId = state.SessionId;
        payerDecisionId = state.PayerDecisionId;
        generation = state.Generation;
        installReceipt = outboundAccelerationOfferInstallReceipt;
        authorityBoundary = currentBoundary;
        RetireOutboundAccelerationOfferLocked(state.SessionId, retiredReason);
        return true;
    }

    private bool TryCaptureUnobservedRuntimeUnlockOfferResetRetryLocked(
        string reason,
        out string sessionId,
        out long payerDecisionId,
        out long generation,
        out string retryReason,
        out RuntimeUnlockRetryDispatchInstallReceipt? installReceipt,
        out RuntimeUnlockOfferAuthorityBoundary? authorityBoundary)
    {
        var normalizedReason = SanitizeLogToken(reason);
        sessionId = string.Empty;
        payerDecisionId = 0;
        generation = 0;
        retryReason = string.Empty;
        installReceipt = null;
        authorityBoundary = null;

        if (normalizedReason is not "sidecar_remote_closed" and not "remote_sidecar_remote_closed")
        {
            return false;
        }

        if (!TryGetCurrentRuntimeUnlockOfferAuthorityBoundaryUnsafe(
                out var state,
                out var currentBoundary) ||
            state is null ||
            currentBoundary is null)
        {
            return false;
        }

        if (state.ObservedSend ||
            state.PeerReceived ||
            state.AnswerTimeoutScheduled)
        {
            return false;
        }

        retryReason = $"runtime_unlock_{normalizedReason}";
        state.Retired = true;
        state.RetiredReason = $"{normalizedReason}_unobserved_runtime_unlock_offer_reset";
        state.RetryReason = retryReason;
        sessionId = state.SessionId;
        payerDecisionId = state.PayerDecisionId;
        generation = state.Generation;
        installReceipt = outboundAccelerationOfferInstallReceipt;
        authorityBoundary = currentBoundary;
        return true;
    }

    private static bool IsRuntimeUnlockPendingAnswerRetiredReason(string? reason)
        => reason is
            "payer_yield_pending_runtime_unlock_answer" or
            "sidecar_remote_closed_pending_runtime_unlock_answer" or
            "remote_sidecar_remote_closed_pending_runtime_unlock_answer" or
            "sidecar_payer_yield_to_helpee_pending_runtime_unlock_answer" or
            "payer_yield_to_helpee_pending_runtime_unlock_answer" or
            "runtime_unlock_offer_peer_response_timeout_pending_runtime_unlock_answer";

    private static bool IsPayerYieldRuntimeUnlockPendingAnswerRetiredReason(string? reason)
        => reason is
            "payer_yield_pending_runtime_unlock_answer" or
            "sidecar_payer_yield_to_helpee_pending_runtime_unlock_answer" or
            "payer_yield_to_helpee_pending_runtime_unlock_answer";

    private bool HasPendingRuntimeUnlockAnswerTimeoutTarget(string nonce)
    {
        lock (accelerationGate)
        {
            if (string.Equals(outboundAccelerationOfferNonce, nonce, StringComparison.Ordinal) &&
                outboundRuntimeUnlockOfferAuthorityBoundary is { } currentBoundary &&
                string.Equals(currentBoundary.Nonce, nonce, StringComparison.Ordinal))
            {
                return true;
            }

            var state = runtimeUnlockOfferProofState;
            return state is { Retired: true } &&
                   IsRuntimeUnlockPendingAnswerRetiredReason(state.RetiredReason) &&
                   !string.IsNullOrWhiteSpace(retiredAccelerationOfferNonce) &&
                   string.Equals(retiredAccelerationOfferNonce, nonce, StringComparison.Ordinal) &&
                   string.Equals(retiredAccelerationOfferNonce, state.Nonce, StringComparison.Ordinal) &&
                   string.Equals(retiredAccelerationOfferSessionId, state.SessionId, StringComparison.Ordinal) &&
                   DateTimeOffset.UtcNow.ToUnixTimeMilliseconds() < retiredAccelerationOfferExpiresUtcMs;
        }
    }

    private void ScheduleRuntimeUnlockOfferPeerResponseTimeout(
        string nonce,
        long payerDecisionId,
        long generation,
        string sessionId,
        string? observedLane,
        RuntimeUnlockRetryDispatchInstallReceipt? expectedInstallReceipt = null,
        bool resumedAfterReceiveRecoveryHold = false)
    {
        var timeout = RuntimeUnlockOfferPeerResponseTimeoutOverrideForTests ??
            RuntimeUnlockOfferPeerResponseTimeout;
        var pendingAnswerTimeout =
            AccelerationOfferAnswerTimeoutOverrideForTests ??
            RuntimeUnlockAccelerationOfferAnswerTimeout;
        if (timeout <= TimeSpan.Zero)
        {
            return;
        }

        var offerAuthorityBoundary =
            CaptureRuntimeUnlockOfferAuthorityBoundary(
                nonce,
                payerDecisionId,
                generation);
        if (offerAuthorityBoundary is null)
        {
            return;
        }
        var installedRetry =
            offerAuthorityBoundary.Mode ==
            RuntimeUnlockOfferAuthorityMode.InstalledRetry;
        lock (accelerationGate)
        {
            var proof = runtimeUnlockOfferProofState;
            if (proof is not null &&
                (proof.RetiredAnswerExpiresUtcMs <= 0 ||
                 resumedAfterReceiveRecoveryHold) &&
                proof.Generation == generation &&
                proof.PayerDecisionId == payerDecisionId &&
                string.Equals(
                    proof.SessionId,
                    sessionId,
                    StringComparison.Ordinal) &&
                string.Equals(
                    proof.Nonce,
                    nonce,
                    StringComparison.Ordinal))
            {
                proof.RetiredAnswerExpiresUtcMs =
                    DateTimeOffset.UtcNow
                        .Add(timeout)
                        .Add(pendingAnswerTimeout)
                        .ToUnixTimeMilliseconds();
            }
        }

        _ = Task.Run(
            async () =>
            {
                try
                {
                    await Task.Delay(timeout, CancellationToken.None).ConfigureAwait(false);
                    if (!ValidateRuntimeUnlockOfferAuthorityBoundary(
                            offerAuthorityBoundary,
                            "offer_peer_response_timeout",
                            allowDispatchObservedSettlement: true))
                    {
                        return;
                    }

                    if (disposed || IsAccelerationNegotiatedAndHealthy())
                    {
                        return;
                    }

                    var holdResult =
                        await WaitForRuntimeUnlockInitialActivationReceiveRecoveryTimeoutHoldAsync(
                                offerAuthorityBoundary,
                                RuntimeUnlockInitialActivationReceiveRecoveryHoldBoundary
                                    .PeerResponseTimeout,
                                "offer_peer_response_timeout_hold_released")
                            .ConfigureAwait(false);
                    if (!IsRuntimeUnlockInitialActivationReceiveRecoveryHoldReleased(
                            holdResult))
                    {
                        return;
                    }
                    if (ShouldResumeRuntimeUnlockInitialActivationSameGeneration(
                            holdResult))
                    {
                        if (IsRuntimeUnlockInitialActivationEnvelopeRefreshReplayRequired())
                        {
                            await ReplayCommittedRuntimeUnlockInitialActivationEnvelopeAfterHoldAsync(
                                offerAuthorityBoundary,
                                holdResult,
                                "peer_response_timeout")
                                .ConfigureAwait(false);
                            return;
                        }

                        ScheduleRuntimeUnlockOfferPeerResponseTimeout(
                            nonce,
                            payerDecisionId,
                            generation,
                            sessionId,
                            observedLane,
                            expectedInstallReceipt,
                            resumedAfterReceiveRecoveryHold: true);
                        return;
                    }

                    RuntimeUnlockOfferProofState? timedOutOffer = null;
                    RuntimeUnlockRecoveryRetryState? cutThroughTimedOutState = null;
                    var pendingAnswerPreserved = false;
                    lock (accelerationGate)
                    {
                        var offer = runtimeUnlockOfferProofState;
                        var contract = installedRetry
                            ? runtimeUnlockRecoveryRetryState
                            : null;
                        if (offer is null ||
                            offer.Retired ||
                            offer.PeerReceived ||
                            offer.Generation != generation ||
                            offer.PayerDecisionId != payerDecisionId ||
                            !string.Equals(offer.Nonce, nonce, StringComparison.Ordinal) ||
                            !offer.ObservedSend ||
                            !offer.AnswerTimeoutScheduled ||
                            outboundAccelerationOfferGeneration != generation ||
                            outboundAccelerationOfferPayerDecisionId != payerDecisionId ||
                            !string.Equals(outboundAccelerationOfferNonce, nonce, StringComparison.Ordinal) ||
                            (installedRetry &&
                             (contract is null ||
                              contract.ContractState is SessionRecoveryContractState.Completed or SessionRecoveryContractState.Failed ||
                              !string.Equals(contract.SessionId, sessionId.Trim(), StringComparison.Ordinal) ||
                              contract.CurrentOfferGeneration != generation ||
                              !contract.ObservedSendPending ||
                              contract.RetryObserved ||
                              expectedInstallReceipt is not { } receipt ||
                              outboundAccelerationOfferInstallReceipt != receipt ||
                              !TryValidateRuntimeUnlockRetryDispatchInstallReceiptCurrentUnsafe(
                                  contract,
                                  receipt,
                                  out _,
                                  allowDispatchObservedSettlement: true))))
                        {
                            return;
                        }

                        pendingAnswerPreserved = RetireRuntimeUnlockOfferForPendingAnswerLocked(
                            "runtime_unlock_offer_peer_response_timeout_pending_runtime_unlock_answer");
                        if (!pendingAnswerPreserved)
                        {
                            offer.Retired = true;
                            offer.RetiredReason = "runtime_unlock_offer_peer_response_timeout";
                            offer.RetryReason = "runtime_unlock_offer_peer_response_timeout";
                            RetireOutboundAccelerationOfferLocked(offer.SessionId, "runtime_unlock_offer_peer_response_timeout");
                        }

                        if (installedRetry && contract is not null)
                        {
                            contract.ObservedSendPending = false;
                            contract.RetryAuthorityPending = false;
                            contract.AuthorityFailureReason = pendingAnswerPreserved
                                ? "runtime_unlock_pending_answer_preserved"
                                : "runtime_unlock_offer_peer_response_timeout";
                            if (!pendingAnswerPreserved &&
                                contract.CutThroughActive &&
                                !contract.CutThroughPeerReceived)
                            {
                                cutThroughTimedOutState = contract;
                                if (contract.CutThroughAttempt >= RuntimeUnlockCutThroughMaxAttempts)
                                {
                                    contract.AuthorityFailureReason = "runtime_unlock_peer_response_not_received";
                                }
                            }
                        }

                        timedOutOffer = offer;
                    }

                    if (timedOutOffer is null)
                    {
                        return;
                    }

                    LocalOperationalLog.Warn(
                        "NKN.Tuna",
                        $"event=tuna_acceleration_runtime_unlock_offer_peer_response_timeout; timeout_ms={(long)timeout.TotalMilliseconds}; session_id={SanitizeLogToken(timedOutOffer.SessionId)}; payer_decision_id={timedOutOffer.PayerDecisionId}; generation={timedOutOffer.Generation}; observed_lane={SanitizeLogToken(observedLane ?? timedOutOffer.ObservedSendLane)}");
                    if (pendingAnswerPreserved)
                    {
                        LocalOperationalLog.Info(
                            "NKN.Tuna",
                            $"event=runtime_unlock_offer_peer_response_timeout_pending_answer_preserved; session_id={SanitizeLogToken(timedOutOffer.SessionId)}; payer_decision_id={timedOutOffer.PayerDecisionId}; generation={timedOutOffer.Generation}; observed_lane={SanitizeLogToken(observedLane ?? timedOutOffer.ObservedSendLane)}; answer_timeout_scheduled=1; retry_scheduled=0; retry_after_recovery_armed=0; recovery_requested=0");
                        NotifyTransportAccelerationStateChanged("runtime_unlock_pending_answer_preserved");
                        TryResumeFileTransferDataSessionsAfterTunaActivationNegotiation(
                            "runtime_unlock_pending_answer_regular_v4_resumed",
                            timedOutOffer.SessionId,
                            "runtime_unlock_pending_answer_preserved");
                        return;
                    }

                    NotifyTransportAccelerationStateChanged("activation_offer_not_observed");
                    TryResumeFileTransferDataSessionsAfterTunaActivationNegotiation(
                        "tuna_activation_failed_regular_v4_resumed",
                        timedOutOffer.SessionId,
                        "runtime_unlock_offer_peer_response_timeout");

                    if (!installedRetry)
                    {
                        var retryScheduled =
                            ScheduleRuntimeUnlockOfferAuthorityRetry(
                                "runtime_unlock_offer_peer_response_timeout",
                                offerAuthorityBoundary,
                                expectedInstallReceipt: null);
                        LocalOperationalLog.Warn(
                            "NKN.Tuna",
                            $"event=tuna_acceleration_activation_offer_not_observed; trigger={SanitizeLogToken(timedOutOffer.Trigger)}; session_id={SanitizeLogToken(timedOutOffer.SessionId)}; payer_decision_id={timedOutOffer.PayerDecisionId}; generation={timedOutOffer.Generation}; authority_mode={SanitizeLogToken(RuntimeUnlockOfferAuthorityMode.InitialActivation.ToString())}; interruption_reason=runtime_unlock_offer_peer_response_timeout; retry_scheduled={(retryScheduled ? 1 : 0)}; retry_after_recovery_armed=0; replay_scheduled=0; answer_timeout_scheduled=0; recovery_requested=0; recovery_reason=initial_activation_peer_response_timeout");
                        return;
                    }

                    if (cutThroughTimedOutState is not null)
                    {
                        if (FailRuntimeUnlockRegularV4ActivationWindowIfUnproven(
                                timedOutOffer.SessionId,
                                timedOutOffer.Generation,
                                "runtime_unlock_offer_peer_response_timeout",
                                "runtime_unlock_regular_v4_peer_visible_window_failed"))
                        {
                            LocalOperationalLog.Warn(
                                "NKN.Tuna",
                                $"event=tuna_acceleration_activation_offer_not_observed; trigger={SanitizeLogToken(timedOutOffer.Trigger)}; session_id={SanitizeLogToken(timedOutOffer.SessionId)}; payer_decision_id={timedOutOffer.PayerDecisionId}; generation={timedOutOffer.Generation}; interruption_reason=runtime_unlock_offer_peer_response_timeout; retry_scheduled=0; retry_after_recovery_armed=0; replay_scheduled=0; answer_timeout_scheduled=0; recovery_requested=0; recovery_reason=runtime_unlock_regular_v4_peer_visible_window_failed");
                            return;
                        }

                        FailRuntimeUnlockRecoveryContractIfActive(
                            timedOutOffer.SessionId,
                            "runtime_unlock_peer_response_not_received");
                        RuntimeUnlockRecoveryRetryState? failedCutThroughState;
                        lock (accelerationGate)
                        {
                            var state = runtimeUnlockRecoveryRetryState;
                            failedCutThroughState = state is not null &&
                                state.ContractGeneration == cutThroughTimedOutState.ContractGeneration &&
                                state.ContractState == SessionRecoveryContractState.Failed
                                    ? state
                                    : null;
                        }

                        LocalOperationalLog.Warn(
                            "NKN.Tuna",
                            $"event=runtime_unlock_cutthrough_failed; session_id={SanitizeLogToken(cutThroughTimedOutState.SessionId)}; payer_decision_id={timedOutOffer.PayerDecisionId}; offer_generation={timedOutOffer.Generation}; contract_generation={cutThroughTimedOutState.ContractGeneration}; attempt={cutThroughTimedOutState.CutThroughAttempt}; max_attempts={RuntimeUnlockCutThroughMaxAttempts}; reason=runtime_unlock_peer_response_not_received");
                        if (failedCutThroughState is not null)
                        {
                            LogRuntimeUnlockRecoveryContract(
                                "session_recovery_contract_failed",
                                failedCutThroughState.SessionId);
                        }

                        LocalOperationalLog.Warn(
                            "NKN.Tuna",
                            $"event=tuna_acceleration_activation_offer_not_observed; trigger={SanitizeLogToken(timedOutOffer.Trigger)}; session_id={SanitizeLogToken(timedOutOffer.SessionId)}; payer_decision_id={timedOutOffer.PayerDecisionId}; generation={timedOutOffer.Generation}; interruption_reason=runtime_unlock_offer_peer_response_timeout; retry_scheduled=0; retry_after_recovery_armed=0; replay_scheduled=0; answer_timeout_scheduled=0; recovery_requested=0; recovery_reason=runtime_unlock_peer_response_not_received");
                        return;
                    }

                    if (FailRuntimeUnlockRegularV4ActivationWindowIfUnproven(
                            timedOutOffer.SessionId,
                            timedOutOffer.Generation,
                            "runtime_unlock_offer_peer_response_timeout",
                            "runtime_unlock_regular_v4_peer_visible_window_failed"))
                    {
                        LocalOperationalLog.Warn(
                            "NKN.Tuna",
                            $"event=tuna_acceleration_activation_offer_not_observed; trigger={SanitizeLogToken(timedOutOffer.Trigger)}; session_id={SanitizeLogToken(timedOutOffer.SessionId)}; payer_decision_id={timedOutOffer.PayerDecisionId}; generation={timedOutOffer.Generation}; interruption_reason=runtime_unlock_offer_peer_response_timeout; retry_scheduled=0; retry_after_recovery_armed=0; replay_scheduled=0; answer_timeout_scheduled=0; recovery_requested=0; recovery_reason=runtime_unlock_regular_v4_peer_visible_window_failed");
                        return;
                    }

                    var recoveryRequested = TryRequestFileTransferTunaActivationOfferSendRecovery(
                        "offer_peer_response",
                        timedOutOffer.SessionId,
                        "peer_response_timeout_without_peer_response",
                        offerAuthorityBoundary,
                        out var recoveryReason,
                        out var recoverySessionId);
                    LocalOperationalLog.Warn(
                        "NKN.Tuna",
                        $"event=tuna_acceleration_activation_offer_not_observed; trigger={SanitizeLogToken(timedOutOffer.Trigger)}; session_id={SanitizeLogToken(timedOutOffer.SessionId)}; payer_decision_id={timedOutOffer.PayerDecisionId}; generation={timedOutOffer.Generation}; interruption_reason=runtime_unlock_offer_peer_response_timeout; retry_scheduled={(recoveryRequested ? 0 : 1)}; retry_after_recovery_armed={(recoveryRequested ? 1 : 0)}; replay_scheduled=0; answer_timeout_scheduled=0; recovery_requested={(recoveryRequested ? 1 : 0)}; recovery_reason={SanitizeLogToken(recoveryReason)}; peer_received=0");
                    var listenerReadyReuse =
                        ShouldUseListenerReadyFastRetry(
                            "runtime_unlock_offer_peer_response_timeout",
                            runtimeUnlockRetry: true);
                    if (listenerReadyReuse)
                    {
                        LocalOperationalLog.Info(
                            "NKN.Tuna",
                            $"event=session_recovery_contract_listener_rearm_skipped; session_id={SanitizeLogToken(timedOutOffer.SessionId)}; reason=runtime_unlock_offer_peer_response_timeout; trigger=peer_response_timeout; payer_decision_id={timedOutOffer.PayerDecisionId}; listener_ready_reuse=1");
                    }
                    else
                    {
                        LocalOperationalLog.Warn(
                            "NKN.Tuna",
                            $"event=session_recovery_contract_listener_rearm_required; session_id={SanitizeLogToken(timedOutOffer.SessionId)}; reason=runtime_unlock_offer_peer_response_timeout; trigger=peer_response_timeout; payer_decision_id={timedOutOffer.PayerDecisionId}; listener_ready_reuse=0");
                        ScheduleAccelerationLaneStop("runtime_unlock_offer_peer_response_timeout");
                    }

                    if (recoveryRequested)
                    {
                        ArmRuntimeUnlockRetryAfterRecovery(
                            timedOutOffer.Generation,
                            recoverySessionId ?? timedOutOffer.SessionId,
                            "runtime_unlock_offer_peer_response_timeout",
                            recoveryReason ?? "tuna_activation_offer_peer_response_timeout",
                            requiresLocalListenerRetry: !listenerReadyReuse,
                            listenerReadyReuse
                                ? RuntimeUnlockRetryDispatchListenerRearmRequirement.None
                                : RuntimeUnlockRetryDispatchListenerRearmRequirement.Required,
                            offerAuthorityBoundary);
                    }
                    else
                    {
                        ScheduleRuntimeUnlockOfferAuthorityRetry(
                            "runtime_unlock_offer_peer_response_timeout",
                            offerAuthorityBoundary,
                            expectedInstallReceipt);
                    }
                }
                catch (Exception ex) when (ex is not OperationCanceledException)
                {
                    LocalOperationalLog.Warn(
                        "NKN.Tuna",
                        $"event=tuna_acceleration_runtime_unlock_offer_peer_response_timeout_failed; error={ex.GetType().Name}");
                }
            },
            CancellationToken.None);
    }

    private void ClearOutboundAccelerationOfferLocked()
    {
        outboundAccelerationOfferNonce = null;
        outboundAccelerationOfferTrigger = null;
        outboundAccelerationOfferInstallReceipt = null;
        outboundRuntimeUnlockOfferAuthorityBoundary = null;
        outboundAccelerationOfferPayerDecisionId = 0;
        runtimeUnlockInitialActivationEnvelopeState = null;
        lastRuntimeUnlockInitialActivationEnvelopeRefreshReceipt = null;
    }

    private void ClearRetiredOutboundAccelerationOfferLocked()
    {
        retiredAccelerationOfferSessionId = null;
        retiredAccelerationOfferNonce = null;
        retiredAccelerationOfferTrigger = null;
        retiredAccelerationOfferInstallReceipt = null;
        retiredRuntimeUnlockOfferAuthorityBoundary = null;
        retiredAccelerationOfferPayerDecisionId = 0;
        retiredAccelerationOfferExpiresUtcMs = 0;
    }

    private long GetPendingAccelerationAnswerAckGeneration()
    {
        lock (accelerationGate)
        {
            return pendingAccelerationAnswerAckGeneration;
        }
    }

    private bool IsPendingAccelerationAnswerAck(
        string? sessionId,
        string? nonce,
        long payerDecisionId,
        long generation)
    {
        var normalizedSessionId = string.IsNullOrWhiteSpace(sessionId) ? string.Empty : sessionId.Trim();
        var normalizedNonce = string.IsNullOrWhiteSpace(nonce) ? string.Empty : nonce.Trim();
        lock (accelerationGate)
        {
            return generation > 0 &&
                   pendingAccelerationAnswerAckGeneration == generation &&
                   string.Equals(pendingAccelerationAnswerAckSessionId, normalizedSessionId, StringComparison.Ordinal) &&
                   string.Equals(pendingAccelerationAnswerAckNonce, normalizedNonce, StringComparison.Ordinal) &&
                   pendingAccelerationAnswerAckPayerDecisionId == payerDecisionId;
        }
    }

    private void ClearPendingAccelerationAnswerAckLocked()
    {
        pendingAccelerationAnswerAckSessionId = null;
        pendingAccelerationAnswerAckNonce = null;
        pendingAccelerationAnswerAckTrigger = null;
        pendingAccelerationAnswerAckLanes = NknAccelerationLaneKind.None;
        pendingAccelerationAnswerAckPayerDecisionId = 0;
        pendingAccelerationAnswerAckAuthorityMode = null;
        pendingAccelerationAnswerAckReplyTarget = null;
        pendingAccelerationAnswerReplyShadow = null;
        pendingAccelerationAnswerAckReplyShadow = null;
        pendingAccelerationAnswerAckGeneration++;
        SchedulePendingRuntimeUnlockAccelerationNegotiationAfterCurrentOperationUnsafe("answer_ack_cleared");
    }

    private bool RetirePendingAccelerationAnswerAckForRuntimeUnlockListenerRearm(
        string sessionId,
        string recoveryReason,
        string trigger)
    {
        string? pendingTrigger;
        long payerDecisionId;
        long generation;
        NknAccelerationLaneKind lanes;
        var normalizedSessionId = string.IsNullOrWhiteSpace(sessionId) ? string.Empty : sessionId.Trim();
        if (string.IsNullOrWhiteSpace(normalizedSessionId))
        {
            return false;
        }

        lock (accelerationGate)
        {
            if (string.IsNullOrWhiteSpace(pendingAccelerationAnswerAckNonce) ||
                !string.Equals(pendingAccelerationAnswerAckSessionId, normalizedSessionId, StringComparison.Ordinal))
            {
                return false;
            }

            pendingTrigger = pendingAccelerationAnswerAckTrigger;
            payerDecisionId = pendingAccelerationAnswerAckPayerDecisionId;
            generation = pendingAccelerationAnswerAckGeneration;
            lanes = pendingAccelerationAnswerAckLanes;
            ClearPendingAccelerationAnswerAckLocked();
        }

        LocalOperationalLog.Warn(
            "NKN.Tuna",
            $"event=tuna_acceleration_pending_answer_ack_retired_for_listener_rearm; session_id={SanitizeLogToken(normalizedSessionId)}; payer_decision_id={payerDecisionId}; generation={generation}; lanes={FormatAccelerationLanesForLog(lanes)}; pending_trigger={SanitizeLogToken(pendingTrigger)}; recovery_reason={SanitizeLogToken(recoveryReason)}; trigger={SanitizeLogToken(trigger)}");
        return true;
    }

    private TimeSpan ResolveAccelerationAnswerAckTimeout(
        string sessionId,
        string nonce,
        long payerDecisionId,
        long generation)
    {
        if (AccelerationAnswerAckTimeoutOverrideForTests is { } overrideTimeout)
        {
            return overrideTimeout;
        }

        lock (accelerationGate)
        {
            return IsPendingAccelerationAnswerAck(sessionId, nonce, payerDecisionId, generation) &&
                   pendingAccelerationAnswerAckAuthorityMode is not null
                ? RuntimeUnlockAccelerationAnswerAckTimeout
                : AccelerationAnswerAckTimeout;
        }
    }

    private void ScheduleAccelerationAnswerAckTimeout(
        string sessionId,
        string nonce,
        long payerDecisionId,
        long generation)
        => ScheduleAccelerationAnswerAckTimeoutForReply(
            sessionId,
            nonce,
            payerDecisionId,
            generation,
            replyShadow: null);

    private void ScheduleAccelerationAnswerAckTimeoutForReply(
        string sessionId,
        string nonce,
        long payerDecisionId,
        long generation,
        PendingAccelerationReplyShadow? replyShadow)
    {
        if (generation <= 0)
        {
            return;
        }

        var timeout = AccelerationAnswerAckTimeoutOverrideForTests is { } overrideTimeout
            ? overrideTimeout
            : replyShadow is { AuthorityMode: not null }
            ? TimeSpan.FromMilliseconds(Math.Max(
                0,
                replyShadow.DeadlineUtcMs -
                DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()))
            : ResolveAccelerationAnswerAckTimeout(
                sessionId,
                nonce,
                payerDecisionId,
                generation);
        timeout = timeout <= TimeSpan.Zero ? TimeSpan.FromMilliseconds(1) : timeout;

        _ = Task.Run(
            async () =>
            {
                try
                {
                    await Task.Delay(timeout, CancellationToken.None).ConfigureAwait(false);
                    if (disposed ||
                        !IsPendingAccelerationAnswerAck(sessionId, nonce, payerDecisionId, generation) ||
                        (replyShadow is not null &&
                         !TryGetCurrentPendingAccelerationReplyShadow(
                             replyShadow,
                             out _)))
                    {
                        return;
                    }

                    string? pendingTrigger;
                    RuntimeUnlockOfferAuthorityMode? pendingAuthorityMode;
                    lock (accelerationGate)
                    {
                        if (!IsPendingAccelerationAnswerAck(sessionId, nonce, payerDecisionId, generation))
                        {
                            return;
                        }

                        pendingTrigger = pendingAccelerationAnswerAckTrigger;
                        pendingAuthorityMode =
                            pendingAccelerationAnswerAckAuthorityMode;
                    }

                    var runtimeUnlockAnswerAck =
                        pendingAuthorityMode is not null;

                    lock (accelerationGate)
                    {
                        if (!IsPendingAccelerationAnswerAck(
                                sessionId,
                                nonce,
                                payerDecisionId,
                             generation) ||
                            pendingAccelerationAnswerAckAuthorityMode !=
                                pendingAuthorityMode)
                        {
                            return;
                        }

                        ClearPendingAccelerationAnswerAckLocked();
                    }

                    var timeoutReason = runtimeUnlockAnswerAck
                        ? "runtime_unlock_answer_ack_timeout"
                        : "answer_ack_timeout";
                    LocalOperationalLog.Warn(
                        "NKN.Tuna",
                        $"event=tuna_acceleration_answer_ack_timeout; session_id={SanitizeLogToken(sessionId)}; timeout_ms={(long)timeout.TotalMilliseconds}; payer_decision_id={payerDecisionId}; generation={generation}; trigger={SanitizeLogToken(pendingTrigger)}; reply_deadline_utc_ms={replyShadow?.DeadlineUtcMs ?? 0}; delivery_evidence=local_submission_only; retry_reason={SanitizeLogToken(timeoutReason)}");
                    ResumeFileTransferDataSessionsAfterTunaActivationNegotiation(
                        timeoutReason,
                        sessionId,
                        "answer_ack_timeout");
                    NotifyTransportAccelerationStateChanged(timeoutReason);
                    ScheduleAccelerationLaneStop(timeoutReason);
                    if (runtimeUnlockAnswerAck)
                    {
                        ScheduleInitialRuntimeUnlockAccelerationNegotiationRetry(
                            timeoutReason);
                    }
                    else
                    {
                        ScheduleAccelerationNegotiationRetry(timeoutReason);
                    }
                }
                catch (Exception ex) when (ex is not OperationCanceledException)
                {
                    LocalOperationalLog.Warn(
                        "NKN.Tuna",
                        $"event=tuna_acceleration_answer_ack_timeout_failed; error={ex.GetType().Name}");
                }
            },
            CancellationToken.None);
    }

    private static AccelerationReplyTargetEvidence CreateAccelerationReplyTargetEvidence(
        string source,
        string inboundMessageId,
        string sessionId,
        string nonce,
        long payerDecisionId,
        long lineageGeneration,
        string purpose)
    {
        var target = source.Trim();
        var peerFingerprint = Convert.ToHexString(
                SHA256.HashData(Encoding.UTF8.GetBytes(target)))
            .ToLowerInvariant();
        return new AccelerationReplyTargetEvidence(
            target,
            peerFingerprint,
            inboundMessageId.Trim(),
            sessionId.Trim(),
            nonce.Trim(),
            payerDecisionId,
            lineageGeneration,
            purpose);
    }

    private bool ValidateAccelerationReplyTarget(
        AccelerationReplyTargetEvidence replyTarget,
        string sessionId,
        string nonce,
        long payerDecisionId,
        string boundary)
    {
        var expectedSessionId = currentSessionSecurityState.SessionId?.Value;
        var expectedSource = ResolveExpectedRemotePeerAddressForCurrentSession();
        var valid =
            !disposed &&
            !string.IsNullOrWhiteSpace(replyTarget.Target) &&
            string.Equals(replyTarget.SessionId, sessionId.Trim(), StringComparison.Ordinal) &&
            string.Equals(replyTarget.SessionId, expectedSessionId, StringComparison.Ordinal) &&
            string.Equals(replyTarget.Nonce, nonce.Trim(), StringComparison.Ordinal) &&
            replyTarget.PayerDecisionId == payerDecisionId &&
            AddressMatchesForSessionPolicy(replyTarget.Target, expectedSource);
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=runtime_unlock_acceleration_reply_target_decided; purpose={SanitizeLogToken(replyTarget.Purpose)}; boundary={SanitizeLogToken(boundary)}; status={(valid ? "accepted" : "rejected")}; target_mode=validated_inbound_source; target_peer_fingerprint={replyTarget.PeerFingerprint}; inbound_msg_id={SanitizeLogToken(replyTarget.InboundMessageId)}; session_id={SanitizeLogToken(replyTarget.SessionId)}; payer_decision_id={replyTarget.PayerDecisionId}; generation={replyTarget.LineageGeneration}; reason={(valid ? "exact_validated_source" : "reply_target_not_current")}");
        return valid;
    }

    private async Task SendAccelerationAnswerAsync(
        TransportAccelerationOfferPayload offer,
        AccelerationReplyTargetEvidence replyTarget,
        bool accepted,
        NknAccelerationLaneKind lanes,
        string? rejectReason,
        long pendingAnswerAckGeneration,
        CancellationToken ct,
        bool scheduleReplay = true)
    {
        if (!ValidateAccelerationReplyTarget(
                replyTarget,
                offer.SessionId,
                offer.Nonce,
                offer.PayerDecisionId,
                "answer_send") ||
            !TryGetCurrentEnvelopeCode(out var envelopeCode))
        {
            return;
        }

        var answer = new TransportAccelerationAnswerPayload
        {
            SessionId = offer.SessionId,
            Accepted = accepted,
            SupportedLanes = NknAccelerationLaneCodec.ToNames(lanes),
            ExpiresAtUnixMs = Math.Min(offer.ExpiresAtUnixMs, DateTimeOffset.UtcNow.Add(AccelerationOfferLifetime).ToUnixTimeMilliseconds()),
            Nonce = offer.Nonce,
            SidecarProtocolVersion = TunaSidecarProtocolVersion,
            RejectReason = accepted ? null : rejectReason,
            PayerDecisionId = offer.PayerDecisionId,
        };
        var payload = CreateSecureControlPayload(
            MsgType.TransportAccelerationAnswer,
            offer.Nonce,
            JsonSerializer.SerializeToUtf8Bytes(answer));
        var envelope = CreateEnvelope(envelopeCode, MsgType.TransportAccelerationAnswer, payload, replyTo: null);
        var requireRuntimeUnlockAnswerObservedSend =
            accepted &&
            pendingAnswerAckGeneration > 0 &&
            IsPendingAccelerationAnswerAckForSession(offer.SessionId);
        PendingAccelerationReplyShadow? replyShadow = null;
        var replayWorkerCreated = false;
        if (accepted && pendingAnswerAckGeneration > 0)
        {
            replyShadow = BindPendingAccelerationAnswerReplyShadow(
                envelope,
                replyTarget,
                answer.SessionId,
                answer.Nonce,
                answer.PayerDecisionId,
                pendingAnswerAckGeneration,
                answer.ExpiresAtUnixMs,
                out replayWorkerCreated);
            if (replyShadow is null)
            {
                return;
            }

            envelope = replyShadow.Envelope;
            replyTarget = replyShadow.ReplyTarget;
        }

        var queued = await SendAccelerationControlEnvelopeWithBulkBypassAsync(
                replyTarget.Target,
                envelope,
                "answer",
                ct,
                requireRuntimeUnlockAnswerObservedSend,
                offer.SessionId)
            .ConfigureAwait(false);
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=tuna_acceleration_answer_{(queued.Succeeded ? "sent" : "rejected")}; accepted={(accepted ? 1 : 0)}; reason={SanitizeLogToken(rejectReason)}; lanes={string.Join(",", answer.SupportedLanes)}; payer_decision_id={answer.PayerDecisionId}; generation={pendingAnswerAckGeneration}; target_mode=validated_inbound_source; target_peer_fingerprint={replyTarget.PeerFingerprint}; inbound_msg_id={SanitizeLogToken(replyTarget.InboundMessageId)}; msg_id={SanitizeLogToken(envelope.MessageId)}; reply_deadline_utc_ms={replyShadow?.DeadlineUtcMs ?? answer.ExpiresAtUnixMs}; remaining_lifetime_ms={Math.Max(0, (replyShadow?.DeadlineUtcMs ?? answer.ExpiresAtUnixMs) - DateTimeOffset.UtcNow.ToUnixTimeMilliseconds())}; delivery_evidence=local_submission_only");
        if (accepted &&
            pendingAnswerAckGeneration > 0 &&
            replayWorkerCreated &&
            replyShadow is not null &&
            (replyShadow.AuthorityMode is not null || queued.Succeeded))
        {
            ScheduleAccelerationAnswerAckTimeoutForReply(
                answer.SessionId,
                answer.Nonce,
                answer.PayerDecisionId,
                pendingAnswerAckGeneration,
                replyShadow);
            if (scheduleReplay || replyShadow.AuthorityMode is not null)
            {
                ScheduleAccelerationAnswerReplay(
                    replyShadow,
                    ResolveAccelerationAnswerReplayAttempts(),
                    requireRuntimeUnlockAnswerObservedSend);
            }
        }
    }

    private void ScheduleAccelerationAnswerReplay(
        PendingAccelerationReplyShadow replyShadow,
        int maxAttempts = AccelerationAnswerReplayAttempts,
        bool requireObservedSend = false)
    {
        if (replyShadow.PendingGeneration <= 0 ||
            (replyShadow.AuthorityMode is null && maxAttempts <= 0))
        {
            return;
        }

        _ = Task.Run(
            async () =>
            {
                for (var attempt = 1;
                     replyShadow.AuthorityMode is not null || attempt <= maxAttempts;
                     attempt++)
                {
                    try
                    {
                        var remainingMs = replyShadow.DeadlineUtcMs -
                            DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
                        if (remainingMs <= 0)
                        {
                            return;
                        }

                        var delay = ResolveAccelerationAnswerReplayDelay();
                        if (replyShadow.AuthorityMode is not null &&
                            delay.TotalMilliseconds > remainingMs)
                        {
                            delay = TimeSpan.FromMilliseconds(remainingMs);
                        }

                        await Task.Delay(delay, CancellationToken.None).ConfigureAwait(false);
                        if (disposed ||
                            DateTimeOffset.UtcNow.ToUnixTimeMilliseconds() >=
                                replyShadow.DeadlineUtcMs ||
                            !TryGetCurrentPendingAccelerationReplyShadow(
                                replyShadow,
                                out var currentShadow))
                        {
                            return;
                        }

                        var requireReplayObservedSend =
                            requireObservedSend &&
                            IsPendingAccelerationAnswerAckForSession(
                                currentShadow.SessionId);
                        if (!ValidateAccelerationReplyTarget(
                                currentShadow.ReplyTarget,
                                currentShadow.SessionId,
                                currentShadow.Nonce,
                                currentShadow.PayerDecisionId,
                                "answer_replay"))
                        {
                            return;
                        }

                        var queued = await SendAccelerationControlEnvelopeWithBulkBypassAsync(
                                currentShadow.ReplyTarget.Target,
                                currentShadow.Envelope,
                                "answer_replay",
                                CancellationToken.None,
                                requireReplayObservedSend,
                                currentShadow.SessionId)
                            .ConfigureAwait(false);
                        LocalOperationalLog.Info(
                            "NKN.Tuna",
                            $"event=tuna_acceleration_answer_replay_{(queued.Succeeded ? "sent" : "rejected")}; attempt={attempt}; max_attempts={(currentShadow.AuthorityMode is not null ? 0 : maxAttempts)}; session_id={SanitizeLogToken(currentShadow.SessionId)}; payer_decision_id={currentShadow.PayerDecisionId}; generation={currentShadow.PendingGeneration}; target_mode=validated_inbound_source; target_peer_fingerprint={currentShadow.ReplyTarget.PeerFingerprint}; inbound_msg_id={SanitizeLogToken(currentShadow.ReplyTarget.InboundMessageId)}; msg_id={SanitizeLogToken(currentShadow.Envelope.MessageId)}; reply_deadline_utc_ms={currentShadow.DeadlineUtcMs}; remaining_lifetime_ms={Math.Max(0, currentShadow.DeadlineUtcMs - DateTimeOffset.UtcNow.ToUnixTimeMilliseconds())}; delivery_evidence=local_submission_only");
                    }
                    catch (Exception ex) when (ex is not OperationCanceledException)
                    {
                        LocalOperationalLog.Warn(
                            "NKN.Tuna",
                            $"event=tuna_acceleration_answer_replay_failed; attempt={attempt}; error={ex.GetType().Name}");
                    }
                }
            },
            CancellationToken.None);
    }

    private static TimeSpan ResolveAccelerationAnswerReplayDelay()
        => AccelerationAnswerReplayDelayOverrideForTests ?? AccelerationAnswerReplayDelay;

    private static int ResolveAccelerationAnswerReplayAttempts()
    {
        if (AccelerationAnswerReplayAttemptsOverrideForTests is { } overrideAttempts)
        {
            return Math.Max(0, overrideAttempts);
        }

        return AccelerationAnswerReplayAttempts;
    }

    private async Task SendAccelerationAnswerAckAsync(
        TransportAccelerationAnswerPayload answer,
        AccelerationReplyTargetEvidence replyTarget,
        NknAccelerationLaneKind lanes,
        CancellationToken ct,
        bool runtimeUnlock = false)
    {
        if (!ValidateAccelerationReplyTarget(
                replyTarget,
                answer.SessionId,
                answer.Nonce,
                answer.PayerDecisionId,
                "answer_ack_send") ||
            !TryGetCurrentEnvelopeCode(out var envelopeCode))
        {
            return;
        }

        var nowMs = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
        var ack = new TransportAccelerationAnswerAckPayload
        {
            SessionId = answer.SessionId,
            Accepted = true,
            SupportedLanes = NknAccelerationLaneCodec.ToNames(lanes),
            SentAtUnixMs = nowMs,
            ExpiresAtUnixMs = Math.Min(answer.ExpiresAtUnixMs, DateTimeOffset.UtcNow.Add(AccelerationOfferLifetime).ToUnixTimeMilliseconds()),
            Nonce = answer.Nonce,
            SidecarProtocolVersion = TunaSidecarProtocolVersion,
            PayerDecisionId = answer.PayerDecisionId,
        };
        var payload = CreateSecureControlPayload(
            MsgType.TransportAccelerationAnswerAck,
            answer.Nonce,
            JsonSerializer.SerializeToUtf8Bytes(ack));
        var envelope = CreateEnvelope(envelopeCode, MsgType.TransportAccelerationAnswerAck, payload, replyTo: null);
        var replyShadow = BindPendingAccelerationAnswerAckReplyShadow(
            envelope,
            replyTarget,
            answer.SessionId,
            answer.Nonce,
            answer.PayerDecisionId,
            replyTarget.LineageGeneration,
            ack.ExpiresAtUnixMs,
            runtimeUnlock,
            out var replayWorkerCreated);
        envelope = replyShadow.Envelope;
        replyTarget = replyShadow.ReplyTarget;
        var queued = await SendAccelerationControlEnvelopeWithBulkBypassAsync(
                replyTarget.Target,
                envelope,
                "answer_ack",
                ct)
            .ConfigureAwait(false);
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=tuna_acceleration_answer_ack_{(queued.Succeeded ? "sent" : "rejected")}; session_id={SanitizeLogToken(answer.SessionId)}; lanes={FormatAccelerationLanesForLog(lanes)}; payer_decision_id={answer.PayerDecisionId}; generation={replyShadow.PendingGeneration}; target_mode=validated_inbound_source; target_peer_fingerprint={replyTarget.PeerFingerprint}; inbound_msg_id={SanitizeLogToken(replyTarget.InboundMessageId)}; msg_id={SanitizeLogToken(envelope.MessageId)}; reply_deadline_utc_ms={replyShadow.DeadlineUtcMs}; remaining_lifetime_ms={Math.Max(0, replyShadow.DeadlineUtcMs - DateTimeOffset.UtcNow.ToUnixTimeMilliseconds())}; delivery_evidence=local_submission_only");
        if (replayWorkerCreated && (runtimeUnlock || queued.Succeeded))
        {
            ScheduleAccelerationAnswerAckReplay(replyShadow);
        }
    }

    private Task SendAccelerationAnswerAckAsync(
        TransportAccelerationAnswerPayload answer,
        NknAccelerationLaneKind lanes,
        CancellationToken ct)
        => SendAccelerationAnswerAckAsync(
            answer,
            CreateAccelerationReplyTargetEvidence(
                remoteEndpoint ?? string.Empty,
                "legacy_test_boundary",
                answer.SessionId,
                answer.Nonce,
                answer.PayerDecisionId,
                lineageGeneration: 0,
                purpose: "answer_ack"),
            lanes,
            ct);

    private Task SendAccelerationAnswerAsync(
        TransportAccelerationOfferPayload offer,
        bool accepted,
        NknAccelerationLaneKind lanes,
        string? rejectReason,
        long pendingAnswerAckGeneration,
        CancellationToken ct)
        => SendAccelerationAnswerAsync(
            offer,
            GetPendingAccelerationAnswerReplyTarget() ??
                CreateAccelerationReplyTargetEvidence(
                    remoteEndpoint ?? string.Empty,
                    "legacy_test_boundary",
                    offer.SessionId,
                    offer.Nonce,
                    offer.PayerDecisionId,
                    pendingAnswerAckGeneration,
                    "answer"),
            accepted,
            lanes,
            rejectReason,
            pendingAnswerAckGeneration,
            ct);

    private void ScheduleAccelerationAnswerAckReplay(
        PendingAccelerationReplyShadow replyShadow)
    {
        _ = Task.Run(
            async () =>
            {
                for (var attempt = 1;
                     replyShadow.AuthorityMode is not null ||
                         attempt <= AccelerationAnswerAckReplayAttempts;
                     attempt++)
                {
                    try
                    {
                        var remainingMs = replyShadow.DeadlineUtcMs -
                            DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
                        if (remainingMs <= 0)
                        {
                            return;
                        }

                        var delay = AccelerationAnswerAckReplayDelay;
                        if (replyShadow.AuthorityMode is not null &&
                            delay.TotalMilliseconds > remainingMs)
                        {
                            delay = TimeSpan.FromMilliseconds(remainingMs);
                        }

                        await Task.Delay(delay, CancellationToken.None).ConfigureAwait(false);
                        if (disposed ||
                            DateTimeOffset.UtcNow.ToUnixTimeMilliseconds() >=
                                replyShadow.DeadlineUtcMs ||
                            !TryGetCurrentPendingAccelerationAnswerAckReplyShadow(
                                replyShadow,
                                out var currentShadow) ||
                            (currentShadow.AuthorityMode is null &&
                             !IsAccelerationNegotiatedAndHealthy()))
                        {
                            return;
                        }

                        if (!ValidateAccelerationReplyTarget(
                                currentShadow.ReplyTarget,
                                currentShadow.SessionId,
                                currentShadow.Nonce,
                                currentShadow.PayerDecisionId,
                                "answer_ack_replay"))
                        {
                            return;
                        }

                        var queued = await SendAccelerationControlEnvelopeWithBulkBypassAsync(
                                currentShadow.ReplyTarget.Target,
                                currentShadow.Envelope,
                                "answer_ack_replay",
                                CancellationToken.None)
                            .ConfigureAwait(false);
                        LocalOperationalLog.Info(
                            "NKN.Tuna",
                            $"event=tuna_acceleration_answer_ack_replay_{(queued.Succeeded ? "sent" : "rejected")}; attempt={attempt}; session_id={SanitizeLogToken(currentShadow.SessionId)}; payer_decision_id={currentShadow.PayerDecisionId}; generation={currentShadow.PendingGeneration}; target_mode=validated_inbound_source; target_peer_fingerprint={currentShadow.ReplyTarget.PeerFingerprint}; inbound_msg_id={SanitizeLogToken(currentShadow.ReplyTarget.InboundMessageId)}; msg_id={SanitizeLogToken(currentShadow.Envelope.MessageId)}; reply_deadline_utc_ms={currentShadow.DeadlineUtcMs}; remaining_lifetime_ms={Math.Max(0, currentShadow.DeadlineUtcMs - DateTimeOffset.UtcNow.ToUnixTimeMilliseconds())}; delivery_evidence=local_submission_only");
                    }
                    catch (Exception ex) when (ex is not OperationCanceledException)
                    {
                        LocalOperationalLog.Warn(
                            "NKN.Tuna",
                            $"event=tuna_acceleration_answer_ack_replay_failed; attempt={attempt}; error={ex.GetType().Name}");
                    }
                }
            },
            CancellationToken.None);
    }

    private async Task<AccelerationControlSendResult> SendAccelerationControlEnvelopeWithBulkBypassAsync(
        string target,
        Envelope envelope,
        string purpose,
        CancellationToken ct,
        bool requireObservedSend = false,
        string? activationSessionId = null,
        Action? onBeforeSend = null,
        Action? onQueueAccepted = null,
        Action? onObservedSendWaitStarted = null,
        Func<string?>? queueAcceptedAsObservedReason = null,
        Func<Task<AccelerationControlSendResult>>? observedSendFallbackAsync = null,
        RuntimeUnlockRetryDispatchInstallReceipt? expectedInstallReceipt = null,
        bool allowDispatchObservedInstallReceipt = false,
        RuntimeUnlockOfferAuthorityBoundary? expectedOfferAuthorityBoundary = null,
        RuntimeUnlockOfferAuthorityMode? expectedOfferAuthorityMode = null,
        long latestSubmissionUtcMs = 0,
        Func<long>?
            rebaseLatestSubmissionAfterInitialActivationHold = null,
        RuntimeUnlockInitialActivationReceiveRecoveryHoldBoundary?
            initialActivationPhysicalHoldBoundary = null,
        RuntimeUnlockInitialActivationReceiveRecoveryHoldPrevalidation?
            initialActivationHoldPrevalidation = null)
    {
        bool ValidateControlSendAuthority(string boundary)
            => expectedOfferAuthorityBoundary is not null
                ? ValidateRuntimeUnlockOfferAuthorityBoundary(
                    expectedOfferAuthorityBoundary,
                    boundary,
                    allowDispatchObservedInstallReceipt)
                : expectedOfferAuthorityMode is { } mode
                    ? ValidatePendingRuntimeUnlockOfferAuthority(
                        mode,
                        expectedInstallReceipt,
                        boundary)
                : ValidateRuntimeUnlockRetryDispatchInstallReceiptBoundary(
                    expectedInstallReceipt,
                    boundary,
                    allowDispatchObservedInstallReceipt);

        if (!ValidateControlSendAuthority("control_send_entry"))
        {
            return AccelerationControlSendResult.StaleCallback;
        }

        var usesInstalledRetryOfferAuthority =
            expectedOfferAuthorityBoundary?.Mode ==
                RuntimeUnlockOfferAuthorityMode.InstalledRetry ||
            expectedOfferAuthorityMode ==
                RuntimeUnlockOfferAuthorityMode.InstalledRetry ||
            (expectedOfferAuthorityBoundary is null &&
             expectedOfferAuthorityMode is null &&
             expectedInstallReceipt is not null);
        RuntimeUnlockRecoveryRetryState? retryAuthorityStateForSend = null;
        RuntimeUnlockRetryDispatchAttempt? retryDispatchAttemptForSend = null;
        RuntimeUnlockInitialActivationReceiveRecoveryHoldPrevalidation
            exactInitialActivationHoldPrevalidation = default;

        bool ValidateRetainedRetryAttempt(string callbackKind)
        {
            if (retryDispatchAttemptForSend is not { } retainedAttempt ||
                retryAuthorityStateForSend?.DispatchContract is not { } retainedContract)
            {
                return true;
            }

            bool attemptCurrent;
            lock (accelerationGate)
            {
                attemptCurrent = ReferenceEquals(
                                     runtimeUnlockRecoveryRetryState?.DispatchContract,
                                     retainedContract) &&
                                 retainedContract.MatchesAttempt(retainedAttempt) &&
                                 (!retainedContract.Lifecycle.IsSettled ||
                                  retainedContract.Lifecycle.SettlementOutcome ==
                                   RuntimeUnlockRetryDispatchSettlementOutcome.DispatchObserved) &&
                                 (expectedInstallReceipt is not { } receipt ||
                                  (retryAuthorityStateForSend is not null &&
                                   runtimeUnlockRetryDispatchInstallShadow.LastCommittedReceipt == receipt &&
                                   retainedContract.Authority == receipt.Authority));
            }

            if (attemptCurrent)
            {
                return true;
            }

            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=runtime_unlock_retry_dispatch_stale_callback_ignored; {FormatRuntimeUnlockRetryDispatchAuthorityTuple(retainedContract.Authority)}; callback_offer_generation={retainedAttempt.OfferGeneration}; bound_offer_generation={retainedContract.OfferGeneration}; callback_kind={SanitizeLogToken(callbackKind)}; decision_reason=dispatch_attempt_no_longer_current");
            return false;
        }

        if (expectedOfferAuthorityBoundary is
            {
                Mode: RuntimeUnlockOfferAuthorityMode.InitialActivation,
                TransferId: { Length: > 0 },
            } initialActivationSendBoundary)
        {
            exactInitialActivationHoldPrevalidation =
                initialActivationHoldPrevalidation ?? default;
            if (!exactInitialActivationHoldPrevalidation.IsReleased)
            {
                if (!TryCreateRuntimeUnlockInitialActivationReceiveRecoveryHoldRequest(
                        initialActivationSendBoundary,
                        initialActivationPhysicalHoldBoundary ??
                        RuntimeUnlockInitialActivationReceiveRecoveryHoldBoundary
                            .OfferPreSend,
                        out var initialActivationHoldRequest))
                {
                    return AccelerationControlSendResult.StaleCallback;
                }

                exactInitialActivationHoldPrevalidation =
                    await PrevalidateRuntimeUnlockInitialActivationReceiveRecoveryHoldAsync(
                            initialActivationHoldRequest,
                            ct)
                        .ConfigureAwait(false);
            }

            if (!ValidateRuntimeUnlockInitialActivationReceiveRecoveryHoldPrevalidation(
                    initialActivationSendBoundary,
                    exactInitialActivationHoldPrevalidation,
                    purpose,
                    out _))
            {
                return AccelerationControlSendResult.StaleCallback;
            }
        }

        var initialActivationHoldPrevalidated =
            exactInitialActivationHoldPrevalidation.IsReleased;
        if (!initialActivationHoldPrevalidated &&
            !await WaitForFileTransferTunaActivationBridgeRecoveryBeforeControlSendAsync(
                    purpose,
                    activationSessionId,
                    expectedOfferAuthorityBoundary,
                    ct)
                .ConfigureAwait(false))
        {
            if (requireObservedSend &&
                TryRequestFileTransferTunaActivationOfferSendRecovery(
                    purpose,
                    activationSessionId,
                    "bridge_recovery_wait_timeout",
                    expectedOfferAuthorityBoundary,
                    out var recoveryReason,
                    out var recoverySessionId))
            {
                return AccelerationControlSendResult.RecoveryRequestedResult(
                    recoveryReason ?? "tuna_activation_offer_send_timeout",
                    recoverySessionId);
            }

            return AccelerationControlSendResult.Failed;
        }

        var queueObservedReason = requireObservedSend
            ? queueAcceptedAsObservedReason?.Invoke()
            : null;
        if (requireObservedSend &&
            IsTunaActivationOfferSendPurpose(purpose) &&
            usesInstalledRetryOfferAuthority &&
            TryGetRuntimeUnlockRetryAuthorityForCurrentOffer(out retryAuthorityStateForSend))
        {
            if (!ValidateControlSendAuthority("send_begin"))
            {
                return AccelerationControlSendResult.StaleCallback;
            }

            RuntimeUnlockRetryDispatchContract? retryDispatchContract;
            RuntimeUnlockRetryDispatchAttempt retryDispatchAttempt;
            RuntimeUnlockRetryDispatchInstallReceipt receiptForSend = default;
            RuntimeUnlockRetryDispatchExecutionObservation sendProposal =
                default;
            lock (accelerationGate)
            {
                var currentState = runtimeUnlockRecoveryRetryState;
                retryDispatchContract = currentState?.DispatchContract;
                if (!ReferenceEquals(
                        currentState,
                        retryAuthorityStateForSend) ||
                    currentState is null ||
                    currentState.PendingDispatchSettlementReport is not null ||
                    retryDispatchContract is null)
                {
                    retryDispatchAttempt = default;
                }
                else
                {
                    receiptForSend =
                        expectedInstallReceipt ??
                        runtimeUnlockRetryDispatchInstallShadow
                            .LastCommittedReceipt ??
                        default;
                    if (!TryValidateRuntimeUnlockRetryDispatchInstallReceiptCurrentUnsafe(
                            currentState,
                            receiptForSend,
                            out _,
                            allowDispatchObservedInstallReceipt) ||
                        retryDispatchContract.AttemptPhase !=
                            RuntimeUnlockRetryDispatchAttemptPhase.AliasBound ||
                        retryDispatchContract.OfferGeneration <= 0 ||
                        string.IsNullOrWhiteSpace(
                            retryDispatchContract.OfferNonce))
                    {
                        retryDispatchAttempt = default;
                    }
                    else
                    {
                        retryDispatchAttempt =
                            new RuntimeUnlockRetryDispatchAttempt(
                                retryDispatchContract.Authority.AuthorityId,
                                retryDispatchContract.OfferGeneration,
                                retryDispatchContract.OfferNonce!);
                        sendProposal =
                            new RuntimeUnlockRetryDispatchExecutionObservation(
                                retryDispatchContract.Authority,
                                RuntimeUnlockRetryDispatchAttemptPhase
                                    .SendInFlight,
                                retryDispatchAttempt.OfferGeneration,
                                retryDispatchAttempt.OfferNonce,
                                DispatchObserved: false)
                            {
                                InstallReceipt = receiptForSend,
                            };
                    }
                }
            }

            if (retryDispatchContract is null ||
                retryDispatchAttempt == default ||
                sendProposal.IsDefault ||
                !PublishRuntimeUnlockRetryDispatchExecutionObservation(
                    sendProposal))
            {
                if (retryDispatchContract is not null)
                {
                    LocalOperationalLog.Info(
                        "NKN.Tuna",
                        $"event=runtime_unlock_retry_dispatch_stale_callback_ignored; {FormatRuntimeUnlockRetryDispatchAuthorityTuple(retryDispatchContract.Authority)}; callback_offer_generation={retryDispatchContract.OfferGeneration}; bound_offer_generation={retryDispatchContract.OfferGeneration}; callback_kind=send_begin; attempt_phase={SanitizeLogToken(retryDispatchContract.AttemptPhase.ToString())}; decision_reason=dispatch_attempt_begin_rejected");
                }
                return AccelerationControlSendResult.StaleCallback;
            }

            lock (accelerationGate)
            {
                var currentState = runtimeUnlockRecoveryRetryState;
                if (!ReferenceEquals(
                        currentState,
                        retryAuthorityStateForSend) ||
                    currentState is null ||
                    currentState.PendingDispatchSettlementReport is not null ||
                    !ReferenceEquals(
                        currentState.DispatchContract,
                        retryDispatchContract) ||
                    !TryValidateRuntimeUnlockRetryDispatchInstallReceiptCurrentUnsafe(
                        currentState,
                        receiptForSend,
                        out _,
                        allowDispatchObservedInstallReceipt) ||
                    !retryDispatchContract.MatchesAttempt(
                        retryDispatchAttempt) ||
                    !retryDispatchContract.TryBeginSend(
                        out var appliedAttempt) ||
                    appliedAttempt != retryDispatchAttempt)
                {
                    return AccelerationControlSendResult.StaleCallback;
                }
            }

            retryDispatchAttemptForSend = retryDispatchAttempt;
            MarkRuntimeUnlockRecoveryContractAuthoritySendStarted(purpose);
        }

        var controlSendLogSessionId = !string.IsNullOrWhiteSpace(activationSessionId)
            ? activationSessionId
            : retryAuthorityStateForSend?.SessionId;

        var isAtomicRegularV4RuntimeUnlockOfferWindow = requireObservedSend &&
            observedSendFallbackAsync is not null &&
            IsTunaActivationOfferSendPurpose(purpose) &&
            usesInstalledRetryOfferAuthority &&
            HasCurrentRuntimeUnlockRegularV4ActivationWindowPending(activationSessionId);
        if (!ValidateControlSendAuthority("control_send_before_runtime_effects"))
        {
            return AccelerationControlSendResult.StaleCallback;
        }
        if (!isAtomicRegularV4RuntimeUnlockOfferWindow)
        {
            onBeforeSend?.Invoke();
        }

        if (isAtomicRegularV4RuntimeUnlockOfferWindow)
        {
            onBeforeSend?.Invoke();
            if (!ValidateControlSendAuthority("control_send_after_activation_pause"))
            {
                return AccelerationControlSendResult.StaleCallback;
            }
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=runtime_unlock_regular_v4_peer_visible_window_delivery_started; session_id={SanitizeLogToken(activationSessionId ?? "none")}; purpose={SanitizeLogToken(purpose)}; reason=atomic_peer_visible_window");

            StartRuntimeUnlockRegularV4PeerVisibleWindowBestEffortOfferCopies(
                target,
                envelope,
                purpose);

            var peerVisibleSend = await observedSendFallbackAsync!().ConfigureAwait(false);
            if (!ValidateRetainedRetryAttempt("atomic_peer_visible_send_completion"))
            {
                return AccelerationControlSendResult.StaleCallback;
            }

            if (peerVisibleSend.Succeeded &&
                IsRuntimeUnlockPeerVisibleConfirmedObservedLane(peerVisibleSend.ObservedLane))
            {
                onObservedSendWaitStarted?.Invoke();
                return peerVisibleSend;
            }

            if (TryGetCurrentRuntimeUnlockPeerVisibleOfferProof(
                    activationSessionId,
                    out var proofLane))
            {
                LocalOperationalLog.Info(
                    "NKN.Tuna",
                    $"event=runtime_unlock_regular_v4_peer_visible_window_delivery_confirmed_by_transaction; session_id={SanitizeLogToken(activationSessionId ?? "none")}; purpose={SanitizeLogToken(purpose)}; observed_lane={SanitizeLogToken(proofLane)}; reason=peer_visible_transaction_proof");
                onObservedSendWaitStarted?.Invoke();
                return AccelerationControlSendResult.Success(proofLane);
            }

            LocalOperationalLog.Warn(
                "NKN.Tuna",
                $"event=runtime_unlock_regular_v4_peer_visible_window_delivery_failed; session_id={SanitizeLogToken(activationSessionId ?? "none")}; purpose={SanitizeLogToken(purpose)}; observed_lane={SanitizeLogToken(peerVisibleSend.ObservedLane ?? "(none)")}; reason=peer_visible_proof_missing");
            MarkRuntimeUnlockRecoveryContractAuthorityBlocked("runtime_unlock_regular_v4_peer_visible_window_failed");
            return AccelerationControlSendResult.Failed;
        }

        if (!ValidateControlSendAuthority("control_send_dispatch"))
        {
            return AccelerationControlSendResult.StaleCallback;
        }

        Func<string?>? bulkQueueFallbackSkipReason =
            requireObservedSend &&
            usesInstalledRetryOfferAuthority
            ? () => GetRuntimeUnlockBulkQueueFallbackObservedProofSkipReason(activationSessionId, queueObservedReason)
            : null;
        Func<string?>? bulkQueueFallbackAfterDirectSuccessReason = requireObservedSend &&
            (IsTunaActivationAnswerSendPurpose(purpose) ||
             (usesInstalledRetryOfferAuthority &&
              IsRuntimeUnlockPeerVisibleActivationSendPurpose(
                  purpose,
                  activationSessionId)))
            ? () => GetRuntimeUnlockBulkQueueFallbackAfterDirectSuccessReason(purpose, activationSessionId)
            : null;
        Func<string?>? bulkQueueFallbackObservedProofFailureReason = requireObservedSend &&
            usesInstalledRetryOfferAuthority &&
            IsTunaActivationOfferSendPurpose(purpose)
            ? () => GetRuntimeUnlockBulkQueueFallbackObservedProofFailureReason(activationSessionId, purpose)
            : null;

        RuntimeUnlockOfferAuthorityBoundary?
            initialActivationSubmissionBoundary = null;
        if (expectedOfferAuthorityBoundary is
            {
                Mode: RuntimeUnlockOfferAuthorityMode.InitialActivation,
                TransferId: { Length: > 0 },
            } initialActivationBoundary)
        {
            if (!exactInitialActivationHoldPrevalidation.IsReleased ||
                !ValidateRuntimeUnlockInitialActivationReceiveRecoveryHoldPrevalidation(
                    initialActivationBoundary,
                    exactInitialActivationHoldPrevalidation,
                    $"{purpose}_before_physical_submission",
                    out _,
                    emitTelemetry: false) ||
                !ValidateControlSendAuthority(
                    "control_send_initial_activation_receive_recovery_hold_released"))
            {
                return AccelerationControlSendResult.StaleCallback;
            }

            initialActivationSubmissionBoundary = initialActivationBoundary;
            if (latestSubmissionUtcMs > 0 &&
                ShouldResumeRuntimeUnlockInitialActivationSameGeneration(
                    exactInitialActivationHoldPrevalidation.Result))
            {
                if (rebaseLatestSubmissionAfterInitialActivationHold is null)
                {
                    return AccelerationControlSendResult.StaleCallback;
                }

                latestSubmissionUtcMs =
                    rebaseLatestSubmissionAfterInitialActivationHold();
                LocalOperationalLog.Info(
                    "NKN.Tuna",
                    $"event=runtime_unlock_initial_activation_receive_recovery_hold_submission_deadline_rebased; purpose={SanitizeLogToken(purpose)}; session_id={SanitizeLogToken(initialActivationBoundary.SessionId)}; transfer_id={SanitizeLogToken(initialActivationBoundary.TransferId)}; offer_generation={initialActivationBoundary.OfferGeneration}; transaction_generation={initialActivationBoundary.TransactionGeneration}; tuna_path_lease_generation={initialActivationBoundary.TunaPathLeaseGeneration}; submission_deadline_utc_ms={latestSubmissionUtcMs}; decision_reason=exact_receive_recovery_hold_released");
            }
        }
        if (latestSubmissionUtcMs > 0 &&
            DateTimeOffset.UtcNow.ToUnixTimeMilliseconds() >=
                latestSubmissionUtcMs)
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=tuna_acceleration_control_submission_rejected; purpose={SanitizeLogToken(purpose)}; message_type={MapAccelerationControlMessageType(envelope.Type)}; submission_deadline_utc_ms={latestSubmissionUtcMs}; decision_reason=offer_answer_deadline_elapsed");
            return AccelerationControlSendResult.StaleCallback;
        }

        if (initialActivationSubmissionBoundary is { } submittedBoundary)
        {
            var refreshGeneration =
                exactInitialActivationHoldPrevalidation.Decision
                    .EnvelopeRefreshCommand?.RefreshGeneration ?? 0;
            if (refreshGeneration <= 0)
            {
                lock (accelerationGate)
                {
                    if (lastRuntimeUnlockInitialActivationEnvelopeRefreshReceipt is
                            { } committedRefresh &&
                        runtimeUnlockInitialActivationEnvelopeState is
                            { } currentEnvelope &&
                        currentEnvelope.Boundary == submittedBoundary &&
                        committedRefresh.Command.SuccessorEnvelopeGeneration ==
                            submittedBoundary.EnvelopeGeneration &&
                        string.Equals(
                            committedRefresh.SuccessorEnvelopeFingerprint,
                            submittedBoundary.ControlEnvelopeFingerprint,
                            StringComparison.Ordinal) &&
                        string.Equals(
                            committedRefresh.MessageId,
                            currentEnvelope.Envelope.MessageId,
                            StringComparison.Ordinal))
                    {
                        refreshGeneration =
                            committedRefresh.Command.RefreshGeneration;
                    }
                }
            }
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=runtime_unlock_initial_activation_receive_recovery_hold_post_prevalidation_submission; session_id={SanitizeLogToken(submittedBoundary.SessionId)}; transfer_id={SanitizeLogToken(submittedBoundary.TransferId)}; direction={SanitizeLogToken(submittedBoundary.Direction.ToString().ToLowerInvariant())}; offer_nonce={SanitizeLogToken(submittedBoundary.Nonce)}; payer_decision_id={submittedBoundary.PayerDecisionId}; offer_generation={submittedBoundary.OfferGeneration}; transaction_generation={submittedBoundary.TransactionGeneration}; tuna_path_lease_generation={submittedBoundary.TunaPathLeaseGeneration}; tuna_path_lease_listener_run_id={SanitizeLogToken(submittedBoundary.TunaPathLeaseListenerRunId)}; semantic_offer_fingerprint={SanitizeLogToken(submittedBoundary.SemanticOfferFingerprint)}; envelope_generation={submittedBoundary.EnvelopeGeneration}; control_envelope_fingerprint={SanitizeLogToken(submittedBoundary.ControlEnvelopeFingerprint)}; envelope_sent_at_unix_ms={submittedBoundary.EnvelopeSentAtUnixMs}; envelope_expires_at_unix_ms={submittedBoundary.EnvelopeExpiresAtUnixMs}; refresh_generation={refreshGeneration}; message_id={SanitizeLogToken(envelope.MessageId)}; send_path={SanitizeLogToken(purpose)}; decision_reason=exact_prevalidated_envelope_submitted");
        }

        var bytes = EnvelopeCodec.Serialize(envelope);
        var controlTask = QueueControlEnvelopeAsync(target, envelope, ControlOutboundLane.High, ct);
        ObserveAccelerationControlSendTask(controlTask, purpose, "control_queue");

        var priorityControlTask = SendAccelerationControlPriorityCopyAsync(target, envelope, bytes, purpose, ct);
        ObserveAccelerationControlSendTask(priorityControlTask, purpose, "control_priority");

        Task<AccelerationControlSendResult>? bulkTask = null;
        var replyRequiresExactTarget = purpose is
            "answer" or "answer_replay" or "answer_ack" or
            "answer_ack_replay";
        var bulkTarget = replyRequiresExactTarget
            ? target
            : remoteBulkEndpoint;
        if (string.IsNullOrWhiteSpace(bulkTarget))
        {
            LocalOperationalLog.Warn(
                "NKN.Tuna",
                $"event=tuna_acceleration_control_bulk_bypass_unavailable; purpose={SanitizeLogToken(purpose)}; message_type={MapAccelerationControlMessageType(envelope.Type)}; reason=missing_remote_bulk_endpoint");
        }
        else
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=tuna_acceleration_control_bulk_bypass_started; purpose={SanitizeLogToken(purpose)}; message_type={MapAccelerationControlMessageType(envelope.Type)}; delay_ms=0; mode=control_to_bulk_endpoint");
            bulkTask = SendAccelerationControlBulkCopyAsync(
                bulkTarget,
                envelope,
                bytes,
                purpose,
                ct,
                bulkQueueFallbackSkipReason,
                bulkQueueFallbackAfterDirectSuccessReason,
                bulkQueueFallbackObservedProofFailureReason);
            ObserveAccelerationControlSendTask(bulkTask, purpose, "control_to_bulk_endpoint");
        }

        if (IsAccelerationControlQueueAccepted(controlTask, ct, out var queueRejected))
        {
            var queueCompletedSuccessfully = controlTask.IsCompletedSuccessfully && controlTask.Result;
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=tuna_acceleration_control_queue_accepted; purpose={SanitizeLogToken(purpose)}; message_type={MapAccelerationControlMessageType(envelope.Type)}; completed={(controlTask.IsCompletedSuccessfully ? 1 : 0)}");
            if (queueCompletedSuccessfully)
            {
                onQueueAccepted?.Invoke();
            }

            if (!string.IsNullOrWhiteSpace(queueObservedReason) && queueCompletedSuccessfully)
            {
                LocalOperationalLog.Info(
                    "NKN.Tuna",
                    $"event=tuna_acceleration_control_queue_accepted_as_observed; purpose={SanitizeLogToken(purpose)}; message_type={MapAccelerationControlMessageType(envelope.Type)}; reason={SanitizeLogToken(queueObservedReason)}");
                return ValidateRetainedRetryAttempt("queue_observed_completion")
                    ? AccelerationControlSendResult.Success(AccelerationObservedLaneControlQueueExplicitObserved)
                    : AccelerationControlSendResult.StaleCallback;
            }

            if (!string.IsNullOrWhiteSpace(queueObservedReason) && !queueCompletedSuccessfully)
            {
                LocalOperationalLog.Info(
                    "NKN.Tuna",
                    $"event=tuna_acceleration_control_queue_pending_not_observed; purpose={SanitizeLogToken(purpose)}; message_type={MapAccelerationControlMessageType(envelope.Type)}; reason={SanitizeLogToken(queueObservedReason)}");
            }

            if (!requireObservedSend)
            {
                return AccelerationControlSendResult.Success(AccelerationObservedLaneControlQueue);
            }
        }
        else if (queueRejected)
        {
            LocalOperationalLog.Warn(
                "NKN.Tuna",
                $"event=tuna_acceleration_control_queue_rejected; purpose={SanitizeLogToken(purpose)}; message_type={MapAccelerationControlMessageType(envelope.Type)}");
        }

        var preferPriorityObservedLane = ShouldPreferPriorityObservedLaneForRuntimeUnlockObservedOfferReplay(
            requireObservedSend,
            purpose);
        var preferBulkObservedLane =
            !preferPriorityObservedLane &&
            (IsTunaActivationAnswerSendPurpose(purpose) ||
             usesInstalledRetryOfferAuthority) &&
            ShouldPreferBulkObservedLaneForRuntimeUnlockAuthority(
                requireObservedSend,
                purpose,
                activationSessionId);

        var attempts = new List<AccelerationControlSendAttempt>
        {
            new(
                MapAccelerationControlSendAttemptAsync(priorityControlTask, AccelerationObservedLaneControlPriority),
                preferPriorityObservedLane),
        };
        if (!requireObservedSend)
        {
            attempts.Add(new AccelerationControlSendAttempt(MapAccelerationControlSendAttemptAsync(controlTask, AccelerationObservedLaneControlQueue)));
        }
        else if (!string.IsNullOrWhiteSpace(queueObservedReason))
        {
            attempts.Add(new AccelerationControlSendAttempt(MapAccelerationControlQueueAcceptedObservedAttemptAsync(
                controlTask,
                purpose,
                envelope.Type,
                queueObservedReason)));
        }
        else
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=tuna_acceleration_control_queue_excluded_from_observed_wait; purpose={SanitizeLogToken(purpose)}; message_type={MapAccelerationControlMessageType(envelope.Type)}; reason=observed_send_requires_direct_or_bulk_proof");
        }

        if (bulkTask is not null)
        {
            attempts.Add(new AccelerationControlSendAttempt(bulkTask, preferBulkObservedLane));
        }

        var observedSend = await WaitForFirstSuccessfulAccelerationControlSendAsync(
                attempts,
                purpose,
                controlSendLogSessionId,
                preferPriorityObservedLane || preferBulkObservedLane)
            .ConfigureAwait(false);
        if (!ValidateRetainedRetryAttempt("observed_send_completion"))
        {
            return AccelerationControlSendResult.StaleCallback;
        }

        if (!observedSend.Succeeded &&
            requireObservedSend &&
            observedSendFallbackAsync is not null)
        {
            observedSend = await observedSendFallbackAsync().ConfigureAwait(false);
            if (!ValidateRetainedRetryAttempt("observed_send_fallback_completion"))
            {
                return AccelerationControlSendResult.StaleCallback;
            }
        }

        if (observedSend.Succeeded &&
            requireObservedSend &&
            observedSendFallbackAsync is not null &&
            usesInstalledRetryOfferAuthority &&
            ShouldRequireSynchronousRuntimeUnlockPeerVisibleOfferConfirmation(
                activationSessionId,
                purpose) &&
            !IsRuntimeUnlockPeerVisibleConfirmedObservedLane(observedSend.ObservedLane))
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=runtime_unlock_regular_v4_peer_visible_window_confirmation_required; session_id={SanitizeLogToken(activationSessionId ?? "none")}; purpose={SanitizeLogToken(purpose)}; observed_lane={SanitizeLogToken(observedSend.ObservedLane ?? "(none)")}; reason=atomic_peer_visible_window");

            var confirmedSend = await observedSendFallbackAsync().ConfigureAwait(false);
            if (!ValidateRetainedRetryAttempt("peer_visible_confirmation_completion"))
            {
                return AccelerationControlSendResult.StaleCallback;
            }

            if (confirmedSend.Succeeded &&
                IsRuntimeUnlockPeerVisibleConfirmedObservedLane(confirmedSend.ObservedLane))
            {
                observedSend = confirmedSend;
            }
            else
            {
                LocalOperationalLog.Warn(
                    "NKN.Tuna",
                    $"event=runtime_unlock_regular_v4_peer_visible_window_confirmation_failed; session_id={SanitizeLogToken(activationSessionId ?? "none")}; purpose={SanitizeLogToken(purpose)}; observed_lane={SanitizeLogToken(observedSend.ObservedLane ?? "(none)")}; confirmed_lane={SanitizeLogToken(confirmedSend.ObservedLane ?? "(none)")}; reason=peer_visible_proof_missing");
                MarkRuntimeUnlockRecoveryContractAuthorityBlocked("runtime_unlock_regular_v4_peer_visible_window_failed");
                return AccelerationControlSendResult.Failed;
            }
        }

        if (observedSend.Succeeded && requireObservedSend)
        {
            var priorityReplayTrusted = ShouldTrustPriorityObservedLaneForRuntimeUnlockObservedOfferReplay(
                purpose,
                observedSend.ObservedLane);
            if (priorityReplayTrusted)
            {
                LocalOperationalLog.Info(
                    "NKN.Tuna",
                    $"event=tuna_acceleration_control_priority_offer_replay_observed_trusted; purpose={SanitizeLogToken(purpose)}; message_type={MapAccelerationControlMessageType(envelope.Type)}; observed_lane={SanitizeLogToken(observedSend.ObservedLane ?? "(none)")}; session_id={SanitizeLogToken(activationSessionId ?? "none")}; reason=runtime_unlock_observed_offer_replay_lane_diversity");
            }

            var hasRuntimeUnlockRetryAuthority =
                usesInstalledRetryOfferAuthority &&
                TryGetRuntimeUnlockRetryAuthorityForCurrentOffer(out _);
            var hasRuntimeUnlockObservedReplayWindow =
                usesInstalledRetryOfferAuthority &&
                string.Equals(purpose, "offer_replay", StringComparison.OrdinalIgnoreCase) &&
                TryGetRuntimeUnlockObservedOfferReplayWindowForCurrentOffer(out _, out _);
            if (IsTunaActivationOfferSendPurpose(purpose) &&
                IsCurrentRuntimeUnlockActivationOffer() &&
                (hasRuntimeUnlockRetryAuthority || hasRuntimeUnlockObservedReplayWindow) &&
                !HasRecentSessionLivenessProofForRuntimeUnlockAuthority(activationSessionId))
            {
                const string missingPeerProofReason = "runtime_unlock_authority_missing_recent_peer_proof";
                var retryAuthorityObservedSendTrusted =
                    ShouldTrustRuntimeUnlockObservedSendWithRetryAuthority(
                        activationSessionId,
                        purpose,
                        observedSend.ObservedLane,
                        out var retryAuthorityContractGeneration,
                        out var retryAuthorityAttempt);
                var fallbackPairedInstallTrusted =
                    TryGetEffectiveFallbackPairedTailYieldInstallReceiptForObservedLane(
                        activationSessionId,
                        observedSend.ObservedLane,
                        out var fallbackInstallReceipt);
                if (retryAuthorityObservedSendTrusted)
                {
                    LocalOperationalLog.Info(
                        "NKN.Tuna",
                        $"event=tuna_acceleration_control_observed_trusted_by_runtime_unlock_authority; purpose={SanitizeLogToken(purpose)}; message_type={MapAccelerationControlMessageType(envelope.Type)}; observed_lane={SanitizeLogToken(observedSend.ObservedLane ?? "(none)")}; session_id={SanitizeLogToken(activationSessionId ?? "none")}; contract_generation={retryAuthorityContractGeneration}; authority_attempt={retryAuthorityAttempt}; reason=bounded_authority_peer_visible_lane");
                }
                else if (fallbackPairedInstallTrusted)
                {
                    LocalOperationalLog.Warn(
                        "NKN.Tuna",
                        $"event=tuna_acceleration_control_send_observed_without_recent_peer_proof; purpose={SanitizeLogToken(purpose)}; message_type={MapAccelerationControlMessageType(envelope.Type)}; observed_lane={SanitizeLogToken(observedSend.ObservedLane ?? "(none)")}; session_id={SanitizeLogToken(activationSessionId ?? "none")}; reason={missingPeerProofReason}; fallback_paired_install_trusted=1; authority_id={fallbackInstallReceipt.Authority.AuthorityId}; direction={fallbackInstallReceipt.Authority.Direction.ToString().ToLowerInvariant()}; install_generation={fallbackInstallReceipt.InstallGeneration}");
                    LocalOperationalLog.Info(
                        "NKN.Tuna",
                        $"event=tuna_acceleration_control_observed_trusted_by_fallback_paired_tail_yield_install; purpose={SanitizeLogToken(purpose)}; message_type={MapAccelerationControlMessageType(envelope.Type)}; observed_lane={SanitizeLogToken(observedSend.ObservedLane ?? "(none)")}; session_id={SanitizeLogToken(activationSessionId ?? "none")}; authority_id={fallbackInstallReceipt.Authority.AuthorityId}; direction={fallbackInstallReceipt.Authority.Direction.ToString().ToLowerInvariant()}; install_generation={fallbackInstallReceipt.InstallGeneration}; reason=fallback_paired_tail_yield_install_receipt");
                }
                else if (!priorityReplayTrusted)
                {
                    LocalOperationalLog.Warn(
                        "NKN.Tuna",
                        $"event=tuna_acceleration_control_send_observed_without_recent_peer_proof; purpose={SanitizeLogToken(purpose)}; message_type={MapAccelerationControlMessageType(envelope.Type)}; observed_lane={SanitizeLogToken(observedSend.ObservedLane ?? "(none)")}; session_id={SanitizeLogToken(activationSessionId ?? "none")}; reason={missingPeerProofReason}");
                    if (string.Equals(
                            observedSend.ObservedLane,
                            AccelerationObservedLaneControlPriority,
                            StringComparison.OrdinalIgnoreCase))
                    {
                        LocalOperationalLog.Warn(
                            "NKN.Tuna",
                            $"event=tuna_acceleration_control_priority_observed_untrusted; purpose={SanitizeLogToken(purpose)}; message_type={MapAccelerationControlMessageType(envelope.Type)}; observed_lane={SanitizeLogToken(observedSend.ObservedLane)}; session_id={SanitizeLogToken(activationSessionId ?? "none")}; reason={missingPeerProofReason}; preferred_bulk_required=1");
                    }
                    else
                    {
                        LocalOperationalLog.Warn(
                            "NKN.Tuna",
                            $"event=tuna_acceleration_control_observed_untrusted; purpose={SanitizeLogToken(purpose)}; message_type={MapAccelerationControlMessageType(envelope.Type)}; observed_lane={SanitizeLogToken(observedSend.ObservedLane ?? "(none)")}; session_id={SanitizeLogToken(activationSessionId ?? "none")}; reason={missingPeerProofReason}; peer_visible_proof_required=1");
                    }

                    if (TryRequestFileTransferTunaActivationOfferSendRecovery(
                            purpose,
                            activationSessionId,
                            missingPeerProofReason,
                            expectedOfferAuthorityBoundary,
                            out var recoveryReason,
                            out var recoverySessionId))
                    {
                        return AccelerationControlSendResult.RecoveryRequestedResult(
                            recoveryReason ?? "tuna_activation_offer_send_timeout",
                            recoverySessionId);
                    }

                    if (usesInstalledRetryOfferAuthority)
                    {
                        MarkRuntimeUnlockRecoveryContractAuthorityBlocked(
                            missingPeerProofReason);
                    }
                    return AccelerationControlSendResult.Failed;
                }
            }

            onObservedSendWaitStarted?.Invoke();
        }
        else if (!observedSend.Succeeded && requireObservedSend)
        {
            if (usesInstalledRetryOfferAuthority &&
                ShouldFailRuntimeUnlockRegularV4ActivationWindowInsteadOfRecovery(
                    activationSessionId,
                    purpose))
            {
                MarkRuntimeUnlockRecoveryContractAuthorityBlocked("runtime_unlock_regular_v4_peer_visible_window_failed");
                return AccelerationControlSendResult.Failed;
            }

            if (TryRequestFileTransferTunaActivationOfferSendRecovery(
                purpose,
                activationSessionId,
                "observed_send_timeout",
                expectedOfferAuthorityBoundary,
                out var recoveryReason,
                out var recoverySessionId))
            {
                return AccelerationControlSendResult.RecoveryRequestedResult(
                    recoveryReason ?? "tuna_activation_offer_send_timeout",
                    recoverySessionId);
            }
        }

        return ValidateRetainedRetryAttempt("send_completion")
            ? observedSend
            : AccelerationControlSendResult.StaleCallback;
    }

    private void StartRuntimeUnlockRegularV4PeerVisibleWindowBestEffortOfferCopies(
        string target,
        Envelope envelope,
        string purpose)
    {
        if (envelope.Type != MsgType.TransportAccelerationOffer ||
            !IsTunaActivationOfferSendPurpose(purpose))
        {
            return;
        }

        var bytes = EnvelopeCodec.Serialize(envelope);
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=runtime_unlock_regular_v4_peer_visible_window_transport_copies_started; purpose={SanitizeLogToken(purpose)}; message_type={MapAccelerationControlMessageType(envelope.Type)}; reason=atomic_peer_visible_window_delivery_diversity");

        var controlTask = QueueControlEnvelopeAsync(
            target,
            envelope,
            ControlOutboundLane.High,
            CancellationToken.None);
        ObserveAccelerationControlSendTask(controlTask, purpose, "control_queue_atomic_peer_visible_window");

        var priorityControlTask = SendAccelerationControlPriorityCopyAsync(
            target,
            envelope,
            bytes,
            purpose,
            CancellationToken.None);
        ObserveAccelerationControlSendTask(priorityControlTask, purpose, "control_priority_atomic_peer_visible_window");

        if (string.IsNullOrWhiteSpace(remoteBulkEndpoint))
        {
            LocalOperationalLog.Warn(
                "NKN.Tuna",
                $"event=tuna_acceleration_control_bulk_bypass_unavailable; purpose={SanitizeLogToken(purpose)}; message_type={MapAccelerationControlMessageType(envelope.Type)}; reason=missing_remote_bulk_endpoint; scope=atomic_peer_visible_window");
            return;
        }

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=tuna_acceleration_control_bulk_bypass_started; purpose={SanitizeLogToken(purpose)}; message_type={MapAccelerationControlMessageType(envelope.Type)}; delay_ms=0; mode=control_to_bulk_endpoint; scope=atomic_peer_visible_window");
        var bulkTask = SendAccelerationControlBulkCopyAsync(
            remoteBulkEndpoint,
            envelope,
            bytes,
            purpose,
            CancellationToken.None);
        ObserveAccelerationControlSendTask(bulkTask, purpose, "control_to_bulk_endpoint_atomic_peer_visible_window");
    }

    private bool TryGetCurrentRuntimeUnlockPeerVisibleOfferProof(
        string? sessionId,
        out string observedLane)
    {
        observedLane = AccelerationObservedLaneControlPlanePeerVisible;
        if (string.IsNullOrWhiteSpace(sessionId))
        {
            return false;
        }

        var normalizedSessionId = sessionId.Trim();
        lock (accelerationGate)
        {
            var recoveryState = runtimeUnlockRecoveryRetryState;
            if (recoveryState is null ||
                recoveryState.ContractState is SessionRecoveryContractState.Completed or SessionRecoveryContractState.Failed ||
                !recoveryState.RegularV4ActivationWindowStarted ||
                !string.Equals(recoveryState.SessionId, normalizedSessionId, StringComparison.Ordinal))
            {
                return false;
            }

            var transaction = runtimeUnlockTransactionState;
            if (!string.Equals(transaction.SessionId, normalizedSessionId, StringComparison.Ordinal) ||
                transaction.OfferGeneration != recoveryState.CurrentOfferGeneration ||
                !transaction.HasPeerVisibleProof ||
                transaction.State is RuntimeUnlockTransactionState.Failed or RuntimeUnlockTransactionState.Retired)
            {
                return false;
            }

            observedLane = transaction.AnswerReceived
                ? AccelerationObservedLanePeerAnswer
                : AccelerationObservedLaneControlPlanePeerVisible;
            return true;
        }
    }

    private static bool IsRuntimeUnlockPeerVisibleConfirmedObservedLane(string? observedLane)
    {
        if (string.IsNullOrWhiteSpace(observedLane))
        {
            return false;
        }

        return string.Equals(observedLane, AccelerationObservedLaneControlPlanePeerVisible, StringComparison.OrdinalIgnoreCase) ||
               string.Equals(observedLane, AccelerationObservedLanePeerAnswer, StringComparison.OrdinalIgnoreCase);
    }

    private bool HasCurrentRuntimeUnlockRegularV4ActivationWindowPending(string? sessionId)
    {
        if (string.IsNullOrWhiteSpace(sessionId))
        {
            return false;
        }

        if (!TryGetRuntimeUnlockRetryAuthorityForCurrentOffer(out var authorityState, sessionId.Trim()) ||
            authorityState is null)
        {
            return false;
        }

        return authorityState.RegularV4ActivationWindowStarted &&
               !authorityState.RegularV4ActivationWindowPeerVisible &&
               !authorityState.RegularV4ActivationWindowFailed &&
               authorityState.RetryAuthorityGranted &&
               authorityState.RetryAuthorityPending &&
               authorityState.ObservedSendPending &&
               authorityState.ContractState is not (SessionRecoveryContractState.Completed or SessionRecoveryContractState.Failed);
    }

    private bool ShouldRequireSynchronousRuntimeUnlockPeerVisibleOfferConfirmation(
        string? sessionId,
        string purpose)
    {
        if (!IsTunaActivationOfferSendPurpose(purpose) ||
            !IsCurrentInstalledRetryRuntimeUnlockOffer() ||
            string.IsNullOrWhiteSpace(sessionId))
        {
            return false;
        }

        if (HasCurrentRuntimeUnlockRegularV4ActivationWindowPending(sessionId))
        {
            return true;
        }

        var normalizedSessionId = sessionId.Trim();
        return TryGetEffectiveFallbackPairedTailYieldInstallReceipt(
            normalizedSessionId,
            transferId: null,
            direction: null,
            out _);
    }

    private bool ShouldFailRuntimeUnlockRegularV4ActivationWindowInsteadOfRecovery(
        string? sessionId,
        string purpose)
    {
        if (!IsTunaActivationOfferSendPurpose(purpose) ||
            !IsCurrentInstalledRetryRuntimeUnlockOffer() ||
            string.IsNullOrWhiteSpace(sessionId))
        {
            return false;
        }

        var normalizedSessionId = sessionId.Trim();
        if (!TryGetRuntimeUnlockRetryAuthorityForCurrentOffer(out var authorityState, normalizedSessionId) ||
            authorityState is null)
        {
            return false;
        }

        return authorityState.RegularV4ActivationWindowStarted &&
               !authorityState.RegularV4ActivationWindowPeerVisible &&
               authorityState.RetryAuthorityGranted &&
               authorityState.RetryAuthorityPending &&
               authorityState.ObservedSendPending &&
               authorityState.ContractState is not (SessionRecoveryContractState.Completed or SessionRecoveryContractState.Failed);
    }

    private bool ShouldTrustRuntimeUnlockObservedSendWithRetryAuthority(
        string? sessionId,
        string purpose,
        string? observedLane,
        out long contractGeneration,
        out int authorityAttempt)
    {
        contractGeneration = 0;
        authorityAttempt = 0;
        if (string.IsNullOrWhiteSpace(sessionId) ||
            string.IsNullOrWhiteSpace(observedLane) ||
            !IsCurrentInstalledRetryRuntimeUnlockOffer())
        {
            return false;
        }

        var normalizedLane = observedLane.Trim();
        var isPriorityLane = string.Equals(normalizedLane, AccelerationObservedLaneControlPriority, StringComparison.OrdinalIgnoreCase);
        var isBulkEndpointLane = string.Equals(normalizedLane, AccelerationObservedLaneControlToBulkEndpoint, StringComparison.OrdinalIgnoreCase);
        var isBulkFallbackLane = string.Equals(normalizedLane, AccelerationObservedLaneBulkQueueFallback, StringComparison.OrdinalIgnoreCase);
        var isControlPlanePeerVisibleLane = string.Equals(normalizedLane, AccelerationObservedLaneControlPlanePeerVisible, StringComparison.OrdinalIgnoreCase);
        var isPeerAnswerLane = string.Equals(normalizedLane, AccelerationObservedLanePeerAnswer, StringComparison.OrdinalIgnoreCase);
        if (!isPriorityLane && !isBulkEndpointLane && !isBulkFallbackLane && !isControlPlanePeerVisibleLane && !isPeerAnswerLane)
        {
            return false;
        }

        if (!TryGetRuntimeUnlockRetryAuthorityForCurrentOffer(out var authorityState) ||
            authorityState is null ||
            !string.Equals(authorityState.SessionId, sessionId.Trim(), StringComparison.Ordinal))
        {
            if (!string.Equals(purpose, "offer_replay", StringComparison.OrdinalIgnoreCase) ||
                isPriorityLane ||
                !TryGetRuntimeUnlockObservedOfferReplayWindowForCurrentOffer(out var replayState, out _) ||
                replayState is null ||
                !string.Equals(replayState.SessionId, sessionId.Trim(), StringComparison.Ordinal))
            {
                return false;
            }

            contractGeneration = replayState.ContractGeneration;
            authorityAttempt = replayState.AuthorityAttempt;
            return true;
        }

        if (isPriorityLane)
        {
            return false;
        }

        contractGeneration = authorityState.ContractGeneration;
        authorityAttempt = authorityState.AuthorityAttempt;
        return true;
    }

    private bool ShouldPreferBulkObservedLaneForRuntimeUnlockAuthority(
        bool requireObservedSend,
        string purpose,
        string? sessionId)
    {
        if (!requireObservedSend)
        {
            return false;
        }

        if (IsTunaActivationAnswerSendPurpose(purpose))
        {
            return IsPendingAccelerationAnswerAckForSession(sessionId);
        }

        if (!IsTunaActivationOfferSendPurpose(purpose))
        {
            return false;
        }

        if (!IsCurrentInstalledRetryRuntimeUnlockOffer())
        {
            return false;
        }

        if (TryGetRuntimeUnlockRetryAuthorityForCurrentOffer(out _) ||
            (string.Equals(purpose, "offer_replay", StringComparison.OrdinalIgnoreCase) &&
             TryGetRuntimeUnlockObservedOfferReplayWindowForCurrentOffer(out _, out _)))
        {
            return true;
        }

        return IsRuntimeUnlockPeerVisibleActivationSendPurpose(purpose, sessionId) ||
               ShouldRequireRuntimeUnlockBulkQueueDuplicateForPostTunaFallback(
                   sessionId,
                   requireCurrentRuntimeUnlockOffer: false);
    }

    private bool ShouldPreferPriorityObservedLaneForRuntimeUnlockObservedOfferReplay(
        bool requireObservedSend,
        string purpose)
        => false;

    private bool ShouldTrustPriorityObservedLaneForRuntimeUnlockObservedOfferReplay(
        string purpose,
        string? observedLane)
        => false;

    private bool TryGetEffectiveFallbackPairedTailYieldInstallReceiptForObservedLane(
        string? sessionId,
        string? observedLane,
        out RuntimeUnlockRetryDispatchInstallReceipt receipt)
    {
        receipt = default;
        if (string.IsNullOrWhiteSpace(sessionId) ||
            string.IsNullOrWhiteSpace(observedLane) ||
            !IsCurrentInstalledRetryRuntimeUnlockOffer())
        {
            return false;
        }

        var normalizedSessionId = sessionId.Trim();
        if (!HasActivePostTunaFallbackFileTransferRouteHint(normalizedSessionId))
        {
            return false;
        }

        var normalizedLane = observedLane.Trim();
        if (!string.Equals(normalizedLane, AccelerationObservedLaneControlToBulkEndpoint, StringComparison.OrdinalIgnoreCase) &&
            !string.Equals(normalizedLane, AccelerationObservedLaneBulkQueueFallback, StringComparison.OrdinalIgnoreCase))
        {
            return false;
        }

        return TryGetEffectiveFallbackPairedTailYieldInstallReceiptForSession(
            normalizedSessionId,
            out receipt);
    }

    private string? GetRuntimeUnlockBulkQueueFallbackObservedProofSkipReason(string? sessionId, string? queueObservedReason)
    {
        if (!IsCurrentInstalledRetryRuntimeUnlockOffer())
        {
            return null;
        }

        if (TryGetRuntimeUnlockObservedOfferReplayWindowForCurrentOffer(out _, out _))
        {
            return null;
        }

        if (TryGetEffectiveFallbackPairedTailYieldInstallReceiptForObservedLane(
                sessionId,
                AccelerationObservedLaneBulkQueueFallback,
                out var installReceipt))
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=tuna_acceleration_control_bulk_queue_fallback_trusted_by_fallback_paired_tail_yield_install; purpose=offer; message_type={MapAccelerationControlMessageType(MsgType.TransportAccelerationOffer)}; lane=bulk_queue_fallback; session_id={SanitizeLogToken(sessionId ?? "none")}; authority_id={installReceipt.Authority.AuthorityId}; direction={installReceipt.Authority.Direction.ToString().ToLowerInvariant()}; install_generation={installReceipt.InstallGeneration}; reason=fallback_paired_tail_yield_install_receipt");
            return null;
        }

        if (RuntimeUnlockOfferObservedSendBlockerReasonOverrideForTests?.Invoke(this) is { Length: > 0 } overrideReason)
        {
            if (TryGetRuntimeUnlockRetryAuthorityForCurrentOffer(out _))
            {
                return null;
            }

            MarkRuntimeUnlockRecoveryContractAuthorityBlocked(overrideReason);
            return SanitizeLogToken(overrideReason);
        }

        if (IsRuntimeUnlockActiveFileTransferObservedSendBlocker(queueObservedReason) ||
            string.Equals(queueObservedReason, "test_regular_v4_pressure", StringComparison.OrdinalIgnoreCase))
        {
            if (TryGetRuntimeUnlockRetryAuthorityForCurrentOffer(out _))
            {
                return null;
            }

            MarkRuntimeUnlockRecoveryContractAuthorityBlocked(queueObservedReason);
            return SanitizeLogToken(queueObservedReason);
        }

        if (client is not RealNknClientAdapter realClient)
        {
            return null;
        }

        if (realClient.TryGetFileTransferRegularV4ActivationSendBlocker(
                out var blockerReason,
                out _,
                includeRegularV4Pressure: true) &&
            IsRuntimeUnlockActiveFileTransferObservedSendBlocker(blockerReason))
        {
            if (TryGetRuntimeUnlockRetryAuthorityForCurrentOffer(out _))
            {
                return null;
            }

            MarkRuntimeUnlockRecoveryContractAuthorityBlocked(blockerReason);
            return SanitizeLogToken(blockerReason);
        }

        if (realClient.HasActiveFileTransferRuntimeForActivationSend())
        {
            if (TryGetRuntimeUnlockRetryAuthorityForCurrentOffer(out _))
            {
                return null;
            }

            MarkRuntimeUnlockRecoveryContractAuthorityBlocked("active_file_transfer_runtime");
            return "active_file_transfer_runtime";
        }

        return null;
    }

    private string? GetRuntimeUnlockBulkQueueFallbackAfterDirectSuccessReason(string purpose, string? sessionId)
        => IsTunaActivationAnswerSendPurpose(purpose) &&
            IsPendingAccelerationAnswerAckForSession(sessionId)
            ? IsPendingRuntimeUnlockAccelerationAnswerAck(sessionId)
                ? "runtime_unlock_answer_requires_bulk_queue_duplicate"
                : "answer_requires_bulk_queue_duplicate"
            : IsTunaActivationOfferSendPurpose(purpose) &&
              ShouldRequireRuntimeUnlockBulkQueueDuplicateForPostTunaFallback(sessionId, requireCurrentRuntimeUnlockOffer: false)
            ? "post_tuna_fallback_requires_bulk_queue_duplicate"
            : null;

    private bool ShouldRequireRuntimeUnlockBulkQueueDuplicateForPostTunaFallback(
        string? sessionId,
        bool requireCurrentRuntimeUnlockOffer = true)
    {
        if ((requireCurrentRuntimeUnlockOffer && !IsCurrentRuntimeUnlockActivationOffer()) ||
            string.IsNullOrWhiteSpace(sessionId) ||
            HasRecentSessionLivenessProofForRuntimeUnlockAuthority(sessionId) ||
            !HasActivePostTunaFallbackFileTransferRouteHint(sessionId))
        {
            return false;
        }

        return TryGetEffectiveFallbackPairedTailYieldInstallReceiptForSession(
            sessionId,
            out _);
    }

    private string? GetRuntimeUnlockBulkQueueFallbackObservedProofFailureReason(string? sessionId, string purpose)
    {
        if (!IsCurrentInstalledRetryRuntimeUnlockOffer() ||
            HasRecentSessionLivenessProofForRuntimeUnlockAuthority(sessionId))
        {
            return null;
        }

        if (TryGetEffectiveFallbackPairedTailYieldInstallReceiptForObservedLane(
                sessionId,
                AccelerationObservedLaneBulkQueueFallback,
                out _))
        {
            return null;
        }

        if (RuntimeUnlockBulkQueueObservedProofBlockerOverrideForTests?.Invoke(this) is { Length: > 0 } forcedOverrideReason &&
            string.Equals(
                forcedOverrideReason,
                "force_control_plane_observed_send_for_tests",
                StringComparison.OrdinalIgnoreCase))
        {
            return SanitizeLogToken(forcedOverrideReason);
        }

        if (TryGetRuntimeUnlockRetryAuthorityForCurrentOffer(out var authorityState))
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=tuna_acceleration_control_bulk_queue_fallback_trusted_by_runtime_unlock_authority; purpose=offer; message_type={MapAccelerationControlMessageType(MsgType.TransportAccelerationOffer)}; lane=bulk_queue_fallback; session_id={SanitizeLogToken(sessionId ?? "none")}; contract_generation={authorityState?.ContractGeneration ?? 0}; authority_attempt={authorityState?.AuthorityAttempt ?? 0}; reason=bounded_authority_peer_visible_lane");
            return null;
        }

        if (RuntimeUnlockBulkQueueObservedProofBlockerOverrideForTests?.Invoke(this) is { Length: > 0 } overrideReason)
        {
            return SanitizeLogToken(overrideReason);
        }

        if (client is RealNknClientAdapter readinessClient &&
            readinessClient.TryGetRuntimeUnlockBulkQueueObservedProofBlocker(out var readinessReason) &&
            IsRuntimeUnlockBridgeConnectivityObservedProofBlocker(readinessReason))
        {
            return readinessReason;
        }

        if (string.Equals(purpose, "offer_replay", StringComparison.OrdinalIgnoreCase) &&
            TryGetRuntimeUnlockObservedOfferReplayWindowForCurrentOffer(out var replayState, out var offerState) &&
            replayState is not null &&
            offerState is not null &&
            (string.IsNullOrWhiteSpace(sessionId) ||
             string.Equals(replayState.SessionId, sessionId.Trim(), StringComparison.Ordinal)))
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=tuna_acceleration_control_bulk_observed_send_allowed_by_runtime_unlock_observed_replay; purpose=offer_replay; message_type={MapAccelerationControlMessageType(MsgType.TransportAccelerationOffer)}; lane=bulk_observed; session_id={SanitizeLogToken(sessionId ?? "none")}; contract_generation={replayState.ContractGeneration}; authority_attempt={replayState.AuthorityAttempt}; offer_generation={offerState.Generation}; previous_observed_lane={SanitizeLogToken(offerState.ObservedSendLane ?? "(none)")}; reason=bounded_observed_offer_replay");
            return null;
        }

        if (client is RealNknClientAdapter realClient &&
            realClient.TryGetRuntimeUnlockBulkQueueObservedProofBlocker(out var reason) &&
            !string.IsNullOrWhiteSpace(reason))
        {
            return reason;
        }

        const string missingPeerProofReason = "runtime_unlock_authority_missing_recent_peer_proof";
        return missingPeerProofReason;
    }

    private static bool IsRuntimeUnlockBridgeConnectivityObservedProofBlocker(string? reason)
        => string.Equals(reason, "bridge_health_missing", StringComparison.OrdinalIgnoreCase) ||
           string.Equals(reason, "bridge_health_stale", StringComparison.OrdinalIgnoreCase) ||
           string.Equals(reason, "bridge_disconnect_signal", StringComparison.OrdinalIgnoreCase) ||
           string.Equals(reason, "bridge_not_ready", StringComparison.OrdinalIgnoreCase);

    private static bool IsRuntimeUnlockActiveFileTransferObservedSendBlocker(string? reason)
    {
        if (IsRegularV4PressureActivationSendBlocker(reason) ||
            IsReceiveStallActivationSendBlocker(reason))
        {
            return true;
        }

        return string.Equals(reason, "all_zero_receive_window", StringComparison.OrdinalIgnoreCase) ||
               string.Equals(reason, "control_zero_receive_window", StringComparison.OrdinalIgnoreCase) ||
               string.Equals(reason, "bulk_zero_receive_window", StringComparison.OrdinalIgnoreCase) ||
               string.Equals(reason, "regular_v4_receive_stall_bypass", StringComparison.OrdinalIgnoreCase) ||
               string.Equals(reason, "recent_zero_receive_health", StringComparison.OrdinalIgnoreCase);
    }

    private static bool IsAccelerationControlQueueAccepted(
        Task<bool> controlTask,
        CancellationToken ct,
        out bool rejected)
    {
        rejected = false;
        if (!controlTask.IsCompleted)
        {
            return true;
        }

        if (controlTask.IsCanceled)
        {
            ct.ThrowIfCancellationRequested();
            return false;
        }

        if (controlTask.IsFaulted)
        {
            return false;
        }

        if (controlTask.Result)
        {
            return true;
        }

        rejected = true;
        return false;
    }

    private static async Task<AccelerationControlSendResult> MapAccelerationControlSendAttemptAsync(
        Task<bool> attempt,
        string lane)
        => await attempt.ConfigureAwait(false)
            ? AccelerationControlSendResult.Success(lane)
            : AccelerationControlSendResult.Failed;

    private static async Task<AccelerationControlSendResult> MapAccelerationControlQueueAcceptedObservedAttemptAsync(
        Task<bool> attempt,
        string purpose,
        MsgType messageType,
        string queueObservedReason)
    {
        if (!await attempt.ConfigureAwait(false))
        {
            return AccelerationControlSendResult.Failed;
        }

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=tuna_acceleration_control_queue_accepted_as_observed; purpose={SanitizeLogToken(purpose)}; message_type={MapAccelerationControlMessageType(messageType)}; reason={SanitizeLogToken(queueObservedReason)}");
        return AccelerationControlSendResult.Success(AccelerationObservedLaneControlQueueExplicitObserved);
    }

    private static async Task<AccelerationControlSendResult> WaitForFirstSuccessfulAccelerationControlSendAsync(
        List<AccelerationControlSendAttempt> attempts,
        string purpose,
        string? sessionId,
        bool preferPreferredObservedLane = false)
    {
        if (attempts.Count == 0)
        {
            return AccelerationControlSendResult.Failed;
        }

        var waitTimeout = ResolveAccelerationControlBulkBypassWait();
        var remaining = new List<AccelerationControlSendAttempt>(attempts);
        AccelerationControlSendResult? fallbackObservedSend = null;
        var waitingForPreferredLaneLogged = false;
        var timeoutTask = Task.Delay(waitTimeout);
        while (remaining.Count > 0)
        {
            var completed = await Task.WhenAny(remaining.Select(static attempt => (Task)attempt.Task).Append(timeoutTask)).ConfigureAwait(false);
            if (ReferenceEquals(completed, timeoutTask))
            {
                if (fallbackObservedSend is { Succeeded: true })
                {
                    LocalOperationalLog.Warn(
                        "NKN.Tuna",
                        $"event=tuna_acceleration_control_send_preferred_bulk_observed_lane_unavailable; purpose={SanitizeLogToken(purpose)}; fallback_lane={SanitizeLogToken(fallbackObservedSend.Value.ObservedLane ?? "(none)")}; reason=timeout; wait_ms={(long)waitTimeout.TotalMilliseconds}; remaining={remaining.Count}");
                    return fallbackObservedSend.Value;
                }

                LocalOperationalLog.Warn(
                    "NKN.Tuna",
                    $"event=tuna_acceleration_control_send_wait_timeout; purpose={SanitizeLogToken(purpose)}; wait_ms={(long)waitTimeout.TotalMilliseconds}; remaining={remaining.Count}");
                return AccelerationControlSendResult.Failed;
            }

            var completedAttempt = remaining.First(attempt => ReferenceEquals(attempt.Task, completed));
            remaining.Remove(completedAttempt);
            try
            {
                var result = await completedAttempt.Task.ConfigureAwait(false);
                if (result.Succeeded)
                {
                    if (preferPreferredObservedLane && !completedAttempt.PreferredObservedLane)
                    {
                        fallbackObservedSend ??= result;
                        if (remaining.Any(static attempt => attempt.PreferredObservedLane))
                        {
                            if (!waitingForPreferredLaneLogged)
                            {
                                waitingForPreferredLaneLogged = true;
                                LocalOperationalLog.Info(
                                    "NKN.Tuna",
                                    $"event=tuna_acceleration_control_send_waiting_for_preferred_bulk_observed_lane; purpose={SanitizeLogToken(purpose)}; session_id={SanitizeLogToken(sessionId ?? "none")}; fallback_lane={SanitizeLogToken(result.ObservedLane ?? "(none)")}; wait_ms={(long)waitTimeout.TotalMilliseconds}");
                            }

                            continue;
                        }

                        LocalOperationalLog.Warn(
                            "NKN.Tuna",
                            $"event=tuna_acceleration_control_send_preferred_bulk_observed_lane_unavailable; purpose={SanitizeLogToken(purpose)}; session_id={SanitizeLogToken(sessionId ?? "none")}; fallback_lane={SanitizeLogToken(result.ObservedLane ?? "(none)")}; reason=preferred_attempts_completed");
                        return result;
                    }

                    if (preferPreferredObservedLane && completedAttempt.PreferredObservedLane)
                    {
                        LocalOperationalLog.Info(
                            "NKN.Tuna",
                            $"event=tuna_acceleration_control_send_preferred_bulk_observed_lane_selected; purpose={SanitizeLogToken(purpose)}; session_id={SanitizeLogToken(sessionId ?? "none")}; observed_lane={SanitizeLogToken(result.ObservedLane ?? "(none)")}");
                    }

                    return result;
                }
            }
            catch (Exception ex) when (ex is not OperationCanceledException)
            {
                LocalOperationalLog.Warn(
                    "NKN.Tuna",
                    $"event=tuna_acceleration_control_send_attempt_failed; purpose={SanitizeLogToken(purpose)}; error={ex.GetType().Name}");
            }

            if (preferPreferredObservedLane &&
                fallbackObservedSend is { Succeeded: true } &&
                !remaining.Any(static attempt => attempt.PreferredObservedLane))
            {
                LocalOperationalLog.Warn(
                    "NKN.Tuna",
                    $"event=tuna_acceleration_control_send_preferred_bulk_observed_lane_unavailable; purpose={SanitizeLogToken(purpose)}; session_id={SanitizeLogToken(sessionId ?? "none")}; fallback_lane={SanitizeLogToken(fallbackObservedSend.Value.ObservedLane ?? "(none)")}; reason=preferred_attempts_failed");
                return fallbackObservedSend.Value;
            }
        }

        if (fallbackObservedSend is { Succeeded: true })
        {
            return fallbackObservedSend.Value;
        }

        return AccelerationControlSendResult.Failed;
    }

    private async Task<AccelerationControlSendResult> TrySendRuntimeUnlockOfferViaPeerVisibleControlPlaneAsObservedAsync(
        string target,
        Envelope envelope,
        string sessionId,
        long payerDecisionId,
        string nonce,
        long offerGeneration,
        string trigger,
        RuntimeUnlockOfferAuthorityBoundary expectedOfferAuthorityBoundary)
    {
        if (expectedOfferAuthorityBoundary.Mode !=
                RuntimeUnlockOfferAuthorityMode.InstalledRetry ||
            !ValidateRuntimeUnlockOfferAuthorityBoundary(
                expectedOfferAuthorityBoundary,
                "peer_visible_observed_send_entry",
                allowDispatchObservedSettlement: true))
        {
            return AccelerationControlSendResult.StaleCallback;
        }

        var attemptReason = "unknown";
        if (!ShouldAttemptRuntimeUnlockPeerVisibleControlPlaneObservedSend(
                sessionId,
                offerGeneration,
                expectedOfferAuthorityBoundary,
                out attemptReason))
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=runtime_unlock_control_plane_observed_send_skipped; session_id={SanitizeLogToken(sessionId)}; payer_decision_id={payerDecisionId}; generation={offerGeneration}; trigger={SanitizeLogToken(trigger)}; reason={SanitizeLogToken(attemptReason)}");
            return AccelerationControlSendResult.Failed;
        }

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=runtime_unlock_control_plane_observed_send_started; session_id={SanitizeLogToken(sessionId)}; payer_decision_id={payerDecisionId}; generation={offerGeneration}; trigger={SanitizeLogToken(trigger)}; lane={AccelerationObservedLaneControlPlanePeerVisible}; reason={SanitizeLogToken(attemptReason)}");

        var peerVisible = await TryConfirmRuntimeUnlockPeerVisibleOfferDeliveryAsync(
                target,
                envelope,
                sessionId,
                payerDecisionId,
                nonce,
                offerGeneration,
                trigger,
                CancellationToken.None,
                expectedOfferAuthorityBoundary)
            .ConfigureAwait(false);
        if (!peerVisible)
        {
            LocalOperationalLog.Warn(
                "NKN.Tuna",
                $"event=runtime_unlock_control_plane_observed_send_failed; session_id={SanitizeLogToken(sessionId)}; payer_decision_id={payerDecisionId}; generation={offerGeneration}; trigger={SanitizeLogToken(trigger)}; lane={AccelerationObservedLaneControlPlanePeerVisible}");
            return AccelerationControlSendResult.Failed;
        }

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=runtime_unlock_control_plane_observed_send_succeeded; session_id={SanitizeLogToken(sessionId)}; payer_decision_id={payerDecisionId}; generation={offerGeneration}; trigger={SanitizeLogToken(trigger)}; lane={AccelerationObservedLaneControlPlanePeerVisible}; reason={SanitizeLogToken(attemptReason)}");
        if (expectedOfferAuthorityBoundary?.Mode ==
            RuntimeUnlockOfferAuthorityMode.InstalledRetry)
        {
            MarkRuntimeUnlockRegularV4ActivationWindowPeerVisibleIfCurrent(
                sessionId,
                offerGeneration,
                "runtime_unlock_peer_visible_offer_delivery");
        }
        return AccelerationControlSendResult.Success(AccelerationObservedLaneControlPlanePeerVisible);
    }

    private bool ShouldAttemptRuntimeUnlockPeerVisibleControlPlaneObservedSend(
        string? sessionId,
        long offerGeneration,
        RuntimeUnlockOfferAuthorityBoundary authorityBoundary,
        out string reason)
    {
        reason = "unknown";
        if (authorityBoundary.Mode !=
            RuntimeUnlockOfferAuthorityMode.InstalledRetry)
        {
            reason = "initial_activation_has_no_retry_observed_send_authority";
            return false;
        }

        if (string.IsNullOrWhiteSpace(sessionId))
        {
            reason = "missing_session_id";
            return false;
        }

        var normalizedSessionId = sessionId.Trim();
        if (!IsCurrentRuntimeUnlockActivationOffer())
        {
            reason = "not_current_runtime_unlock_offer";
            return false;
        }

        var fallbackYieldAdmissionTransferId =
            ResolveSingleActiveFileTransferDataSessionTransferId(normalizedSessionId, transferId: null);
        var hasFallbackYieldAdmission =
            !string.IsNullOrWhiteSpace(fallbackYieldAdmissionTransferId) &&
            TryGetEffectiveFallbackPairedTailYieldInstallReceipt(
                normalizedSessionId,
                fallbackYieldAdmissionTransferId,
                direction: null,
                out _);
        var currentOfferMatches = HasCurrentRuntimeUnlockOfferProofState(
            normalizedSessionId,
            offerGeneration);
        if (!HasActiveRegularV4FileTransferRouteHint(normalizedSessionId) &&
            !(hasFallbackYieldAdmission && currentOfferMatches))
        {
            reason = "regular_v4_route_not_active";
            return false;
        }

        if (HasActivePostTunaFallbackFileTransferRouteHint(normalizedSessionId) ||
            TryGetUnresolvedFileTransferV6TransportEpochForCurrentSession(out _))
        {
            if (hasFallbackYieldAdmission && currentOfferMatches)
            {
                reason = "post_tuna_fallback_tail_quiescent";
                return true;
            }

            reason = "fallback_recovery_owns_survival_path";
            return false;
        }

        if (hasFallbackYieldAdmission && currentOfferMatches)
        {
            reason = "post_tuna_fallback_tail_quiescent";
            return true;
        }

        if (!TryGetRuntimeUnlockRetryAuthorityForCurrentOffer(out var authorityState, normalizedSessionId) ||
            authorityState is null)
        {
            reason = IsRuntimeUnlockRetryDispatchEvaluationHeldForSession(
                normalizedSessionId,
                out var heldReason)
                ? heldReason
                : "missing_runtime_unlock_retry_authority";
            return false;
        }

        if (authorityState.ContractState is SessionRecoveryContractState.Completed or SessionRecoveryContractState.Failed)
        {
            reason = "runtime_unlock_contract_terminal";
            return false;
        }

        if (!authorityState.RetryAuthorityGranted ||
            !authorityState.RetryAuthorityPending ||
            !authorityState.ObservedSendPending)
        {
            reason = "runtime_unlock_retry_authority_not_pending";
            return false;
        }

        if (authorityState.CurrentOfferGeneration != offerGeneration)
        {
            reason = "stale_offer_generation";
            return false;
        }

        if (!authorityState.RegularV4ActivationWindowStarted)
        {
            reason = "regular_v4_activation_window_not_started";
            return false;
        }

        reason = "current_regular_v4_runtime_unlock_authority";
        return true;
    }

    private bool HasCurrentRuntimeUnlockOfferProofState(
        string sessionId,
        long offerGeneration)
    {
        if (string.IsNullOrWhiteSpace(sessionId) || offerGeneration <= 0)
        {
            return false;
        }

        var normalizedSessionId = sessionId.Trim();
        lock (accelerationGate)
        {
            var offer = runtimeUnlockOfferProofState;
            return offer is not null &&
                   !offer.Retired &&
                   offer.Generation == offerGeneration &&
                   string.Equals(offer.SessionId, normalizedSessionId, StringComparison.Ordinal);
        }
    }

    private bool ShouldPauseRegularNknV4FileTransferForRuntimeUnlockActivationWindowOfferSend(
        string? sessionId,
        long offerGeneration,
        out string reason)
    {
        reason = "unknown";
        if (string.IsNullOrWhiteSpace(sessionId))
        {
            reason = "missing_session_id";
            return false;
        }

        if (offerGeneration <= 0)
        {
            reason = "missing_offer_generation";
            return false;
        }

        var normalizedSessionId = sessionId.Trim();
        if (!IsCurrentRuntimeUnlockActivationOffer())
        {
            reason = "not_current_runtime_unlock_offer";
            return false;
        }

        if (!HasActiveRegularV4FileTransferRouteHint(normalizedSessionId))
        {
            reason = "regular_v4_route_not_active";
            return false;
        }

        if (HasActivePostTunaFallbackFileTransferRouteHint(normalizedSessionId) ||
            TryGetUnresolvedFileTransferV6TransportEpochForCurrentSession(out _))
        {
            reason = "fallback_recovery_owns_survival_path";
            return false;
        }

        if (!TryGetRuntimeUnlockRetryAuthorityForCurrentOffer(out var authorityState, normalizedSessionId) ||
            authorityState is null)
        {
            reason = IsRuntimeUnlockRetryDispatchEvaluationHeldForSession(
                normalizedSessionId,
                out var heldReason)
                ? heldReason
                : "missing_runtime_unlock_retry_authority";
            return false;
        }

        if (authorityState.ContractState is SessionRecoveryContractState.Completed or SessionRecoveryContractState.Failed)
        {
            reason = "runtime_unlock_contract_terminal";
            return false;
        }

        if (!authorityState.RetryAuthorityGranted ||
            !authorityState.RetryAuthorityPending)
        {
            reason = "runtime_unlock_retry_authority_not_pending";
            return false;
        }

        if (authorityState.CurrentOfferGeneration != offerGeneration)
        {
            reason = "stale_offer_generation";
            return false;
        }

        if (!authorityState.RegularV4ActivationWindowStarted)
        {
            reason = "regular_v4_activation_window_not_started";
            return false;
        }

        if (authorityState.RegularV4ActivationWindowPeerVisible)
        {
            reason = "regular_v4_activation_window_already_peer_visible";
            return false;
        }

        reason = "current_regular_v4_runtime_unlock_activation_window";
        return true;
    }

    private void ScheduleRuntimeUnlockPeerVisibleOfferDeliveryConfirmation(
        string target,
        Envelope envelope,
        string sessionId,
        long payerDecisionId,
        string nonce,
        long offerGeneration,
        string trigger,
        RuntimeUnlockOfferAuthorityBoundary expectedOfferAuthorityBoundary)
    {
        _ = Task.Run(
            () => TryConfirmRuntimeUnlockPeerVisibleOfferDeliveryAsync(
                target,
                envelope,
                sessionId,
                payerDecisionId,
                nonce,
                offerGeneration,
                trigger,
                CancellationToken.None,
                expectedOfferAuthorityBoundary),
            CancellationToken.None);
    }

    private async Task<bool> TryConfirmRuntimeUnlockPeerVisibleOfferDeliveryAsync(
        string target,
        Envelope envelope,
        string sessionId,
        long payerDecisionId,
        string nonce,
        long offerGeneration,
        string trigger,
        CancellationToken ct,
        RuntimeUnlockOfferAuthorityBoundary expectedOfferAuthorityBoundary)
    {
        if (!ValidateRuntimeUnlockOfferAuthorityBoundary(
                expectedOfferAuthorityBoundary,
                "peer_visible_confirmation_entry",
                allowDispatchObservedSettlement: true))
        {
            return false;
        }

        if (string.IsNullOrWhiteSpace(target) ||
            string.IsNullOrWhiteSpace(sessionId) ||
            string.IsNullOrWhiteSpace(nonce) ||
            offerGeneration <= 0 ||
            envelope.Type != MsgType.TransportAccelerationOffer)
        {
            return false;
        }

        LifecycleDeliveryResult result;
        try
        {
            result = await SendLifecycleEnvelopeAsync(
                    new LifecycleDeliveryOptions(
                        MessageType: MsgType.TransportAccelerationOffer,
                        RequestId: nonce,
                        ControlDestination: target,
                        BulkDestination: remoteBulkEndpoint,
                        LogCategory: "NKN.Tuna",
                        LogEvent: "runtime_unlock_control_plane_delivery",
                        AllowBulkDuplicate: true,
                        IgnoreCallerCancellation: true,
                        AcceptancePolicy: LifecycleDeliveryAcceptancePolicy.PeerVisibleRequired,
                        UseControlAckRetry: true,
                        PeerCopyAttempts: 2,
                        ThrowOnFailure: false,
                        CopyTimeout: ResolveRuntimeUnlockPeerVisibleLifecycleCopyTimeout()),
                    envelope,
                    ct)
                .ConfigureAwait(false);
        }
        catch (OperationCanceledException) when (!ct.IsCancellationRequested)
        {
            return false;
        }
        catch (Exception ex)
        {
            LocalOperationalLog.Warn(
                "NKN.Tuna",
                $"event=runtime_unlock_control_plane_delivery_failed; session_id={SanitizeLogToken(sessionId)}; payer_decision_id={payerDecisionId}; generation={offerGeneration}; trigger={SanitizeLogToken(trigger)}; error={ex.GetType().Name}");
            return false;
        }

        if (!ValidateRuntimeUnlockOfferAuthorityBoundary(
                expectedOfferAuthorityBoundary,
                "peer_visible_confirmation_completion",
                allowDispatchObservedSettlement: true))
        {
            return false;
        }

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=runtime_unlock_control_plane_delivery_result; session_id={SanitizeLogToken(sessionId)}; payer_decision_id={payerDecisionId}; generation={offerGeneration}; trigger={SanitizeLogToken(trigger)}; control_ack={(result.ControlAck ? 1 : 0)}; control_copy={(result.ControlCopy ? 1 : 0)}; bulk_copy={(result.BulkCopy ? 1 : 0)}; peer_visible_any={(result.PeerVisibleAny ? 1 : 0)}; accepted_any={(result.AcceptedAny ? 1 : 0)}; control_ack_error={result.ControlAckErrorName}; control_copy_error={result.ControlCopyErrorName}; bulk_copy_error={result.BulkCopyErrorName}");

        if (!result.ControlAck && !result.PeerVisibleAny)
        {
            LocalOperationalLog.Warn(
                "NKN.Tuna",
                $"event=runtime_unlock_control_plane_ack_not_observed; session_id={SanitizeLogToken(sessionId)}; payer_decision_id={payerDecisionId}; generation={offerGeneration}; trigger={SanitizeLogToken(trigger)}; control_copy={(result.ControlCopy ? 1 : 0)}; bulk_copy={(result.BulkCopy ? 1 : 0)}; reason=offer_ack_not_received");
            return false;
        }

        if (result.ControlAck)
        {
            if (!ValidateRuntimeUnlockOfferAuthorityBoundary(
                    expectedOfferAuthorityBoundary,
                    "peer_visible_confirmation_control_ack_apply",
                    allowDispatchObservedSettlement: true))
            {
                return false;
            }

            if (!MarkRuntimeUnlockCutThroughPeerReceived(
                    sessionId,
                    payerDecisionId,
                    nonce,
                    "transport_acceleration_offer_control_ack"))
            {
                if (!MarkRuntimeUnlockPeerReceivedIfCurrent(
                    sessionId,
                    payerDecisionId,
                    nonce,
                    offerGeneration,
                    "transport_acceleration_offer_control_ack"))
                {
                    LogRuntimeUnlockPeerVisibleWindowLateProofIgnored(
                        sessionId,
                        payerDecisionId,
                        offerGeneration,
                        "control_ack",
                        "stale_or_retired_generation");
                }
            }

            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=runtime_unlock_control_plane_peer_received; session_id={SanitizeLogToken(sessionId)}; payer_decision_id={payerDecisionId}; generation={offerGeneration}; trigger={SanitizeLogToken(trigger)}; proof=control_ack");
            return true;
        }

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=runtime_unlock_control_plane_peer_visible_copy_observed; session_id={SanitizeLogToken(sessionId)}; payer_decision_id={payerDecisionId}; generation={offerGeneration}; trigger={SanitizeLogToken(trigger)}; control_copy={(result.ControlCopy ? 1 : 0)}; bulk_copy={(result.BulkCopy ? 1 : 0)}; proof=peer_visible_copy; reason=peer_visible_delivery_satisfies_offer_window");
        if (!ValidateRuntimeUnlockOfferAuthorityBoundary(
                expectedOfferAuthorityBoundary,
                "peer_visible_confirmation_peer_copy_apply",
                allowDispatchObservedSettlement: true))
        {
            return false;
        }

        if (!MarkRuntimeUnlockCutThroughPeerReceived(
                sessionId,
                payerDecisionId,
                nonce,
                "runtime_unlock_control_plane_peer_copy") &&
            !MarkRuntimeUnlockPeerReceivedIfCurrent(
                sessionId,
                payerDecisionId,
                nonce,
                offerGeneration,
                "runtime_unlock_control_plane_peer_copy"))
        {
            LogRuntimeUnlockPeerVisibleWindowLateProofIgnored(
                sessionId,
                payerDecisionId,
                offerGeneration,
                "peer_copy",
                "stale_or_retired_generation");
        }

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=runtime_unlock_control_plane_peer_received; session_id={SanitizeLogToken(sessionId)}; payer_decision_id={payerDecisionId}; generation={offerGeneration}; trigger={SanitizeLogToken(trigger)}; proof=peer_visible_copy; reason=probe_required_before_route_commit");
        return true;
    }

    private void LogRuntimeUnlockPeerVisibleWindowLateProofIgnored(
        string sessionId,
        long payerDecisionId,
        long offerGeneration,
        string proof,
        string reason)
    {
        LocalOperationalLog.Warn(
            "NKN.Tuna",
            $"event=runtime_unlock_regular_v4_peer_visible_window_late_proof_ignored; session_id={SanitizeLogToken(sessionId)}; payer_decision_id={payerDecisionId}; generation={offerGeneration}; proof={SanitizeLogToken(proof)}; reason={SanitizeLogToken(reason)}");
    }

    private static TimeSpan ResolveRuntimeUnlockPeerVisibleLifecycleCopyTimeout()
        => RuntimeUnlockPeerVisibleLifecycleCopyTimeoutOverrideForTests ?? RuntimeUnlockPeerVisibleLifecycleCopyTimeout;

    private static TimeSpan ResolveAccelerationControlBulkBypassWait()
        => AccelerationControlBulkBypassWaitOverrideForTests ?? AccelerationControlBulkBypassWait;

    private static TimeSpan ResolveAccelerationControlDirectSendWait()
        => AccelerationControlDirectSendWaitOverrideForTests ?? AccelerationControlDirectSendWait;

    private async Task<bool> SendAccelerationControlPriorityCopyAsync(
        string destination,
        Envelope envelope,
        byte[] bytes,
        string purpose,
        CancellationToken ct)
    {
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=tuna_acceleration_control_priority_started; purpose={SanitizeLogToken(purpose)}; message_type={MapAccelerationControlMessageType(envelope.Type)}; lane=control_priority");
        try
        {
            return await TrySendAccelerationControlDirectCopyAsync(
                destination,
                bytes,
                purpose,
                envelope.Type,
                "control_priority",
                "tuna_acceleration_control_priority_sent",
                "tuna_acceleration_control_priority_failed",
                ct).ConfigureAwait(false);
        }
        catch (Exception ex) when (ex is not OperationCanceledException)
        {
            LocalOperationalLog.Warn(
                "NKN.Tuna",
                $"event=tuna_acceleration_control_priority_failed; purpose={SanitizeLogToken(purpose)}; message_type={MapAccelerationControlMessageType(envelope.Type)}; error={ex.GetType().Name}");
            return false;
        }
    }

    private async Task<AccelerationControlSendResult> SendAccelerationControlBulkCopyAsync(
        string destination,
        Envelope envelope,
        byte[] bytes,
        string purpose,
        CancellationToken ct,
        Func<string?>? skipBulkQueueFallbackObservedProofReason = null,
        Func<string?>? continueToBulkQueueFallbackAfterDirectSuccessReason = null,
        Func<string?>? bulkQueueFallbackObservedProofFailureReason = null)
    {
        try
        {
            var endpointPreSendFailureReason =
                envelope.Type == MsgType.TransportAccelerationOffer &&
                IsTunaActivationOfferSendPurpose(purpose)
                    ? bulkQueueFallbackObservedProofFailureReason?.Invoke()
                    : null;
            if (!string.IsNullOrWhiteSpace(endpointPreSendFailureReason))
            {
                LocalOperationalLog.Warn(
                    "NKN.Tuna",
                    $"event=tuna_acceleration_control_bulk_endpoint_observed_untrusted; purpose={SanitizeLogToken(purpose)}; message_type={MapAccelerationControlMessageType(envelope.Type)}; observed_lane=control_to_bulk_endpoint; reason={SanitizeLogToken(endpointPreSendFailureReason)}; stage=pre_send; peer_visible_proof_required=1");
                return AccelerationControlSendResult.Failed;
            }

            if (await TrySendAccelerationControlDirectCopyAsync(
                    destination,
                    bytes,
                    purpose,
                    envelope.Type,
                    "control_to_bulk_endpoint",
                    "tuna_acceleration_control_bulk_bypass_sent",
                    "tuna_acceleration_control_bulk_bypass_priority_failed",
                    ct).ConfigureAwait(false))
            {
                var continueReason = continueToBulkQueueFallbackAfterDirectSuccessReason?.Invoke();
                if (!string.IsNullOrWhiteSpace(continueReason))
                {
                    LocalOperationalLog.Warn(
                        "NKN.Tuna",
                        $"event=tuna_acceleration_control_bulk_endpoint_observed_untrusted; purpose={SanitizeLogToken(purpose)}; message_type={MapAccelerationControlMessageType(envelope.Type)}; observed_lane=control_to_bulk_endpoint; reason={SanitizeLogToken(continueReason)}; fallback_lane=bulk_queue_fallback");
                }
                else
                {
                    return AccelerationControlSendResult.Success(AccelerationObservedLaneControlToBulkEndpoint);
                }
            }
        }
        catch (Exception ex) when (ex is not OperationCanceledException)
        {
            LocalOperationalLog.Warn(
                "NKN.Tuna",
                $"event=tuna_acceleration_control_bulk_bypass_priority_failed; purpose={SanitizeLogToken(purpose)}; message_type={MapAccelerationControlMessageType(envelope.Type)}; error={ex.GetType().Name}");
        }

        var skipReason = skipBulkQueueFallbackObservedProofReason?.Invoke();
        if (!string.IsNullOrWhiteSpace(skipReason))
        {
            LocalOperationalLog.Warn(
                "NKN.Tuna",
                $"event=tuna_acceleration_control_bulk_queue_fallback_skipped; purpose={SanitizeLogToken(purpose)}; message_type={MapAccelerationControlMessageType(envelope.Type)}; reason=runtime_unlock_active_filetransfer_requires_direct_observed_send; blocker_reason={SanitizeLogToken(skipReason)}");
            return AccelerationControlSendResult.Failed;
        }

        try
        {
            var preSendFailureReason = bulkQueueFallbackObservedProofFailureReason?.Invoke();
            if (!string.IsNullOrWhiteSpace(preSendFailureReason))
            {
                LocalOperationalLog.Warn(
                    "NKN.Tuna",
                    $"event=tuna_acceleration_control_bulk_queue_fallback_observed_untrusted; purpose={SanitizeLogToken(purpose)}; message_type={MapAccelerationControlMessageType(envelope.Type)}; lane=bulk_queue_fallback; reason={SanitizeLogToken(preSendFailureReason)}; stage=pre_send");
                return AccelerationControlSendResult.Failed;
            }

            await SendBulkEnvelopeAsync(destination, envelope, bytes, ct, allowAcceleration: false).ConfigureAwait(false);
            var failureReason = bulkQueueFallbackObservedProofFailureReason?.Invoke();
            if (!string.IsNullOrWhiteSpace(failureReason))
            {
                LocalOperationalLog.Warn(
                    "NKN.Tuna",
                    $"event=tuna_acceleration_control_bulk_queue_fallback_observed_untrusted; purpose={SanitizeLogToken(purpose)}; message_type={MapAccelerationControlMessageType(envelope.Type)}; lane=bulk_queue_fallback; reason={SanitizeLogToken(failureReason)}");
                return AccelerationControlSendResult.Failed;
            }

            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=tuna_acceleration_control_bulk_bypass_sent; purpose={SanitizeLogToken(purpose)}; message_type={MapAccelerationControlMessageType(envelope.Type)}; lane=bulk_queue_fallback");
            return AccelerationControlSendResult.Success(AccelerationObservedLaneBulkQueueFallback);
        }
        catch (Exception ex) when (ex is not OperationCanceledException)
        {
            LocalOperationalLog.Warn(
                "NKN.Tuna",
                $"event=tuna_acceleration_control_bulk_bypass_failed; purpose={SanitizeLogToken(purpose)}; message_type={MapAccelerationControlMessageType(envelope.Type)}; error={ex.GetType().Name}");
            return AccelerationControlSendResult.Failed;
        }
    }

    private async Task<bool> TrySendAccelerationControlDirectCopyAsync(
        string destination,
        byte[] bytes,
        string purpose,
        MsgType messageType,
        string lane,
        string sentEvent,
        string failedEvent,
        CancellationToken ct)
    {
        if (messageType == MsgType.TransportAccelerationOffer &&
            IsTunaActivationOfferSendPurpose(purpose) &&
            RuntimeUnlockOfferDirectObservedLaneBlockerOverrideForTests?.Invoke(this, lane) is { Length: > 0 } blockerReason)
        {
            LocalOperationalLog.Warn(
                "NKN.Tuna",
                $"event={failedEvent}; purpose={SanitizeLogToken(purpose)}; message_type={MapAccelerationControlMessageType(messageType)}; lane={SanitizeLogToken(lane)}; error={SanitizeLogToken(blockerReason)}");
            return false;
        }

        Task sendTask;
        try
        {
            NknRuntimeDiagnostics.IncrementMessagesSent();
            sendTask = client.SendAsync(destination, bytes, ct);
        }
        catch (Exception ex) when (ex is not OperationCanceledException)
        {
            LocalOperationalLog.Warn(
                "NKN.Tuna",
                $"event={failedEvent}; purpose={SanitizeLogToken(purpose)}; message_type={MapAccelerationControlMessageType(messageType)}; lane={SanitizeLogToken(lane)}; error={ex.GetType().Name}");
            return false;
        }

        var waitTimeout = ResolveAccelerationControlDirectSendWait();
        var timeoutTask = Task.Delay(waitTimeout, ct);
        var completed = await Task.WhenAny(sendTask, timeoutTask).ConfigureAwait(false);
        if (!ReferenceEquals(completed, sendTask))
        {
            if (ct.IsCancellationRequested)
            {
                ct.ThrowIfCancellationRequested();
            }

            LocalOperationalLog.Warn(
                "NKN.Tuna",
                $"event={failedEvent}; purpose={SanitizeLogToken(purpose)}; message_type={MapAccelerationControlMessageType(messageType)}; lane={SanitizeLogToken(lane)}; error=Timeout; wait_ms={(long)waitTimeout.TotalMilliseconds}");
            ObserveAccelerationControlDirectSendLateTask(sendTask, purpose, lane);
            return false;
        }

        try
        {
            await sendTask.ConfigureAwait(false);
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event={sentEvent}; purpose={SanitizeLogToken(purpose)}; message_type={MapAccelerationControlMessageType(messageType)}; lane={SanitizeLogToken(lane)}");
            return true;
        }
        catch (Exception ex) when (ex is not OperationCanceledException)
        {
            LocalOperationalLog.Warn(
                "NKN.Tuna",
                $"event={failedEvent}; purpose={SanitizeLogToken(purpose)}; message_type={MapAccelerationControlMessageType(messageType)}; lane={SanitizeLogToken(lane)}; error={ex.GetType().Name}");
            return false;
        }
    }

    private static void ObserveAccelerationControlDirectSendLateTask(Task task, string purpose, string lane)
    {
        _ = task.ContinueWith(
            completed =>
            {
                if (completed.IsFaulted)
                {
                    var ex = completed.Exception?.GetBaseException();
                    LocalOperationalLog.Warn(
                        "NKN.Tuna",
                        $"event=tuna_acceleration_control_direct_send_late_failure; purpose={SanitizeLogToken(purpose)}; lane={SanitizeLogToken(lane)}; error={ex?.GetType().Name ?? "unknown"}");
                }
                else if (completed.IsCanceled)
                {
                    LocalOperationalLog.Warn(
                        "NKN.Tuna",
                        $"event=tuna_acceleration_control_direct_send_late_canceled; purpose={SanitizeLogToken(purpose)}; lane={SanitizeLogToken(lane)}");
                }
            },
            CancellationToken.None,
            TaskContinuationOptions.ExecuteSynchronously,
            TaskScheduler.Default);
    }

    private static void ObserveAccelerationControlSendTask(Task<bool> task, string purpose, string lane)
    {
        _ = task.ContinueWith(
            completed =>
            {
                if (completed.IsFaulted)
                {
                    var ex = completed.Exception?.GetBaseException();
                    LocalOperationalLog.Warn(
                        "NKN.Tuna",
                        $"event=tuna_acceleration_control_send_late_failure; purpose={SanitizeLogToken(purpose)}; lane={SanitizeLogToken(lane)}; error={ex?.GetType().Name ?? "unknown"}");
                }
            },
            CancellationToken.None,
            TaskContinuationOptions.ExecuteSynchronously,
            TaskScheduler.Default);
    }

    private static void ObserveAccelerationControlSendTask(Task<AccelerationControlSendResult> task, string purpose, string lane)
    {
        _ = task.ContinueWith(
            completed =>
            {
                if (completed.IsFaulted)
                {
                    var ex = completed.Exception?.GetBaseException();
                    LocalOperationalLog.Warn(
                        "NKN.Tuna",
                        $"event=tuna_acceleration_control_send_late_failure; purpose={SanitizeLogToken(purpose)}; lane={SanitizeLogToken(lane)}; error={ex?.GetType().Name ?? "unknown"}");
                }
            },
            CancellationToken.None,
            TaskContinuationOptions.ExecuteSynchronously,
            TaskScheduler.Default);
    }

    private static string MapAccelerationControlMessageType(MsgType messageType)
        => messageType switch
        {
            MsgType.TransportAccelerationOffer => "transport_acceleration_offer",
            MsgType.TransportAccelerationAnswer => "transport_acceleration_answer",
            MsgType.TransportAccelerationAnswerAck => "transport_acceleration_answer_ack",
            MsgType.TransportAccelerationDown => "transport_acceleration_down",
            MsgType.TransportAccelerationPayerIntent => "transport_acceleration_payer_intent",
            _ => SanitizeLogToken(messageType.ToString()),
        };

    private void SendAccelerationLifecycleAckIfValid(string source, Envelope env, string messageType)
    {
        if (string.IsNullOrWhiteSpace(source))
        {
            return;
        }

        SendAckFireAndForget(source, env.Code, env.MessageId);
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=tuna_acceleration_lifecycle_ack_sent; message_type={SanitizeLogToken(messageType)}; msg_id={SanitizeLogToken(env.MessageId)}");
    }

    private void HandleTransportAccelerationAnswer(string source, Envelope env)
    {
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=tuna_acceleration_answer_received_raw; msg_id={SanitizeLogToken(env.MessageId)}");
        if (!TryDecryptControlPayload(source, env, MsgType.TransportAccelerationAnswer, out var securePayload))
        {
            return;
        }

        if (!TryDeserializeAccelerationPayload<TransportAccelerationAnswerPayload>(securePayload.Plaintext, out var answer) ||
            answer is null)
        {
            RejectAccelerationEnvelope("transport_acceleration_answer", "payload_invalid", env.MessageId);
            return;
        }

        if (!TryValidateControlSecureMetadata("transport_acceleration_answer", securePayload.Metadata, answer.Nonce, env.MessageId))
        {
            return;
        }

        SendAccelerationLifecycleAckIfValid(source, env, "transport_acceleration_answer");

        string? expectedNonce;
        string? expectedTrigger;
        RuntimeUnlockRetryDispatchInstallReceipt? expectedInstallReceipt;
        RuntimeUnlockOfferAuthorityBoundary? expectedOfferAuthorityBoundary;
        long expectedPayerDecisionId;
        long expectedOfferGeneration;
        bool matchedRetiredOffer;
        bool matchedRetiredRuntimeUnlockGeneration;
        bool matchedPayerYieldRetiredRuntimeUnlockGeneration;
        var answerSessionId = string.IsNullOrWhiteSpace(answer.SessionId) ? string.Empty : answer.SessionId.Trim();
        var answerNonce = string.IsNullOrWhiteSpace(answer.Nonce) ? string.Empty : answer.Nonce.Trim();
        var nowMs = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
        lock (accelerationGate)
        {
            matchedRetiredOffer = false;
            matchedRetiredRuntimeUnlockGeneration = false;
            matchedPayerYieldRetiredRuntimeUnlockGeneration = false;
            if (!string.IsNullOrWhiteSpace(outboundAccelerationOfferNonce) &&
                string.Equals(outboundAccelerationOfferNonce, answerNonce, StringComparison.Ordinal))
            {
                expectedNonce = outboundAccelerationOfferNonce;
                expectedTrigger = outboundAccelerationOfferTrigger;
                expectedInstallReceipt =
                    outboundAccelerationOfferInstallReceipt;
                expectedOfferAuthorityBoundary =
                    outboundRuntimeUnlockOfferAuthorityBoundary;
                expectedPayerDecisionId = outboundAccelerationOfferPayerDecisionId;
                expectedOfferGeneration = outboundAccelerationOfferGeneration;
            }
            else if (!string.IsNullOrWhiteSpace(retiredAccelerationOfferNonce) &&
                     string.Equals(retiredAccelerationOfferNonce, answerNonce, StringComparison.Ordinal) &&
                     string.Equals(retiredAccelerationOfferSessionId, answerSessionId, StringComparison.Ordinal) &&
                     nowMs < retiredAccelerationOfferExpiresUtcMs)
            {
                expectedNonce = retiredAccelerationOfferNonce;
                expectedTrigger = retiredAccelerationOfferTrigger;
                expectedInstallReceipt =
                    retiredAccelerationOfferInstallReceipt;
                expectedOfferAuthorityBoundary =
                    retiredRuntimeUnlockOfferAuthorityBoundary;
                expectedPayerDecisionId = retiredAccelerationOfferPayerDecisionId;
                expectedOfferGeneration =
                    expectedOfferAuthorityBoundary?.OfferGeneration ?? 0;
                matchedRetiredOffer = true;
                var state = runtimeUnlockOfferProofState;
                matchedRetiredRuntimeUnlockGeneration =
                    state is not null &&
                    ShouldRejectRetiredRuntimeUnlockAnswer(state) &&
                    state.PayerDecisionId == expectedPayerDecisionId &&
                    string.Equals(state.Nonce, answerNonce, StringComparison.Ordinal) &&
                    string.Equals(state.SessionId, answerSessionId, StringComparison.Ordinal);
                matchedPayerYieldRetiredRuntimeUnlockGeneration =
                    state is not null &&
                    IsPayerYieldRuntimeUnlockPendingAnswerRetiredReason(state.RetiredReason) &&
                    state.PayerDecisionId == expectedPayerDecisionId &&
                    string.Equals(state.Nonce, answerNonce, StringComparison.Ordinal) &&
                    string.Equals(state.SessionId, answerSessionId, StringComparison.Ordinal);
            }
            else
            {
                expectedNonce = null;
                expectedTrigger = null;
                expectedInstallReceipt = null;
                expectedOfferAuthorityBoundary = null;
                expectedPayerDecisionId = 0;
                expectedOfferGeneration = 0;
            }
        }

        if (string.IsNullOrWhiteSpace(expectedNonce) ||
            !string.Equals(expectedNonce, answerNonce, StringComparison.Ordinal))
        {
            RejectAccelerationEnvelope("transport_acceleration_answer", "nonce_mismatch", env.MessageId);
            ResumeFileTransferDataSessionsAfterTunaActivationFailure(
                "nonce_mismatch",
                answer.SessionId,
                "transport_acceleration_answer");
            return;
        }

        var isRuntimeUnlockOffer =
            expectedOfferAuthorityBoundary is not null;
        if (isRuntimeUnlockOffer &&
            !ValidateRuntimeUnlockOfferAuthorityBoundary(
                expectedOfferAuthorityBoundary,
                "answer_received",
                allowDispatchObservedSettlement: true))
        {
            return;
        }

        if (matchedRetiredRuntimeUnlockGeneration)
        {
            lock (accelerationGate)
            {
                ClearRetiredOutboundAccelerationOfferLocked();
            }

            LocalOperationalLog.Warn(
                "NKN.Tuna",
                $"event=tuna_acceleration_stale_offer_answer_ignored; reason=retired_generation; session_id={SanitizeLogToken(answer.SessionId)}; payer_decision_id={answer.PayerDecisionId}");
            RejectAccelerationEnvelope("transport_acceleration_answer", "stale_offer_generation", env.MessageId);
            return;
        }

        if (matchedPayerYieldRetiredRuntimeUnlockGeneration)
        {
            lock (accelerationGate)
            {
                ClearRetiredOutboundAccelerationOfferLocked();
            }

            LocalOperationalLog.Warn(
                "NKN.Tuna",
                $"event=runtime_unlock_answer_rejected_tuna_path_lease_unavailable; session_id={SanitizeLogToken(answer.SessionId)}; payer_decision_id={expectedPayerDecisionId}; offer_generation={expectedOfferGeneration}; reject_reason=payer_yield_pending_runtime_unlock_answer");
            RejectAccelerationEnvelope("transport_acceleration_answer", "tuna_path_lease_unavailable", env.MessageId);
            ResumeFileTransferDataSessionsAfterTunaActivationFailure(
                "tuna_path_lease_unavailable",
                answer.SessionId,
                "transport_acceleration_answer_payer_yield_retired");
            return;
        }

        if (expectedPayerDecisionId > 0 &&
            answer.PayerDecisionId != expectedPayerDecisionId)
        {
            RejectAccelerationEnvelope("transport_acceleration_answer", "payer_decision_mismatch", env.MessageId);
            ResumeFileTransferDataSessionsAfterTunaActivationFailure(
                "payer_decision_mismatch",
                answer.SessionId,
                "transport_acceleration_answer");
            return;
        }

        if (isRuntimeUnlockOffer &&
            expectedOfferGeneration > 0)
        {
            if (expectedOfferAuthorityBoundary?.Mode !=
                    RuntimeUnlockOfferAuthorityMode.InstalledRetry ||
                !MarkRuntimeUnlockCutThroughPeerReceived(
                answer.SessionId,
                answer.PayerDecisionId,
                answerNonce,
                "transport_acceleration_answer"))
            {
                MarkRuntimeUnlockPeerReceivedIfCurrent(
                    answer.SessionId,
                    answer.PayerDecisionId,
                    answerNonce,
                    expectedOfferGeneration,
                    "transport_acceleration_answer");
            }
        }

        var validation = ValidateAccelerationAnswer(source, answer, requireAcceptedLanes: answer.Accepted);
        if (validation.IsHardReject)
        {
            RejectAccelerationEnvelope("transport_acceleration_answer", validation.Reason ?? "invalid", env.MessageId);
            ResumeFileTransferDataSessionsAfterTunaActivationFailure(
                validation.Reason ?? "invalid",
                answer.SessionId,
                "transport_acceleration_answer");
            return;
        }

        var answerReplyTarget = CreateAccelerationReplyTargetEvidence(
            source,
            env.MessageId,
            answer.SessionId,
            answer.Nonce,
            answer.PayerDecisionId,
            expectedOfferGeneration,
            "answer_ack");

        if (!answer.Accepted || !validation.IsValid)
        {
            var effectiveRejectReason = !answer.Accepted
                ? answer.RejectReason ?? validation.Reason ?? "rejected"
                : validation.Reason ?? answer.RejectReason ?? "rejected";
            lock (accelerationGate)
            {
                if (matchedRetiredOffer)
                {
                    ClearRetiredOutboundAccelerationOfferLocked();
                }
                else
                {
                    ClearOutboundAccelerationOfferLocked();
                }
            }

            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=tuna_acceleration_answer_rejected; reason={SanitizeLogToken(effectiveRejectReason)}; offer_trigger={SanitizeLogToken(expectedTrigger)}; payer_decision_id={expectedPayerDecisionId}");
            NotifyTransportAccelerationStateChanged($"answer_rejected_{effectiveRejectReason}");
            ResumeFileTransferDataSessionsAfterTunaActivationFailure(
                effectiveRejectReason,
                answer.SessionId,
                "transport_acceleration_answer_rejected");
            if (isRuntimeUnlockOffer &&
                expectedOfferGeneration > 0)
            {
                var normalizedRejectReason = SanitizeLogToken(effectiveRejectReason);
                if (normalizedRejectReason is "sidecar_unavailable" or "listener_sidecar_unavailable" or "runtime_unlock_tuna_dial_failed")
                {
                    var leaseReason = normalizedRejectReason is "runtime_unlock_tuna_dial_failed"
                        ? "runtime_unlock_tuna_dial_failed_before_answer"
                        : "runtime_unlock_answer_rejected_tuna_path_lease_unavailable";
                    FailRuntimeUnlockTunaPathLeaseIfCurrent(
                        answer.SessionId,
                        expectedOfferGeneration,
                        leaseReason,
                        failTransaction: true);
                    LocalOperationalLog.Warn(
                        "NKN.Tuna",
                        $"event=runtime_unlock_answer_rejected_tuna_path_lease_unavailable; session_id={SanitizeLogToken(answer.SessionId)}; payer_decision_id={expectedPayerDecisionId}; offer_generation={expectedOfferGeneration}; reject_reason={SanitizeLogToken(effectiveRejectReason)}; lease_reason={SanitizeLogToken(leaseReason)}");
                }

                if (expectedOfferAuthorityBoundary?.Mode ==
                    RuntimeUnlockOfferAuthorityMode.InstalledRetry)
                {
                    FailRuntimeUnlockCutThroughIfCurrent(
                        answer.SessionId,
                        answer.PayerDecisionId,
                        expectedOfferGeneration,
                        $"runtime_unlock_answer_rejected_{SanitizeLogToken(effectiveRejectReason)}");
                }
            }

            if (string.Equals(SanitizeLogToken(effectiveRejectReason), "helpee_payer_preferred", StringComparison.Ordinal))
            {
                AdvancePayerDecisionEpoch("yield_to_helpee_payer");
                NotifyTransportAccelerationStateChanged("suppressed_by_peer_payer");
                ScheduleAccelerationLaneStopIfStillLocalPaidListener("payer_yield_to_helpee");
                return;
            }

            var retryPeerStopAfterUnlock =
                isRuntimeUnlockOffer &&
                ShouldRetryPeerUserStoppedAfterRuntimeUnlock(effectiveRejectReason);
            var retryRuntimeUnlockAfterRejectedAnswer =
                isRuntimeUnlockOffer &&
                ShouldRetryRuntimeUnlockAfterRejectedAnswer(effectiveRejectReason);
            if (ShouldRetryAccelerationNegotiation(effectiveRejectReason) ||
                retryPeerStopAfterUnlock ||
                retryRuntimeUnlockAfterRejectedAnswer)
            {
                var retryReason = retryRuntimeUnlockAfterRejectedAnswer
                    ? SanitizeLogToken(effectiveRejectReason).StartsWith("runtime_unlock_", StringComparison.Ordinal)
                        ? SanitizeLogToken(effectiveRejectReason)
                        : $"runtime_unlock_{SanitizeLogToken(effectiveRejectReason)}"
                    : retryPeerStopAfterUnlock
                        ? "peer_user_stopped_tuna"
                        : effectiveRejectReason!;
                if (retryRuntimeUnlockAfterRejectedAnswer &&
                    expectedOfferAuthorityBoundary?.Mode ==
                        RuntimeUnlockOfferAuthorityMode.InstalledRetry &&
                    IsRuntimeUnlockListenerRearmRequiredRetryReason(retryReason))
                {
                    var listenerReadyReuse =
                        ShouldUseListenerReadyFastRetry(
                            retryReason,
                            runtimeUnlockRetry: true);
                    if (listenerReadyReuse)
                    {
                        LocalOperationalLog.Warn(
                            "NKN.Tuna",
                            $"event=session_recovery_contract_listener_rearm_skipped; session_id={SanitizeLogToken(answer.SessionId)}; reason={SanitizeLogToken(retryReason)}; trigger=transport_acceleration_answer_rejected; payer_decision_id={expectedPayerDecisionId}; listener_ready_reuse=1");
                    }
                    else
                    {
                        LocalOperationalLog.Warn(
                            "NKN.Tuna",
                            $"event=session_recovery_contract_listener_rearm_required; session_id={SanitizeLogToken(answer.SessionId)}; reason={SanitizeLogToken(retryReason)}; trigger=transport_acceleration_answer_rejected; payer_decision_id={expectedPayerDecisionId}; listener_ready_reuse=0");
                        ScheduleAccelerationLaneStop(retryReason);
                    }
                }

                if (isRuntimeUnlockOffer)
                {
                    ScheduleRuntimeUnlockOfferAuthorityRetry(
                        retryReason,
                        expectedOfferAuthorityBoundary,
                        expectedInstallReceipt);
                }
                else
                {
                    ScheduleAccelerationNegotiationRetry(retryReason);
                }
            }

            return;
        }

        if (isRuntimeUnlockOffer)
        {
            if (expectedOfferGeneration > 0)
            {
                if (IsRuntimeUnlockTunaPathLeaseUnavailableForAnswer(
                        answer.SessionId,
                        expectedOfferGeneration,
                        out var leaseUnavailableReason))
                {
                    var leaseReason = "runtime_unlock_answer_rejected_tuna_path_lease_unavailable";
                    FailRuntimeUnlockTunaPathLeaseIfCurrent(
                        answer.SessionId,
                        expectedOfferGeneration,
                        leaseReason,
                        failTransaction: true);
                    LocalOperationalLog.Warn(
                        "NKN.Tuna",
                        $"event=runtime_unlock_answer_rejected_tuna_path_lease_unavailable; session_id={SanitizeLogToken(answer.SessionId)}; payer_decision_id={expectedPayerDecisionId}; offer_generation={expectedOfferGeneration}; reject_reason={SanitizeLogToken(leaseUnavailableReason)}");
                    NotifyTransportAccelerationStateChanged("answer_rejected_tuna_path_lease_unavailable");
                    ResumeFileTransferDataSessionsAfterTunaActivationFailure(
                        "tuna_path_lease_unavailable",
                        answer.SessionId,
                        "transport_acceleration_answer_lease_unavailable");
                    ScheduleAccelerationLaneStop("runtime_unlock_sidecar_unavailable");
                    ScheduleRuntimeUnlockOfferAuthorityRetry(
                        "runtime_unlock_sidecar_unavailable",
                        expectedOfferAuthorityBoundary,
                        expectedInstallReceipt);
                    return;
                }

                if (matchedRetiredOffer &&
                    expectedOfferAuthorityBoundary?.Mode ==
                        RuntimeUnlockOfferAuthorityMode.InitialActivation)
                {
                    if (!TryPromoteRetiredPendingRuntimeUnlockAnswer(
                            expectedOfferAuthorityBoundary,
                            answer.SessionId,
                            answer.PayerDecisionId,
                            answerNonce,
                            "transport_acceleration_answer"))
                    {
                        return;
                    }
                }
                else if (expectedOfferAuthorityBoundary?.Mode !=
                             RuntimeUnlockOfferAuthorityMode.InstalledRetry ||
                         !MarkRuntimeUnlockCutThroughAnswerReceived(
                             answer.SessionId,
                             answer.PayerDecisionId,
                             expectedOfferGeneration,
                             "transport_acceleration_answer"))
                {
                    MarkRuntimeUnlockAnswerReceivedIfCurrent(
                        answer.SessionId,
                        answer.PayerDecisionId,
                        answerNonce,
                        expectedOfferGeneration,
                        "transport_acceleration_answer");
                }
            }

            PauseFileTransferDataSessionsForTunaActivationNegotiation(
                "activation_negotiation_pending",
                answer.SessionId,
                "answer_accepted");
        }

        lock (accelerationGate)
        {
            if (matchedRetiredOffer)
            {
                ClearRetiredOutboundAccelerationOfferLocked();
                ClearOutboundAccelerationOfferLocked();
            }
            else
            {
                ClearOutboundAccelerationOfferLocked();
            }

            ClearPendingAccelerationAnswerAckLocked();
            accelerationSessionId = answer.SessionId.Trim();
            accelerationNegotiatedLanes = validation.AcceptedLanes;
        }

        if (matchedRetiredOffer)
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=tuna_acceleration_retired_offer_answer_accepted; session_id={SanitizeLogToken(answer.SessionId)}; payer_decision_id={answer.PayerDecisionId}");
        }

        if (isRuntimeUnlockOffer)
        {
            _ = Task.Run(
                async () =>
                {
                    await SendAccelerationAnswerAckAsync(
                            answer,
                            answerReplyTarget,
                            validation.AcceptedLanes,
                            CancellationToken.None,
                            runtimeUnlock: true)
                        .ConfigureAwait(false);
                    await Task.Delay(RuntimeUnlockAnswerAckProbeSettleDelay, CancellationToken.None).ConfigureAwait(false);
                    Interlocked.Exchange(ref accelerationNegotiationRetryAttempts, 0);
                    LocalOperationalLog.Info(
                        "NKN.Tuna",
                        $"event=runtime_unlock_answer_ack_probe_barrier_released; session_id={SanitizeLogToken(answer.SessionId)}; lanes={FormatAccelerationLanesForLog(validation.AcceptedLanes)}; payer_decision_id={answer.PayerDecisionId}; delay_ms={(long)RuntimeUnlockAnswerAckProbeSettleDelay.TotalMilliseconds}; reason=answer_ack_sent_before_tuna_probe");
                    RequestFileTransferTunaActivationHandoff(answer.SessionId, validation.AcceptedLanes, "runtime_unlock_answer_ack_probe_ready");
                    NotifyTransportAccelerationStateChanged("runtime_unlock_pending_probe_commit");
                },
                CancellationToken.None);
            NotifyTransportAccelerationStateChanged("runtime_unlock_answer_ack_pending_probe");
            return;
        }

        RecordInitialTunaReadinessAnswerReceived(
            answer.SessionId,
            expectedOfferGeneration,
            answer.PayerDecisionId,
            "transport_acceleration_answer_received",
            answerAckReceived: false);
        _ = Task.Run(
            () => SendAccelerationAnswerAckAsync(
                answer,
                answerReplyTarget,
                validation.AcceptedLanes,
                CancellationToken.None),
            CancellationToken.None);
        Interlocked.Exchange(ref accelerationNegotiationRetryAttempts, 0);
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=tuna_acceleration_negotiated; session_id={answer.SessionId}; lanes={string.Join(",", answer.SupportedLanes)}; payer_decision_id={answer.PayerDecisionId}");
        CompleteRuntimeUnlockRecoveryContractIfActive(answer.SessionId, "transport_acceleration_answer");
        RequestFileTransferTunaActivationHandoff(answer.SessionId, validation.AcceptedLanes, "tuna_activation_negotiated");
        NotifyTransportAccelerationStateChanged(GetActiveAccelerationStatusReason());
    }

    private static bool ShouldRejectRetiredRuntimeUnlockAnswer(RuntimeUnlockOfferProofState state)
    {
        if (!state.Retired)
        {
            return false;
        }

        if (!state.ObservedSend && !state.AnswerTimeoutScheduled)
        {
            return true;
        }

        return state.RetiredReason is "offer_answer_timeout" ||
               !IsRuntimeUnlockPendingAnswerRetiredReason(state.RetiredReason);
    }

    private void HandleTransportAccelerationAnswerAck(string source, Envelope env)
    {
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=tuna_acceleration_answer_ack_received_raw; msg_id={SanitizeLogToken(env.MessageId)}");
        if (!TryDecryptControlPayload(source, env, MsgType.TransportAccelerationAnswerAck, out var securePayload))
        {
            return;
        }

        if (!TryDeserializeAccelerationPayload<TransportAccelerationAnswerAckPayload>(securePayload.Plaintext, out var ack) ||
            ack is null)
        {
            RejectAccelerationEnvelope("transport_acceleration_answer_ack", "payload_invalid", env.MessageId);
            return;
        }

        if (!TryValidateControlSecureMetadata("transport_acceleration_answer_ack", securePayload.Metadata, ack.Nonce, env.MessageId))
        {
            return;
        }

        SendAccelerationLifecycleAckIfValid(source, env, "transport_acceleration_answer_ack");

        var validation = ValidateAccelerationAnswerAck(source, ack);
        if (validation.IsHardReject || !validation.IsValid || !ack.Accepted)
        {
            RejectAccelerationEnvelope(
                "transport_acceleration_answer_ack",
                validation.Reason ?? (ack.Accepted ? "invalid" : "not_accepted"),
                env.MessageId);
            ResumeFileTransferDataSessionsAfterTunaActivationFailure(
                validation.Reason ?? (ack.Accepted ? "invalid" : "not_accepted"),
                ack.SessionId,
                "transport_acceleration_answer_ack");
            return;
        }

        var pendingLanes = NknAccelerationLaneKind.None;
        var pendingPayerDecisionId = 0L;
        var pendingAnswerAckGeneration = 0L;
        string? pendingTrigger = null;
        RuntimeUnlockOfferAuthorityMode? pendingAuthorityMode = null;
        RuntimeUnlockResponderPeerProbeHandoffEvidence? responderPeerProbeEvidence = null;
        bool alreadyNegotiated;
        string? activationFailureReason = null;
        lock (accelerationGate)
        {
            alreadyNegotiated =
                accelerationLane?.IsAvailable == true &&
                accelerationNegotiatedLanes != NknAccelerationLaneKind.None &&
                string.Equals(accelerationSessionId, ack.SessionId.Trim(), StringComparison.Ordinal);
            if (string.IsNullOrWhiteSpace(pendingAccelerationAnswerAckNonce))
            {
                if (alreadyNegotiated)
                {
                    LocalOperationalLog.Info(
                        "NKN.Tuna",
                        $"event=tuna_acceleration_answer_ack_duplicate_ignored; session_id={SanitizeLogToken(ack.SessionId)}; payer_decision_id={ack.PayerDecisionId}");
                    return;
                }
            }

            if (!string.Equals(pendingAccelerationAnswerAckNonce, ack.Nonce.Trim(), StringComparison.Ordinal))
            {
                RejectAccelerationEnvelope("transport_acceleration_answer_ack", "nonce_mismatch", env.MessageId);
                activationFailureReason = "nonce_mismatch";
            }
            else if (!string.Equals(pendingAccelerationAnswerAckSessionId, ack.SessionId.Trim(), StringComparison.Ordinal))
            {
                RejectAccelerationEnvelope("transport_acceleration_answer_ack", "session_id_mismatch", env.MessageId);
                activationFailureReason = "session_id_mismatch";
            }
            else
            {
                pendingLanes = pendingAccelerationAnswerAckLanes;
                pendingPayerDecisionId = pendingAccelerationAnswerAckPayerDecisionId;
                pendingAnswerAckGeneration = pendingAccelerationAnswerAckGeneration;
                pendingTrigger = pendingAccelerationAnswerAckTrigger;
                pendingAuthorityMode = pendingAccelerationAnswerAckAuthorityMode;
                if (pendingPayerDecisionId > 0 && ack.PayerDecisionId != pendingPayerDecisionId)
                {
                    RejectAccelerationEnvelope("transport_acceleration_answer_ack", "payer_decision_mismatch", env.MessageId);
                    activationFailureReason = "payer_decision_mismatch";
                }
                else
                {
                    var acceptedLanes = validation.AcceptedLanes & pendingLanes;
                    if (acceptedLanes == NknAccelerationLaneKind.None)
                    {
                        RejectAccelerationEnvelope("transport_acceleration_answer_ack", "unsupported_lane", env.MessageId);
                        activationFailureReason = "unsupported_lane";
                    }
                    else
                    {
                        accelerationSessionId = ack.SessionId.Trim();
                        accelerationNegotiatedLanes = acceptedLanes;
                        if (pendingAuthorityMode is { } authorityMode &&
                            runtimeUnlockTransactionState is { IsTerminal: false } transaction &&
                            transaction.AnswerReceived &&
                            transaction.PathProbeState is (
                                RuntimeUnlockPathProbeState.Started or
                                RuntimeUnlockPathProbeState.Acked) &&
                            string.Equals(transaction.SessionId, ack.SessionId.Trim(), StringComparison.Ordinal) &&
                            transaction.TransactionGeneration > 0 &&
                            transaction.OfferGeneration > 0 &&
                            transaction.TunaPathLeaseGeneration > 0 &&
                            transaction.TunaPathLeaseCurrent &&
                            !string.IsNullOrWhiteSpace(transaction.TunaPathLeaseListenerRunId) &&
                            !string.IsNullOrWhiteSpace(transaction.PathProbeId))
                        {
                            var normalizedSource = source.Trim();
                            var sourceFingerprint = Convert.ToHexString(
                                    SHA256.HashData(Encoding.UTF8.GetBytes(normalizedSource)))
                                .ToLowerInvariant();
                            responderPeerProbeEvidence = new RuntimeUnlockResponderPeerProbeHandoffEvidence(
                                transaction.SessionId,
                                transaction.TransferId,
                                transaction.TransactionGeneration,
                                transaction.OfferGeneration,
                                pendingAnswerAckGeneration,
                                authorityMode,
                                ack.PayerDecisionId,
                                env.MessageId.Trim(),
                                sourceFingerprint,
                                transaction.TunaPathLeaseGeneration,
                                transaction.TunaPathLeaseListenerRunId,
                                transaction.PathProbeId,
                                transaction.PathProbeState,
                                transaction.PathProbeTransport,
                                transaction.PathProbeAckedUtcMs);
                        }
                        ClearPendingAccelerationAnswerAckLocked();
                    }
                }
            }
        }

        if (activationFailureReason is not null)
        {
            ResumeFileTransferDataSessionsAfterTunaActivationFailure(
                activationFailureReason,
                ack.SessionId,
                "transport_acceleration_answer_ack");
            return;
        }

        if (responderPeerProbeEvidence is { } capturedEvidence &&
            string.IsNullOrWhiteSpace(capturedEvidence.TransferId))
        {
            var resolvedTransferId = ResolveSingleActiveFileTransferDataSessionTransferId(
                ack.SessionId,
                transferId: null);
            if (!string.IsNullOrWhiteSpace(resolvedTransferId))
            {
                responderPeerProbeEvidence = capturedEvidence with
                {
                    TransferId = resolvedTransferId,
                };
            }
        }

        Interlocked.Exchange(ref accelerationNegotiationRetryAttempts, 0);
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=tuna_acceleration_answer_ack_received; session_id={SanitizeLogToken(ack.SessionId)}; lanes={FormatAccelerationLanesForLog(validation.AcceptedLanes & pendingLanes)}; payer_decision_id={ack.PayerDecisionId}");
        if (pendingAuthorityMode is not null)
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=runtime_unlock_answer_ack_probe_barrier_received; session_id={SanitizeLogToken(ack.SessionId)}; lanes={FormatAccelerationLanesForLog(validation.AcceptedLanes & pendingLanes)}; payer_decision_id={ack.PayerDecisionId}; reason=answer_ack_received_before_tuna_probe");
            RequestFileTransferTunaActivationHandoffWithResponderPeerProbe(
                ack.SessionId,
                validation.AcceptedLanes & pendingLanes,
                "runtime_unlock_answer_ack_probe_ready",
                responderPeerProbeEvidence);
            NotifyTransportAccelerationStateChanged("runtime_unlock_pending_probe_commit");
            return;
        }

        RecordInitialTunaReadinessAnswerReceived(
            ack.SessionId,
            pendingAnswerAckGeneration,
            ack.PayerDecisionId,
            "transport_acceleration_answer_ack_received",
            answerAckReceived: true);
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=tuna_acceleration_negotiated; session_id={ack.SessionId}; lanes={string.Join(",", ack.SupportedLanes)}; payer_decision_id={ack.PayerDecisionId}; handshake=answer_ack");
        CompleteRuntimeUnlockRecoveryContractIfActive(ack.SessionId, "transport_acceleration_answer_ack");
        RequestFileTransferTunaActivationHandoff(ack.SessionId, validation.AcceptedLanes & pendingLanes, "tuna_activation_answer_ack");
        NotifyTransportAccelerationStateChanged(GetActiveAccelerationStatusReason());
    }

    private void HandleTransportAccelerationDown(string source, Envelope env)
    {
        if (!TryDecryptControlPayload(source, env, MsgType.TransportAccelerationDown, out var securePayload))
        {
            return;
        }

        if (!TryDeserializeAccelerationPayload<TransportAccelerationDownPayload>(securePayload.Plaintext, out var down) ||
            down is null)
        {
            RejectAccelerationEnvelope("transport_acceleration_down", "payload_invalid", env.MessageId);
            return;
        }

        if (!TryValidateControlSecureMetadata("transport_acceleration_down", securePayload.Metadata, down.Nonce, env.MessageId))
        {
            return;
        }

        var rejectReason = ValidateAccelerationDown(source, down);
        if (rejectReason is not null)
        {
            RejectAccelerationEnvelope("transport_acceleration_down", rejectReason, env.MessageId);
            return;
        }

        var downReason = $"remote_{down.Reason}";
        var downLanes = NknAccelerationLaneCodec.FromNames(down.SupportedLanes);
        var isUserRequestedDown = IsUserRequestedAccelerationStopReason(down.Reason);
        if (IsAccelerationNegotiatedAndHealthy())
        {
            if (!ResetAccelerationNegotiation(
                    downReason,
                    invalidationKind:
                        isUserRequestedDown
                            ? RuntimeUnlockInitialActivationReceiveRecoveryHoldInvalidationKind
                                .PeerCancellation
                            : RuntimeUnlockInitialActivationReceiveRecoveryHoldInvalidationKind
                                .GenericReset))
            {
                return;
            }
            if (isUserRequestedDown)
            {
                MarkAccelerationPeerUserStoppedForCurrentSession(
                    down.SessionId);
            }
            ScheduleAccelerationLaneStop(downReason);
            TryForceFileTransferFallbackForRemoteUserDown(downReason, down.SessionId, downLanes);
        }
        else if (isUserRequestedDown)
        {
            if (!ResetAccelerationNegotiation(
                    downReason,
                    invalidationKind:
                        RuntimeUnlockInitialActivationReceiveRecoveryHoldInvalidationKind
                            .PeerCancellation))
            {
                return;
            }
            MarkAccelerationPeerUserStoppedForCurrentSession(
                down.SessionId);
            ScheduleAccelerationLaneStop(downReason);
            TryForceFileTransferFallbackForRemoteUserDown(downReason, down.SessionId, downLanes);
        }
        else if (StartTunaFallbackProofIfNeeded(downReason, down.SessionId, downLanes))
        {
            RecordFileTransferTunaFallbackEvidence(downReason, down.SessionId, downLanes);
        }

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=tuna_acceleration_remote_down; reason={SanitizeLogToken(down.Reason)}; lanes={string.Join(",", down.SupportedLanes)}");
    }

    private void TryForceFileTransferFallbackForRemoteUserDown(
        string downReason,
        string? sessionId,
        NknAccelerationLaneKind downLanes)
    {
        var fileLanes = downLanes & NknAccelerationLaneKind.File;
        if (fileLanes == NknAccelerationLaneKind.None ||
            !ShouldStartFileTransferFallbackAfterUserStop(downReason, fileLanes))
        {
            return;
        }

        if (!StartTunaFallbackProofIfNeeded(downReason, sessionId, fileLanes))
        {
            return;
        }

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=tuna_acceleration_remote_down_filetransfer_fallback_forced; reason={SanitizeLogToken(downReason)}; session_id={SanitizeLogToken(sessionId ?? "none")}; lanes={FormatAccelerationLanesForLog(fileLanes)}");
        RecordFileTransferTunaFallbackEvidence(downReason, sessionId, fileLanes);
    }

    private enum AccelerationNegotiationRetryAuthorityRequirement
    {
        None = 0,
        InitialRuntimeUnlock = 1,
        RuntimeUnlockRetryDispatchInstall = 2,
    }

    private bool ScheduleAccelerationNegotiationRetry(
        string reason,
        RuntimeUnlockRetryDispatchInstallReceipt? expectedInstallReceipt = null)
        => ScheduleAccelerationNegotiationRetryCore(
            reason,
            expectedInstallReceipt,
            expectedInstallReceipt is null
                ? AccelerationNegotiationRetryAuthorityRequirement.None
                : AccelerationNegotiationRetryAuthorityRequirement
                    .RuntimeUnlockRetryDispatchInstall);

    private bool ScheduleRuntimeUnlockAccelerationNegotiationRetry(
        string reason,
        RuntimeUnlockRetryDispatchInstallReceipt? expectedInstallReceipt = null)
        => ScheduleAccelerationNegotiationRetryCore(
            reason,
            expectedInstallReceipt,
            AccelerationNegotiationRetryAuthorityRequirement
                .RuntimeUnlockRetryDispatchInstall);

    private bool ScheduleInitialRuntimeUnlockAccelerationNegotiationRetry(
        string reason)
        => ScheduleAccelerationNegotiationRetryCore(
            reason,
            expectedInstallReceipt: null,
            AccelerationNegotiationRetryAuthorityRequirement
                .InitialRuntimeUnlock);

    private bool ScheduleRuntimeUnlockOfferAuthorityRetry(
        string reason,
        RuntimeUnlockOfferAuthorityBoundary? authorityBoundary,
        RuntimeUnlockRetryDispatchInstallReceipt? expectedInstallReceipt)
    {
        if (authorityBoundary is null ||
            authorityBoundary.InstallReceipt != expectedInstallReceipt)
        {
            LogRuntimeUnlockOfferAuthorityBoundaryDecision(
                authorityBoundary,
                "retry_schedule",
                accepted: false,
                authorityBoundary is null
                    ? "runtime_unlock_offer_authority_boundary_missing"
                    : "runtime_unlock_offer_authority_mode_receipt_mismatch");
            return false;
        }

        return authorityBoundary.Mode == RuntimeUnlockOfferAuthorityMode.InitialActivation
            ? ScheduleInitialRuntimeUnlockAccelerationNegotiationRetry(reason)
            : ScheduleRuntimeUnlockAccelerationNegotiationRetry(
                reason,
                expectedInstallReceipt);
    }

    private bool ScheduleAccelerationNegotiationRetryCore(
        string reason,
        RuntimeUnlockRetryDispatchInstallReceipt? expectedInstallReceipt,
        AccelerationNegotiationRetryAuthorityRequirement authorityRequirement)
    {
        var normalizedReason = SanitizeLogToken(reason);
        var requiresRuntimeUnlockRetryDispatchInstall =
            authorityRequirement ==
            AccelerationNegotiationRetryAuthorityRequirement
                .RuntimeUnlockRetryDispatchInstall;
        var usesRuntimeUnlockRetryPolicy =
            authorityRequirement !=
            AccelerationNegotiationRetryAuthorityRequirement.None;
        if (authorityRequirement !=
                AccelerationNegotiationRetryAuthorityRequirement
                    .InitialRuntimeUnlock &&
            !ValidateRuntimeUnlockRetryDispatchInstallReceiptBoundary(
                expectedInstallReceipt,
                "retry_schedule",
                requireInstalledReceipt:
                    requiresRuntimeUnlockRetryDispatchInstall))
        {
            return false;
        }

        RuntimeUnlockRetryDispatchContract? settledPredecessor = null;
        if (requiresRuntimeUnlockRetryDispatchInstall)
        {
            lock (accelerationGate)
            {
                var state = runtimeUnlockRecoveryRetryState;
                if (state?.DispatchContract is { } candidatePredecessor &&
                    candidatePredecessor.Lifecycle.SettlementOutcome ==
                        RuntimeUnlockRetryDispatchSettlementOutcome.MissingDispatch)
                {
                    settledPredecessor = candidatePredecessor;
                }
            }
        }

        if (settledPredecessor is not null)
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=runtime_unlock_retry_settled_predecessor_retry_blocked; {FormatRuntimeUnlockRetryDispatchAuthorityTuple(settledPredecessor.Authority)}; failed_offer_generation={settledPredecessor.OfferGeneration}; local_retry_reused_predecessor=0; trigger={normalizedReason}; decision_reason=coordinator_successor_required");
            RequestRuntimeUnlockRetryDispatchAuthority(
                settledPredecessor.Authority.SessionId,
                "settled_predecessor_schedule_coalesced");

            return true;
        }

        if (disposed)
        {
            LogAccelerationRetryNotScheduled(normalizedReason, "disposed");
            return false;
        }

        if (accelerationLane is not INknTunaAccelerationSession)
        {
            LogAccelerationRetryNotScheduled(normalizedReason, "missing_acceleration_lane");
            return false;
        }

        if (IsAccelerationNegotiatedAndHealthy() &&
            (!usesRuntimeUnlockRetryPolicy ||
             !ShouldAllowRuntimeUnlockRetryDespiteHealthyTransport(
                  normalizedReason,
                  requiresRuntimeUnlockRetryDispatchInstall)))
        {
            LogAccelerationRetryNotScheduled(normalizedReason, "already_healthy");
            return false;
        }

        if (!IsSessionAccelerationEligible(out _))
        {
            LogAccelerationRetryNotScheduled(normalizedReason, "session_not_eligible");
            return false;
        }

        if (requiresRuntimeUnlockRetryDispatchInstall &&
            ShouldSuppressRuntimeUnlockRetryAfterTerminalTransactionFailure(normalizedReason))
        {
            LogAccelerationRetryNotScheduled(normalizedReason, "runtime_unlock_transaction_failed");
            return false;
        }

        if (TryGetUnresolvedFileTransferV6TransportEpochForCurrentSession(out var pendingEpoch) &&
            !ShouldAllowAccelerationRetryDespiteUnresolvedV6Epoch(
                pendingEpoch,
                normalizedReason,
                "preflight",
                requiresRuntimeUnlockRetryDispatchInstall))
        {
            LocalOperationalLog.Warn(
                "NKN.Tuna",
                $"event=tuna_acceleration_retry_blocked_v6_epoch_unresolved; reason={normalizedReason}; session_id={SanitizeLogToken(pendingEpoch.SessionId)}; transfer_id={SanitizeLogToken(pendingEpoch.TransferId)}; direction={pendingEpoch.Direction.ToString().ToLowerInvariant()}; transport_epoch={pendingEpoch.TransportEpoch}; state={FormatFileTransferV6TransportEpochStateForLog(pendingEpoch.State)}; handoff_kind={FormatFileTransferTransportHandoffKindForLog(pendingEpoch.HandoffKind)}; target_transport={FormatFileTransferTransportKindForLog(pendingEpoch.TargetTransport)}");
            return false;
        }

        if (TryGetFileTransferFallbackControlProofPendingSnapshot(out var pendingSessionId, out var pendingReason, out var pendingLanes) &&
            !ShouldAllowAccelerationRetryDespiteFallbackControlPendingWithInstalledAuthority(
                pendingSessionId,
                pendingReason,
                pendingLanes,
                normalizedReason,
                "preflight",
                requiresRuntimeUnlockRetryDispatchInstall))
        {
            LocalOperationalLog.Warn(
                "NKN.Tuna",
                $"event=tuna_acceleration_retry_blocked_fallback_control_unproven; reason={normalizedReason}; fallback_reason={SanitizeLogToken(pendingReason)}; session_id={SanitizeLogToken(pendingSessionId ?? "none")}; lanes={FormatAccelerationLanesForLog(pendingLanes)}");
            return false;
        }

        var maxAttempts = usesRuntimeUnlockRetryPolicy
            ? RuntimeUnlockAccelerationNegotiationMaxRetryAttempts
            : AccelerationNegotiationMaxRetryAttempts;
        var attempt = Interlocked.Increment(ref accelerationNegotiationRetryAttempts);
        if (attempt > maxAttempts)
        {
            LocalOperationalLog.Warn(
                "NKN.Tuna",
                $"event=tuna_acceleration_retry_exhausted; reason={normalizedReason}; attempts={attempt - 1}");
            if (requiresRuntimeUnlockRetryDispatchInstall)
            {
                FailRuntimeUnlockRecoveryContractIfActive(
                    currentSessionSecurityState.SessionId?.Value,
                    $"retry_exhausted_{normalizedReason}");
            }

            if (TryGetActiveFileTransferTunaActivationPauseForCurrentSession(out var pausedSessionId))
            {
                    LocalOperationalLog.Warn(
                        "NKN.Tuna",
                        $"event=filetransfer_tuna_activation_retry_exhausted_resuming_regular_nkn; reason={normalizedReason}; session_id={SanitizeLogToken(pausedSessionId ?? "none")}; attempts={attempt - 1}");
                ResumeFileTransferDataSessionsAfterTunaActivationNegotiation(
                    $"retry_exhausted_{normalizedReason}",
                    pausedSessionId,
                    "retry_exhausted");
                return false;
            }

            ResumeFileTransferDataSessionsAfterTunaActivationNegotiation(
                $"retry_exhausted_{normalizedReason}",
                currentSessionSecurityState.SessionId?.Value,
                "retry_exhausted");
            return false;
        }

        var useListenerReadyFastRetry = ShouldUseListenerReadyFastRetry(
            normalizedReason,
            usesRuntimeUnlockRetryPolicy);
        var delay = useListenerReadyFastRetry
            ? AccelerationListenerReadyRetryDelay
            : TimeSpan.FromMilliseconds(
                AccelerationNegotiationRetryBaseDelay.TotalMilliseconds * Math.Pow(2, attempt - 1));
        var genericDelay = delay;
        if (requiresRuntimeUnlockRetryDispatchInstall &&
            TryGetRuntimeUnlockRecoveryContractRetryDelay(
                normalizedReason,
                delay,
                out var contractDelay,
                out var contractRetryReason))
        {
            delay = contractDelay;
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=session_recovery_contract_retry_backoff_capped; reason={normalizedReason}; attempt={attempt}; generic_delay_ms={(int)genericDelay.TotalMilliseconds}; capped_delay_ms={(int)delay.TotalMilliseconds}; cap_reason={SanitizeLogToken(contractRetryReason)}");
        }
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=tuna_acceleration_retry_scheduled; reason={normalizedReason}; attempt={attempt}; max_attempts={maxAttempts}; delay_ms={(int)delay.TotalMilliseconds}; listener_ready_reuse={(useListenerReadyFastRetry ? 1 : 0)}");
        if (string.Equals(normalizedReason, RuntimeUnlockProbeSidecarClosedRetryReason, StringComparison.Ordinal))
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=runtime_unlock_precommit_probe_sidecar_rearm_scheduled; session_id={SanitizeLogToken(currentSessionSecurityState.SessionId?.Value ?? "none")}; retry_reason={normalizedReason}; trigger=schedule_retry; listener_ready_reuse={(useListenerReadyFastRetry ? 1 : 0)}; decision_reason=sidecar_closed_requires_listener_rearm");
        }

        _ = Task.Run(
            async () =>
            {
                try
                {
                    await Task.Delay(delay, CancellationToken.None).ConfigureAwait(false);
                    if (authorityRequirement !=
                            AccelerationNegotiationRetryAuthorityRequirement
                                .InitialRuntimeUnlock &&
                        !ValidateRuntimeUnlockRetryDispatchInstallReceiptBoundary(
                            expectedInstallReceipt,
                            "retry_delay",
                            requireInstalledReceipt:
                                requiresRuntimeUnlockRetryDispatchInstall))
                    {
                        return;
                    }

                    if (disposed)
                    {
                        LogAccelerationRetryNotScheduled(normalizedReason, "delayed_disposed");
                        return;
                    }

                    if (IsAccelerationNegotiatedAndHealthy() &&
                        (!usesRuntimeUnlockRetryPolicy ||
                          !ShouldAllowRuntimeUnlockRetryDespiteHealthyTransport(
                              normalizedReason,
                              requiresRuntimeUnlockRetryDispatchInstall)))
                    {
                        LogAccelerationRetryNotScheduled(normalizedReason, "delayed_already_healthy");
                        return;
                    }

                    if (HasPendingOutboundAccelerationOffer())
                    {
                        if (usesRuntimeUnlockRetryPolicy &&
                            TryQueueRuntimeUnlockNegotiationBehindPendingGeneration(
                                normalizedReason,
                                "delayed_pending_offer",
                                expectedInstallReceipt,
                                requiresRuntimeUnlockRetryDispatchInstall
                                    ? RuntimeUnlockOfferAuthorityMode.InstalledRetry
                                    : RuntimeUnlockOfferAuthorityMode.InitialActivation))
                        {
                            LogAccelerationRetryNotScheduled(normalizedReason, "delayed_pending_offer_queued");
                            return;
                        }

                        LogAccelerationRetryNotScheduled(normalizedReason, "delayed_pending_offer");
                        return;
                    }

                    if (HasPendingAccelerationAnswerAck())
                    {
                        if (usesRuntimeUnlockRetryPolicy &&
                            TryQueueRuntimeUnlockNegotiationBehindPendingGeneration(
                                normalizedReason,
                                "delayed_pending_answer_ack",
                                expectedInstallReceipt,
                                requiresRuntimeUnlockRetryDispatchInstall
                                    ? RuntimeUnlockOfferAuthorityMode.InstalledRetry
                                    : RuntimeUnlockOfferAuthorityMode.InitialActivation))
                        {
                            LogAccelerationRetryNotScheduled(normalizedReason, "delayed_pending_answer_ack_queued");
                            return;
                        }

                        LogAccelerationRetryNotScheduled(normalizedReason, "delayed_pending_answer_ack");
                        return;
                    }

                    if (!IsSessionAccelerationEligible(out _))
                    {
                        LogAccelerationRetryNotScheduled(normalizedReason, "delayed_session_not_eligible");
                        return;
                    }

                    if (TryGetUnresolvedFileTransferV6TransportEpochForCurrentSession(out var delayedPendingEpoch) &&
                        !ShouldAllowAccelerationRetryDespiteUnresolvedV6Epoch(
                            delayedPendingEpoch,
                            normalizedReason,
                            "delayed",
                            requiresRuntimeUnlockRetryDispatchInstall))
                    {
                        LocalOperationalLog.Warn(
                            "NKN.Tuna",
                            $"event=tuna_acceleration_retry_skipped_v6_epoch_unresolved; reason={normalizedReason}; session_id={SanitizeLogToken(delayedPendingEpoch.SessionId)}; transfer_id={SanitizeLogToken(delayedPendingEpoch.TransferId)}; direction={delayedPendingEpoch.Direction.ToString().ToLowerInvariant()}; transport_epoch={delayedPendingEpoch.TransportEpoch}; state={FormatFileTransferV6TransportEpochStateForLog(delayedPendingEpoch.State)}; handoff_kind={FormatFileTransferTransportHandoffKindForLog(delayedPendingEpoch.HandoffKind)}; target_transport={FormatFileTransferTransportKindForLog(delayedPendingEpoch.TargetTransport)}");
                        return;
                    }

                    if (TryGetFileTransferFallbackControlProofPendingSnapshot(out var delayedPendingSessionId, out var delayedPendingReason, out var delayedPendingLanes) &&
                        !ShouldAllowAccelerationRetryDespiteFallbackControlPendingWithInstalledAuthority(
                            delayedPendingSessionId,
                            delayedPendingReason,
                            delayedPendingLanes,
                            normalizedReason,
                            "delayed",
                            requiresRuntimeUnlockRetryDispatchInstall))
                    {
                        LocalOperationalLog.Warn(
                            "NKN.Tuna",
                            $"event=tuna_acceleration_retry_skipped_fallback_control_unproven; reason={normalizedReason}; fallback_reason={SanitizeLogToken(delayedPendingReason)}; session_id={SanitizeLogToken(delayedPendingSessionId ?? "none")}; lanes={FormatAccelerationLanesForLog(delayedPendingLanes)}");
                        return;
                    }

                    LocalOperationalLog.Info(
                        "NKN.Tuna",
                        $"event=tuna_acceleration_retry_fired; reason={normalizedReason}; listener_ready_reuse={(useListenerReadyFastRetry ? 1 : 0)}");
                    if (string.Equals(normalizedReason, RuntimeUnlockProbeSidecarClosedRetryReason, StringComparison.Ordinal))
                    {
                        LocalOperationalLog.Info(
                            "NKN.Tuna",
                            $"event=runtime_unlock_precommit_probe_sidecar_rearm_started; session_id={SanitizeLogToken(currentSessionSecurityState.SessionId?.Value ?? "none")}; retry_reason={normalizedReason}; listener_ready_reuse={(useListenerReadyFastRetry ? 1 : 0)}; decision_reason=sidecar_closed_requires_listener_rearm");
                    }

                    var negotiationReason = usesRuntimeUnlockRetryPolicy
                        ? IsRuntimeUnlockActivationReason(normalizedReason)
                            ? normalizedReason
                            : "runtime_unlock"
                        : $"retry_{normalizedReason}";
                    ScheduleAccelerationNegotiationIfEligible(
                        negotiationReason,
                        expectedInstallReceipt,
                        requireRuntimeUnlockRetryDispatchInstall:
                            requiresRuntimeUnlockRetryDispatchInstall,
                        runtimeUnlockActivation:
                            usesRuntimeUnlockRetryPolicy);
                }
                catch (Exception ex) when (ex is not OperationCanceledException)
                {
                    LocalOperationalLog.Warn(
                        "NKN.Tuna",
                        $"event=tuna_acceleration_retry_failed; reason={normalizedReason}; error={ex.GetType().Name}");
                }
            },
            CancellationToken.None);
        return true;
    }

    private bool TryGetRuntimeUnlockRecoveryContractRetryDelay(
        string reason,
        TimeSpan currentDelay,
        out TimeSpan delay,
        out string capReason)
    {
        delay = currentDelay;
        capReason = string.Empty;
        RuntimeUnlockRecoveryRetryState? stateSnapshot;
        lock (accelerationGate)
        {
            var state = runtimeUnlockRecoveryRetryState;
            if (state is null ||
                state.ContractState is SessionRecoveryContractState.Completed or SessionRecoveryContractState.Failed ||
                !string.Equals(state.RetryReason, reason, StringComparison.Ordinal) ||
                !IsSessionRecoveryContractRetryRequired(state))
            {
                return false;
            }

            stateSnapshot = state;
        }

        var nowMs = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
        var maxDelay = RuntimeUnlockRecoveryContractRetryMaxDelay;
        if (stateSnapshot.RetryDeadlineUtcMs > nowMs)
        {
            var retryDeadlineDelay = TimeSpan.FromMilliseconds(Math.Max(
                0,
                stateSnapshot.RetryDeadlineUtcMs -
                nowMs -
                (long)RuntimeUnlockRecoveryContractRetryDeadlineSlack.TotalMilliseconds));
            maxDelay = MinTimeSpan(maxDelay, retryDeadlineDelay);
        }

        if (stateSnapshot.LivenessDeferralDeadlineUtcMs > nowMs)
        {
            var livenessDeadlineDelay = TimeSpan.FromMilliseconds(Math.Max(
                0,
                stateSnapshot.LivenessDeferralDeadlineUtcMs -
                nowMs -
                (long)RuntimeUnlockRecoveryContractRetryDeadlineSlack.TotalMilliseconds));
            maxDelay = MinTimeSpan(maxDelay, livenessDeadlineDelay);
        }

        if (maxDelay < TimeSpan.Zero)
        {
            maxDelay = TimeSpan.Zero;
        }

        if (currentDelay <= maxDelay)
        {
            return false;
        }

        delay = maxDelay;
        capReason = stateSnapshot.RequiresLocalListenerRetry
            ? "runtime_unlock_listener_rearm_contract"
            : "runtime_unlock_recovery_contract";
        return true;
    }

    private static TimeSpan MinTimeSpan(TimeSpan left, TimeSpan right)
        => left <= right ? left : right;

    private void LogAccelerationRetryNotScheduled(string reason, string skipReason)
    {
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=tuna_acceleration_retry_not_scheduled; reason={SanitizeLogToken(reason)}; skip_reason={SanitizeLogToken(skipReason)}");
    }

    private bool ShouldAllowRuntimeUnlockRetryDespiteHealthyTransport(
        string reason,
        bool installedRuntimeUnlockRetry)
    {
        var sessionId = currentSessionSecurityState.SessionId?.Value;
        if (string.IsNullOrWhiteSpace(sessionId))
        {
            return false;
        }

        if (HasActiveRegularV4FileTransferRouteHint(sessionId) ||
            HasActivePostTunaFallbackFileTransferRouteHint(sessionId))
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=tuna_acceleration_retry_allowed_despite_healthy_transport; reason={SanitizeLogToken(reason)}; session_id={SanitizeLogToken(sessionId)}; active_filetransfer_route=1");
            return true;
        }

        if (HasActiveFileTransferDataSessionForSession(sessionId))
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=tuna_acceleration_retry_allowed_despite_healthy_transport; reason={SanitizeLogToken(reason)}; session_id={SanitizeLogToken(sessionId)}; active_filetransfer_session=1");
            return true;
        }

        return installedRuntimeUnlockRetry &&
               TryGetUnresolvedFileTransferV6TransportEpochForCurrentSession(out var pendingEpoch) &&
               IsPostTunaFallbackRegularNknEpoch(pendingEpoch) &&
               TryGetEffectiveFallbackPairedTailYieldInstallReceipt(
                   pendingEpoch.SessionId,
                   pendingEpoch.TransferId,
                   pendingEpoch.Direction,
                   out _);
    }

    private bool HasActiveFileTransferDataSessionForSession(string sessionId)
    {
        lock (gate)
        {
            foreach (var session in fileTransferDataSessions.Values)
            {
                if (!session.IsDisposed &&
                    string.Equals(session.SessionId, sessionId, StringComparison.Ordinal))
                {
                    return true;
                }
            }
        }

        return false;
    }

    private string? ResolveSingleActiveFileTransferDataSessionTransferId(string sessionId, string? transferId)
    {
        if (!string.IsNullOrWhiteSpace(transferId))
        {
            return transferId.Trim();
        }

        string? resolvedTransferId = null;
        lock (gate)
        {
            foreach (var session in fileTransferDataSessions.Values)
            {
                if (session.IsDisposed ||
                    !string.Equals(session.SessionId, sessionId, StringComparison.Ordinal))
                {
                    continue;
                }

                if (resolvedTransferId is not null)
                {
                    return null;
                }

                resolvedTransferId = session.TransferId;
            }
        }

        return resolvedTransferId;
    }

    private bool HasActiveFileTransferDataSessionForTransfer(string sessionId, string? transferId)
    {
        if (string.IsNullOrWhiteSpace(transferId))
        {
            return false;
        }

        var normalizedTransferId = transferId.Trim();
        lock (gate)
        {
            return fileTransferDataSessions.TryGetValue(normalizedTransferId, out var session) &&
                   !session.IsDisposed &&
                   string.Equals(session.SessionId, sessionId, StringComparison.Ordinal);
        }
    }

    private static bool RuntimeUnlockTransactionTransferMatches(string? transactionTransferId, string? expectedTransferId)
        => string.IsNullOrWhiteSpace(transactionTransferId) ||
           string.Equals(transactionTransferId.Trim(), expectedTransferId, StringComparison.Ordinal);

    private static bool IsRegularNknRecoveryEpoch(FileTransferV6TransportEpochSnapshot snapshot)
        => snapshot.TargetTransport == FileTransferTransportKind.RegularNkn &&
           snapshot.HandoffKind == FileTransferTransportHandoffKind.RegularNknRecovery;

    private static bool IsPostTunaFallbackRegularNknEpoch(FileTransferV6TransportEpochSnapshot snapshot)
        => snapshot.TargetTransport == FileTransferTransportKind.RegularNkn &&
           snapshot.HandoffKind == FileTransferTransportHandoffKind.TunaToNormalFallback;

    private bool ShouldAllowAccelerationRetryDespiteUnresolvedV6Epoch(
        FileTransferV6TransportEpochSnapshot pendingEpoch,
        string reason,
        string stage,
        bool installedRuntimeUnlockRetry)
    {
        if (IsPostTunaFallbackRegularNknEpoch(pendingEpoch) &&
            installedRuntimeUnlockRetry)
        {
            if (TryGetEffectiveFallbackPairedTailYieldInstallReceipt(
                    pendingEpoch.SessionId,
                    pendingEpoch.TransferId,
                    pendingEpoch.Direction,
                    out _))
            {
                LocalOperationalLog.Info(
                    "NKN.Tuna",
                    $"event=tuna_acceleration_retry_allowed_after_fallback_tail_quiescent; reason={SanitizeLogToken(reason)}; stage={SanitizeLogToken(stage)}; session_id={SanitizeLogToken(pendingEpoch.SessionId)}; transfer_id={SanitizeLogToken(pendingEpoch.TransferId)}; direction={pendingEpoch.Direction.ToString().ToLowerInvariant()}; transport_epoch={pendingEpoch.TransportEpoch}; state={FormatFileTransferV6TransportEpochStateForLog(pendingEpoch.State)}; handoff_kind={FormatFileTransferTransportHandoffKindForLog(pendingEpoch.HandoffKind)}; target_transport={FormatFileTransferTransportKindForLog(pendingEpoch.TargetTransport)}");
                return true;
            }

            const string fallbackOwnerReason =
                "fallback_paired_tail_yield_install_receipt_missing";
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=filetransfer_runtime_unlock_waiting_for_fallback_owner; reason={SanitizeLogToken(reason)}; stage={SanitizeLogToken(stage)}; session_id={SanitizeLogToken(pendingEpoch.SessionId)}; transfer_id={SanitizeLogToken(pendingEpoch.TransferId)}; direction={pendingEpoch.Direction.ToString().ToLowerInvariant()}; transport_epoch={pendingEpoch.TransportEpoch}; state={FormatFileTransferV6TransportEpochStateForLog(pendingEpoch.State)}; handoff_kind={FormatFileTransferTransportHandoffKindForLog(pendingEpoch.HandoffKind)}; target_transport={FormatFileTransferTransportKindForLog(pendingEpoch.TargetTransport)}; fallback_owner_reason={SanitizeLogToken(fallbackOwnerReason)}; source=unresolved_v6_epoch");
            LocalOperationalLog.Warn(
                "NKN.Tuna",
                $"event=runtime_unlock_fallback_unavailable_suppressed; reason={SanitizeLogToken(reason)}; stage={SanitizeLogToken(stage)}; session_id={SanitizeLogToken(pendingEpoch.SessionId)}; transfer_id={SanitizeLogToken(pendingEpoch.TransferId)}; fallback_owner_reason={SanitizeLogToken(fallbackOwnerReason)}; source=unresolved_v6_epoch");
            return false;
        }

        if (!IsRegularNknRecoveryEpoch(pendingEpoch))
        {
            return false;
        }

        const string recoveryOwnerReason =
            "coordinator_route_transition_authority_pending";
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=filetransfer_runtime_unlock_waiting_for_fallback_owner; reason={SanitizeLogToken(reason)}; stage={SanitizeLogToken(stage)}; session_id={SanitizeLogToken(pendingEpoch.SessionId)}; transfer_id={SanitizeLogToken(pendingEpoch.TransferId)}; direction={pendingEpoch.Direction.ToString().ToLowerInvariant()}; transport_epoch={pendingEpoch.TransportEpoch}; state={FormatFileTransferV6TransportEpochStateForLog(pendingEpoch.State)}; handoff_kind={FormatFileTransferTransportHandoffKindForLog(pendingEpoch.HandoffKind)}; target_transport={FormatFileTransferTransportKindForLog(pendingEpoch.TargetTransport)}; fallback_owner_reason={recoveryOwnerReason}; source=regular_nkn_recovery_epoch");
        LocalOperationalLog.Warn(
            "NKN.Tuna",
            $"event=runtime_unlock_fallback_unavailable_suppressed; reason={SanitizeLogToken(reason)}; stage={SanitizeLogToken(stage)}; session_id={SanitizeLogToken(pendingEpoch.SessionId)}; transfer_id={SanitizeLogToken(pendingEpoch.TransferId)}; fallback_owner_reason={recoveryOwnerReason}; source=regular_nkn_recovery_epoch");
        return false;
    }

    private bool ShouldAllowAccelerationRetryDespiteFallbackControlPendingWithInstalledAuthority(
        string? pendingSessionId,
        string pendingReason,
        NknAccelerationLaneKind pendingLanes,
        string retryReason,
        string stage,
        bool installedRuntimeUnlockRetry)
    {
        if ((pendingLanes & NknAccelerationLaneKind.File) != NknAccelerationLaneKind.File ||
            !installedRuntimeUnlockRetry)
        {
            return false;
        }

        var currentSessionId = currentSessionSecurityState.SessionId?.Value;
        var normalizedPendingSessionId = string.IsNullOrWhiteSpace(pendingSessionId)
            ? currentSessionId
            : pendingSessionId.Trim();
        if (string.IsNullOrWhiteSpace(currentSessionId) ||
            string.IsNullOrWhiteSpace(normalizedPendingSessionId) ||
            !string.Equals(currentSessionId, normalizedPendingSessionId, StringComparison.Ordinal))
        {
            return false;
        }

        if (IsRuntimeUnlockActivationRecoveryFailure(pendingReason) &&
            HasActiveRegularV4FileTransferRouteHint(normalizedPendingSessionId))
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=tuna_acceleration_retry_allowed_runtime_unlock_recovery_unproven; reason={SanitizeLogToken(retryReason)}; fallback_reason={SanitizeLogToken(pendingReason)}; stage={SanitizeLogToken(stage)}; session_id={SanitizeLogToken(normalizedPendingSessionId)}; lanes={FormatAccelerationLanesForLog(pendingLanes)}; active_regular_v4_route=1");
            return true;
        }

        if (HasActivePostTunaFallbackFileTransferRouteHint(normalizedPendingSessionId))
        {
            if (TryGetEffectiveFallbackPairedTailYieldInstallReceiptForSession(
                    normalizedPendingSessionId,
                    out var installReceipt))
            {
                LocalOperationalLog.Info(
                    "NKN.Tuna",
                    $"event=tuna_acceleration_retry_allowed_post_tuna_fallback_installed_authority; reason={SanitizeLogToken(retryReason)}; fallback_reason={SanitizeLogToken(pendingReason)}; stage={SanitizeLogToken(stage)}; session_id={SanitizeLogToken(normalizedPendingSessionId)}; lanes={FormatAccelerationLanesForLog(pendingLanes)}; transfer_id={SanitizeLogToken(installReceipt.Authority.TransferId)}; direction={installReceipt.Authority.Direction.ToString().ToLowerInvariant()}; authority_id={installReceipt.Authority.AuthorityId}; install_generation={installReceipt.InstallGeneration}; release_kind={installReceipt.Authority.ReleaseKind}; release_outcome={SanitizeLogToken(installReceipt.Authority.ReleaseOutcome)}; reason_detail=fallback_paired_tail_yield_install_receipt");
                return true;
            }

            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=tuna_acceleration_retry_blocked_fallback_control_unproven_for_post_tuna_fallback; reason={SanitizeLogToken(retryReason)}; fallback_reason={SanitizeLogToken(pendingReason)}; stage={SanitizeLogToken(stage)}; session_id={SanitizeLogToken(normalizedPendingSessionId)}; lanes={FormatAccelerationLanesForLog(pendingLanes)}; decision_reason=fallback_paired_tail_yield_install_receipt_missing");
            return false;
        }

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=tuna_acceleration_retry_blocked_fallback_control_without_coordinator_route; reason={SanitizeLogToken(retryReason)}; fallback_reason={SanitizeLogToken(pendingReason)}; stage={SanitizeLogToken(stage)}; session_id={SanitizeLogToken(normalizedPendingSessionId)}; lanes={FormatAccelerationLanesForLog(pendingLanes)}; decision_reason=coordinator_fallback_route_and_install_receipt_required");
        return false;
    }

    private static bool IsSameSessionOrUnknown(string? candidateSessionId, string sessionId)
        => string.IsNullOrWhiteSpace(candidateSessionId) ||
           string.Equals(candidateSessionId.Trim(), sessionId.Trim(), StringComparison.Ordinal);

    private void RejectAccelerationOfferPreflight(
        string trigger,
        string reason,
        bool retryable,
        NknAccelerationLaneKind eligibleLanes = NknAccelerationLaneKind.None,
        RuntimeUnlockRetryDispatchInstallReceipt? expectedInstallReceipt = null,
        RuntimeUnlockOfferAuthorityMode? offerAuthorityMode = null)
    {
        var normalizedReason = SanitizeLogToken(reason);
        var normalizedTrigger = SanitizeLogToken(trigger);
        var sessionId = currentSessionSecurityState.SessionId?.Value;
        var isRuntimeUnlockOffer = offerAuthorityMode is not null;
        var suppliedInstalledRetryAuthority =
            offerAuthorityMode == RuntimeUnlockOfferAuthorityMode.InstalledRetry &&
            expectedInstallReceipt is not null;
        var currentRuntimeUnlockAuthority = false;
        var currentRouteTransitionAuthority = false;
        lock (accelerationGate)
        {
            if (suppliedInstalledRetryAuthority &&
                expectedInstallReceipt is { } receipt)
            {
                var state = runtimeUnlockRecoveryRetryState;
                currentRuntimeUnlockAuthority =
                    state is not null &&
                    TryValidateRuntimeUnlockRetryDispatchInstallReceiptCurrentUnsafe(
                        state,
                        receipt,
                        out _);
            }

            var routeTransition =
                GetFileTransferRouteTransitionPauseAuthorityUnsafe();
            currentRouteTransitionAuthority =
                routeTransition is { } authority &&
                (string.IsNullOrWhiteSpace(sessionId) ||
                 string.Equals(
                     authority.SessionId,
                     sessionId,
                     StringComparison.Ordinal));
        }
        var shouldRetry =
            retryable &&
            !currentRouteTransitionAuthority &&
            (offerAuthorityMode != RuntimeUnlockOfferAuthorityMode.InstalledRetry ||
             currentRuntimeUnlockAuthority);
        shouldRetry =
            shouldRetry &&
            (offerAuthorityMode != RuntimeUnlockOfferAuthorityMode.InitialActivation ||
             expectedInstallReceipt is null) &&
            ShouldRetryAccelerationOfferPreflight(
                normalizedTrigger,
                normalizedReason,
                isRuntimeUnlockOffer);
        var hasRemoteEndpoint = !string.IsNullOrWhiteSpace(remoteEndpoint);
        var canOfferListener = accelerationLane is INknTunaAccelerationSession tunaSession && tunaSession.CanOfferListener;

        NotifyTransportAccelerationStateChanged($"preflight_{normalizedReason}");
        LocalOperationalLog.Warn(
            "NKN.Tuna",
            $"event=tuna_acceleration_offer_preflight_rejected; reason={normalizedReason}; trigger={normalizedTrigger}; authority_mode={SanitizeLogToken(offerAuthorityMode?.ToString() ?? "none")}; retryable={(retryable ? 1 : 0)}; retry_scheduled={(shouldRetry ? 1 : 0)}; session_id={SanitizeLogToken(sessionId)}; has_remote_endpoint={(hasRemoteEndpoint ? 1 : 0)}; can_offer_listener={(canOfferListener ? 1 : 0)}; eligible_lanes={FormatAccelerationLanesForLog(eligibleLanes)}");

        if (shouldRetry)
        {
            var retryReason = isRuntimeUnlockOffer
                ? $"runtime_unlock_preflight_{normalizedReason}"
                : $"preflight_{normalizedReason}";
            if (offerAuthorityMode == RuntimeUnlockOfferAuthorityMode.InstalledRetry)
            {
                ScheduleRuntimeUnlockAccelerationNegotiationRetry(
                    retryReason,
                    expectedInstallReceipt);
            }
            else if (offerAuthorityMode == RuntimeUnlockOfferAuthorityMode.InitialActivation)
            {
                ScheduleInitialRuntimeUnlockAccelerationNegotiationRetry(
                    retryReason);
            }
            else
            {
                ScheduleAccelerationNegotiationRetry(retryReason);
            }
        }
    }

    private static bool ShouldRetryAccelerationOfferPreflight(
        string trigger,
        string reason,
        bool isRuntimeUnlockOffer)
    {
        if (string.Equals(trigger, "session_security_state_ready", StringComparison.Ordinal))
        {
            return string.Equals(reason, "listener_unavailable", StringComparison.Ordinal);
        }

        if (!isRuntimeUnlockOffer &&
            !trigger.StartsWith("retry_preflight_", StringComparison.Ordinal) &&
            !trigger.StartsWith("retry_early_drop_", StringComparison.Ordinal) &&
            !trigger.StartsWith("retry_sidecar_", StringComparison.Ordinal) &&
            !string.Equals(trigger, "helpee_payer_preferred", StringComparison.Ordinal))
        {
            return false;
        }

        return reason is "missing_remote_endpoint" or
            "listener_unavailable" or
            "missing_secure_session_context";
    }

    private void ScheduleAccelerationEarlyDropRetry(string reason, NknAccelerationLaneDiagnostics diagnostics)
    {
        var attempt = Interlocked.Increment(ref accelerationEarlyDropRetryAttempts);
        if (attempt > AccelerationEarlyDropMaxRetryAttempts)
        {
            LocalOperationalLog.Warn(
                "NKN.Tuna",
                $"event=tuna_acceleration_early_drop_retry_skipped; reason={SanitizeLogToken(reason)}; attempts={attempt - 1}; frame_count={TunaPayloadFrameCount(diagnostics)}");
            return;
        }

        LocalOperationalLog.Warn(
            "NKN.Tuna",
            $"event=tuna_acceleration_early_drop_retry_scheduled; reason={SanitizeLogToken(reason)}; attempt={attempt}; frame_count={TunaPayloadFrameCount(diagnostics)}; terminal_reason={SanitizeLogToken(diagnostics.TerminalSidecarReason)}");
        ScheduleAccelerationNegotiationRetry($"early_drop_{SanitizeLogToken(reason)}");
    }

    private static bool ShouldRetryEarlyAccelerationDrop(string? reason, NknAccelerationLaneDiagnostics diagnostics)
    {
        var normalized = SanitizeLogToken(reason);
        if (IsUserRequestedAccelerationStopReason(normalized) ||
            normalized.Contains("cap", StringComparison.Ordinal) ||
            normalized.Contains("queue_overflow", StringComparison.Ordinal))
        {
            return false;
        }

        if (TunaPayloadFrameCount(diagnostics) > 0)
        {
            return false;
        }

        return normalized is
            "read_failed" or
            "write_failed" or
            "remote_closed" or
            "sidecar_read_failed" or
            "sidecar_write_failed" or
            "sidecar_remote_closed" or
            "sidecar_local_ipc_eof" or
            "sidecar_tuna_stream_eof" or
            "sidecar_local_write_failed" or
            "sidecar_tuna_write_failed" or
            "sidecar_process_exited" or
            "sidecar_unexpected_exit";
    }

    private static long TunaPayloadFrameCount(NknAccelerationLaneDiagnostics diagnostics)
        => diagnostics.ControlFramesAccepted +
           diagnostics.MediaFramesAccepted +
           diagnostics.BulkFramesAccepted +
           diagnostics.ControlFramesWritten +
           diagnostics.MediaFramesWritten +
           diagnostics.BulkFramesWritten +
           diagnostics.ControlFramesReceived +
           diagnostics.MediaFramesReceived +
           diagnostics.BulkFramesReceived;

    private TimeSpan ResolveAccelerationOfferAnswerTimeout(
        string nonce,
        bool requireRuntimeUnlockRetryDispatchInstall)
    {
        if (AccelerationOfferAnswerTimeoutOverrideForTests is { } overrideTimeout)
        {
            return overrideTimeout;
        }

        lock (accelerationGate)
        {
            if (outboundRuntimeUnlockOfferAuthorityBoundary is { } currentBoundary &&
                string.Equals(
                    outboundAccelerationOfferNonce,
                    nonce,
                    StringComparison.Ordinal) &&
                string.Equals(currentBoundary.Nonce, nonce, StringComparison.Ordinal))
            {
                return RuntimeUnlockAccelerationOfferAnswerTimeout;
            }

            var state = runtimeUnlockOfferProofState;
            if (state is { Retired: true } &&
                IsRuntimeUnlockPendingAnswerRetiredReason(state.RetiredReason) &&
                !string.IsNullOrWhiteSpace(retiredAccelerationOfferNonce) &&
                string.Equals(retiredAccelerationOfferNonce, nonce, StringComparison.Ordinal) &&
                string.Equals(retiredAccelerationOfferNonce, state.Nonce, StringComparison.Ordinal) &&
                string.Equals(retiredAccelerationOfferSessionId, state.SessionId, StringComparison.Ordinal) &&
                DateTimeOffset.UtcNow.ToUnixTimeMilliseconds() < retiredAccelerationOfferExpiresUtcMs)
            {
                return RuntimeUnlockAccelerationOfferAnswerTimeout;
            }
        }

        return AccelerationOfferAnswerTimeout;
    }

    private void ScheduleAccelerationOfferAnswerTimeout(
        string nonce,
        RuntimeUnlockRetryDispatchInstallReceipt? expectedInstallReceipt,
        bool requireRuntimeUnlockRetryDispatchInstall)
    {
        var offerAuthorityBoundary =
            CaptureRuntimeUnlockOfferAuthorityBoundary(nonce);
        var installedRetry =
            offerAuthorityBoundary?.Mode ==
            RuntimeUnlockOfferAuthorityMode.InstalledRetry;
        var timeout = ResolveAccelerationOfferAnswerTimeout(
            nonce,
            requireRuntimeUnlockRetryDispatchInstall);
        if (timeout <= TimeSpan.Zero)
        {
            return;
        }

        _ = Task.Run(
            async () =>
            {
                try
                {
                    await Task.Delay(timeout, CancellationToken.None).ConfigureAwait(false);
                    if (offerAuthorityBoundary is not null
                            ? !ValidateRuntimeUnlockOfferAuthorityBoundary(
                                offerAuthorityBoundary,
                                "offer_answer_timeout",
                                allowDispatchObservedSettlement: true)
                            : !ValidateRuntimeUnlockRetryDispatchInstallReceiptBoundary(
                                expectedInstallReceipt,
                                "offer_answer_timeout",
                                allowDispatchObservedSettlement: true,
                                requireInstalledReceipt:
                                    requireRuntimeUnlockRetryDispatchInstall))
                    {
                        return;
                    }

                    if (disposed ||
                        IsAccelerationNegotiatedAndHealthy() ||
                        (!IsSessionAccelerationEligible(out _) &&
                         !HasPendingRuntimeUnlockAnswerTimeoutTarget(nonce)))
                    {
                        return;
                    }

                    if (offerAuthorityBoundary is { } timeoutBoundary)
                    {
                        var holdResult =
                            await WaitForRuntimeUnlockInitialActivationReceiveRecoveryTimeoutHoldAsync(
                                    timeoutBoundary,
                                    RuntimeUnlockInitialActivationReceiveRecoveryHoldBoundary
                                        .AnswerTimeout,
                                    "offer_answer_timeout_hold_released")
                                .ConfigureAwait(false);
                        if (!IsRuntimeUnlockInitialActivationReceiveRecoveryHoldReleased(
                                holdResult))
                        {
                            return;
                        }
                        if (ShouldResumeRuntimeUnlockInitialActivationSameGeneration(
                                holdResult))
                        {
                            if (IsRuntimeUnlockInitialActivationEnvelopeRefreshReplayRequired())
                            {
                                await ReplayCommittedRuntimeUnlockInitialActivationEnvelopeAfterHoldAsync(
                                    timeoutBoundary,
                                    holdResult,
                                    "answer_timeout")
                                    .ConfigureAwait(false);
                                return;
                            }

                            ScheduleAccelerationOfferAnswerTimeout(
                                nonce,
                                expectedInstallReceipt,
                                requireRuntimeUnlockRetryDispatchInstall);
                            return;
                        }
                    }

                    string? offerTrigger;
                    long offerPayerDecisionId;
                    long offerGeneration;
                    var sessionId = currentSessionSecurityState.SessionId?.Value;
                    var isRuntimeUnlockOffer = false;
                    var runtimeUnlockPeerReceived = false;
                    var lateAnswerGrace = false;
                    var matchedRetiredPendingAnswer = false;
                    lock (accelerationGate)
                    {
                        var activeOfferMatches =
                            string.Equals(outboundAccelerationOfferNonce, nonce, StringComparison.Ordinal);
                        var state = runtimeUnlockOfferProofState;
                        var retiredPendingAnswerMatches =
                            !activeOfferMatches &&
                            state is { Retired: true } &&
                            IsRuntimeUnlockPendingAnswerRetiredReason(state.RetiredReason) &&
                            !string.IsNullOrWhiteSpace(retiredAccelerationOfferNonce) &&
                            string.Equals(retiredAccelerationOfferNonce, nonce, StringComparison.Ordinal) &&
                            string.Equals(retiredAccelerationOfferNonce, state.Nonce, StringComparison.Ordinal) &&
                            string.Equals(retiredAccelerationOfferSessionId, state.SessionId, StringComparison.Ordinal) &&
                            DateTimeOffset.UtcNow.ToUnixTimeMilliseconds() < retiredAccelerationOfferExpiresUtcMs;
                        if (!activeOfferMatches && !retiredPendingAnswerMatches)
                        {
                            return;
                        }

                        if (expectedInstallReceipt is { } receipt)
                        {
                            var boundReceipt = activeOfferMatches
                                ? outboundAccelerationOfferInstallReceipt
                                : retiredAccelerationOfferInstallReceipt;
                            var retryState = runtimeUnlockRecoveryRetryState;
                            if (boundReceipt != receipt ||
                                retryState is null ||
                                !TryValidateRuntimeUnlockRetryDispatchInstallReceiptCurrentUnsafe(
                                    retryState,
                                    receipt,
                                    out _,
                                    allowDispatchObservedSettlement: true))
                            {
                                return;
                            }
                        }

                        matchedRetiredPendingAnswer = retiredPendingAnswerMatches;
                        offerTrigger = activeOfferMatches ? outboundAccelerationOfferTrigger : retiredAccelerationOfferTrigger;
                        offerPayerDecisionId = activeOfferMatches
                            ? outboundAccelerationOfferPayerDecisionId
                            : retiredAccelerationOfferPayerDecisionId;
                        offerGeneration = activeOfferMatches
                            ? outboundAccelerationOfferGeneration
                            : state?.Generation ?? 0;
                        isRuntimeUnlockOffer = offerAuthorityBoundary is not null;
                        if (state is not null &&
                            state.Generation == offerGeneration &&
                            state.PayerDecisionId == offerPayerDecisionId &&
                            string.Equals(state.Nonce, nonce, StringComparison.Ordinal))
                        {
                            runtimeUnlockPeerReceived = state.PeerReceived;
                            state.Retired = true;
                            state.RetiredReason = "offer_answer_timeout";
                            state.RetryReason = isRuntimeUnlockOffer
                                ? "runtime_unlock_offer_answer_timeout"
                                : "offer_answer_timeout";
                            lateAnswerGrace = false;
                            if (lateAnswerGrace && string.IsNullOrWhiteSpace(sessionId))
                            {
                                sessionId = state.SessionId;
                            }
                        }

                        if (lateAnswerGrace)
                        {
                            if (matchedRetiredPendingAnswer)
                            {
                                retiredAccelerationOfferExpiresUtcMs = DateTimeOffset.UtcNow
                                    .Add(timeout)
                                    .ToUnixTimeMilliseconds();
                            }
                            else
                            {
                                RetireOutboundAccelerationOfferLocked(
                                    sessionId ?? string.Empty,
                                    "offer_answer_timeout_late_answer_grace");
                            }
                        }
                        else if (matchedRetiredPendingAnswer)
                        {
                            ClearRetiredOutboundAccelerationOfferLocked();
                        }
                        else if (activeOfferMatches &&
                                 isRuntimeUnlockOffer)
                        {
                            RetireOutboundAccelerationOfferLocked(
                                sessionId ?? state?.SessionId ?? string.Empty,
                                "offer_answer_timeout");
                        }
                        else
                        {
                            outboundAccelerationOfferNonce = null;
                            outboundAccelerationOfferTrigger = null;
                            outboundAccelerationOfferInstallReceipt = null;
                            outboundAccelerationOfferPayerDecisionId = 0;
                        }
                    }

                    LocalOperationalLog.Warn(
                        "NKN.Tuna",
                        $"event=tuna_acceleration_offer_answer_timeout; timeout_ms={(int)timeout.TotalMilliseconds}");
                    if (lateAnswerGrace)
                    {
                        LocalOperationalLog.Info(
                            "NKN.Tuna",
                            $"event=tuna_acceleration_offer_answer_timeout_late_answer_grace; session_id={SanitizeLogToken(sessionId ?? "none")}; payer_decision_id={offerPayerDecisionId}; generation={offerGeneration}");
                    }
                    NotifyTransportAccelerationStateChanged("offer_answer_timeout");
                    ResumeFileTransferDataSessionsAfterTunaActivationFailure(
                        "offer_answer_timeout",
                        sessionId,
                        "offer_answer_timeout");
                    if (isRuntimeUnlockOffer)
                    {
                        var peerResponseMissing = !runtimeUnlockPeerReceived;
                        var retryReason = peerResponseMissing
                            ? RuntimeUnlockCutThroughRetryReason
                            : "runtime_unlock_offer_answer_timeout";
                        if (!installedRetry)
                        {
                            var retryScheduled =
                                ScheduleRuntimeUnlockOfferAuthorityRetry(
                                    retryReason,
                                    offerAuthorityBoundary,
                                    expectedInstallReceipt: null);
                            LocalOperationalLog.Warn(
                                "NKN.Tuna",
                                $"event=tuna_acceleration_activation_offer_not_observed; trigger={SanitizeLogToken(offerTrigger)}; session_id={SanitizeLogToken(sessionId ?? "none")}; payer_decision_id={offerPayerDecisionId}; generation={offerGeneration}; authority_mode={SanitizeLogToken(RuntimeUnlockOfferAuthorityMode.InitialActivation.ToString())}; interruption_reason=offer_answer_timeout; retry_scheduled={(retryScheduled ? 1 : 0)}; retry_after_recovery_armed=0; replay_scheduled=0; answer_timeout_scheduled=0; recovery_requested=0; recovery_reason=initial_activation_answer_timeout; peer_received={(runtimeUnlockPeerReceived ? 1 : 0)}");
                            return;
                        }

                        var listenerRetryReason = retryReason;
                        var effectiveRecoveryReason = peerResponseMissing
                            ? RuntimeUnlockCutThroughRecoveryReason
                            : "tuna_activation_offer_answer_timeout";
                        var recoveryRequested = TryRequestFileTransferTunaActivationOfferSendRecovery(
                            "offer_answer",
                            sessionId,
                            "answer_timeout_without_peer_response",
                            offerAuthorityBoundary,
                            out var recoveryReason,
                            out var recoverySessionId);
                        effectiveRecoveryReason = peerResponseMissing
                            ? RuntimeUnlockCutThroughRecoveryReason
                            : recoveryReason ?? effectiveRecoveryReason;
                        LocalOperationalLog.Warn(
                            "NKN.Tuna",
                            $"event=tuna_acceleration_activation_offer_not_observed; trigger={SanitizeLogToken(offerTrigger)}; session_id={SanitizeLogToken(sessionId ?? "none")}; payer_decision_id={offerPayerDecisionId}; generation={offerGeneration}; interruption_reason=offer_answer_timeout; retry_scheduled={(recoveryRequested ? 0 : 1)}; retry_after_recovery_armed={(recoveryRequested ? 1 : 0)}; replay_scheduled=0; answer_timeout_scheduled=0; recovery_requested={(recoveryRequested ? 1 : 0)}; recovery_reason={SanitizeLogToken(effectiveRecoveryReason)}; peer_received={(runtimeUnlockPeerReceived ? 1 : 0)}");
                        var listenerReadyReuse = peerResponseMissing &&
                            ShouldUseListenerReadyFastRetry(
                                RuntimeUnlockCutThroughRetryReason,
                                runtimeUnlockRetry: true);
                        if (recoveryRequested)
                        {
                            if (listenerReadyReuse)
                            {
                                LocalOperationalLog.Info(
                                    "NKN.Tuna",
                                    $"event=session_recovery_contract_listener_rearm_skipped; session_id={SanitizeLogToken(sessionId ?? "none")}; reason={SanitizeLogToken(listenerRetryReason)}; trigger=offer_answer_timeout; payer_decision_id={offerPayerDecisionId}; listener_ready_reuse=1");
                            }
                            else
                            {
                                LocalOperationalLog.Warn(
                                    "NKN.Tuna",
                                    $"event=session_recovery_contract_listener_rearm_required; session_id={SanitizeLogToken(sessionId ?? "none")}; reason={SanitizeLogToken(listenerRetryReason)}; trigger=offer_answer_timeout; payer_decision_id={offerPayerDecisionId}; listener_ready_reuse=0");
                                ScheduleAccelerationLaneStop(listenerRetryReason);
                            }

                            ArmRuntimeUnlockRetryAfterRecovery(
                                offerGeneration,
                                recoverySessionId ?? sessionId ?? string.Empty,
                                retryReason,
                                effectiveRecoveryReason,
                                requiresLocalListenerRetry: !listenerReadyReuse,
                                listenerReadyReuse
                                    ? RuntimeUnlockRetryDispatchListenerRearmRequirement.None
                                    : RuntimeUnlockRetryDispatchListenerRearmRequirement.Required,
                                offerAuthorityBoundary!);
                        }
                        else
                        {
                            LocalOperationalLog.Warn(
                                "NKN.Tuna",
                                $"event=session_recovery_contract_listener_rearm_required; session_id={SanitizeLogToken(sessionId ?? "none")}; reason={SanitizeLogToken(listenerRetryReason)}; trigger=offer_answer_timeout; payer_decision_id={offerPayerDecisionId}; listener_ready_reuse=0");
                            ScheduleAccelerationLaneStop(listenerRetryReason);
                            ScheduleRuntimeUnlockOfferAuthorityRetry(
                                retryReason,
                                offerAuthorityBoundary,
                                expectedInstallReceipt);
                        }
                    }
                    else
                    {
                        ScheduleAccelerationNegotiationRetry("offer_answer_timeout");
                    }
                }
                catch (Exception ex) when (ex is not OperationCanceledException)
                {
                    LocalOperationalLog.Warn(
                        "NKN.Tuna",
                        $"event=tuna_acceleration_offer_answer_timeout_failed; error={ex.GetType().Name}");
                }
            },
            CancellationToken.None);
    }

    private static bool ShouldRetryAccelerationNegotiation(string? reason)
        => string.Equals(reason, "sidecar_unavailable", StringComparison.Ordinal) ||
           string.Equals(reason, "listener_sidecar_unavailable", StringComparison.Ordinal) ||
           string.Equals(reason, "offer_queue_rejected", StringComparison.Ordinal) ||
           string.Equals(reason, "offer_answer_timeout", StringComparison.Ordinal) ||
           string.Equals(reason, "answer_ack_timeout", StringComparison.Ordinal) ||
           string.Equals(reason, "session_not_eligible", StringComparison.Ordinal);

    private static bool ShouldRetryPeerUserStoppedAfterRuntimeUnlock(string? reason)
        => string.Equals(SanitizeLogToken(reason), "user_stopped_tuna", StringComparison.Ordinal);

    private static bool ShouldRetryRuntimeUnlockAfterRejectedAnswer(string? reason)
    {
        var normalizedReason = SanitizeLogToken(reason);
        return normalizedReason is "sidecar_unavailable" or
            "listener_sidecar_unavailable" or
            "runtime_unlock_tuna_dial_failed";
    }

    private bool ShouldUseListenerReadyFastRetry(
        string? reason,
        bool runtimeUnlockRetry)
    {
        var normalized = SanitizeLogToken(reason);
        if (IsRuntimeUnlockListenerRearmRequiredRetryReason(normalized) &&
            !CanReuseCurrentListenerForRuntimeUnlockAnswerRetry(normalized))
        {
            return false;
        }

        if (normalized is not ("sidecar_unavailable" or "offer_answer_timeout" or "offer_queue_rejected" or "peer_user_stopped_tuna" or "preflight_listener_unavailable" or "early_drop_remote_closed") &&
            !runtimeUnlockRetry)
        {
            return false;
        }

        return accelerationLane is INknTunaAccelerationSession tunaSession &&
               tunaSession.CanOfferListener &&
               tunaSession.IsAvailable &&
               !string.IsNullOrWhiteSpace(tunaSession.LocalTunaAddress);
    }

    private bool CanReuseCurrentListenerForRuntimeUnlockAnswerRetry(string reason)
    {
        if (HasFailedRuntimeUnlockTunaPathLeaseForCurrentSession(currentSessionSecurityState.SessionId?.Value))
        {
            return false;
        }

        return (reason is "runtime_unlock_sidecar_unavailable" or "runtime_unlock_listener_sidecar_unavailable") &&
               accelerationLane is INknTunaAccelerationSession tunaSession &&
               tunaSession.CanOfferListener &&
               tunaSession.IsAvailable &&
               !string.IsNullOrWhiteSpace(tunaSession.LocalTunaAddress);
    }

    private string ResolveRuntimeUnlockListenerRearmFailedReason(string sessionId)
    {
        if (!string.IsNullOrWhiteSpace(sessionId))
        {
            var normalizedSessionId = sessionId.Trim();
            lock (accelerationGate)
            {
                if (runtimeUnlockRecoveryRetryState is { } state &&
                    string.Equals(state.SessionId, normalizedSessionId, StringComparison.Ordinal) &&
                    string.Equals(state.RetryReason, RuntimeUnlockProbeSidecarClosedRetryReason, StringComparison.Ordinal))
                {
                    return RuntimeUnlockProbeSidecarClosedListenerRearmFailedReason;
                }
            }
        }

        return "runtime_unlock_listener_rearm_failed";
    }

    private static bool IsRuntimeUnlockListenerRearmRequiredRetryReason(string? reason)
    {
        var normalized = SanitizeLogToken(reason);
        return normalized is "runtime_unlock_sidecar_unavailable" or
            "runtime_unlock_listener_sidecar_unavailable" or
            RuntimeUnlockProbeSidecarClosedRetryReason or
            "runtime_unlock_offer_answer_timeout" or
            "runtime_unlock_answer_ack_timeout";
    }

    private static bool IsRuntimeUnlockSidecarDropListenerRearmRetryReason(string? reason)
        => SanitizeLogToken(reason) is "runtime_unlock_listener_sidecar_unavailable" or
            RuntimeUnlockProbeSidecarClosedRetryReason;

    private static bool ShouldNotifyRemoteAccelerationDown(string? reason)
    {
        if (string.IsNullOrWhiteSpace(reason))
        {
            return false;
        }

        return reason.Trim() switch
        {
            "read_failed" or
            "write_failed" or
            "remote_closed" or
            "queue_overflow" or
            "status_timeout" or
            "invalid_status" or
            "status_parse_failed" => true,
            _ => false,
        };
    }

    private bool TryCaptureAccelerationNegotiation(out string sessionId, out NknAccelerationLaneKind lanes)
    {
        lock (accelerationGate)
        {
            sessionId = accelerationSessionId ?? string.Empty;
            lanes = accelerationNegotiatedLanes;
        }

        return lanes != NknAccelerationLaneKind.None &&
               !string.IsNullOrWhiteSpace(sessionId) &&
               string.Equals(sessionId, currentSessionSecurityState.SessionId?.Value, StringComparison.Ordinal);
    }

    private bool TryCaptureAccelerationNegotiationForFallback(out string sessionId, out NknAccelerationLaneKind lanes)
    {
        lock (accelerationGate)
        {
            sessionId = accelerationSessionId ?? string.Empty;
            lanes = accelerationNegotiatedLanes;
        }

        if (lanes == NknAccelerationLaneKind.None ||
            string.IsNullOrWhiteSpace(sessionId))
        {
            return false;
        }

        var currentSessionId = currentSessionSecurityState.SessionId?.Value;
        if (string.IsNullOrWhiteSpace(currentSessionId) ||
            string.Equals(sessionId, currentSessionId, StringComparison.Ordinal))
        {
            return true;
        }

        var capturedSessionId = sessionId;
        lock (gate)
        {
            return fileTransferDataSessions.Values.Any(session =>
                !session.IsDisposed &&
                string.Equals(session.SessionId, capturedSessionId, StringComparison.Ordinal));
        }
    }

    private void ScheduleAccelerationDownNotification(string sessionId, NknAccelerationLaneKind lanes, string reason)
    {
        _ = Task.Run(
            async () =>
            {
                try
                {
                    await SendAccelerationDownAsync(sessionId, lanes, reason, CancellationToken.None).ConfigureAwait(false);
                }
                catch (Exception ex) when (ex is not OperationCanceledException)
                {
                    LocalOperationalLog.Warn(
                        "NKN.Tuna",
                        $"event=tuna_acceleration_down_notify_failed; reason={SanitizeLogToken(reason)}; error={ex.GetType().Name}");
                }
            },
            CancellationToken.None);
    }

    private async Task SendAccelerationDownAsync(
        string sessionId,
        NknAccelerationLaneKind lanes,
        string reason,
        CancellationToken ct)
    {
        if (string.IsNullOrWhiteSpace(remoteEndpoint) ||
            string.IsNullOrWhiteSpace(sessionId) ||
            !string.Equals(sessionId.Trim(), currentSessionSecurityState.SessionId?.Value, StringComparison.Ordinal) ||
            !TryGetCurrentEnvelopeCode(out var envelopeCode))
        {
            return;
        }

        var nonce = Convert.ToHexString(RandomNumberGenerator.GetBytes(16)).ToLowerInvariant();
        var down = new TransportAccelerationDownPayload
        {
            SessionId = sessionId.Trim(),
            SupportedLanes = NknAccelerationLaneCodec.ToNames(lanes),
            SentAtUnixMs = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds(),
            Nonce = nonce,
            SidecarProtocolVersion = TunaSidecarProtocolVersion,
            Reason = reason,
            PayerDecisionId = Volatile.Read(ref accelerationPayerDecisionId),
        };
        var payload = CreateSecureControlPayload(
            MsgType.TransportAccelerationDown,
            nonce,
            JsonSerializer.SerializeToUtf8Bytes(down));
        var envelope = CreateEnvelope(envelopeCode, MsgType.TransportAccelerationDown, payload, replyTo: null);
        var queued = await QueueControlEnvelopeAsync(remoteEndpoint, envelope, ControlOutboundLane.High, ct).ConfigureAwait(false);
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=tuna_acceleration_down_notify_{(queued ? "queued" : "rejected")}; reason={SanitizeLogToken(reason)}; lanes={string.Join(",", down.SupportedLanes)}; payer_decision_id={down.PayerDecisionId}");
    }

    private bool TryGetPendingRuntimeUnlockAnswerAckForOffer(
        TransportAccelerationOfferPayload offer,
        out long generation,
        out NknAccelerationLaneKind lanes,
        out bool matchesPendingOffer)
    {
        generation = 0;
        lanes = NknAccelerationLaneKind.None;
        matchesPendingOffer = false;

        var sessionId = string.IsNullOrWhiteSpace(offer.SessionId)
            ? currentSessionSecurityState.SessionId?.Value ?? string.Empty
            : offer.SessionId.Trim();
        var nonce = string.IsNullOrWhiteSpace(offer.Nonce) ? string.Empty : offer.Nonce.Trim();
        if (string.IsNullOrWhiteSpace(sessionId) ||
            string.IsNullOrWhiteSpace(nonce))
        {
            return false;
        }

        lock (accelerationGate)
        {
            if (string.IsNullOrWhiteSpace(pendingAccelerationAnswerAckNonce) ||
                pendingAccelerationAnswerAckAuthorityMode is null ||
                !string.Equals(pendingAccelerationAnswerAckSessionId, sessionId, StringComparison.Ordinal))
            {
                return false;
            }

            generation = pendingAccelerationAnswerAckGeneration;
            lanes = pendingAccelerationAnswerAckLanes;
            matchesPendingOffer =
                string.Equals(pendingAccelerationAnswerAckNonce, nonce, StringComparison.Ordinal) &&
                pendingAccelerationAnswerAckPayerDecisionId == offer.PayerDecisionId;
            return true;
        }
    }

    private AccelerationValidationResult ValidateAccelerationOffer(
        string source,
        TransportAccelerationOfferPayload offer)
    {
        if (!TryGetAccelerationSessionCapabilityLanes(out var capabilityLanes))
        {
            return AccelerationValidationResult.HardReject("session_not_eligible");
        }

        var expectedSessionId = currentSessionSecurityState.SessionId?.Value;
        if (string.IsNullOrWhiteSpace(offer.SessionId) ||
            !string.Equals(offer.SessionId.Trim(), expectedSessionId, StringComparison.Ordinal))
        {
            return AccelerationValidationResult.HardReject("session_id_mismatch");
        }

        var expectedSource = ResolveExpectedRemotePeerAddressForCurrentSession();
        if (!AddressMatchesForSessionPolicy(source, expectedSource))
        {
            return AccelerationValidationResult.HardReject("source_identity_mismatch");
        }

        if (!IsAccelerationNonceValid(offer.Nonce))
        {
            return AccelerationValidationResult.HardReject("nonce_invalid");
        }

        if (offer.SidecarProtocolVersion != TunaSidecarProtocolVersion)
        {
            return AccelerationValidationResult.HardReject("sidecar_app_protocol_mismatch");
        }

        var allowsDelayedStaleOffer = false;
        if (!TryObserveRemotePayerDecision(offer.PayerDecisionId, "offer"))
        {
            allowsDelayedStaleOffer = ShouldAcceptDelayedHelpeeOfferDespiteStalePayerDecision(offer);
            if (!allowsDelayedStaleOffer)
            {
                return AccelerationValidationResult.HardReject("stale_payer_decision");
            }

            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=tuna_acceleration_delayed_helpee_offer_stale_payer_decision_allowed; payer_decision_id={offer.PayerDecisionId}; latest_payer_decision_id={Volatile.Read(ref remoteAccelerationPayerDecisionId)}");
        }

        var nowMs = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
        if (offer.SentAtUnixMs > 0 &&
            (offer.SentAtUnixMs > nowMs + TimeSpan.FromSeconds(30).TotalMilliseconds ||
             nowMs - offer.SentAtUnixMs > AccelerationOfferLifetime.TotalMilliseconds))
        {
            return AccelerationValidationResult.HardReject("expired");
        }

        if (nowMs >= offer.ExpiresAtUnixMs)
        {
            return AccelerationValidationResult.HardReject("expired");
        }

        if (string.IsNullOrWhiteSpace(offer.TunaAddress))
        {
            return AccelerationValidationResult.HardReject("missing_tuna_address");
        }

        var acceptedLanes = NknAccelerationLaneCodec.FromNames(offer.SupportedLanes) & capabilityLanes & ResolveConfiguredAccelerationLanes();
        return acceptedLanes == NknAccelerationLaneKind.None
            ? AccelerationValidationResult.SoftReject("unsupported_lane")
            : AccelerationValidationResult.Valid(acceptedLanes, allowsDelayedStaleOffer);
    }

    private AccelerationValidationResult ValidateAccelerationPayerIntent(
        string source,
        TransportAccelerationPayerIntentPayload intent)
    {
        if (!TryGetAccelerationSessionCapabilityLanes(out var capabilityLanes))
        {
            return AccelerationValidationResult.HardReject("session_not_eligible");
        }

        var expectedSessionId = currentSessionSecurityState.SessionId?.Value;
        if (string.IsNullOrWhiteSpace(intent.SessionId) ||
            !string.Equals(intent.SessionId.Trim(), expectedSessionId, StringComparison.Ordinal))
        {
            return AccelerationValidationResult.HardReject("session_id_mismatch");
        }

        var expectedSource = ResolveExpectedRemotePeerAddressForCurrentSession();
        if (!AddressMatchesForSessionPolicy(source, expectedSource))
        {
            return AccelerationValidationResult.HardReject("source_identity_mismatch");
        }

        if (!IsAccelerationNonceValid(intent.Nonce))
        {
            return AccelerationValidationResult.HardReject("nonce_invalid");
        }

        if (intent.SidecarProtocolVersion != TunaSidecarProtocolVersion)
        {
            return AccelerationValidationResult.HardReject("sidecar_app_protocol_mismatch");
        }

        if (!TryObserveRemotePayerDecision(intent.PayerDecisionId, "payer_intent"))
        {
            return AccelerationValidationResult.HardReject("stale_payer_decision");
        }

        var nowMs = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
        if (nowMs >= intent.ExpiresAtUnixMs ||
            intent.SentAtUnixMs <= 0 ||
            nowMs - intent.SentAtUnixMs > AccelerationOfferLifetime.TotalMilliseconds)
        {
            return AccelerationValidationResult.HardReject("expired");
        }

        var normalizedIntent = SanitizeLogToken(intent.Intent);
        if (normalizedIntent is not "will_listen" and not "dialer_only")
        {
            return AccelerationValidationResult.HardReject("invalid_intent");
        }

        var acceptedLanes = NknAccelerationLaneCodec.FromNames(intent.SupportedLanes) & capabilityLanes & ResolveConfiguredAccelerationLanes();
        return acceptedLanes == NknAccelerationLaneKind.None
            ? AccelerationValidationResult.SoftReject("unsupported_lane")
            : AccelerationValidationResult.Valid(acceptedLanes);
    }

    private AccelerationValidationResult ValidateAccelerationAnswer(
        string source,
        TransportAccelerationAnswerPayload answer,
        bool requireAcceptedLanes)
    {
        if (!TryGetAccelerationSessionCapabilityLanes(out var capabilityLanes))
        {
            return AccelerationValidationResult.HardReject("session_not_eligible");
        }

        var expectedSessionId = currentSessionSecurityState.SessionId?.Value;
        if (string.IsNullOrWhiteSpace(answer.SessionId) ||
            !string.Equals(answer.SessionId.Trim(), expectedSessionId, StringComparison.Ordinal))
        {
            return AccelerationValidationResult.HardReject("session_id_mismatch");
        }

        var expectedSource = ResolveExpectedRemotePeerAddressForCurrentSession();
        if (!AddressMatchesForSessionPolicy(source, expectedSource))
        {
            return AccelerationValidationResult.HardReject("source_identity_mismatch");
        }

        if (!IsAccelerationNonceValid(answer.Nonce))
        {
            return AccelerationValidationResult.HardReject("nonce_invalid");
        }

        if (answer.SidecarProtocolVersion != TunaSidecarProtocolVersion)
        {
            return AccelerationValidationResult.HardReject("sidecar_app_protocol_mismatch");
        }

        if (DateTimeOffset.UtcNow.ToUnixTimeMilliseconds() >= answer.ExpiresAtUnixMs)
        {
            return AccelerationValidationResult.HardReject("expired");
        }

        if (!requireAcceptedLanes)
        {
            return AccelerationValidationResult.Valid(NknAccelerationLaneKind.None);
        }

        var acceptedLanes = NknAccelerationLaneCodec.FromNames(answer.SupportedLanes) & capabilityLanes & ResolveConfiguredAccelerationLanes();
        return acceptedLanes == NknAccelerationLaneKind.None
            ? AccelerationValidationResult.SoftReject("unsupported_lane")
            : AccelerationValidationResult.Valid(acceptedLanes);
    }

